const HSK4_DATA = {"lessons":[{"id":1,"title_cn":"我们来中国学习了","title_pinyin":"","title_vn":"Chúng em đã đến Trung Quốc học tập","goals":["Có thể nghe hiểu và trao đổi thông tin về làm thủ tục nhập học và xin học bổng.","Có thể trình bày bằng lời hoặc bằng văn bản lý do chọn chuyên ngành và định hướng phát triển nghề nghiệp trong tương lai.","Hiểu được tình hình học tập và sinh hoạt của du học sinh nước ngoài tại các trường đại học Trung Quốc."],"vocab":[{"hanzi":"签证","pinyin":"qiānzhèng","pos":"dt.","vn":"thị thực, visa","examples":[{"cn":"我已经申请了去美国的签证。","pinyin":"Wǒ yǐjīng shēnqǐng le qù Měiguó de qiānzhèng.","vn":"Tôi đã xin visa đi Mỹ rồi."},{"cn":"办签证需要准备很多材料。","pinyin":"Bàn qiānzhèng xūyào zhǔnbèi hěn duō cáiliào.","vn":"Làm visa cần chuẩn bị rất nhiều giấy tờ."},{"cn":"他的签证下个月就到期了。","pinyin":"Tā de qiānzhèng xià ge yuè jiù dàoqī le.","vn":"Visa của anh ấy tháng sau là hết hạn rồi."}]},{"hanzi":"入学","pinyin":"rùxué","pos":"dgt.","vn":"nhập học","examples":[{"cn":"孩子今年九月入学。","pinyin":"Háizi jīnnián jiǔyuè rùxué.","vn":"Đứa trẻ tháng chín năm nay nhập học."},{"cn":"入学以后你会认识很多新朋友。","pinyin":"Rùxué yǐhòu nǐ huì rènshi hěn duō xīn péngyou.","vn":"Sau khi nhập học bạn sẽ quen được rất nhiều bạn mới."},{"cn":"我们学校的入学考试挺难的。","pinyin":"Wǒmen xuéxiào de rùxué kǎoshì tǐng nán de.","vn":"Kỳ thi nhập học của trường chúng tôi khá khó."}]},{"hanzi":"通知","pinyin":"tōngzhī","pos":"dgt./dt.","vn":"thông báo","examples":[{"cn":"老师在群里发了一个通知。","pinyin":"Lǎoshī zài qún lǐ fā le yí ge tōngzhī.","vn":"Thầy giáo đã đăng một thông báo trong nhóm."},{"cn":"公司通知我们明天放假。","pinyin":"Gōngsī tōngzhī wǒmen míngtiān fàngjià.","vn":"Công ty thông báo chúng tôi được nghỉ ngày mai."},{"cn":"你收到录取通知了吗？","pinyin":"Nǐ shōudào lùqǔ tōngzhī le ma?","vn":"Bạn nhận được thông báo trúng tuyển chưa?"}]},{"hanzi":"证件","pinyin":"zhèngjiàn","pos":"dt.","vn":"giấy tờ, giấy chứng nhận","examples":[{"cn":"进大楼需要出示证件。","pinyin":"Jìn dàlóu xūyào chūshì zhèngjiàn.","vn":"Vào tòa nhà cần xuất trình giấy tờ."},{"cn":"我把证件忘在家里了。","pinyin":"Wǒ bǎ zhèngjiàn wàng zài jiā li le.","vn":"Tôi quên giấy tờ ở nhà mất rồi."},{"cn":"办理手续时一定要带好证件。","pinyin":"Bànlǐ shǒuxù shí yídìng yào dài hǎo zhèngjiàn.","vn":"Khi làm thủ tục nhất định phải mang theo đầy đủ giấy tờ."}]},{"hanzi":"材料","pinyin":"cáiliào","pos":"dt.","vn":"tài liệu, tư liệu","examples":[{"cn":"申请奖学金需要准备哪些材料？","pinyin":"Shēnqǐng jiǎngxuéjīn xūyào zhǔnbèi nǎxiē cáiliào?","vn":"Xin học bổng cần chuẩn bị những tài liệu gì?"},{"cn":"这个包的材料摸起来很舒服。","pinyin":"Zhège bāo de cáiliào mō qǐlai hěn shūfu.","vn":"Chất liệu của chiếc túi này sờ vào rất dễ chịu."},{"cn":"他正在收集写论文的材料。","pinyin":"Tā zhèngzài shōují xiě lùnwén de cáiliào.","vn":"Anh ấy đang thu thập tài liệu để viết luận văn."}]},{"hanzi":"证","pinyin":"zhèng","pos":"dt.","vn":"giấy chứng nhận, chứng","examples":[{"cn":"你带学生证了吗？","pinyin":"Nǐ dài xuéshēngzhèng le ma?","vn":"Bạn mang thẻ sinh viên chưa?"},{"cn":"他考了一个驾驶证。","pinyin":"Tā kǎo le yí ge jiàshǐzhèng.","vn":"Anh ấy đã thi được bằng lái xe."},{"cn":"这个证明文件需要盖章才有效。","pinyin":"Zhège zhèngmíng wénjiàn xūyào gàizhāng cái yǒuxiào.","vn":"Giấy chứng nhận này cần đóng dấu mới có hiệu lực."}]},{"hanzi":"任何","pinyin":"rènhé","pos":"đt.","vn":"bất cứ, bất kỳ","examples":[{"cn":"任何人都可以参加这个活动。","pinyin":"Rènhé rén dōu kěyǐ cānjiā zhège huódòng.","vn":"Bất cứ ai cũng có thể tham gia hoạt động này."},{"cn":"我现在没有任何办法解决这个问题。","pinyin":"Wǒ xiànzài méiyǒu rènhé bànfǎ jiějué zhège wèntí.","vn":"Bây giờ tôi không có cách nào để giải quyết vấn đề này cả."},{"cn":"不管任何时候，你都可以给我打电话。","pinyin":"Bùguǎn rènhé shíhou, nǐ dōu kěyǐ gěi wǒ dǎ diànhuà.","vn":"Bất kể lúc nào, bạn đều có thể gọi điện cho tôi."}]},{"hanzi":"食堂","pinyin":"shítáng","pos":"dt.","vn":"nhà ăn, căng tin","examples":[{"cn":"我们一般中午在食堂吃饭。","pinyin":"Wǒmen yìbān zhōngwǔ zài shítáng chīfàn.","vn":"Chúng tôi thường ăn trưa ở căng tin."},{"cn":"学校食堂的菜又便宜又好吃。","pinyin":"Xuéxiào shítáng de cài yòu piányi yòu hǎochī.","vn":"Món ăn ở căng tin trường vừa rẻ vừa ngon."},{"cn":"食堂今天中午人特别多。","pinyin":"Shítáng jīntiān zhōngwǔ rén tèbié duō.","vn":"Trưa nay căng tin đông người đặc biệt."}]},{"hanzi":"座","pinyin":"zuò","pos":"lượng.","vn":"(lượng từ dùng cho núi, tòa nhà và các vật thể cố định tương tự)","examples":[{"cn":"那座山看起来很高。","pinyin":"Nà zuò shān kàn qǐlai hěn gāo.","vn":"Ngọn núi đó nhìn có vẻ rất cao."},{"cn":"学校旁边新建了一座图书馆。","pinyin":"Xuéxiào pángbiān xīn jiàn le yí zuò túshūguǎn.","vn":"Bên cạnh trường mới xây một tòa thư viện."},{"cn":"这座城市的夜景特别美。","pinyin":"Zhè zuò chéngshì de yèjǐng tèbié měi.","vn":"Cảnh đêm của thành phố này đặc biệt đẹp."}]},{"hanzi":"申请","pinyin":"shēnqǐng","pos":"dgt.","vn":"xin, nộp đơn xin","examples":[{"cn":"我打算申请这所大学的硕士。","pinyin":"Wǒ dǎsuàn shēnqǐng zhè suǒ dàxué de shuòshì.","vn":"Tôi định nộp đơn xin học thạc sĩ ở trường đại học này."},{"cn":"他已经申请了三份工作。","pinyin":"Tā yǐjīng shēnqǐng le sān fèn gōngzuò.","vn":"Anh ấy đã nộp đơn xin ba công việc rồi."},{"cn":"申请的时候一定要填清楚自己的信息。","pinyin":"Shēnqǐng de shíhou yídìng yào tián qīngchu zìjǐ de xìnxī.","vn":"Khi nộp đơn nhất định phải điền rõ ràng thông tin của mình."}]},{"hanzi":"奖学金","pinyin":"jiǎngxuéjīn","pos":"dt.","vn":"học bổng","examples":[{"cn":"她这学期得了一等奖学金。","pinyin":"Tā zhè xuéqī dé le yīděng jiǎngxuéjīn.","vn":"Học kỳ này cô ấy được học bổng hạng nhất."},{"cn":"学习好就有机会申请奖学金。","pinyin":"Xuéxí hǎo jiù yǒu jīhuì shēnqǐng jiǎngxuéjīn.","vn":"Học tốt thì có cơ hội xin học bổng."},{"cn":"这个奖学金能减轻不少经济压力。","pinyin":"Zhège jiǎngxuéjīn néng jiǎnqīng bùshǎo jīngjì yālì.","vn":"Học bổng này có thể giảm bớt khá nhiều áp lực kinh tế."}]},{"hanzi":"表现","pinyin":"biǎoxiàn","pos":"dgt.","vn":"biểu hiện, thể hiện","examples":[{"cn":"他最近在公司的表现很好。","pinyin":"Tā zuìjìn zài gōngsī de biǎoxiàn hěn hǎo.","vn":"Dạo gần đây anh ấy thể hiện rất tốt ở công ty."},{"cn":"老师表扬了他这学期的表现。","pinyin":"Lǎoshī biǎoyáng le tā zhè xuéqī de biǎoxiàn.","vn":"Thầy giáo đã khen ngợi biểu hiện của cậu ấy học kỳ này."},{"cn":"比赛那天他表现得特别紧张。","pinyin":"Bǐsài nà tiān tā biǎoxiàn de tèbié jǐnzhāng.","vn":"Hôm thi đấu cậu ấy thể hiện rất căng thẳng."}]},{"hanzi":"获得","pinyin":"huòdé","pos":"dgt.","vn":"giành được, đạt được","examples":[{"cn":"他在这次比赛中获得了第一名。","pinyin":"Tā zài zhè cì bǐsài zhōng huòdé le dì yī míng.","vn":"Anh ấy đã giành được giải nhất trong cuộc thi lần này."},{"cn":"努力学习才能获得好成绩。","pinyin":"Nǔlì xuéxí cái néng huòdé hǎo chéngjì.","vn":"Phải chăm chỉ học tập mới đạt được thành tích tốt."},{"cn":"她终于获得了去国外留学的机会。","pinyin":"Tā zhōngyú huòdé le qù guówài liúxué de jīhuì.","vn":"Cuối cùng cô ấy cũng giành được cơ hội đi du học nước ngoài."}]},{"hanzi":"要是","pinyin":"yàoshi","pos":"liên.","vn":"nếu, nếu như","examples":[{"cn":"要是明天下雨，我们就不去了。","pinyin":"Yàoshi míngtiān xiàyǔ, wǒmen jiù bú qù le.","vn":"Nếu mai trời mưa thì chúng ta không đi nữa."},{"cn":"要是你有时间，就来帮帮我吧。","pinyin":"Yàoshi nǐ yǒu shíjiān, jiù lái bāngbang wǒ ba.","vn":"Nếu bạn có thời gian thì đến giúp tôi một chút nhé."},{"cn":"要是早知道堵车，我就早点出门了。","pinyin":"Yàoshi zǎo zhīdào dǔchē, wǒ jiù zǎodiǎn chūmén le.","vn":"Nếu sớm biết tắc đường thì tôi đã ra khỏi nhà sớm hơn rồi."}]},{"hanzi":"减轻","pinyin":"jiǎnqīng","pos":"dgt.","vn":"giảm nhẹ, giảm bớt","examples":[{"cn":"多运动可以减轻压力。","pinyin":"Duō yùndòng kěyǐ jiǎnqīng yālì.","vn":"Vận động nhiều có thể giảm bớt áp lực."},{"cn":"这个药能减轻疼痛。","pinyin":"Zhège yào néng jiǎnqīng téngtòng.","vn":"Loại thuốc này có thể giảm nhẹ cơn đau."},{"cn":"父母想办法减轻孩子的学习负担。","pinyin":"Fùmǔ xiǎng bànfǎ jiǎnqīng háizi de xuéxí fùdān.","vn":"Cha mẹ nghĩ cách giảm nhẹ gánh nặng học tập cho con cái."}]},{"hanzi":"经济","pinyin":"jīngjì","pos":"dt.","vn":"kinh tế","examples":[{"cn":"这几年国家的经济发展得很快。","pinyin":"Zhè jǐ nián guójiā de jīngjì fāzhǎn de hěn kuài.","vn":"Mấy năm nay kinh tế quốc gia phát triển rất nhanh."},{"cn":"他大学学的是国际经济专业。","pinyin":"Tā dàxué xué de shì guójì jīngjì zhuānyè.","vn":"Anh ấy học chuyên ngành kinh tế quốc tế ở đại học."},{"cn":"我现在经济上不太宽裕。","pinyin":"Wǒ xiànzài jīngjì shang bú tài kuānyù.","vn":"Hiện giờ tôi không mấy dư dả về kinh tế."}]},{"hanzi":"压力","pinyin":"yālì","pos":"dt.","vn":"áp lực","examples":[{"cn":"最近工作压力特别大。","pinyin":"Zuìjìn gōngzuò yālì tèbié dà.","vn":"Gần đây áp lực công việc đặc biệt lớn."},{"cn":"他给自己的压力太大了。","pinyin":"Tā gěi zìjǐ de yālì tài dà le.","vn":"Anh ấy tự tạo áp lực cho mình quá lớn."},{"cn":"听音乐是我放松压力的方法。","pinyin":"Tīng yīnyuè shì wǒ fàngsōng yālì de fāngfǎ.","vn":"Nghe nhạc là cách tôi giải tỏa áp lực."}]},{"hanzi":"加油","pinyin":"jiāyóu","pos":"dgt.","vn":"cố gắng, cổ vũ","examples":[{"cn":"考试加油，你一定可以的！","pinyin":"Kǎoshì jiāyóu, nǐ yídìng kěyǐ de!","vn":"Cố lên thi nhé, bạn chắc chắn làm được!"},{"cn":"大家都在为运动员加油。","pinyin":"Dàjiā dōu zài wèi yùndòngyuán jiāyóu.","vn":"Mọi người đều đang cổ vũ cho vận động viên."},{"cn":"别放弃，再加油一下就成功了。","pinyin":"Bié fàngqì, zài jiāyóu yíxià jiù chénggōng le.","vn":"Đừng bỏ cuộc, cố thêm một chút nữa là thành công rồi."}]},{"hanzi":"随着","pinyin":"suízhe","pos":"giới.","vn":"cùng với","examples":[{"cn":"随着年龄的增长，他变得更成熟了。","pinyin":"Suízhe niánlíng de zēngzhǎng, tā biàn de gèng chéngshú le.","vn":"Cùng với tuổi tác tăng lên, anh ấy trở nên chín chắn hơn."},{"cn":"随着科技的发展，生活越来越方便。","pinyin":"Suízhe kējì de fāzhǎn, shēnghuó yuè lái yuè fāngbiàn.","vn":"Cùng với sự phát triển của khoa học kỹ thuật, cuộc sống ngày càng tiện lợi."},{"cn":"随着天气变冷，穿的衣服也多了起来。","pinyin":"Suízhe tiānqì biàn lěng, chuān de yīfu yě duō le qǐlai.","vn":"Cùng với thời tiết trở lạnh, quần áo mặc cũng nhiều lên."}]},{"hanzi":"课程","pinyin":"kèchéng","pos":"dt.","vn":"khóa học, chương trình học","examples":[{"cn":"这学期我选了五门课程。","pinyin":"Zhè xuéqī wǒ xuǎn le wǔ mén kèchéng.","vn":"Học kỳ này tôi đã đăng ký năm môn học."},{"cn":"这门课程的内容特别有意思。","pinyin":"Zhè mén kèchéng de nèiróng tèbié yǒu yìsi.","vn":"Nội dung môn học này đặc biệt thú vị."},{"cn":"学校最近调整了课程安排。","pinyin":"Xuéxiào zuìjìn tiáozhěng le kèchéng ānpái.","vn":"Gần đây trường đã điều chỉnh lịch trình học."}]},{"hanzi":"专业","pinyin":"zhuānyè","pos":"dt./tt.","vn":"chuyên ngành; chuyên nghiệp","examples":[{"cn":"你大学学的是什么专业？","pinyin":"Nǐ dàxué xué de shì shénme zhuānyè?","vn":"Bạn học chuyên ngành gì ở đại học?"},{"cn":"他对电脑维修特别专业。","pinyin":"Tā duì diànnǎo wéixiū tèbié zhuānyè.","vn":"Anh ấy rất chuyên nghiệp trong việc sửa máy tính."},{"cn":"这个医生看起来很专业。","pinyin":"Zhège yīshēng kàn qǐlai hěn zhuānyè.","vn":"Vị bác sĩ này trông rất chuyên nghiệp."}]},{"hanzi":"本科","pinyin":"běnkē","pos":"dt.","vn":"đại học (hệ cử nhân), bậc cử nhân","examples":[{"cn":"他本科毕业以后就去工作了。","pinyin":"Tā běnkē bìyè yǐhòu jiù qù gōngzuò le.","vn":"Anh ấy tốt nghiệp đại học xong là đi làm luôn."},{"cn":"我本科学的专业跟现在的工作不太一样。","pinyin":"Wǒ běnkē xué de zhuānyè gēn xiànzài de gōngzuò bú tài yíyàng.","vn":"Chuyên ngành tôi học hồi đại học không giống với công việc hiện tại."},{"cn":"这所学校的本科教育很有名。","pinyin":"Zhè suǒ xuéxiào de běnkē jiàoyù hěn yǒumíng.","vn":"Nền giáo dục bậc cử nhân của trường này rất nổi tiếng."}]},{"hanzi":"硕士","pinyin":"shuòshì","pos":"dt.","vn":"thạc sĩ","examples":[{"cn":"她正在读硕士研究生。","pinyin":"Tā zhèngzài dú shuòshì yánjiūshēng.","vn":"Cô ấy đang học thạc sĩ."},{"cn":"他打算毕业后去国外读硕士。","pinyin":"Tā dǎsuàn bìyè hòu qù guówài dú shuòshì.","vn":"Anh ấy định tốt nghiệp xong sẽ đi nước ngoài học thạc sĩ."},{"cn":"硕士学位对找工作很有帮助。","pinyin":"Shuòshì xuéwèi duì zhǎo gōngzuò hěn yǒu bāngzhù.","vn":"Bằng thạc sĩ rất có ích cho việc tìm việc làm."}]},{"hanzi":"研究生","pinyin":"yánjiūshēng","pos":"dt.","vn":"nghiên cứu sinh, học viên cao học","examples":[{"cn":"我表姐现在是研究生。","pinyin":"Wǒ biǎojiě xiànzài shì yánjiūshēng.","vn":"Chị họ tôi hiện giờ là nghiên cứu sinh."},{"cn":"他考上了北京大学的研究生。","pinyin":"Tā kǎoshàng le Běijīng Dàxué de yánjiūshēng.","vn":"Anh ấy đã thi đỗ cao học trường Đại học Bắc Kinh."},{"cn":"研究生的学习压力比本科大很多。","pinyin":"Yánjiūshēng de xuéxí yālì bǐ běnkē dà hěn duō.","vn":"Áp lực học tập của nghiên cứu sinh lớn hơn đại học rất nhiều."}]},{"hanzi":"博士","pinyin":"bóshì","pos":"dt.","vn":"tiến sĩ","examples":[{"cn":"他花了五年时间才拿到博士学位。","pinyin":"Tā huā le wǔ nián shíjiān cái nádào bóshì xuéwèi.","vn":"Anh ấy mất năm năm mới lấy được bằng tiến sĩ."},{"cn":"她是一位很有名的博士。","pinyin":"Tā shì yí wèi hěn yǒumíng de bóshì.","vn":"Cô ấy là một vị tiến sĩ rất nổi tiếng."},{"cn":"读博士需要很强的研究能力。","pinyin":"Dú bóshì xūyào hěn qiáng de yánjiū nénglì.","vn":"Học tiến sĩ cần có năng lực nghiên cứu rất mạnh."}]},{"hanzi":"研究","pinyin":"yánjiū","pos":"dgt.","vn":"nghiên cứu","examples":[{"cn":"他正在研究一个新课题。","pinyin":"Tā zhèngzài yánjiū yí ge xīn kètí.","vn":"Anh ấy đang nghiên cứu một đề tài mới."},{"cn":"我们应该好好研究一下这个问题。","pinyin":"Wǒmen yīnggāi hǎohǎo yánjiū yíxià zhège wèntí.","vn":"Chúng ta nên nghiên cứu kỹ vấn đề này."},{"cn":"这项研究花了他很多年时间。","pinyin":"Zhè xiàng yánjiū huā le tā hěn duō nián shíjiān.","vn":"Công trình nghiên cứu này đã tiêu tốn của anh ấy rất nhiều năm."}]},{"hanzi":"活动","pinyin":"huódòng","pos":"dt./dgt.","vn":"hoạt động","examples":[{"cn":"学校周末组织了一个活动。","pinyin":"Xuéxiào zhōumò zǔzhī le yí ge huódòng.","vn":"Cuối tuần trường tổ chức một hoạt động."},{"cn":"他很少参加课外活动。","pinyin":"Tā hěn shǎo cānjiā kèwài huódòng.","vn":"Anh ấy rất ít khi tham gia hoạt động ngoại khóa."},{"cn":"多活动活动对身体有好处。","pinyin":"Duō huódòng huódòng duì shēntǐ yǒu hǎochù.","vn":"Vận động nhiều có lợi cho sức khỏe."}]},{"hanzi":"通过","pinyin":"tōngguò","pos":"giới./dgt.","vn":"thông qua","examples":[{"cn":"他通过努力终于成功了。","pinyin":"Tā tōngguò nǔlì zhōngyú chénggōng le.","vn":"Anh ấy thông qua nỗ lực cuối cùng đã thành công."},{"cn":"这次考试他顺利通过了。","pinyin":"Zhè cì kǎoshì tā shùnlì tōngguò le.","vn":"Kỳ thi lần này anh ấy đã vượt qua một cách suôn sẻ."},{"cn":"我们通过朋友认识了这个老师。","pinyin":"Wǒmen tōngguò péngyou rènshi le zhège lǎoshī.","vn":"Chúng tôi quen biết thầy giáo này thông qua một người bạn."}]},{"hanzi":"交流","pinyin":"jiāoliú","pos":"dgt.","vn":"giao lưu","examples":[{"cn":"我们应该多和外国朋友交流。","pinyin":"Wǒmen yīnggāi duō hé wàiguó péngyou jiāoliú.","vn":"Chúng ta nên giao lưu nhiều hơn với bạn bè nước ngoài."},{"cn":"这次会议是为了促进两国之间的文化交流。","pinyin":"Zhè cì huìyì shì wèile cùjìn liǎng guó zhījiān de wénhuà jiāoliú.","vn":"Hội nghị lần này là để thúc đẩy giao lưu văn hóa giữa hai nước."},{"cn":"他跟同事的交流越来越少了。","pinyin":"Tā gēn tóngshì de jiāoliú yuè lái yuè shǎo le.","vn":"Việc giao lưu của anh ấy với đồng nghiệp ngày càng ít đi."}]},{"hanzi":"适应","pinyin":"shìyìng","pos":"dgt.","vn":"thích nghi, thích ứng","examples":[{"cn":"我已经适应了这里的生活。","pinyin":"Wǒ yǐjīng shìyìng le zhèlǐ de shēnghuó.","vn":"Tôi đã thích nghi với cuộc sống ở đây rồi."},{"cn":"刚开始他很难适应新的环境。","pinyin":"Gāng kāishǐ tā hěn nán shìyìng xīn de huánjìng.","vn":"Lúc mới đầu anh ấy rất khó thích nghi với môi trường mới."},{"cn":"多数人需要时间去适应变化。","pinyin":"Duōshù rén xūyào shíjiān qù shìyìng biànhuà.","vn":"Phần lớn mọi người cần thời gian để thích nghi với sự thay đổi."}]},{"hanzi":"将来","pinyin":"jiānglái","pos":"dt.","vn":"tương lai","examples":[{"cn":"你将来想做什么工作？","pinyin":"Nǐ jiānglái xiǎng zuò shénme gōngzuò?","vn":"Trong tương lai bạn muốn làm công việc gì?"},{"cn":"我对将来充满了希望。","pinyin":"Wǒ duì jiānglái chōngmǎn le xīwàng.","vn":"Tôi tràn đầy hy vọng về tương lai."},{"cn":"这个决定会影响他的将来。","pinyin":"Zhège juédìng huì yǐngxiǎng tā de jiānglái.","vn":"Quyết định này sẽ ảnh hưởng đến tương lai của anh ấy."}]},{"hanzi":"国际","pinyin":"guójì","pos":"tt./dt.","vn":"quốc tế","examples":[{"cn":"他在一家国际公司工作。","pinyin":"Tā zài yì jiā guójì gōngsī gōngzuò.","vn":"Anh ấy làm việc ở một công ty quốc tế."},{"cn":"这个城市每年都举办国际电影节。","pinyin":"Zhège chéngshì měi nián dōu jǔbàn guójì diànyǐngjié.","vn":"Thành phố này mỗi năm đều tổ chức liên hoan phim quốc tế."},{"cn":"她希望以后能从事国际贸易方面的工作。","pinyin":"Tā xīwàng yǐhòu néng cóngshì guójì màoyì fāngmiàn de gōngzuò.","vn":"Cô ấy hy vọng sau này có thể làm công việc liên quan đến thương mại quốc tế."}]},{"hanzi":"当","pinyin":"dāng","pos":"dgt.","vn":"làm (nghề gì)","examples":[{"cn":"我从小就想当一名老师。","pinyin":"Wǒ cóngxiǎo jiù xiǎng dāng yì míng lǎoshī.","vn":"Từ nhỏ tôi đã muốn làm giáo viên."},{"cn":"他毕业以后当上了工程师。","pinyin":"Tā bìyè yǐhòu dāngshàng le gōngchéngshī.","vn":"Anh ấy tốt nghiệp xong thì trở thành kỹ sư."},{"cn":"她在学校一直当班长。","pinyin":"Tā zài xuéxiào yìzhí dāng bānzhǎng.","vn":"Ở trường cô ấy luôn luôn làm lớp trưởng."}]},{"hanzi":"教育","pinyin":"jiàoyù","pos":"dt./dgt.","vn":"giáo dục","examples":[{"cn":"父母很重视孩子的教育。","pinyin":"Fùmǔ hěn zhòngshì háizi de jiàoyù.","vn":"Cha mẹ rất coi trọng việc giáo dục con cái."},{"cn":"这个国家的教育水平很高。","pinyin":"Zhège guójiā de jiàoyù shuǐpíng hěn gāo.","vn":"Trình độ giáo dục của quốc gia này rất cao."},{"cn":"他从事教育工作已经二十年了。","pinyin":"Tā cóngshì jiàoyù gōngzuò yǐjīng èrshí nián le.","vn":"Anh ấy làm công tác giáo dục đã hai mươi năm rồi."}]},{"hanzi":"成为","pinyin":"chéngwéi","pos":"dgt.","vn":"trở thành","examples":[{"cn":"他的梦想是成为一名医生。","pinyin":"Tā de mèngxiǎng shì chéngwéi yì míng yīshēng.","vn":"Ước mơ của anh ấy là trở thành một bác sĩ."},{"cn":"这座城市已经成为了旅游胜地。","pinyin":"Zhè zuò chéngshì yǐjīng chéngwéi le lǚyóu shèngdì.","vn":"Thành phố này đã trở thành điểm du lịch nổi tiếng."},{"cn":"经过努力，他终于成为了一名律师。","pinyin":"Jīngguò nǔlì, tā zhōngyú chéngwéi le yì míng lǜshī.","vn":"Qua nỗ lực, cuối cùng anh ấy đã trở thành một luật sư."}]},{"hanzi":"教师","pinyin":"jiàoshī","pos":"dt.","vn":"giáo viên","examples":[{"cn":"我妈妈是一名小学教师。","pinyin":"Wǒ māma shì yì míng xiǎoxué jiàoshī.","vn":"Mẹ tôi là một giáo viên tiểu học."},{"cn":"当教师是一份很有意义的工作。","pinyin":"Dāng jiàoshī shì yí fèn hěn yǒu yìyì de gōngzuò.","vn":"Làm giáo viên là một công việc rất có ý nghĩa."},{"cn":"这位教师对学生非常耐心。","pinyin":"Zhè wèi jiàoshī duì xuésheng fēicháng nàixīn.","vn":"Vị giáo viên này rất kiên nhẫn với học sinh."}]},{"hanzi":"贸易","pinyin":"màoyì","pos":"dt.","vn":"thương mại, mậu dịch","examples":[{"cn":"两国之间的贸易越来越频繁。","pinyin":"Liǎng guó zhījiān de màoyì yuè lái yuè pínfán.","vn":"Thương mại giữa hai nước ngày càng nhộn nhịp."},{"cn":"他大学学的是国际贸易专业。","pinyin":"Tā dàxué xué de shì guójì màoyì zhuānyè.","vn":"Anh ấy học chuyên ngành thương mại quốc tế ở đại học."},{"cn":"这家公司主要做电子产品贸易。","pinyin":"Zhè jiā gōngsī zhǔyào zuò diànzǐ chǎnpǐn màoyì.","vn":"Công ty này chủ yếu kinh doanh mậu dịch sản phẩm điện tử."}]},{"hanzi":"方面","pinyin":"fāngmiàn","pos":"dt.","vn":"phương diện, mặt","examples":[{"cn":"他在学习方面很努力。","pinyin":"Tā zài xuéxí fāngmiàn hěn nǔlì.","vn":"Anh ấy rất nỗ lực về mặt học tập."},{"cn":"这件事在很多方面都值得我们学习。","pinyin":"Zhè jiàn shì zài hěn duō fāngmiàn dōu zhídé wǒmen xuéxí.","vn":"Việc này ở nhiều phương diện đều đáng để chúng ta học hỏi."},{"cn":"我们应该从经济和文化两个方面来分析。","pinyin":"Wǒmen yīnggāi cóng jīngjì hé wénhuà liǎng ge fāngmiàn lái fēnxī.","vn":"Chúng ta nên phân tích từ hai phương diện kinh tế và văn hóa."}]},{"hanzi":"知识","pinyin":"zhīshi","pos":"dt.","vn":"kiến thức","examples":[{"cn":"他的知识特别丰富。","pinyin":"Tā de zhīshi tèbié fēngfù.","vn":"Kiến thức của anh ấy đặc biệt phong phú."},{"cn":"读书可以增长知识。","pinyin":"Dúshū kěyǐ zēngzhǎng zhīshi.","vn":"Đọc sách có thể tăng thêm kiến thức."},{"cn":"这本书里有很多实用的知识。","pinyin":"Zhè běn shū lǐ yǒu hěn duō shíyòng de zhīshi.","vn":"Trong cuốn sách này có rất nhiều kiến thức thực dụng."}]},{"hanzi":"另","pinyin":"lìng","pos":"đt.","vn":"khác, cái khác","examples":[{"cn":"这件事我们另找时间再说吧。","pinyin":"Zhè jiàn shì wǒmen lìng zhǎo shíjiān zài shuō ba.","vn":"Việc này chúng ta tìm lúc khác nói chuyện nhé."},{"cn":"他已经搬到另一个城市去了。","pinyin":"Tā yǐjīng bān dào lìng yí ge chéngshì qù le.","vn":"Anh ấy đã chuyển đến một thành phố khác rồi."},{"cn":"这件事情还有另外一种解释。","pinyin":"Zhè jiàn shìqing hái yǒu lìngwài yì zhǒng jiěshì.","vn":"Việc này còn có một cách giải thích khác nữa."}]}],"grammar":[{"title":"指示代词\"任何\"","explanation_vn":"Đại từ chỉ định \"任何\" biểu thị ý nghĩa \"bất cứ cái gì\". Khi bổ nghĩa cho danh từ thường không dùng \"的\", phía sau thường đi kèm với \"都\" hoặc \"也\".","examples":[{"cn":"你们以后有任何问题都可以来找我。","pinyin":"","vn":"Sau này các em có bất cứ vấn đề gì đều có thể đến tìm cô."},{"cn":"明天我们8点出发，任何人也不能迟到。","pinyin":"","vn":"Ngày mai chúng ta xuất phát lúc 8 giờ, bất cứ ai cũng không được đến muộn."},{"cn":"学校有任何通知，我都会第一时间告诉你。","pinyin":"","vn":"Trường có bất cứ thông báo gì, mình đều sẽ báo cho cậu ngay lập tức."}]},{"title":"假设复句\"要是……，就……\"","explanation_vn":"Vế trước nêu ra một giả thiết, vế sau biểu thị kết quả xảy ra khi giả thiết đó được thực hiện.","examples":[{"cn":"要是申请到奖学金，就能减轻不少经济压力。","pinyin":"","vn":"Nếu xin được học bổng thì có thể giảm bớt không ít áp lực kinh tế."},{"cn":"你要是明天有时间，就跟我一起去爬山吧。","pinyin":"","vn":"Nếu ngày mai cậu có thời gian thì cùng mình đi leo núi nhé."},{"cn":"要是她不愿意参加比赛，我们就再问问别人。","pinyin":"","vn":"Nếu cô ấy không muốn tham gia thi đấu thì chúng ta sẽ hỏi người khác."}]},{"title":"介词\"随着\"","explanation_vn":"Giới từ \"随着\" thường đi kèm với từ ngữ hoặc cụm từ biểu thị sự thay đổi, biểu thị một sự việc là điều kiện để sự việc khác xảy ra.","examples":[{"cn":"随着中国的发展，越来越多的外国学生来到中国的大学学习。","pinyin":"","vn":"Cùng với sự phát triển của Trung Quốc, ngày càng nhiều du học sinh nước ngoài đến các trường đại học Trung Quốc học tập."},{"cn":"随着中文水平的提高，我现在能看懂中文报纸了。","pinyin":"","vn":"Cùng với trình độ tiếng Trung được nâng cao, bây giờ mình đã có thể đọc hiểu báo tiếng Trung."},{"cn":"随着小区的环境越来越好，来这里买房子的人也变多了。","pinyin":"","vn":"Cùng với môi trường khu dân cư ngày càng tốt lên, số người đến đây mua nhà cũng tăng lên."}]},{"title":"并列复句\"一方面……，另一方面……\"","explanation_vn":"Câu phức liên hợp \"一方面……，另一方面……\" thường dùng để trình bày hai phương diện nguyên nhân, tình huống,... cùng tồn tại song song.","examples":[{"cn":"来到中国留学，一方面是为了学习语言和知识，另一方面也是为将来的工作和生活做准备。","pinyin":"","vn":"Đến Trung Quốc du học, một mặt là để học ngôn ngữ và kiến thức, mặt khác cũng là để chuẩn bị cho công việc và cuộc sống sau này."},{"cn":"他经常在网上买东西，一方面因为便宜，另一方面因为方便。","pinyin":"","vn":"Anh ấy thường mua đồ trên mạng, một mặt vì rẻ, mặt khác vì tiện lợi."},{"cn":"多做运动一方面能让身体更健康，另一方面也能减轻压力。","pinyin":"","vn":"Tập thể dục nhiều một mặt có thể giúp cơ thể khỏe mạnh hơn, mặt khác cũng có thể giảm bớt áp lực."}]}],"texts":[{"label":"Bài khóa 1","type":"dialogue","lines":[{"speaker":"老师","cn":"你们好，欢迎来到中国留学！请把护照、签证和入学通知书给我。","pinyin":""},{"speaker":"白家月","cn":"好的。这是我们的证件和材料。","pinyin":""},{"speaker":"","cn":"（几分钟后。）","pinyin":""},{"speaker":"老师","cn":"办好了，这是你们的学生证，下周一开始上课。先试听两周，然后在网上选课。","pinyin":""},{"speaker":"白家月、陈天中","cn":"谢谢老师。","pinyin":""},{"speaker":"老师","cn":"不客气，你们以后有任何问题都可以来找我。","pinyin":""}],"translation_vn":"Cô giáo: Các em chào, chào mừng các em đến Trung Quốc du học! Hãy đưa hộ chiếu, visa và giấy báo nhập học cho cô.\nBạch Gia Nguyệt: Vâng ạ. Đây là giấy tờ và tài liệu của chúng em.\n(Vài phút sau.)\nCô giáo: Xong rồi, đây là thẻ sinh viên của các em, thứ Hai tuần sau bắt đầu học. Trước tiên dự thính hai tuần, sau đó chọn môn học trên mạng.\nBạch Gia Nguyệt, Trần Thiên Trung: Chúng em cảm ơn cô ạ.\nCô giáo: Không có gì, sau này các em có bất cứ vấn đề gì đều có thể đến tìm cô.","audio_dialogue":"1-1.mp3","audio_vocab":"1-2.mp3"},{"label":"Bài khóa 2","type":"dialogue","lines":[{"speaker":"陈天中","cn":"你看，咱们的校园真大！有图书馆、体育馆、超市，还有好几个食堂。","pinyin":""},{"speaker":"白家月","cn":"是啊，我觉得学校就像一座小城市，什么都有，方便极了。","pinyin":""},{"speaker":"陈天中","cn":"刚才老师说，咱们可以申请奖学金，你了解过吗？","pinyin":""},{"speaker":"白家月","cn":"我听说过一点儿，好像成绩好、表现好的学生都有机会获得奖学金。","pinyin":""},{"speaker":"陈天中","cn":"那太好了，要是申请到奖学金，就能减轻不少经济压力。","pinyin":""},{"speaker":"白家月","cn":"没错，我们一起加油吧！","pinyin":""}],"translation_vn":"Trần Thiên Trung: Cậu xem, khuôn viên trường mình thật rộng! Có thư viện, nhà thi đấu, siêu thị, còn có mấy nhà ăn nữa.\nBạch Gia Nguyệt: Đúng vậy, mình thấy trường học giống như một thành phố nhỏ, cái gì cũng có, tiện lợi vô cùng.\nTrần Thiên Trung: Vừa nãy thầy/cô nói, chúng mình có thể xin học bổng, cậu tìm hiểu chưa?\nBạch Gia Nguyệt: Mình nghe nói một chút, hình như sinh viên có thành tích tốt, biểu hiện tốt đều có cơ hội giành được học bổng.\nTrần Thiên Trung: Thế thì tốt quá, nếu xin được học bổng thì có thể giảm bớt không ít áp lực kinh tế.\nBạch Gia Nguyệt: Đúng vậy, chúng mình cùng cố gắng nhé!","audio_dialogue":"1-3.mp3","audio_vocab":"1-4.mp3"},{"label":"Bài khóa 3","type":"passage","lines":[{"speaker":"","cn":"随着中国的发展，越来越多的外国学生来到中国的大学学习。他们可以先上一年的中文课程，然后根据自己的兴趣和需要选择专业。除了读本科课程，他们还可以申请读硕士研究生或者博士研究生。在大学里，外国学生可以和中国学生一起学习、做研究、参加校园活动。通过这些交流，外国学生能更快地适应中国的大学生活。","pinyin":""}],"translation_vn":"Cùng với sự phát triển của Trung Quốc, ngày càng nhiều du học sinh nước ngoài đến các trường đại học Trung Quốc học tập. Họ có thể học một năm khóa tiếng Trung trước, sau đó căn cứ vào sở thích và nhu cầu của bản thân để chọn chuyên ngành. Ngoài việc học chương trình đại học, họ còn có thể xin học thạc sĩ hoặc tiến sĩ. Ở trường đại học, du học sinh nước ngoài có thể cùng học tập, nghiên cứu, tham gia các hoạt động trong khuôn viên trường với sinh viên Trung Quốc. Thông qua những giao lưu này, du học sinh nước ngoài có thể nhanh chóng thích nghi với cuộc sống đại học ở Trung Quốc.","audio_dialogue":"1-5.mp3","audio_vocab":"1-6.mp3"},{"label":"Bài khóa 4","type":"passage","lines":[{"speaker":"","cn":"很多外国学生来中国学习以前，就已经想好了自己的发展方向。有人对经济感兴趣，希望将来在国际公司工作；有人喜欢学医，打算回国后当一名医生；还有人对教育有热情，想要成为一名教师。陈天中想选择跟经济有关的专业，希望通过学习，了解更多国际贸易方面的知识。安妮以后想做一名中文老师，所以要选择国际中文教育专业。对他们来说，来到中国留学，一方面是为了学习语言和知识，另一方面也是为将来的工作和生活做准备。","pinyin":""}],"translation_vn":"Rất nhiều du học sinh nước ngoài trước khi đến Trung Quốc học tập đã nghĩ kỹ về hướng phát triển của bản thân. Có người hứng thú với kinh tế, hy vọng sau này làm việc trong công ty quốc tế; có người thích học y, dự định về nước làm bác sĩ; lại có người nhiệt huyết với giáo dục, muốn trở thành giáo viên. Trần Thiên Trung muốn chọn chuyên ngành liên quan đến kinh tế, hy vọng thông qua việc học để hiểu biết thêm về lĩnh vực thương mại quốc tế. Annie sau này muốn làm giáo viên tiếng Trung, vì vậy sẽ chọn chuyên ngành Giáo dục tiếng Trung quốc tế. Đối với họ, đến Trung Quốc du học, một mặt là để học ngôn ngữ và kiến thức, mặt khác cũng là để chuẩn bị cho công việc và cuộc sống sau này.","audio_dialogue":"1-7.mp3","audio_vocab":"1-8.mp3"}]},{"id":2,"title_cn":"租到了合适的房子","title_pinyin":"","title_vn":"Tôi đã thuê được căn nhà phù hợp","goals":["Có thể nghe hiểu và trao đổi các chủ đề liên quan đến việc thuê nhà.","Có thể trình bày bằng lời hoặc bằng văn bản nguyện vọng, yêu cầu thuê nhà,...","Hiểu được quan niệm về nhà ở của người Trung Quốc."],"vocab":[{"hanzi":"房东","pinyin":"fángdōng","pos":"dt.","vn":"chủ nhà","examples":[{"cn":"我的房东人很好，经常帮我修东西。","pinyin":"Wǒ de fángdōng rén hěn hǎo, jīngcháng bāng wǒ xiū dōngxi.","vn":"Chủ nhà của tôi rất tốt bụng, thường giúp tôi sửa đồ."},{"cn":"房东昨天通知我下个月要涨房租。","pinyin":"Fángdōng zuótiān tōngzhī wǒ xià ge yuè yào zhǎng fángzū.","vn":"Chủ nhà hôm qua báo tôi là tháng sau sẽ tăng tiền thuê."},{"cn":"我跟房东商量了一下搬家的事。","pinyin":"Wǒ gēn fángdōng shāngliang le yíxià bānjiā de shì.","vn":"Tôi đã bàn bạc với chủ nhà về chuyện chuyển nhà."}]},{"hanzi":"出租","pinyin":"chūzū","pos":"dgt.","vn":"cho thuê","examples":[{"cn":"这套房子正在出租。","pinyin":"Zhè tào fángzi zhèngzài chūzū.","vn":"Căn nhà này đang được cho thuê."},{"cn":"他把多余的房间出租给了学生。","pinyin":"Tā bǎ duōyú de fángjiān chūzū gěi le xuésheng.","vn":"Anh ấy đã cho sinh viên thuê căn phòng thừa."},{"cn":"我们公司有出租车可以用。","pinyin":"Wǒmen gōngsī yǒu chūzūchē kěyǐ yòng.","vn":"Công ty chúng tôi có taxi để sử dụng."}]},{"hanzi":"房租","pinyin":"fángzū","pos":"dt.","vn":"tiền thuê nhà","examples":[{"cn":"这边的房租每个月要三千块。","pinyin":"Zhèbiān de fángzū měi ge yuè yào sānqiān kuài.","vn":"Tiền thuê nhà ở đây mỗi tháng là ba nghìn tệ."},{"cn":"房租这个月还没交呢。","pinyin":"Fángzū zhège yuè hái méi jiāo ne.","vn":"Tiền thuê nhà tháng này vẫn chưa đóng."},{"cn":"市中心的房租比郊区贵多了。","pinyin":"Shìzhōngxīn de fángzū bǐ jiāoqū guì duō le.","vn":"Tiền thuê nhà ở trung tâm thành phố đắt hơn ngoại ô nhiều."}]},{"hanzi":"收拾","pinyin":"shōushi","pos":"dgt.","vn":"dọn dẹp, thu dọn","examples":[{"cn":"周末我打算好好收拾一下房间。","pinyin":"Zhōumò wǒ dǎsuàn hǎohǎo shōushi yíxià fángjiān.","vn":"Cuối tuần tôi định dọn dẹp phòng cho thật sạch sẽ."},{"cn":"出发之前记得把行李收拾好。","pinyin":"Chūfā zhīqián jìde bǎ xíngli shōushi hǎo.","vn":"Trước khi xuất phát nhớ thu dọn hành lý cho gọn gàng."},{"cn":"他从来不收拾自己的桌子。","pinyin":"Tā cónglái bù shōushi zìjǐ de zhuōzi.","vn":"Anh ấy chưa bao giờ dọn dẹp bàn của mình."}]},{"hanzi":"租","pinyin":"zū","pos":"dgt.","vn":"thuê","examples":[{"cn":"我在北京租了一个单间。","pinyin":"Wǒ zài Běijīng zū le yí ge dānjiān.","vn":"Tôi đã thuê một phòng đơn ở Bắc Kinh."},{"cn":"他们打算租一辆车去旅游。","pinyin":"Tāmen dǎsuàn zū yí liàng chē qù lǚyóu.","vn":"Họ định thuê một chiếc xe để đi du lịch."},{"cn":"这里租房子方便吗？","pinyin":"Zhèlǐ zū fángzi fāngbiàn ma?","vn":"Thuê nhà ở đây có tiện không?"}]},{"hanzi":"嗯","pinyin":"ng","pos":"ct.","vn":"ừ, vâng","examples":[{"cn":"嗯，我知道了。","pinyin":"Ng, wǒ zhīdào le.","vn":"Ừ, tôi biết rồi."},{"cn":"嗯，这个主意不错。","pinyin":"Ng, zhège zhǔyi búcuò.","vn":"Ừ, ý kiến này không tệ."},{"cn":"嗯……让我再想想。","pinyin":"Ng……ràng wǒ zài xiǎngxiang.","vn":"Ừm... để tôi nghĩ thêm chút nữa."}]},{"hanzi":"亮","pinyin":"liàng","pos":"tt./dgt.","vn":"sáng, sáng sủa","examples":[{"cn":"这个房间的灯特别亮。","pinyin":"Zhège fángjiān de dēng tèbié liàng.","vn":"Đèn của căn phòng này rất sáng."},{"cn":"天刚亮他就起床了。","pinyin":"Tiān gāng liàng tā jiù qǐchuáng le.","vn":"Trời vừa sáng là anh ấy đã dậy rồi."},{"cn":"屋子里亮着一盏小灯。","pinyin":"Wūzi lǐ liàng zhe yì zhǎn xiǎo dēng.","vn":"Trong phòng sáng một ngọn đèn nhỏ."}]},{"hanzi":"就是","pinyin":"jiùshì","pos":"trợ.","vn":"(trợ từ dùng cuối câu, thường đi với \"了\" để nhấn mạnh sự khẳng định) là được, thế thôi","examples":[{"cn":"你喜欢就是了，别管别人怎么说。","pinyin":"Nǐ xǐhuan jiùshì le, bié guǎn biéren zěnme shuō.","vn":"Bạn thích là được, đừng quan tâm người khác nói gì."},{"cn":"别想太多，做好自己的事就是了。","pinyin":"Bié xiǎng tài duō, zuò hǎo zìjǐ de shì jiùshì le.","vn":"Đừng nghĩ nhiều quá, làm tốt việc của mình là được."},{"cn":"他只是说说而已，你别放在心上就是了。","pinyin":"Tā zhǐshì shuōshuo éryǐ, nǐ bié fàng zài xīnshang jiùshì le.","vn":"Anh ấy chỉ nói vậy thôi, bạn đừng để trong lòng là được rồi."}]},{"hanzi":"种","pinyin":"zhòng","pos":"dgt.","vn":"trồng","examples":[{"cn":"爷爷在院子里种了很多花。","pinyin":"Yéye zài yuànzi lǐ zhòng le hěn duō huā.","vn":"Ông nội đã trồng rất nhiều hoa trong sân."},{"cn":"我们打算在阳台上种点蔬菜。","pinyin":"Wǒmen dǎsuàn zài yángtái shang zhòng diǎn shūcài.","vn":"Chúng tôi định trồng chút rau trên ban công."},{"cn":"这种树很容易种活。","pinyin":"Zhè zhǒng shù hěn róngyì zhòng huó.","vn":"Loại cây này rất dễ trồng sống."}]},{"hanzi":"周围","pinyin":"zhōuwéi","pos":"dt.","vn":"xung quanh","examples":[{"cn":"我家周围有很多商店。","pinyin":"Wǒ jiā zhōuwéi yǒu hěn duō shāngdiàn.","vn":"Xung quanh nhà tôi có rất nhiều cửa hàng."},{"cn":"学校周围环境很安静。","pinyin":"Xuéxiào zhōuwéi huánjìng hěn ānjìng.","vn":"Môi trường xung quanh trường rất yên tĩnh."},{"cn":"他看了看周围，发现没有人。","pinyin":"Tā kàn le kàn zhōuwéi, fāxiàn méiyǒu rén.","vn":"Anh ấy nhìn quanh và phát hiện không có ai."}]},{"hanzi":"不过","pinyin":"búguò","pos":"liên.","vn":"nhưng, tuy nhiên","examples":[{"cn":"这个地方不错，不过有点儿贵。","pinyin":"Zhège dìfang búcuò, búguò yǒudiǎnr guì.","vn":"Chỗ này khá được, nhưng mà hơi đắt một chút."},{"cn":"他很聪明，不过有时候太粗心。","pinyin":"Tā hěn cōngming, búguò yǒushíhou tài cūxīn.","vn":"Anh ấy rất thông minh, nhưng đôi khi hơi bất cẩn."},{"cn":"我想去，不过没有时间。","pinyin":"Wǒ xiǎng qù, búguò méiyǒu shíjiān.","vn":"Tôi muốn đi, nhưng không có thời gian."}]},{"hanzi":"毕业","pinyin":"bìyè","pos":"dgt.","vn":"tốt nghiệp","examples":[{"cn":"他今年夏天就要毕业了。","pinyin":"Tā jīnnián xiàtiān jiù yào bìyè le.","vn":"Mùa hè năm nay anh ấy sắp tốt nghiệp rồi."},{"cn":"毕业以后你有什么打算？","pinyin":"Bìyè yǐhòu nǐ yǒu shénme dǎsuàn?","vn":"Sau khi tốt nghiệp bạn có dự định gì?"},{"cn":"我们是同一年毕业的。","pinyin":"Wǒmen shì tóng yì nián bìyè de.","vn":"Chúng tôi tốt nghiệp cùng một năm."}]},{"hanzi":"恐怕","pinyin":"kǒngpà","pos":"phó.","vn":"e rằng, sợ rằng","examples":[{"cn":"外面下雨了，我们恐怕去不了了。","pinyin":"Wàimiàn xiàyǔ le, wǒmen kǒngpà qù bu liǎo le.","vn":"Ngoài trời đang mưa, e là chúng ta không đi được rồi."},{"cn":"这件事恐怕没那么简单。","pinyin":"Zhè jiàn shì kǒngpà méi nàme jiǎndān.","vn":"Việc này e rằng không đơn giản như vậy."},{"cn":"他今天恐怕来不了了。","pinyin":"Tā jīntiān kǒngpà lái bu liǎo le.","vn":"Hôm nay e là anh ấy không đến được."}]},{"hanzi":"热闹","pinyin":"rènao","pos":"dgt./tt./dt.","vn":"náo nhiệt, nhộn nhịp; sự náo nhiệt","examples":[{"cn":"春节的时候街上特别热闹。","pinyin":"Chūnjié de shíhou jiē shang tèbié rènao.","vn":"Vào dịp Tết Nguyên Đán đường phố rất náo nhiệt."},{"cn":"我喜欢热闹的地方。","pinyin":"Wǒ xǐhuan rènao de dìfang.","vn":"Tôi thích những nơi náo nhiệt."},{"cn":"大家一起聊天，气氛很热闹。","pinyin":"Dàjiā yìqǐ liáotiān, qìfēn hěn rènao.","vn":"Mọi người cùng nhau trò chuyện, không khí rất nhộn nhịp."}]},{"hanzi":"入住","pinyin":"rùzhù","pos":"dgt.","vn":"chuyển vào ở, nhận phòng","examples":[{"cn":"我们下午三点才能入住酒店。","pinyin":"Wǒmen xiàwǔ sān diǎn cái néng rùzhù jiǔdiàn.","vn":"Ba giờ chiều chúng tôi mới có thể nhận phòng khách sạn."},{"cn":"新房子已经装修好了，可以入住了。","pinyin":"Xīn fángzi yǐjīng zhuāngxiū hǎo le, kěyǐ rùzhù le.","vn":"Nhà mới đã trang trí xong rồi, có thể dọn vào ở được rồi."},{"cn":"入住的时候需要出示身份证。","pinyin":"Rùzhù de shíhou xūyào chūshì shēnfènzhèng.","vn":"Khi nhận phòng cần xuất trình chứng minh thư."}]},{"hanzi":"日记","pinyin":"rìjì","pos":"dt.","vn":"nhật ký","examples":[{"cn":"她每天都写日记。","pinyin":"Tā měitiān dōu xiě rìjì.","vn":"Mỗi ngày cô ấy đều viết nhật ký."},{"cn":"我把今天发生的事记在了日记里。","pinyin":"Wǒ bǎ jīntiān fāshēng de shì jì zài le rìjì lǐ.","vn":"Tôi đã ghi lại chuyện xảy ra hôm nay vào nhật ký."},{"cn":"这是我中学时候写的日记。","pinyin":"Zhè shì wǒ zhōngxué shíhou xiě de rìjì.","vn":"Đây là cuốn nhật ký tôi viết hồi trung học."}]},{"hanzi":"顺利","pinyin":"shùnlì","pos":"tt.","vn":"thuận lợi, suôn sẻ","examples":[{"cn":"祝你考试顺利！","pinyin":"Zhù nǐ kǎoshì shùnlì!","vn":"Chúc bạn thi cử thuận lợi!"},{"cn":"这次旅行一切都很顺利。","pinyin":"Zhè cì lǚxíng yíqiè dōu hěn shùnlì.","vn":"Chuyến du lịch lần này mọi thứ đều rất suôn sẻ."},{"cn":"事情没有想象中那么顺利。","pinyin":"Shìqing méiyǒu xiǎngxiàng zhōng nàme shùnlì.","vn":"Mọi việc không suôn sẻ như trong tưởng tượng."}]},{"hanzi":"并","pinyin":"bìng","pos":"liên./phó.","vn":"và, hơn nữa; (nhấn mạnh phủ định) hoàn toàn (không)","examples":[{"cn":"他并没有想象中那么难相处。","pinyin":"Tā bìng méiyǒu xiǎngxiàng zhōng nàme nán xiāngchǔ.","vn":"Anh ấy hoàn toàn không khó gần như trong tưởng tượng."},{"cn":"我并不是不喜欢这个工作。","pinyin":"Wǒ bìng bú shì bù xǐhuan zhège gōngzuò.","vn":"Tôi hoàn toàn không phải là không thích công việc này."},{"cn":"会议通过了这个计划，并决定下周开始实施。","pinyin":"Huìyì tōngguò le zhège jìhuà, bìng juédìng xiàzhōu kāishǐ shíshī.","vn":"Cuộc họp đã thông qua kế hoạch này, và quyết định tuần sau bắt đầu thực hiện."}]},{"hanzi":"客厅","pinyin":"kètīng","pos":"dt.","vn":"phòng khách","examples":[{"cn":"客厅里放着一张大沙发。","pinyin":"Kètīng lǐ fàng zhe yì zhāng dà shāfā.","vn":"Trong phòng khách đặt một chiếc ghế sofa lớn."},{"cn":"我们家的客厅不太大。","pinyin":"Wǒmen jiā de kètīng bú tài dà.","vn":"Phòng khách nhà chúng tôi không to lắm."},{"cn":"晚上大家都坐在客厅看电视。","pinyin":"Wǎnshang dàjiā dōu zuò zài kètīng kàn diànshì.","vn":"Buổi tối mọi người đều ngồi ở phòng khách xem tivi."}]},{"hanzi":"台","pinyin":"tái","pos":"lượng.","vn":"(lượng từ dùng cho máy móc, thiết bị,...)","examples":[{"cn":"我买了一台新电脑。","pinyin":"Wǒ mǎi le yì tái xīn diànnǎo.","vn":"Tôi đã mua một chiếc máy tính mới."},{"cn":"厨房里有一台洗碗机。","pinyin":"Chúfáng lǐ yǒu yì tái xǐwǎnjī.","vn":"Trong bếp có một chiếc máy rửa bát."},{"cn":"这台空调用了好几年了。","pinyin":"Zhè tái kōngtiáo yòng le hǎo jǐ nián le.","vn":"Chiếc điều hòa này đã dùng được mấy năm rồi."}]},{"hanzi":"厨房","pinyin":"chúfáng","pos":"dt.","vn":"nhà bếp","examples":[{"cn":"妈妈在厨房做饭。","pinyin":"Māma zài chúfáng zuòfàn.","vn":"Mẹ đang nấu cơm trong bếp."},{"cn":"这个厨房有点儿小。","pinyin":"Zhège chúfáng yǒudiǎnr xiǎo.","vn":"Nhà bếp này hơi nhỏ một chút."},{"cn":"厨房里有很多锅碗瓢盆。","pinyin":"Chúfáng lǐ yǒu hěn duō guōwǎnpiáopén.","vn":"Trong bếp có rất nhiều nồi niêu xoong chảo."}]},{"hanzi":"平常","pinyin":"píngcháng","pos":"dt./tt.","vn":"ngày thường; bình thường","examples":[{"cn":"他平常不怎么说话。","pinyin":"Tā píngcháng bù zěnme shuōhuà.","vn":"Bình thường anh ấy không hay nói chuyện."},{"cn":"我平常都坐地铁上班。","pinyin":"Wǒ píngcháng dōu zuò dìtiě shàngbān.","vn":"Bình thường tôi đi tàu điện ngầm đi làm."},{"cn":"今天跟平常不太一样。","pinyin":"Jīntiān gēn píngcháng bú tài yíyàng.","vn":"Hôm nay không giống ngày thường lắm."}]},{"hanzi":"基本上","pinyin":"jīběnshàng","pos":"phó.","vn":"về cơ bản, về căn bản","examples":[{"cn":"这件事基本上已经解决了。","pinyin":"Zhè jiàn shì jīběnshàng yǐjīng jiějué le.","vn":"Việc này về cơ bản đã giải quyết xong rồi."},{"cn":"我基本上每天都去健身房。","pinyin":"Wǒ jīběnshàng měitiān dōu qù jiànshēnfáng.","vn":"Về cơ bản mỗi ngày tôi đều đến phòng tập."},{"cn":"他说的基本上都是事实。","pinyin":"Tā shuō de jīběnshàng dōu shì shìshí.","vn":"Những gì anh ấy nói về cơ bản đều là sự thật."}]},{"hanzi":"整个","pinyin":"zhěnggè","pos":"tt.","vn":"cả, toàn bộ","examples":[{"cn":"他整个下午都在睡觉。","pinyin":"Tā zhěnggè xiàwǔ dōu zài shuìjiào.","vn":"Cả buổi chiều anh ấy đều ngủ."},{"cn":"这场雨下了整个晚上。","pinyin":"Zhè chǎng yǔ xià le zhěnggè wǎnshang.","vn":"Trận mưa này đã rơi suốt cả đêm."},{"cn":"整个班都为他感到骄傲。","pinyin":"Zhěnggè bān dōu wèi tā gǎndào jiāo'ào.","vn":"Cả lớp đều cảm thấy tự hào về anh ấy."}]},{"hanzi":"毛巾","pinyin":"máojīn","pos":"dt.","vn":"khăn mặt","examples":[{"cn":"请把毛巾挂在那边。","pinyin":"Qǐng bǎ máojīn guà zài nàbiān.","vn":"Làm ơn treo khăn mặt ở đằng kia."},{"cn":"这条毛巾是新买的。","pinyin":"Zhè tiáo máojīn shì xīn mǎi de.","vn":"Chiếc khăn mặt này mới mua."},{"cn":"洗完脸用毛巾擦干。","pinyin":"Xǐ wán liǎn yòng máojīn cā gān.","vn":"Rửa mặt xong dùng khăn lau khô."}]},{"hanzi":"建议","pinyin":"jiànyì","pos":"dt./dgt.","vn":"đề nghị, gợi ý","examples":[{"cn":"我建议你早点睡觉。","pinyin":"Wǒ jiànyì nǐ zǎodiǎn shuìjiào.","vn":"Tôi đề nghị bạn đi ngủ sớm một chút."},{"cn":"他给了我一个很好的建议。","pinyin":"Tā gěi le wǒ yí ge hěn hǎo de jiànyì.","vn":"Anh ấy đã đưa cho tôi một gợi ý rất hay."},{"cn":"谢谢你的建议，我会考虑的。","pinyin":"Xièxie nǐ de jiànyì, wǒ huì kǎolǜ de.","vn":"Cảm ơn lời đề nghị của bạn, tôi sẽ cân nhắc."}]},{"hanzi":"查看","pinyin":"chákàn","pos":"dgt.","vn":"xem xét, kiểm tra","examples":[{"cn":"请查看一下你的邮箱。","pinyin":"Qǐng chákàn yíxià nǐ de yóuxiāng.","vn":"Hãy kiểm tra hộp thư của bạn một chút."},{"cn":"我每天都会查看天气预报。","pinyin":"Wǒ měitiān dōu huì chákàn tiānqì yùbào.","vn":"Mỗi ngày tôi đều xem dự báo thời tiết."},{"cn":"他打开手机查看了一下时间。","pinyin":"Tā dǎkāi shǒujī chákàn le yíxià shíjiān.","vn":"Anh ấy mở điện thoại xem giờ một chút."}]},{"hanzi":"信息","pinyin":"xìnxī","pos":"dt.","vn":"thông tin","examples":[{"cn":"你可以在网上查这个信息。","pinyin":"Nǐ kěyǐ zài wǎngshàng chá zhège xìnxī.","vn":"Bạn có thể tra thông tin này trên mạng."},{"cn":"他给我发了一条信息。","pinyin":"Tā gěi wǒ fā le yì tiáo xìnxī.","vn":"Anh ấy đã gửi cho tôi một tin nhắn."},{"cn":"这个消息来源的信息不太可靠。","pinyin":"Zhège xiāoxi láiyuán de xìnxī bú tài kěkào.","vn":"Thông tin từ nguồn tin này không mấy đáng tin cậy."}]},{"hanzi":"查找","pinyin":"cházhǎo","pos":"dgt.","vn":"tìm kiếm","examples":[{"cn":"我在网上查找相关的资料。","pinyin":"Wǒ zài wǎngshàng cházhǎo xiāngguān de zīliào.","vn":"Tôi đang tìm kiếm tài liệu liên quan trên mạng."},{"cn":"他花了很长时间查找原因。","pinyin":"Tā huā le hěn cháng shíjiān cházhǎo yuányīn.","vn":"Anh ấy đã mất rất nhiều thời gian tìm hiểu nguyên nhân."},{"cn":"你可以用这个软件查找附近的餐厅。","pinyin":"Nǐ kěyǐ yòng zhège ruǎnjiàn cházhǎo fùjìn de cāntīng.","vn":"Bạn có thể dùng phần mềm này để tìm nhà hàng gần đó."}]},{"hanzi":"接着","pinyin":"jiēzhe","pos":"phó./dgt.","vn":"tiếp theo, sau đó","examples":[{"cn":"他说完以后，接着就离开了。","pinyin":"Tā shuō wán yǐhòu, jiēzhe jiù líkāi le.","vn":"Anh ấy nói xong là lập tức rời đi."},{"cn":"先把菜洗好，接着切成小块。","pinyin":"Xiān bǎ cài xǐ hǎo, jiēzhe qiē chéng xiǎo kuài.","vn":"Trước tiên rửa sạch rau, tiếp theo cắt thành miếng nhỏ."},{"cn":"他接着我的话往下讲。","pinyin":"Tā jiēzhe wǒ de huà wǎng xià jiǎng.","vn":"Anh ấy tiếp lời tôi nói tiếp."}]},{"hanzi":"同时","pinyin":"tóngshí","pos":"liên./dt.","vn":"đồng thời","examples":[{"cn":"他一边听音乐，同时一边做作业。","pinyin":"Tā yìbiān tīng yīnyuè, tóngshí yìbiān zuò zuòyè.","vn":"Anh ấy vừa nghe nhạc, đồng thời vừa làm bài tập."},{"cn":"这个方法又快又好，同时也很省钱。","pinyin":"Zhège fāngfǎ yòu kuài yòu hǎo, tóngshí yě hěn shěngqián.","vn":"Phương pháp này vừa nhanh vừa tốt, đồng thời cũng rất tiết kiệm tiền."},{"cn":"两件事几乎是同时发生的。","pinyin":"Liǎng jiàn shì jīhū shì tóngshí fāshēng de.","vn":"Hai việc này gần như xảy ra đồng thời."}]},{"hanzi":"位置","pinyin":"wèizhì","pos":"dt.","vn":"vị trí","examples":[{"cn":"这个房子的位置很方便。","pinyin":"Zhège fángzi de wèizhì hěn fāngbiàn.","vn":"Vị trí của căn nhà này rất tiện lợi."},{"cn":"请把杯子放回原来的位置。","pinyin":"Qǐng bǎ bēizi fàng huí yuánlái de wèizhì.","vn":"Hãy đặt cốc về vị trí ban đầu."},{"cn":"我找不到这家店的具体位置。","pinyin":"Wǒ zhǎo bu dào zhè jiā diàn de jùtǐ wèizhì.","vn":"Tôi không tìm được vị trí cụ thể của cửa hàng này."}]},{"hanzi":"价格","pinyin":"jiàgé","pos":"dt.","vn":"giá cả","examples":[{"cn":"这家店的价格挺合理的。","pinyin":"Zhè jiā diàn de jiàgé tǐng hélǐ de.","vn":"Giá cả của cửa hàng này khá hợp lý."},{"cn":"最近水果的价格涨了不少。","pinyin":"Zuìjìn shuǐguǒ de jiàgé zhǎng le bùshǎo.","vn":"Dạo gần đây giá hoa quả đã tăng khá nhiều."},{"cn":"你可以比较一下不同商店的价格。","pinyin":"Nǐ kěyǐ bǐjiào yíxià bùtóng shāngdiàn de jiàgé.","vn":"Bạn có thể so sánh giá cả của các cửa hàng khác nhau."}]},{"hanzi":"理想","pinyin":"lǐxiǎng","pos":"tt./dt.","vn":"lý tưởng","examples":[{"cn":"这个结果不太理想。","pinyin":"Zhège jiéguǒ bú tài lǐxiǎng.","vn":"Kết quả này không mấy lý tưởng."},{"cn":"这套房子的位置非常理想。","pinyin":"Zhè tào fángzi de wèizhì fēicháng lǐxiǎng.","vn":"Vị trí của căn nhà này rất lý tưởng."},{"cn":"每个人都有自己的理想。","pinyin":"Měi ge rén dōu yǒu zìjǐ de lǐxiǎng.","vn":"Mỗi người đều có lý tưởng của riêng mình."}]},{"hanzi":"由于","pinyin":"yóuyú","pos":"liên./giới.","vn":"do, bởi vì","examples":[{"cn":"由于下大雨，比赛取消了。","pinyin":"Yóuyú xià dàyǔ, bǐsài qǔxiāo le.","vn":"Do trời mưa to nên trận đấu đã bị hủy."},{"cn":"由于身体不舒服，他请假了。","pinyin":"Yóuyú shēntǐ bù shūfu, tā qǐngjià le.","vn":"Do cảm thấy không khỏe nên anh ấy đã xin nghỉ."},{"cn":"由于工作太忙，他很久没回家了。","pinyin":"Yóuyú gōngzuò tài máng, tā hěn jiǔ méi huíjiā le.","vn":"Do công việc quá bận nên anh ấy đã lâu không về nhà."}]},{"hanzi":"工资","pinyin":"gōngzī","pos":"dt.","vn":"tiền lương","examples":[{"cn":"他这个月的工资还没发。","pinyin":"Tā zhège yuè de gōngzī hái méi fā.","vn":"Lương tháng này của anh ấy vẫn chưa được phát."},{"cn":"这份工作工资不高，但是很稳定。","pinyin":"Zhè fèn gōngzuò gōngzī bù gāo, dànshì hěn wěndìng.","vn":"Công việc này lương không cao nhưng rất ổn định."},{"cn":"公司每个月十号发工资。","pinyin":"Gōngsī měi ge yuè shí hào fā gōngzī.","vn":"Công ty trả lương vào ngày mười hằng tháng."}]},{"hanzi":"感","pinyin":"gǎn","pos":"htố.","vn":"(hậu tố chỉ cảm giác) cảm","examples":[{"cn":"他对这份工作很有成就感。","pinyin":"Tā duì zhè fèn gōngzuò hěn yǒu chéngjiùgǎn.","vn":"Anh ấy có cảm giác thành tựu rất lớn với công việc này."},{"cn":"这件事让我很有安全感。","pinyin":"Zhè jiàn shì ràng wǒ hěn yǒu ānquángǎn.","vn":"Việc này khiến tôi cảm thấy rất an toàn."},{"cn":"住在这里让人有一种归属感。","pinyin":"Zhù zài zhèlǐ ràng rén yǒu yì zhǒng guīshǔgǎn.","vn":"Sống ở đây khiến người ta có cảm giác thuộc về."}]}],"grammar":[{"title":"固定格式\"×就是了\"","explanation_vn":"Cấu trúc cố định \"×就是了\" được dùng trong khẩu ngữ, đặt ở cuối câu để biểu thị ý khẳng định.","examples":[{"cn":"如果决定租了，告诉我就是了。","pinyin":"","vn":"Nếu quyết định thuê rồi thì báo cho tôi là được."},{"cn":"我一定能办到，您放心就是了。","pinyin":"","vn":"Tôi chắc chắn làm được, ông/bà cứ yên tâm."},{"cn":"这次考得不好没关系，下次努力就是了。","pinyin":"","vn":"Lần này thi không tốt cũng không sao, lần sau cố gắng là được."}]},{"title":"转折复句\"……，不过……\"","explanation_vn":"Liên từ \"不过\" được dùng ở đầu vế câu thứ hai trong hai vế câu, biểu thị ý chuyển ngoặt.","examples":[{"cn":"这个小区的环境真不错，不过我听说，附近有十几家公司，很多刚毕业的学生都租住在这里。","pinyin":"","vn":"Môi trường khu dân cư này thật sự không tệ, nhưng tôi nghe nói gần đó có hơn chục công ty, rất nhiều sinh viên mới tốt nghiệp đều thuê nhà ở đây."},{"cn":"我们在动物园看见了很多动物，不过没看见大熊猫。","pinyin":"","vn":"Chúng tôi đã nhìn thấy rất nhiều động vật ở sở thú, nhưng không nhìn thấy gấu trúc."},{"cn":"我刚来北京时还不太习惯这里的天气，不过很快就适应了。","pinyin":"","vn":"Khi mới đến Bắc Kinh tôi vẫn chưa quen lắm với thời tiết ở đây, nhưng rất nhanh đã thích nghi được."}]},{"title":"连词/副词\"并\"","explanation_vn":"\"并\" có nhiều cách dùng. Phần này giới thiệu hai cách dùng của \"并\" là liên từ và phó từ: (1) \"并\" làm liên từ, nối các động từ song âm tiết, cụm từ hoặc vế câu song song, biểu thị quan hệ song song, mang ý nghĩa tiến thêm một bước; (2) \"并\" làm phó từ, đặt trước từ phủ định để nhấn mạnh ngữ khí phủ định, nói rõ sự thật không phải như vậy.","examples":[{"cn":"房东又向我介绍了一下房子里的东西，并告诉我这些东西怎么用。","pinyin":"","vn":"Chủ nhà lại giới thiệu cho tôi một lượt về đồ đạc trong nhà, đồng thời cho tôi biết cách sử dụng những thứ đó."},{"cn":"她考上了北京大学并申请到了奖学金。","pinyin":"","vn":"Cô ấy thi đỗ vào Đại học Bắc Kinh và xin được học bổng."},{"cn":"我并没有答应你就租这个房子，我还要再想想。","pinyin":"","vn":"Tôi hoàn toàn chưa đồng ý thuê căn nhà này, tôi còn phải suy nghĩ thêm."}]},{"title":"连词/介词\"由于\"","explanation_vn":"\"由于\" có hai cách dùng: (1) làm liên từ, đặt ở đầu vế câu trước trong câu phức để biểu thị nguyên nhân, vế câu sau thường có các từ như \"所以\", \"因此\"; (2) làm giới từ, biểu thị nguyên nhân hoặc lý do.","examples":[{"cn":"在中国，由于很多刚工作的年轻人工资还不太高，所以他们一开始也不买房，都选择租房。","pinyin":"","vn":"Ở Trung Quốc, do rất nhiều bạn trẻ mới đi làm có mức lương chưa cao lắm, nên ban đầu họ cũng không mua nhà, đều chọn thuê nhà."},{"cn":"由于一直下大雨，所以我们决定不爬山了。","pinyin":"","vn":"Do trời mưa to liên tục, nên chúng tôi quyết định không leo núi nữa."},{"cn":"由于大家的努力，这次运动会我们班获得了第一名。","pinyin":"","vn":"Nhờ sự nỗ lực của mọi người, trong hội thao lần này lớp chúng tôi đã giành giải nhất."}]}],"texts":[{"label":"Bài khóa 1","type":"dialogue","lines":[{"speaker":"房东","cn":"请进！我给你们介绍一下，这个房子有两个房间，那个大房间出租，房租每月5500元。现在已经收拾好了，想租的话，今天就可以搬进来。","pinyin":""},{"speaker":"白家月","cn":"嗯，这个房间真不小，还挺亮。小区离我们学校也不远。","pinyin":""},{"speaker":"房东","cn":"是的，我们小区离地铁站也很近，生活上很方便。如果决定租了，告诉我就是了。","pinyin":""},{"speaker":"白家月","cn":"好的，我们再去看看外边的环境。","pinyin":""}],"translation_vn":"Chủ nhà: Mời vào! Để tôi giới thiệu cho các em, căn nhà này có hai phòng, phòng lớn kia cho thuê, tiền thuê mỗi tháng 5500 tệ. Hiện tại đã dọn dẹp xong rồi, nếu muốn thuê thì hôm nay có thể dọn vào ở luôn.\nBạch Gia Nguyệt: Dạ, phòng này thật sự không nhỏ, lại khá sáng sủa. Khu này cũng không xa trường của chúng em.\nChủ nhà: Đúng vậy, khu chúng tôi cũng gần ga tàu điện ngầm, sinh hoạt rất tiện lợi. Nếu quyết định thuê thì cứ báo cho tôi là được.\nBạch Gia Nguyệt: Vâng ạ, chúng em đi xem thêm môi trường bên ngoài nữa.","audio_dialogue":"2-1.mp3","audio_vocab":"2-2.mp3"},{"label":"Bài khóa 2","type":"dialogue","lines":[{"speaker":"李文","cn":"家月，你看，那边还有个小花园。","pinyin":""},{"speaker":"白家月","cn":"嗯，这个小区到处是花，还种了不少树，周围也很安静。","pinyin":""},{"speaker":"李文","cn":"是啊！这个小区的环境真不错，不过我听说，附近有十几家公司，很多刚毕业的学生都租住在这里。周末他们可能会玩到很晚，恐怕会影响你休息。","pinyin":""},{"speaker":"白家月","cn":"没关系，我还想多认识一些朋友，和他们一起玩呢。","pinyin":""},{"speaker":"李文","cn":"是呢，大家可以一起热闹热闹。","pinyin":""},{"speaker":"白家月","cn":"这里房租合适，环境很好，而且房东也热情，所以我决定租这个房子了，明天就入住新家。","pinyin":""}],"translation_vn":"Lý Văn: Gia Nguyệt, cậu xem, bên kia còn có một vườn hoa nhỏ nữa.\nBạch Gia Nguyệt: Ừ, khu này chỗ nào cũng có hoa, còn trồng khá nhiều cây, xung quanh cũng rất yên tĩnh.\nLý Văn: Đúng vậy! Môi trường khu này thật sự không tệ, nhưng mình nghe nói gần đây có hơn chục công ty, rất nhiều sinh viên mới tốt nghiệp đều thuê nhà ở đây. Cuối tuần họ có thể chơi đến khuya, e rằng sẽ ảnh hưởng đến việc nghỉ ngơi của cậu.\nBạch Gia Nguyệt: Không sao, mình còn muốn quen thêm vài người bạn, chơi cùng họ nữa.\nLý Văn: Đúng vậy, mọi người có thể cùng nhau vui vẻ náo nhiệt.\nBạch Gia Nguyệt: Ở đây tiền thuê hợp lý, môi trường tốt, hơn nữa chủ nhà cũng nhiệt tình, nên mình quyết định thuê căn nhà này rồi, ngày mai sẽ dọn vào nhà mới.","audio_dialogue":"2-3.mp3","audio_vocab":"2-4.mp3"},{"label":"Bài khóa 3","type":"passage","lines":[{"speaker":"","cn":"8月25日，晴\n昨天我顺利租到了合适的房子，今天李文帮我搬家。搬进去的时候，房东又向我介绍了一下房子里的东西，并告诉我这些东西怎么用。\n我看了一下，客厅里有椅子、沙发，还有一台大电视；厨房里有冰箱和一些做饭用的东西，不过，我平常主要在学校食堂吃，基本上不做饭。我租的房间里，除了一张床以外，还有一台空调、一张书桌和一把椅子。\n看完整个房子后，我准备再去买几条毛巾，其他东西还不需要。","pinyin":""}],"translation_vn":"Ngày 25 tháng 8, trời nắng\nHôm qua mình đã thuận lợi thuê được căn nhà ưng ý, hôm nay Lý Văn giúp mình chuyển nhà. Lúc dọn vào, chủ nhà lại giới thiệu cho mình một lượt về đồ đạc trong nhà, đồng thời cho mình biết cách sử dụng những thứ đó.\nMình xem qua một lượt, phòng khách có ghế, sofa, còn có một chiếc ti vi lớn; nhà bếp có tủ lạnh và một số đồ dùng để nấu ăn, nhưng mình thường chủ yếu ăn ở nhà ăn trường, về cơ bản không nấu ăn. Phòng mình thuê, ngoài một chiếc giường ra, còn có một chiếc điều hòa, một chiếc bàn học và một chiếc ghế.\nSau khi xem xong cả căn nhà, mình định đi mua thêm vài chiếc khăn mặt nữa, những thứ khác thì chưa cần.","audio_dialogue":"2-5.mp3","audio_vocab":"2-6.mp3"},{"label":"Bài khóa 4","type":"passage","lines":[{"speaker":"","cn":"在李文的帮助下，白家月租到了合适的房子。对白家月来说，这次租房并不容易。根据李文的建议，她先在租房网站和App上查看有关信息，查找合适的房子，接着又去看了看房子，同时了解房子周围的环境。她看了好几个房子，才找到一个位置、环境和价格都合适的，最后顺利租到了理想的房子。\n租房的时候，李文告诉白家月，在中国，由于很多刚工作的年轻人工资还不太高，所以他们一开始也不买房，都选择租房。工作几年后，不少人就会买房，因为大家一直觉得，有房才有家，有自己的房子会更有安全感。","pinyin":""}],"translation_vn":"Với sự giúp đỡ của Lý Văn, Bạch Gia Nguyệt đã thuê được căn nhà ưng ý. Đối với Bạch Gia Nguyệt mà nói, lần thuê nhà này không hề dễ dàng. Theo gợi ý của Lý Văn, trước tiên cô xem thông tin liên quan trên các trang web và ứng dụng cho thuê nhà, tìm kiếm căn nhà phù hợp, sau đó lại đi xem nhà, đồng thời tìm hiểu môi trường xung quanh căn nhà. Cô đã xem qua mấy căn nhà mới tìm được một căn có vị trí, môi trường và giá cả đều phù hợp, cuối cùng thuận lợi thuê được căn nhà lý tưởng.\nLúc thuê nhà, Lý Văn nói với Bạch Gia Nguyệt rằng ở Trung Quốc, do rất nhiều bạn trẻ mới đi làm có mức lương chưa cao lắm, nên ban đầu họ cũng không mua nhà, đều chọn thuê nhà. Sau khi đi làm vài năm, không ít người sẽ mua nhà, vì mọi người đều cho rằng có nhà mới có tổ ấm, có nhà riêng sẽ cảm thấy an toàn hơn.","audio_dialogue":"2-7.mp3","audio_vocab":"2-8.mp3"}]},{"id":3,"title_cn":"手机扫一下","title_pinyin":"","title_vn":"Quét điện thoại một chút","goals":["Có thể nghe hiểu và trao đổi về các chủ đề như tải ứng dụng, mua sắm trực tuyến, thanh toán bằng điện thoại.","Có thể diễn đạt bằng lời nói hoặc chữ viết các công dụng khác nhau của điện thoại di động.","Hiểu được các cách bảo vệ thông tin cá nhân trong thời đại mạng internet."],"vocab":[{"hanzi":"十字路口","pinyin":"shízì lùkǒu","pos":"","vn":"ngã tư","examples":[{"cn":"前面的十字路口往左转就到了。","pinyin":"qián miàn de shí zì lù kǒu wǎng zuǒ zhuǎn jiù dào le 。","vn":"Ngã tư phía trước rẽ trái là tới."},{"cn":"他在十字路口等红绿灯。","pinyin":"tā zài shí zì lù kǒu děng hóng lǜ dēng 。","vn":"Anh ấy đứng ở ngã tư đợi đèn giao thông."},{"cn":"这个十字路口车特别多，过马路要小心。","pinyin":"zhè ge shí zì lù kǒu chē tè bié duō ， guò mǎ lù yào xiǎo xīn 。","vn":"Ngã tư này nhiều xe lắm, qua đường phải cẩn thận."}]},{"hanzi":"直接","pinyin":"zhíjiē","pos":"tt.","vn":"trực tiếp","examples":[{"cn":"你有什么问题可以直接问我。","pinyin":"nǐ yǒu shén me wèn tí kě yǐ zhí jiē wèn wǒ 。","vn":"Có vấn đề gì bạn cứ hỏi trực tiếp tôi."},{"cn":"这趟火车直接到北京，不用换车。","pinyin":"zhè tàng huǒ chē zhí jiē dào běi jīng ， bù yòng huàn chē 。","vn":"Chuyến tàu này đi thẳng đến Bắc Kinh, không cần đổi tàu."},{"cn":"他做事很直接，从不拐弯抹角。","pinyin":"tā zuò shì hěn zhí jiē ， cóng bù guǎi wān mò jiǎo 。","vn":"Anh ấy làm việc rất thẳng thắn, chẳng bao giờ vòng vo."}]},{"hanzi":"转","pinyin":"zhuǎn","pos":"dgt.","vn":"rẽ, quay, chuyển","examples":[{"cn":"前面路口往右转就是超市。","pinyin":"qián miàn lù kǒu wǎng yòu zhuǎn jiù shì chāo shì 。","vn":"Phía trước rẽ phải là tới siêu thị."},{"cn":"这件事我得转告一下我的同事。","pinyin":"zhè jiàn shì wǒ dé zhuǎn gào yī xià wǒ de tóng shì 。","vn":"Việc này tôi phải chuyển lời lại cho đồng nghiệp."},{"cn":"他转过身，笑着跟我打招呼。","pinyin":"tā zhuǎn guò shēn ， xiào zhe gēn wǒ dǎ zhāo hū 。","vn":"Anh ấy quay người lại, cười chào tôi."}]},{"hanzi":"正好","pinyin":"zhènghǎo","pos":"phó./tt.","vn":"đúng lúc, vừa khéo, vừa vặn","examples":[{"cn":"我正准备出门，你正好打电话来了。","pinyin":"wǒ zhèng zhǔn bèi chū mén ， nǐ zhèng hǎo dǎ diàn huà lái le 。","vn":"Tôi vừa định ra ngoài thì đúng lúc bạn gọi điện tới."},{"cn":"这件衣服的大小正好合适。","pinyin":"zhè jiàn yī fú de dà xiǎo zhèng hǎo hé shì 。","vn":"Cỡ áo này vừa khéo vừa vặn."},{"cn":"我正好有事要找你，就过来了。","pinyin":"wǒ zhèng hǎo yǒu shì yào zhǎo nǐ ， jiù guò lái le 。","vn":"Tôi đúng lúc có việc muốn tìm bạn nên ghé qua."}]},{"hanzi":"熟悉","pinyin":"shúxī","pos":"dgt.","vn":"quen thuộc, am hiểu","examples":[{"cn":"我对这座城市很熟悉，可以带你逛逛。","pinyin":"wǒ duì zhè zuò chéng shì hěn shú xī ， kě yǐ dài nǐ guàng guàng 。","vn":"Tôi rất quen thuộc với thành phố này, có thể dẫn bạn đi dạo."},{"cn":"这个声音听起来很熟悉，是谁啊？","pinyin":"zhè ge shēng yīn tīng qǐ lái hěn shú xī ， shì shuí a ？","vn":"Giọng nói này nghe quen quen, là ai vậy nhỉ?"},{"cn":"新来的同事还不熟悉公司的规矩。","pinyin":"xīn lái de tóng shì hái bù shú xī gōng sī de guī jǔ 。","vn":"Đồng nghiệp mới vẫn chưa quen với quy định của công ty."}]},{"hanzi":"正","pinyin":"zhèng","pos":"tt.","vn":"thẳng, ngay ngắn","examples":[{"cn":"把画挂正一点，歪了。","pinyin":"bǎ huà guà zhèng yì diǎn ， wāi le 。","vn":"Treo bức tranh thẳng lại chút, nó bị lệch rồi."},{"cn":"他坐得很正，一点都不驼背。","pinyin":"tā zuò dé hěn zhèng ， yì diǎn dōu bù tuó bèi 。","vn":"Anh ấy ngồi rất ngay ngắn, không hề gù lưng."},{"cn":"字写得又正又好看。","pinyin":"zì xiě dé yòu zhèng yòu hǎo kàn 。","vn":"Chữ viết vừa ngay ngắn vừa đẹp."}]},{"hanzi":"目的地","pinyin":"mùdìdì","pos":"dt.","vn":"điểm đến, đích đến","examples":[{"cn":"我们快到目的地了，再坚持一下。","pinyin":"wǒ men kuài dào mù dì dì le ， zài jiān chí yī xià 。","vn":"Chúng ta sắp đến điểm đến rồi, cố thêm chút nữa."},{"cn":"导航显示离目的地还有十分钟的路程。","pinyin":"dǎo háng xiǎn shì lí mù dì dì hái yǒu shí fēn zhōng de lù chéng 。","vn":"Định vị hiển thị còn mười phút nữa là tới đích."},{"cn":"这次旅行的目的地是云南。","pinyin":"zhè cì lǚ xíng de mù dì dì shì yún nán 。","vn":"Điểm đến của chuyến đi lần này là Vân Nam."}]},{"hanzi":"下载","pinyin":"xiàzài","pos":"dgt.","vn":"tải xuống","examples":[{"cn":"我在手机上下载了一个新软件。","pinyin":"wǒ zài shǒu jī shàng xià zài le yí gè xīn ruǎn jiàn 。","vn":"Tôi đã tải một phần mềm mới về điện thoại."},{"cn":"这个视频下载需要一点时间。","pinyin":"zhè ge shì pín xià zài xū yào yì diǎn shí jiān 。","vn":"Video này tải xuống cần một chút thời gian."},{"cn":"你可以直接从网上下载这个文件。","pinyin":"nǐ kě yǐ zhí jiē cóng wǎng shàng xià zài zhè ge wén jiàn 。","vn":"Bạn có thể tải trực tiếp tệp này từ trên mạng."}]},{"hanzi":"进行","pinyin":"jìnxíng","pos":"dgt.","vn":"tiến hành, thực hiện","examples":[{"cn":"会议正在进行中，请不要打扰。","pinyin":"huì yì zhèng zài jìn xíng zhōng ， qǐng bú yào dǎ rǎo 。","vn":"Cuộc họp đang diễn ra, xin đừng làm phiền."},{"cn":"这项研究已经进行了三年。","pinyin":"zhè xiàng yán jiū yǐ jīng jìn xíng le sān nián 。","vn":"Dự án nghiên cứu này đã tiến hành được ba năm."},{"cn":"比赛将在明天上午进行。","pinyin":"bǐ sài jiāng zài míng tiān shàng wǔ jìn xíng 。","vn":"Trận thi đấu sẽ được tổ chức vào sáng mai."}]},{"hanzi":"支付","pinyin":"zhīfù","pos":"dgt.","vn":"thanh toán, chi trả","examples":[{"cn":"现在很多人都用手机支付。","pinyin":"xiàn zài hěn duō rén dōu yòng shǒu jī zhī fù 。","vn":"Bây giờ rất nhiều người thanh toán bằng điện thoại."},{"cn":"这笔钱可以分期支付。","pinyin":"zhè bǐ qián kě yǐ fēn qī zhī fù 。","vn":"Khoản tiền này có thể trả góp."},{"cn":"他忘了支付这个月的房租。","pinyin":"tā wàng le zhī fù zhè ge yuè de fáng zū 。","vn":"Anh ấy quên thanh toán tiền thuê nhà tháng này."}]},{"hanzi":"软件","pinyin":"ruǎnjiàn","pos":"dt.","vn":"phần mềm","examples":[{"cn":"这个软件用起来特别方便。","pinyin":"zhè ge ruǎn jiàn yòng qǐ lái tè bié fāng biàn 。","vn":"Phần mềm này dùng rất tiện."},{"cn":"他是专门做软件开发的。","pinyin":"tā shì zhuān mén zuò ruǎn jiàn kāi fā de 。","vn":"Anh ấy chuyên làm phát triển phần mềm."},{"cn":"我电脑上的软件需要更新了。","pinyin":"wǒ diàn nǎo shàng de ruǎn jiàn xū yào gēng xīn le 。","vn":"Phần mềm trên máy tính của tôi cần cập nhật rồi."}]},{"hanzi":"不仅","pinyin":"bùjǐn","pos":"liên.","vn":"không những...(mà còn...)","examples":[{"cn":"他不仅会说中文，还会说英语。","pinyin":"tā bù jǐn huì shuō zhōng wén ， hái huì shuō yīng yǔ 。","vn":"Anh ấy không những biết nói tiếng Trung mà còn biết tiếng Anh."},{"cn":"这家店不仅便宜，味道也不错。","pinyin":"zhè jiā diàn bù jǐn pián yi ， wèi dào yě bù cuò 。","vn":"Quán này không những rẻ mà vị cũng ngon."},{"cn":"不仅是我，连他也觉得这很难。","pinyin":"bù jǐn shì wǒ ， lián tā yě jué de zhè hěn nán 。","vn":"Không chỉ tôi, mà ngay cả anh ấy cũng thấy việc này khó."}]},{"hanzi":"扫码","pinyin":"sǎomǎ","pos":"dgt.","vn":"quét mã QR","examples":[{"cn":"进门需要扫码登记一下。","pinyin":"jìn mén xū yào sǎo mǎ dēng jì yī xià 。","vn":"Vào cửa cần quét mã đăng ký."},{"cn":"买单的时候直接扫码就行。","pinyin":"mǎi dān de shí hòu zhí jiē sǎo mǎ jiù xíng 。","vn":"Lúc thanh toán chỉ cần quét mã là xong."},{"cn":"他教妈妈怎么扫码支付。","pinyin":"tā jiào mā mā zěn me sǎo mǎ zhī fù 。","vn":"Anh ấy dạy mẹ cách quét mã thanh toán."}]},{"hanzi":"结账","pinyin":"jiézhàng","pos":"dgt.","vn":"thanh toán, tính tiền","examples":[{"cn":"服务员，麻烦结账。","pinyin":"fú wù yuán ， má fán jié zhàng 。","vn":"Phục vụ ơi, tính tiền giúp tôi."},{"cn":"我们俩AA制，各付各的结账。","pinyin":"wǒ men liǎ AA zhì ， gè fù gè de jié zhàng 。","vn":"Hai chúng tôi chia tiền ai nấy tính."},{"cn":"吃完饭他抢着去结账了。","pinyin":"chī wán fàn tā qiǎng zhe qù jié zhàng le 。","vn":"Ăn xong anh ấy giành thanh toán trước."}]},{"hanzi":"购物","pinyin":"gòuwù","pos":"dgt.","vn":"mua sắm","examples":[{"cn":"周末我喜欢去商场购物。","pinyin":"zhōu mò wǒ xǐ huān qù shāng chǎng gòu wù 。","vn":"Cuối tuần tôi thích đi trung tâm thương mại mua sắm."},{"cn":"现在网上购物特别方便。","pinyin":"xiàn zài wǎng shàng gòu wù tè bié fāng biàn 。","vn":"Bây giờ mua sắm online rất tiện lợi."},{"cn":"双十一购物节很多东西都打折。","pinyin":"shuāng shí yī gòu wù jié hěn duō dōng xī dōu dǎ zhé 。","vn":"Ngày hội mua sắm mùng 11 tháng 11 nhiều thứ giảm giá lắm."}]},{"hanzi":"订","pinyin":"dìng","pos":"dgt.","vn":"đặt (hàng, chỗ)","examples":[{"cn":"我已经订好酒店了。","pinyin":"wǒ yǐ jīng dìng hǎo jiǔ diàn le 。","vn":"Tôi đã đặt khách sạn rồi."},{"cn":"周末的票得提前订。","pinyin":"zhōu mò de piào dé tí qián dìng 。","vn":"Vé cuối tuần phải đặt trước."},{"cn":"他帮我订了一张明天的机票。","pinyin":"tā bāng wǒ dìng le yī zhāng míng tiān de jī piào 。","vn":"Anh ấy đặt giúp tôi vé máy bay ngày mai."}]},{"hanzi":"快递","pinyin":"kuàidì","pos":"dt.","vn":"chuyển phát nhanh","examples":[{"cn":"我的快递今天应该能到。","pinyin":"wǒ de kuài dì jīn tiān yīng gāi néng dào 。","vn":"Hôm nay bưu kiện của tôi chắc sẽ tới."},{"cn":"这个东西寄快递要三天。","pinyin":"zhè ge dōng xī jì kuài dì yào sān tiān 。","vn":"Gửi món này qua chuyển phát nhanh mất ba ngày."},{"cn":"快递员刚才给我送来一个包裹。","pinyin":"kuài dì yuán gāng cái gěi wǒ sòng lái yí gè bāo guǒ 。","vn":"Nhân viên giao hàng vừa đưa cho tôi một gói hàng."}]},{"hanzi":"微信","pinyin":"Wēixìn","pos":"danh từ riêng","vn":"WeChat","examples":[{"cn":"加个微信吧，方便联系。","pinyin":"jiā gè wēi xìn ba ， fāng biàn lián xì 。","vn":"Kết bạn WeChat đi, liên lạc cho tiện."},{"cn":"我每天都用微信跟朋友聊天。","pinyin":"wǒ měi tiān dōu yòng wēi xìn gēn péng yǒu liáo tiān 。","vn":"Ngày nào tôi cũng dùng WeChat chat với bạn bè."},{"cn":"这个消息我在微信群里看到的。","pinyin":"zhè ge xiāo xī wǒ zài wēi xìn qún lǐ kàn dào de 。","vn":"Tin này tôi thấy trong nhóm WeChat."}]},{"hanzi":"支付宝","pinyin":"Zhīfùbǎo","pos":"danh từ riêng","vn":"Alipay","examples":[{"cn":"我习惯用支付宝付钱。","pinyin":"wǒ xí guàn yòng zhī fù bǎo fù qián 。","vn":"Tôi quen dùng Alipay để trả tiền."},{"cn":"支付宝里还有一些优惠券。","pinyin":"zhī fù bǎo lǐ hái yǒu yī xiē yōu huì quàn 。","vn":"Trong Alipay còn có vài phiếu giảm giá."},{"cn":"他用支付宝给我转了钱。","pinyin":"tā yòng zhī fù bǎo gěi wǒ zhuǎn le qián 。","vn":"Anh ấy chuyển tiền cho tôi qua Alipay."}]},{"hanzi":"现金","pinyin":"xiànjīn","pos":"dt.","vn":"tiền mặt","examples":[{"cn":"现在很少有人带现金出门了。","pinyin":"xiàn zài hěn shǎo yǒu rén dài xiàn jīn chū mén le 。","vn":"Bây giờ rất ít người mang tiền mặt ra ngoài."},{"cn":"这家店只收现金，不能刷卡。","pinyin":"zhè jiā diàn zhǐ shōu xiàn jīn ， bù néng shuā kǎ 。","vn":"Cửa hàng này chỉ nhận tiền mặt, không quẹt thẻ được."},{"cn":"身上留点现金比较方便。","pinyin":"shēn shàng liú diǎn xiàn jīn bǐ jiào fāng biàn 。","vn":"Mang theo chút tiền mặt vẫn tiện hơn."}]},{"hanzi":"网购","pinyin":"wǎnggòu","pos":"dgt.","vn":"mua sắm trực tuyến","examples":[{"cn":"我这几年很少逛街，都是网购。","pinyin":"wǒ zhè jǐ nián hěn shǎo guàng jiē ， dōu shì wǎng gòu 。","vn":"Mấy năm nay tôi ít đi dạo phố, toàn mua sắm online."},{"cn":"网购虽然方便，但有时候收到的东西不太满意。","pinyin":"wǎng gòu suī rán fāng biàn ， dàn yǒu shí hòu shōu dào de dōng xī bù tài mǎn yì 。","vn":"Mua online tuy tiện nhưng đôi khi nhận hàng không ưng ý."},{"cn":"她是个网购达人，什么都在网上买。","pinyin":"tā shì gè wǎng gòu dá rén ， shén me dōu zài wǎng shàng mǎi 。","vn":"Cô ấy là tín đồ mua sắm online, cái gì cũng mua trên mạng."}]},{"hanzi":"寄","pinyin":"jì","pos":"dgt.","vn":"gửi","examples":[{"cn":"我给你寄了一份生日礼物。","pinyin":"wǒ gěi nǐ jì le yī fèn shēng rì lǐ wù 。","vn":"Tôi đã gửi cho bạn một món quà sinh nhật."},{"cn":"这封信是从国外寄来的。","pinyin":"zhè fēng xìn shì cóng guó wài jì lái de 。","vn":"Lá thư này được gửi từ nước ngoài về."},{"cn":"麻烦帮我把这个包裹寄到上海。","pinyin":"má fán bāng wǒ bǎ zhè ge bāo guǒ jì dào shàng hǎi 。","vn":"Phiền bạn gửi giúp gói hàng này đến Thượng Hải."}]},{"hanzi":"等","pinyin":"děng","pos":"trợ.","vn":"v.v., vân vân","examples":[{"cn":"水果、蔬菜等都要新鲜的才好吃。","pinyin":"shuǐ guǒ 、 shū cài děng dōu yào xīn xiān de cái hǎo chī 。","vn":"Trái cây, rau củ v.v. đều phải tươi mới ngon."},{"cn":"他带了手机、钱包、钥匙等出门。","pinyin":"tā dài le shǒu jī 、 qián bāo 、 yào shi děng chū mén 。","vn":"Anh ấy mang theo điện thoại, ví tiền, chìa khóa v.v. khi ra ngoài."},{"cn":"这次活动准备了礼物、奖金等奖励。","pinyin":"zhè cì huó dòng zhǔn bèi le lǐ wù 、 jiǎng jīn děng jiǎng lì 。","vn":"Hoạt động lần này chuẩn bị quà, tiền thưởng v.v. để khích lệ."}]},{"hanzi":"货","pinyin":"huò","pos":"dt.","vn":"hàng hóa","examples":[{"cn":"这批货明天就能到。","pinyin":"zhè pī huò míng tiān jiù néng dào 。","vn":"Lô hàng này ngày mai sẽ tới."},{"cn":"老板正在仓库里清点货。","pinyin":"lǎo bǎn zhèng zài cāng kù lǐ qīng diǎn huò 。","vn":"Ông chủ đang kiểm hàng trong kho."},{"cn":"这家店的货挺齐全的。","pinyin":"zhè jiā diàn de huò tǐng qí quán de 。","vn":"Hàng hóa ở cửa tiệm này khá đầy đủ."}]},{"hanzi":"甚至","pinyin":"shènzhì","pos":"liên.","vn":"thậm chí","examples":[{"cn":"他忙得甚至没时间吃饭。","pinyin":"tā máng dé shèn zhì méi shí jiān chī fàn 。","vn":"Anh ấy bận đến mức thậm chí không có thời gian ăn cơm."},{"cn":"这件事甚至连他自己都不知道。","pinyin":"zhè jiàn shì shèn zhì lián tā zì jǐ dōu bù zhī dào 。","vn":"Việc này thậm chí chính anh ấy cũng không biết."},{"cn":"天气太热了，甚至晚上也睡不着。","pinyin":"tiān qì tài rè le ， shèn zhì wǎn shàng yě shuì bù zhe 。","vn":"Trời nóng quá, thậm chí ban đêm cũng không ngủ được."}]},{"hanzi":"改变","pinyin":"gǎibiàn","pos":"dgt.","vn":"thay đổi","examples":[{"cn":"这件事改变了我对他的看法。","pinyin":"zhè jiàn shì gǎi biàn le wǒ duì tā de kàn fǎ 。","vn":"Việc này đã thay đổi cách nhìn của tôi về anh ấy."},{"cn":"他决定改变自己的生活方式。","pinyin":"tā jué dìng gǎi biàn zì jǐ de shēng huó fāng shì 。","vn":"Anh ấy quyết định thay đổi lối sống của mình."},{"cn":"时代在改变，我们也要跟上。","pinyin":"shí dài zài gǎi biàn ， wǒ men yě yào gēn shàng 。","vn":"Thời đại đang thay đổi, chúng ta cũng phải bắt kịp."}]},{"hanzi":"手指","pinyin":"shǒuzhǐ","pos":"dt.","vn":"ngón tay","examples":[{"cn":"他的手指被刀割破了。","pinyin":"tā de shǒu zhǐ bèi dāo gē pò le 。","vn":"Ngón tay anh ấy bị dao cắt đứt."},{"cn":"她用手指指了指那个方向。","pinyin":"tā yòng shǒu zhǐ zhǐ le zhǐ nà ge fāng xiàng 。","vn":"Cô ấy dùng ngón tay chỉ về hướng đó."},{"cn":"弹钢琴需要灵活的手指。","pinyin":"tán gāng qín xū yào líng huó de shǒu zhǐ 。","vn":"Chơi piano cần có những ngón tay linh hoạt."}]},{"hanzi":"乱","pinyin":"luàn","pos":"phó./tt.","vn":"bừa bãi, lộn xộn","examples":[{"cn":"房间太乱了，收拾一下吧。","pinyin":"fáng jiān tài luàn le ， shōu shí yī xià ba 。","vn":"Phòng bừa bộn quá, dọn dẹp đi chứ."},{"cn":"别把东西乱扔。","pinyin":"bié bǎ dōng xī luàn rēng 。","vn":"Đừng vứt đồ bừa bãi."},{"cn":"他一着急，说话就乱了。","pinyin":"tā yī zháo jí ， shuō huà jiù luàn le 。","vn":"Anh ấy vừa vội là nói năng lộn xộn liền."}]},{"hanzi":"管","pinyin":"guǎn","pos":"dgt.","vn":"quản lý, kiểm soát","examples":[{"cn":"这件事由他来管。","pinyin":"zhè jiàn shì yóu tā lái guǎn 。","vn":"Việc này để anh ấy quản lý."},{"cn":"父母管孩子也要讲究方法。","pinyin":"fù mǔ guǎn hái zi yě yào jiǎng jiū fāng fǎ 。","vn":"Cha mẹ quản con cái cũng phải có phương pháp."},{"cn":"这事儿不归我管。","pinyin":"zhè shì ér bù guī wǒ guǎn 。","vn":"Việc này không thuộc trách nhiệm của tôi."}]},{"hanzi":"提供","pinyin":"tígōng","pos":"dgt.","vn":"cung cấp","examples":[{"cn":"公司给员工提供免费午餐。","pinyin":"gōng sī gěi yuán gōng tí gōng miǎn fèi wǔ cān 。","vn":"Công ty cung cấp bữa trưa miễn phí cho nhân viên."},{"cn":"能不能提供一些具体的建议？","pinyin":"néng bù néng tí gōng yī xiē jù tǐ de jiàn yì ？","vn":"Bạn có thể đưa ra vài gợi ý cụ thể không?"},{"cn":"这家酒店提供免费的早餐。","pinyin":"zhè jiā jiǔ diàn tí gōng miǎn fèi de zǎo cān 。","vn":"Khách sạn này cung cấp bữa sáng miễn phí."}]},{"hanzi":"身份证","pinyin":"shēnfènzhèng","pos":"dt.","vn":"chứng minh thư, thẻ căn cước","examples":[{"cn":"办卡需要带身份证。","pinyin":"bàn kǎ xū yào dài shēn fèn zhèng 。","vn":"Làm thẻ cần mang theo chứng minh thư."},{"cn":"我把身份证弄丢了，得去补办。","pinyin":"wǒ bǎ shēn fèn zhèng nòng diū le ， dé qù bǔ bàn 。","vn":"Tôi làm mất chứng minh thư rồi, phải đi làm lại."},{"cn":"住酒店要出示身份证。","pinyin":"zhù jiǔ diàn yào chū shì shēn fèn zhèng 。","vn":"Ở khách sạn phải xuất trình chứng minh thư."}]},{"hanzi":"个人","pinyin":"gèrén","pos":"dt.","vn":"cá nhân","examples":[{"cn":"这只是我个人的看法。","pinyin":"zhè zhǐ shì wǒ gè rén de kàn fǎ 。","vn":"Đây chỉ là ý kiến cá nhân của tôi."},{"cn":"请不要透露客户的个人信息。","pinyin":"qǐng bú yào tòu lù kè hù de gè rén xìn xī 。","vn":"Xin đừng tiết lộ thông tin cá nhân của khách hàng."},{"cn":"这是个人问题，跟公司没关系。","pinyin":"zhè shì gè rén wèn tí ， gēn gōng sī méi guān xì 。","vn":"Đây là chuyện cá nhân, không liên quan đến công ty."}]},{"hanzi":"能否","pinyin":"néngfǒu","pos":"dgt.","vn":"có thể hay không","examples":[{"cn":"我想问问能否提前拿到工资。","pinyin":"wǒ xiǎng wèn wèn néng fǒu tí qián ná dào gōng zī 。","vn":"Tôi muốn hỏi xem có thể nhận lương sớm hay không."},{"cn":"能否成功，还要看他的努力。","pinyin":"néng fǒu chéng gōng ， hái yào kàn tā de nǔ lì 。","vn":"Có thành công hay không còn phải xem sự cố gắng của anh ấy."},{"cn":"这件事能否解决，就看明天的会议了。","pinyin":"zhè jiàn shì néng fǒu jiě jué ， jiù kàn míng tiān de huì yì le 。","vn":"Việc này có giải quyết được hay không còn tùy vào cuộc họp ngày mai."}]},{"hanzi":"保护","pinyin":"bǎohù","pos":"dgt.","vn":"bảo vệ","examples":[{"cn":"我们应该保护环境。","pinyin":"wǒ men yīng gāi bǎo hù huán jìng 。","vn":"Chúng ta nên bảo vệ môi trường."},{"cn":"他一直在保护自己的隐私。","pinyin":"tā yì zhí zài bǎo hù zì jǐ de yǐn sī 。","vn":"Anh ấy luôn bảo vệ sự riêng tư của mình."},{"cn":"父母总是想保护孩子。","pinyin":"fù mǔ zǒng shì xiǎng bǎo hù hái zi 。","vn":"Cha mẹ luôn muốn bảo vệ con cái."}]},{"hanzi":"于是","pinyin":"yúshì","pos":"liên.","vn":"thế là, vì vậy","examples":[{"cn":"他说得有道理，于是我就同意了。","pinyin":"tā shuō dé yǒu dào lǐ ， yú shì wǒ jiù tóng yì le 。","vn":"Anh ấy nói có lý, thế là tôi đồng ý."},{"cn":"天下雨了，于是我们取消了计划。","pinyin":"tiān xià yǔ le ， yú shì wǒ men qǔ xiāo le jì huà 。","vn":"Trời mưa nên chúng tôi đã hủy kế hoạch."},{"cn":"她很困，于是早早地睡了。","pinyin":"tā hěn kùn ， yú shì zǎo zǎo dì shuì le 。","vn":"Cô ấy buồn ngủ nên đi ngủ sớm."}]},{"hanzi":"密码","pinyin":"mìmǎ","pos":"dt.","vn":"mật khẩu","examples":[{"cn":"我忘记了手机的密码。","pinyin":"wǒ wàng jì le shǒu jī de mì mǎ 。","vn":"Tôi quên mật khẩu điện thoại rồi."},{"cn":"请设置一个安全的密码。","pinyin":"qǐng shè zhì yí gè ān quán de mì mǎ 。","vn":"Hãy đặt một mật khẩu an toàn."},{"cn":"他的密码被别人偷偷看到了。","pinyin":"tā de mì mǎ bèi bié rén tōu tōu kàn dào le 。","vn":"Mật khẩu của anh ấy đã bị người khác lén xem thấy."}]},{"hanzi":"随便","pinyin":"suíbiàn","pos":"tt./dgt./liên.","vn":"tùy tiện, tùy ý","examples":[{"cn":"你随便坐，别客气。","pinyin":"nǐ suí biàn zuò ， bié kè qì 。","vn":"Bạn cứ ngồi tự nhiên, đừng khách sáo."},{"cn":"这事不能随便答应别人。","pinyin":"zhè shì bù néng suí biàn dā yìng bié rén 。","vn":"Việc này không thể tùy tiện hứa với người khác."},{"cn":"晚饭随便吃点就行。","pinyin":"wǎn fàn suí biàn chī diǎn jiù xíng 。","vn":"Bữa tối ăn tạm gì đó cũng được."}]},{"hanzi":"技术","pinyin":"jìshù","pos":"dt.","vn":"kỹ thuật, công nghệ","examples":[{"cn":"这家公司的技术很先进。","pinyin":"zhè jiā gōng sī de jì shù hěn xiān jìn 。","vn":"Công nghệ của công ty này rất tiên tiến."},{"cn":"他掌握了一门很有用的技术。","pinyin":"tā zhǎng wò le yī mén hěn yǒu yòng de jì shù 。","vn":"Anh ấy đã nắm vững một kỹ thuật rất hữu ích."},{"cn":"现在的技术发展得真快。","pinyin":"xiàn zài de jì shù fā zhǎn dé zhēn kuài 。","vn":"Công nghệ bây giờ phát triển nhanh thật."}]},{"hanzi":"法律","pinyin":"fǎlǜ","pos":"dt.","vn":"pháp luật","examples":[{"cn":"每个人都应该遵守法律。","pinyin":"měi gè rén dōu yīng gāi zūn shǒu fǎ lǜ 。","vn":"Mỗi người đều nên tuân thủ pháp luật."},{"cn":"这件事要用法律来解决。","pinyin":"zhè jiàn shì yào yòng fǎ lǜ lái jiě jué 。","vn":"Việc này phải dùng pháp luật để giải quyết."},{"cn":"他学的是法律专业。","pinyin":"tā xué de shì fǎ lǜ zhuān yè 。","vn":"Anh ấy học chuyên ngành luật."}]},{"hanzi":"手段","pinyin":"shǒuduàn","pos":"dt.","vn":"biện pháp, thủ đoạn","examples":[{"cn":"他用了一些不正当的手段。","pinyin":"tā yòng le yī xiē bù zhèng dāng de shǒu duàn 。","vn":"Anh ta đã dùng vài thủ đoạn không chính đáng."},{"cn":"为了达到目的，他不择手段。","pinyin":"wèi le dá dào mù dì ， tā bù zé shǒu duàn 。","vn":"Để đạt được mục đích, anh ta không từ thủ đoạn nào."},{"cn":"这只是暂时的手段，不是长久之计。","pinyin":"zhè zhǐ shì zàn shí de shǒu duàn ， bú shì cháng jiǔ zhī jì 。","vn":"Đây chỉ là biện pháp tạm thời, không phải kế lâu dài."}]},{"hanzi":"保证","pinyin":"bǎozhèng","pos":"dgt./dt.","vn":"đảm bảo, cam đoan","examples":[{"cn":"我保证以后不会再迟到了。","pinyin":"wǒ bǎo zhèng yǐ hòu bú huì zài chí dào le 。","vn":"Tôi đảm bảo sau này sẽ không đi muộn nữa."},{"cn":"质量是我们最大的保证。","pinyin":"zhì liàng shì wǒ men zuì dà de bǎo zhèng 。","vn":"Chất lượng là bảo đảm lớn nhất của chúng tôi."},{"cn":"他向我保证会按时完成任务。","pinyin":"tā xiàng wǒ bǎo zhèng huì àn shí wán chéng rèn wù 。","vn":"Anh ấy cam đoan với tôi sẽ hoàn thành nhiệm vụ đúng hạn."}]},{"hanzi":"网络","pinyin":"wǎngluò","pos":"dt.","vn":"mạng, internet","examples":[{"cn":"这里的网络信号不太好。","pinyin":"zhè lǐ de wǎng luò xìn hào bù tài hǎo 。","vn":"Sóng mạng ở đây không tốt lắm."},{"cn":"他是靠网络赚钱的。","pinyin":"tā shì kào wǎng luò zhuàn qián de 。","vn":"Anh ấy kiếm tiền nhờ internet."},{"cn":"现在网络购物真方便。","pinyin":"xiàn zài wǎng luò gòu wù zhēn fāng biàn 。","vn":"Bây giờ mua sắm qua mạng thật tiện lợi."}]}],"grammar":[{"title":"转折复句\"……X是X，就是/不过……\"","explanation_vn":"Trong câu phức này, \"X是X\" là cấu trúc cố định, biểu thị sự khẳng định một tình huống hay thuộc tính nào đó, phía sau dùng các từ như \"就是\", \"不过\" để biểu thị ý chuyển ngoặt hoặc bổ sung thêm, chỉ ra rằng nội dung ở vế trước có giới hạn nhất định.","examples":[{"cn":"北京大是大，不过这边的路基本上都是正南正北、正东正西的，很好找。","pinyin":"","vn":"Bắc Kinh rộng thì rộng thật, nhưng đường ở khu này cơ bản đều là chính nam chính bắc, chính đông chính tây, rất dễ tìm."},{"cn":"这个房子便宜是便宜，就是离我的公司太远了。","pinyin":"","vn":"Căn nhà này rẻ thì rẻ thật, chỉ có điều là cách công ty tôi quá xa."},{"cn":"我们想是想了，就是没想出更好的办法。","pinyin":"","vn":"Chúng tôi nghĩ thì có nghĩ rồi, chỉ là chưa nghĩ ra cách nào tốt hơn."}]},{"title":"递进复句\"不仅/不光……，还/而且……\"","explanation_vn":"\"不仅/不光(không những)……，还/而且(mà còn)……\" biểu thị quan hệ tăng tiến. Vế sau là sự mở rộng hoặc bổ sung cho vế trước, biểu thị ý nghĩa tiến thêm một bước. Bài này học dạng câu phức có chung một chủ ngữ, cấu trúc là: Chủ ngữ + 不仅/不光……，还/而且……","examples":[{"cn":"现在我不仅会扫码结账，还会用手机在网上购物了。","pinyin":"","vn":"Bây giờ tôi không những biết quét mã thanh toán, mà còn biết dùng điện thoại mua sắm trực tuyến nữa."},{"cn":"王老师不光教我们说中文，而且带我们了解中国文化。","pinyin":"","vn":"Cô Vương không những dạy chúng tôi nói tiếng Trung, mà còn dẫn chúng tôi tìm hiểu văn hóa Trung Quốc."},{"cn":"现在很多书店不仅卖书，还卖咖啡和奶茶。","pinyin":"","vn":"Hiện nay nhiều hiệu sách không những bán sách, mà còn bán cà phê và trà sữa."}]},{"title":"连词\"甚至\"","explanation_vn":"Liên từ \"甚至\" nhấn mạnh một tình huống nào đó nổi bật hơn, vượt ra ngoài dự đoán thông thường.","examples":[{"cn":"在中国网购，不仅选择多、价格不高，而且送货很快，很多留学生甚至改变了自己的购物习惯。","pinyin":"","vn":"Mua sắm trực tuyến ở Trung Quốc không những có nhiều lựa chọn, giá cả không cao, mà việc giao hàng còn rất nhanh, rất nhiều du học sinh thậm chí đã thay đổi thói quen mua sắm của mình."},{"cn":"高铁速度真快，甚至还没看清楚，它就已经开过去了。","pinyin":"","vn":"Tàu cao tốc nhanh thật, thậm chí còn chưa kịp nhìn rõ thì nó đã chạy qua mất rồi."},{"cn":"这个小区真不错，有小花园、球场，甚至还有一个超市。","pinyin":"","vn":"Khu dân cư này thật tốt, có vườn hoa nhỏ, sân bóng, thậm chí còn có cả một siêu thị."}]},{"title":"承接复句\"……，于是……\"","explanation_vn":"Hai vế câu mô tả theo thứ tự các hành động hoặc sự việc liên tiếp, \"于是\" được dùng ở đầu vế sau. Giữa hai vế có quan hệ trước sau, về mặt logic có quan hệ nối tiếp.","examples":[{"cn":"在提供这些信息时，我们也会担心：我的个人信息能否得到保护？于是，有人在网上说出了自己的担心。","pinyin":"","vn":"Khi cung cấp những thông tin này, chúng ta cũng sẽ lo lắng: liệu thông tin cá nhân của mình có được bảo vệ hay không? Thế là, có người đã nói ra nỗi lo của mình trên mạng."},{"cn":"她从小就想当医生，于是上大学时就选择了学医。","pinyin":"","vn":"Từ nhỏ cô ấy đã muốn làm bác sĩ, vì vậy khi lên đại học đã chọn học ngành y."},{"cn":"最近总感冒，于是他决定病好后就开始锻炼身体。","pinyin":"","vn":"Gần đây cứ bị cảm hoài, thế là anh ấy quyết định sau khi khỏi bệnh sẽ bắt đầu tập luyện thể thao."}]}],"texts":[{"label":"Bài khóa 1","type":"dialogue","lines":[{"speaker":"陈天中","cn":"请问，花园小区怎么走？","pinyin":""},{"speaker":"同学","cn":"你往前走，到十字路口不要过马路，直接右转就到小区门口了。正好我也去那边，一起走吧。","pinyin":""},{"speaker":"陈天中","cn":"好的。我刚来中国，不熟悉路。北京真是太大了。","pinyin":""},{"speaker":"同学","cn":"北京大是大，不过这边的路基本上都是正南正北、正东正西的，很好找。你也可以用手机地图，很容易就能找到目的地。","pinyin":""},{"speaker":"陈天中","cn":"嗯，不过很多中文地名我还不认识。","pinyin":""},{"speaker":"同学","cn":"没关系，你很快就会熟悉的。","pinyin":""}],"translation_vn":"Trần Thiên Trung: Xin hỏi, đi đến khu dân cư Hoa Viên thế nào ạ?\nBạn học: Bạn đi thẳng về phía trước, đến ngã tư thì đừng qua đường, rẽ phải trực tiếp là đến cổng khu dân cư rồi. Đúng lúc mình cũng đi hướng đó, đi cùng nhau nhé.\nTrần Thiên Trung: Được ạ. Mình mới đến Trung Quốc, chưa quen đường. Bắc Kinh thật là quá rộng lớn.\nBạn học: Bắc Kinh thì rộng là rộng thật, nhưng đường ở khu này cơ bản đều là chính nam chính bắc, chính đông chính tây, rất dễ tìm. Bạn cũng có thể dùng bản đồ điện thoại, rất dễ dàng tìm được điểm đến.\nTrần Thiên Trung: Vâng, nhưng có nhiều tên địa danh tiếng Trung mình vẫn chưa biết.\nBạn học: Không sao, bạn sẽ sớm quen thôi.","audio_dialogue":"3-1.mp3","audio_vocab":"3-2.mp3"},{"label":"Bài khóa 2","type":"dialogue","lines":[{"speaker":"陈天中","cn":"前两天和李文喝咖啡时，他帮我下载了微信和支付宝，教我认识里边的汉字，还教我用手机进行支付。","pinyin":""},{"speaker":"白家月","cn":"他也教了我怎么用这两个软件。","pinyin":""},{"speaker":"陈天中","cn":"现在我不仅会扫码结账，还会用手机在网上购物了。昨天我就在网上订了一台电脑，今天下午一点送到。","pinyin":""},{"speaker":"白家月","cn":"学会了这些，我们在中国生活真是方便了不少。","pinyin":""},{"speaker":"陈天中","cn":"对。快递员要到了，我得马上回去！家月，明天见！","pinyin":""},{"speaker":"白家月","cn":"好的，天中，再见。","pinyin":""}],"translation_vn":"Trần Thiên Trung: Hôm trước uống cà phê với Lý Văn, anh ấy đã giúp mình tải WeChat và Alipay, dạy mình nhận biết chữ Hán trong đó, còn dạy mình dùng điện thoại để thanh toán.\nBạch Gia Nguyệt: Anh ấy cũng dạy mình cách dùng hai phần mềm này.\nTrần Thiên Trung: Bây giờ mình không chỉ biết quét mã thanh toán, mà còn biết dùng điện thoại mua sắm trực tuyến nữa. Hôm qua mình đã đặt mua một chiếc máy tính trên mạng, chiều nay một giờ sẽ được giao đến.\nBạch Gia Nguyệt: Học được những điều này, cuộc sống của chúng ta ở Trung Quốc thật sự tiện lợi hơn nhiều.\nTrần Thiên Trung: Đúng vậy. Nhân viên giao hàng sắp đến rồi, mình phải về ngay đây! Gia Nguyệt, hẹn gặp lại ngày mai nhé!\nBạch Gia Nguyệt: Được rồi, Thiên Trung, tạm biệt.","audio_dialogue":"3-3.mp3","audio_vocab":"3-4.mp3"},{"label":"Bài khóa 3","type":"passage","lines":[{"speaker":"","cn":"白家月和陈天中刚到北京时就发现，中国人在饭馆或超市结账时，几乎都用手机支付，只有他们用现金结账。在李文的帮助下，白家月和陈天中也都学会了用手机支付、网购、寄快递等等。在中国网购，不仅选择多、价格不高，而且送货很快，很多留学生甚至改变了自己的购物习惯。不过，由于网购太方便了，动动手指就能买到想要的东西，他们也开始担心自己在网购时会乱花钱。怎么才能管住自己不乱花钱呢？","pinyin":""}],"translation_vn":"Khi Bạch Gia Nguyệt và Trần Thiên Trung mới đến Bắc Kinh đã phát hiện ra rằng người Trung Quốc khi thanh toán ở nhà hàng hay siêu thị hầu như đều dùng điện thoại để trả tiền, chỉ có họ là dùng tiền mặt để thanh toán. Nhờ sự giúp đỡ của Lý Văn, Bạch Gia Nguyệt và Trần Thiên Trung cũng đều đã học được cách thanh toán bằng điện thoại, mua sắm trực tuyến, gửi chuyển phát nhanh, v.v. Khi mua sắm trực tuyến ở Trung Quốc, không những có nhiều lựa chọn, giá cả không cao, mà việc giao hàng còn rất nhanh, rất nhiều du học sinh thậm chí đã thay đổi thói quen mua sắm của mình. Tuy nhiên, vì mua sắm trực tuyến quá tiện lợi, chỉ cần động ngón tay là có thể mua được thứ mình muốn, nên họ cũng bắt đầu lo lắng rằng mình sẽ tiêu tiền bừa bãi khi mua sắm trực tuyến. Làm thế nào để có thể kiểm soát bản thân không tiêu tiền bừa bãi đây?","audio_dialogue":"3-5.mp3","audio_vocab":"3-6.mp3"},{"label":"Bài khóa 4","type":"passage","lines":[{"speaker":"","cn":"网上购物或者订票时，我们经常需要提供姓名、手机号、身份证号等个人信息。在提供这些信息时，我们也会担心：我的个人信息能否得到保护？于是，有人在网上说出了自己的担心，很快就有人给出了一些建议。比如，别把密码随便告诉别人，不在网上发自己的车票、机票信息……现在，很多国家也通过技术、法律等手段来保证个人信息安全。比如中国的网络安全法、个人信息保护法等就很好地保护了人们的个人信息。","pinyin":""}],"translation_vn":"Khi mua sắm trực tuyến hoặc đặt vé, chúng ta thường cần cung cấp các thông tin cá nhân như họ tên, số điện thoại, số chứng minh thư. Khi cung cấp những thông tin này, chúng ta cũng lo lắng: liệu thông tin cá nhân của mình có được bảo vệ hay không? Thế là, có người đã nói ra nỗi lo của mình trên mạng, và nhanh chóng có người đưa ra một số lời khuyên. Chẳng hạn, đừng tùy tiện nói mật khẩu cho người khác biết, không đăng thông tin vé tàu, vé máy bay của mình lên mạng... Hiện nay, rất nhiều quốc gia cũng thông qua các biện pháp như công nghệ, pháp luật để đảm bảo an toàn thông tin cá nhân. Ví dụ như Luật An ninh mạng, Luật Bảo vệ thông tin cá nhân của Trung Quốc đã bảo vệ rất tốt thông tin cá nhân của người dân.","audio_dialogue":"3-7.mp3","audio_vocab":"3-8.mp3"}]},{"id":4,"title_cn":"很高兴能帮到你","title_pinyin":"","title_vn":"Rất vui vì đã giúp được bạn","goals":["Có thể nghe hiểu và trao đổi về các chủ đề nhờ giúp đỡ hoặc giúp đỡ người khác trong cuộc sống hằng ngày.","Có thể diễn đạt bằng lời nói hoặc chữ viết về các phương thức đi lại khác nhau cùng ưu nhược điểm của chúng.","Hiểu được các dịch vụ tiện ích phục vụ người dân ở các thành phố Trung Quốc."],"vocab":[{"hanzi":"啊","pinyin":"ā","pos":"ct.","vn":"a, ôi (thán từ)","examples":[{"cn":"啊，下雨了！","pinyin":"a ， xià yǔ le ！","vn":"A, trời mưa rồi!"},{"cn":"这个蛋糕真好吃啊！","pinyin":"zhè ge dàn gāo zhēn hǎo chī a ！","vn":"Cái bánh này ngon thật đấy!"},{"cn":"啊，我忘带钥匙了。","pinyin":"a ， wǒ wàng dài yào shi le 。","vn":"Ôi, tôi quên mang chìa khóa rồi."}]},{"hanzi":"停","pinyin":"tíng","pos":"dgt.","vn":"dừng; đỗ (xe)","examples":[{"cn":"车停在路边了。","pinyin":"chē tíng zài lù biān le 。","vn":"Xe đã đỗ bên đường rồi."},{"cn":"雨一会儿就停了。","pinyin":"yǔ yī huì er jiù tíng le 。","vn":"Lát nữa mưa sẽ tạnh thôi."},{"cn":"请把车停在那边。","pinyin":"qǐng bǎ chē tíng zài nà biān 。","vn":"Làm ơn đỗ xe ở đằng kia."}]},{"hanzi":"交","pinyin":"jiāo","pos":"dgt.","vn":"nộp, giao","examples":[{"cn":"作业明天要交。","pinyin":"zuò yè míng tiān yào jiāo 。","vn":"Mai phải nộp bài tập."},{"cn":"他把钱交给了老板。","pinyin":"tā bǎ qián jiāo gěi le lǎo bǎn 。","vn":"Anh ấy đã giao tiền cho ông chủ."},{"cn":"这个月的房租还没交。","pinyin":"zhè ge yuè de fáng zū hái méi jiāo 。","vn":"Tiền thuê nhà tháng này chưa nộp."}]},{"hanzi":"费","pinyin":"fèi","pos":"dt./dgt.","vn":"phí, chi phí; tốn kém","examples":[{"cn":"这个月的电费有点多。","pinyin":"zhè ge yuè de diàn fèi yǒu diǎn duō 。","vn":"Tiền điện tháng này hơi nhiều."},{"cn":"做这件事太费时间了。","pinyin":"zuò zhè jiàn shì tài fèi shí jiān le 。","vn":"Làm việc này tốn thời gian quá."},{"cn":"停车费一个小时十块钱。","pinyin":"tíng chē fèi yí gè xiǎo shí shí kuài qián 。","vn":"Phí đỗ xe là mười tệ một giờ."}]},{"hanzi":"信号","pinyin":"xìnhào","pos":"dt.","vn":"tín hiệu, sóng","examples":[{"cn":"这里山区信号不好。","pinyin":"zhè lǐ shān qū xìn hào bù hǎo 。","vn":"Ở vùng núi này sóng điện thoại không tốt."},{"cn":"手机一点信号都没有。","pinyin":"shǒu jī yì diǎn xìn hào dōu méi yǒu 。","vn":"Điện thoại chẳng có chút tín hiệu nào."},{"cn":"他给我打了个信号，让我过去。","pinyin":"tā gěi wǒ dǎ le gè xìn hào ， ràng wǒ guò qù 。","vn":"Anh ấy ra hiệu cho tôi để tôi qua đó."}]},{"hanzi":"感谢","pinyin":"gǎnxiè","pos":"dgt.","vn":"cảm ơn","examples":[{"cn":"非常感谢你的帮助。","pinyin":"fēi cháng gǎn xiè nǐ de bāng zhù 。","vn":"Rất cảm ơn sự giúp đỡ của bạn."},{"cn":"我要感谢所有支持我的人。","pinyin":"wǒ yào gǎn xiè suǒ yǒu zhī chí wǒ de rén 。","vn":"Tôi muốn cảm ơn tất cả những người ủng hộ mình."},{"cn":"他特意来感谢老师。","pinyin":"tā tè yì lái gǎn xiè lǎo shī 。","vn":"Anh ấy đặc biệt đến cảm ơn thầy giáo."}]},{"hanzi":"联系","pinyin":"liánxì","pos":"dgt.","vn":"liên hệ","examples":[{"cn":"有事可以随时联系我。","pinyin":"yǒu shì kě yǐ suí shí lián xì wǒ 。","vn":"Có việc gì cứ liên hệ tôi bất cứ lúc nào."},{"cn":"我们好久没联系了。","pinyin":"wǒ men hǎo jiǔ méi lián xì le 。","vn":"Chúng tôi đã lâu không liên lạc rồi."},{"cn":"请留下你的联系方式。","pinyin":"qǐng liú xià nǐ de lián xì fāng shì 。","vn":"Xin để lại cách liên hệ của bạn."}]},{"hanzi":"方式","pinyin":"fāngshì","pos":"dt.","vn":"phương thức, cách thức","examples":[{"cn":"每个人的学习方式不一样。","pinyin":"měi gè rén de xué xí fāng shì bù yí yàng 。","vn":"Cách học của mỗi người mỗi khác."},{"cn":"这种沟通方式不太好。","pinyin":"zhè zhǒng gōu tōng fāng shì bù tài hǎo 。","vn":"Phương thức giao tiếp này không ổn lắm."},{"cn":"请选择你方便的联系方式。","pinyin":"qǐng xuǎn zé nǐ fāng biàn de lián xì fāng shì 。","vn":"Hãy chọn cách liên hệ thuận tiện cho bạn."}]},{"hanzi":"客气","pinyin":"kèqi","pos":"dgt./tt.","vn":"khách sáo; lịch sự","examples":[{"cn":"别客气，像在自己家一样。","pinyin":"bié kè qì ， xiàng zài zì jǐ jiā yī yàng 。","vn":"Đừng khách sáo, cứ như ở nhà mình vậy."},{"cn":"他对谁都很客气。","pinyin":"tā duì shéi dōu hěn kè qì 。","vn":"Anh ấy rất lịch sự với mọi người."},{"cn":"你太客气了，不用送礼物的。","pinyin":"nǐ tài kè qì le ， bù yòng sòng lǐ wù de 。","vn":"Bạn khách sáo quá, không cần tặng quà đâu."}]},{"hanzi":"剩","pinyin":"shèng","pos":"dgt.","vn":"còn thừa, còn lại","examples":[{"cn":"饭还剩不少，别浪费。","pinyin":"fàn hái shèng bù shǎo ， bié làng fèi 。","vn":"Cơm vẫn còn thừa khá nhiều, đừng lãng phí."},{"cn":"时间不多了，只剩十分钟了。","pinyin":"shí jiān bù duō le ， zhǐ shèng shí fēn zhōng le 。","vn":"Thời gian không còn nhiều, chỉ còn mười phút nữa thôi."},{"cn":"钱都花完了，什么都没剩下。","pinyin":"qián dōu huā wán le ， shén me dōu méi shèng xià 。","vn":"Tiền tiêu hết sạch, chẳng còn lại gì cả."}]},{"hanzi":"提","pinyin":"tí","pos":"dgt.","vn":"xách","examples":[{"cn":"他提着一个大箱子上楼。","pinyin":"tā tí zhe yí gè dà xiāng zi shàng lóu 。","vn":"Anh ấy xách một chiếc va li to lên lầu."},{"cn":"我帮你提东西吧。","pinyin":"wǒ bāng nǐ tí dōng xī ba 。","vn":"Tôi xách đồ giúp bạn nhé."},{"cn":"她手里提着几袋水果。","pinyin":"tā shǒu lǐ tí zhe jǐ dài shuǐ guǒ 。","vn":"Cô ấy tay xách mấy túi hoa quả."}]},{"hanzi":"袋子","pinyin":"dàizi","pos":"dt.","vn":"túi","examples":[{"cn":"买菜的袋子放在厨房。","pinyin":"mǎi cài de dài zi fàng zài chú fáng 。","vn":"Túi đựng rau để trong bếp."},{"cn":"这个袋子装不下这么多东西。","pinyin":"zhè ge dài zi zhuāng bù xià zhè me duō dōng xī 。","vn":"Cái túi này không đựng được nhiều đồ như vậy."},{"cn":"请给我一个塑料袋子。","pinyin":"qǐng gěi wǒ yí gè sù liào dài zi 。","vn":"Cho tôi xin một cái túi ni lông."}]},{"hanzi":"重","pinyin":"zhòng","pos":"tt./dt.","vn":"nặng; trọng lượng","examples":[{"cn":"这个箱子真重，得两个人才能抬。","pinyin":"zhè ge xiāng zi zhēn zhòng ， dé liǎng gè rén cái néng tái 。","vn":"Cái thùng này nặng thật, phải hai người mới khiêng nổi."},{"cn":"他说话的语气很重。","pinyin":"tā shuō huà de yǔ qì hěn zhòng 。","vn":"Giọng nói của anh ấy rất nặng nề."},{"cn":"这次任务很重，大家都要加把劲。","pinyin":"zhè cì rèn wù hěn zhòng ， dà jiā dōu yào jiā bǎ jìn 。","vn":"Nhiệm vụ lần này rất nặng, mọi người phải cố gắng lên."}]},{"hanzi":"算","pinyin":"suàn","pos":"dgt.","vn":"coi như, tính là","examples":[{"cn":"这顿饭就算我请客吧。","pinyin":"zhè dùn fàn jiù suàn wǒ qǐng kè ba 。","vn":"Bữa này coi như tôi mời vậy."},{"cn":"这件事就算了，别再提了。","pinyin":"zhè jiàn shì jiù suàn le ， bié zài tí le 。","vn":"Chuyện này thôi bỏ qua, đừng nhắc lại nữa."},{"cn":"他这次表现还算不错。","pinyin":"tā zhè cì biǎo xiàn hái suàn bú cuò 。","vn":"Lần này anh ấy thể hiện cũng coi như không tệ."}]},{"hanzi":"再说","pinyin":"zàishuō","pos":"liên.","vn":"hơn nữa, vả lại","examples":[{"cn":"今天太晚了，再说我也很累，改天再去吧。","pinyin":"jīn tiān tài wǎn le ， zài shuō wǒ yě hěn lèi ， gǎi tiān zài qù ba 。","vn":"Hôm nay muộn quá rồi, hơn nữa tôi cũng mệt, hôm khác hẵng đi."},{"cn":"这件衣服有点贵，再说颜色也不太适合我。","pinyin":"zhè jiàn yī fú yǒu diǎn guì ， zài shuō yán sè yě bù tài shì hé wǒ 。","vn":"Cái áo này hơi đắt, vả lại màu cũng không hợp với tôi lắm."},{"cn":"他身体不太好，再说年纪也大了，别让他干重活。","pinyin":"tā shēn tǐ bù tài hǎo ， zài shuō nián jì yě dà le ， bié ràng tā gàn zhòng huó 。","vn":"Sức khỏe anh ấy không tốt, vả lại tuổi cũng lớn rồi, đừng để anh ấy làm việc nặng."}]},{"hanzi":"之间","pinyin":"zhījiān","pos":"dt.","vn":"giữa, trong khoảng","examples":[{"cn":"他们俩之间有点误会。","pinyin":"tā men liǎ zhī jiān yǒu diǎn wù huì 。","vn":"Giữa hai người họ có chút hiểu lầm."},{"cn":"这件事发生在上个月之间。","pinyin":"zhè jiàn shì fā shēng zài shàng gè yuè zhī jiān 。","vn":"Chuyện này xảy ra trong khoảng tháng trước."},{"cn":"公司和员工之间要互相信任。","pinyin":"gōng sī hé yuán gōng zhī jiān yào hù xiāng xìn rèn 。","vn":"Công ty và nhân viên phải tin tưởng lẫn nhau."}]},{"hanzi":"互相","pinyin":"hùxiāng","pos":"phó.","vn":"lẫn nhau, qua lại","examples":[{"cn":"我们应该互相帮助。","pinyin":"wǒ men yīng gāi hù xiāng bāng zhù 。","vn":"Chúng ta nên giúp đỡ lẫn nhau."},{"cn":"夫妻之间要互相理解。","pinyin":"fū qī zhī jiān yào hù xiāng lǐ jiě 。","vn":"Vợ chồng phải hiểu nhau."},{"cn":"大家互相认识一下吧。","pinyin":"dà jiā hù xiāng rèn shí yī xià ba 。","vn":"Mọi người làm quen với nhau một chút nhé."}]},{"hanzi":"辛苦","pinyin":"xīnkǔ","pos":"dgt./tt.","vn":"vất vả, cực nhọc","examples":[{"cn":"这段时间你辛苦了。","pinyin":"zhè duàn shí jiān nǐ xīn kǔ le 。","vn":"Dạo này bạn vất vả rồi."},{"cn":"父母为了孩子真的很辛苦。","pinyin":"fù mǔ wèi le hái zi zhēn de hěn xīn kǔ 。","vn":"Cha mẹ vì con cái thật sự rất cực nhọc."},{"cn":"辛苦大家加班完成这个项目。","pinyin":"xīn kǔ dà jiā jiā bān wán chéng zhè ge xiàng mù 。","vn":"Mọi người vất vả tăng ca để hoàn thành dự án này."}]},{"hanzi":"出行","pinyin":"chūxíng","pos":"dgt.","vn":"đi lại, ra ngoài đi đường","examples":[{"cn":"节假日出行的人特别多。","pinyin":"jié jià rì chū xíng de rén tè bié duō 。","vn":"Ngày lễ số người đi lại đặc biệt đông."},{"cn":"骑电动车出行又方便又环保。","pinyin":"qí diàn dòng chē chū xíng yòu fāng biàn yòu huán bǎo 。","vn":"Đi lại bằng xe điện vừa tiện vừa thân thiện môi trường."},{"cn":"下雪天出行要小心路滑。","pinyin":"xià xuě tiān chū xíng yào xiǎo xīn lù huá 。","vn":"Ngày tuyết rơi đi đường phải cẩn thận trơn trượt."}]},{"hanzi":"距离","pinyin":"jùlí","pos":"dt./dgt.","vn":"khoảng cách; cách xa","examples":[{"cn":"这里离公司的距离不远。","pinyin":"zhè lǐ lí gōng sī de jù lí bù yuǎn 。","vn":"Khoảng cách từ đây đến công ty không xa."},{"cn":"我们之间的距离越来越远了。","pinyin":"wǒ men zhī jiān de jù lí yuè lái yuè yuǎn le 。","vn":"Khoảng cách giữa chúng tôi ngày càng xa hơn."},{"cn":"跑步可以锻炼身体，距离不用太长。","pinyin":"pǎo bù kě yǐ duàn liàn shēn tǐ ， jù lí bù yòng tài zhǎng 。","vn":"Chạy bộ có thể rèn luyện sức khỏe, khoảng cách không cần quá dài."}]},{"hanzi":"往往","pinyin":"wǎngwǎng","pos":"phó.","vn":"thường thường","examples":[{"cn":"成功的人往往更努力。","pinyin":"chéng gōng de rén wǎng wǎng gèng nǔ lì 。","vn":"Người thành công thường nỗ lực hơn."},{"cn":"他往往加班到很晚。","pinyin":"tā wǎng wǎng jiā bān dào hěn wǎn 。","vn":"Anh ấy thường tăng ca đến rất khuya."},{"cn":"事情往往没有想象中那么简单。","pinyin":"shì qíng wǎng wǎng méi yǒu xiǎng xiàng zhōng nà me jiǎn dān 。","vn":"Sự việc thường không đơn giản như người ta tưởng."}]},{"hanzi":"既","pinyin":"jì","pos":"phó.","vn":"vừa... (vừa...)","examples":[{"cn":"这个方法既简单又有效。","pinyin":"zhè ge fāng fǎ jì jiǎn dān yòu yǒu xiào 。","vn":"Cách này vừa đơn giản vừa hiệu quả."},{"cn":"他既聪明又勤奋。","pinyin":"tā jì cōng míng yòu qín fèn 。","vn":"Anh ấy vừa thông minh vừa chăm chỉ."},{"cn":"这个房子既便宜又宽敞。","pinyin":"zhè ge fáng zi jì pián yi yòu kuān chǎng 。","vn":"Căn nhà này vừa rẻ vừa rộng rãi."}]},{"hanzi":"电动车","pinyin":"diàndòngchē","pos":"dt.","vn":"xe điện","examples":[{"cn":"他每天骑电动车上班。","pinyin":"tā měi tiān qí diàn dòng chē shàng bān 。","vn":"Anh ấy mỗi ngày đi xe điện đi làm."},{"cn":"电动车比摩托车环保。","pinyin":"diàn dòng chē bǐ mó tuō chē huán bǎo 。","vn":"Xe điện thân thiện môi trường hơn xe máy."},{"cn":"电动车没电了，得找地方充电。","pinyin":"diàn dòng chē méi diàn le ， dé zhǎo dì fāng chōng diàn 。","vn":"Xe điện hết điện rồi, phải tìm chỗ sạc."}]},{"hanzi":"速度","pinyin":"sùdù","pos":"dt.","vn":"tốc độ","examples":[{"cn":"这辆车的速度真快。","pinyin":"zhè liàng chē de sù dù zhēn kuài 。","vn":"Tốc độ của chiếc xe này nhanh thật."},{"cn":"他说话的速度有点快。","pinyin":"tā shuō huà de sù dù yǒu diǎn kuài 。","vn":"Tốc độ nói chuyện của anh ấy hơi nhanh."},{"cn":"这里的网络速度太慢了，看视频总卡。","pinyin":"zhè lǐ de wǎng luò sù dù tài màn le ， kàn shì pín zǒng kǎ 。","vn":"Tốc độ mạng ở đây chậm quá, xem video cứ bị giật."}]},{"hanzi":"充电","pinyin":"chōngdiàn","pos":"dgt.","vn":"sạc điện","examples":[{"cn":"手机没电了，我去充电。","pinyin":"shǒu jī méi diàn le ， wǒ qù chōng diàn 。","vn":"Điện thoại hết pin rồi, tôi đi sạc đây."},{"cn":"电动车晚上一般在家充电。","pinyin":"diàn dòng chē wǎn shàng yì bān zài jiā chōng diàn 。","vn":"Xe điện thường sạc ở nhà vào buổi tối."},{"cn":"这个充电器坏了。","pinyin":"zhè ge chōng diàn qì huài le 。","vn":"Cái sạc này hỏng rồi."}]},{"hanzi":"流行","pinyin":"liúxíng","pos":"dgt.","vn":"phổ biến, thịnh hành","examples":[{"cn":"这种发型现在很流行。","pinyin":"zhè zhǒng fà xíng xiàn zài hěn liú xíng 。","vn":"Kiểu tóc này bây giờ rất thịnh hành."},{"cn":"短视频在年轻人中很流行。","pinyin":"duǎn shì pín zài nián qīng rén zhōng hěn liú xíng 。","vn":"Video ngắn rất phổ biến trong giới trẻ."},{"cn":"这首歌去年特别流行。","pinyin":"zhè shǒu gē qù nián tè bié liú xíng 。","vn":"Bài hát này năm ngoái rất thịnh hành."}]},{"hanzi":"省","pinyin":"shěng","pos":"dgt.","vn":"tiết kiệm","examples":[{"cn":"坐地铁能省不少钱。","pinyin":"zuò dì tiě néng shěng bù shǎo qián 。","vn":"Đi tàu điện ngầm tiết kiệm được khá nhiều tiền."},{"cn":"他平时很省，很少乱花钱。","pinyin":"tā píng shí hěn shěng ， hěn shǎo luàn huā qián 。","vn":"Anh ấy bình thường rất tiết kiệm, ít khi tiêu xài lung tung."},{"cn":"这样做能省不少时间。","pinyin":"zhè yàng zuò néng shěng bù shǎo shí jiān 。","vn":"Làm vậy có thể tiết kiệm được nhiều thời gian."}]},{"hanzi":"力气","pinyin":"lìqi","pos":"dt.","vn":"sức lực","examples":[{"cn":"搬这个箱子真费力气。","pinyin":"bān zhè ge xiāng zi zhēn fèi lì qì 。","vn":"Khiêng cái thùng này thật tốn sức."},{"cn":"他力气很大，一个人就能抬起来。","pinyin":"tā lì qì hěn dà ， yí gè rén jiù néng tái qǐ lái 。","vn":"Anh ấy khỏe lắm, một mình cũng khiêng nổi."},{"cn":"我今天没什么力气，想休息一下。","pinyin":"wǒ jīn tiān méi shén me lì qì ， xiǎng xiū xī yī xià 。","vn":"Hôm nay tôi không còn sức, muốn nghỉ ngơi một chút."}]},{"hanzi":"乘客","pinyin":"chéngkè","pos":"dt.","vn":"hành khách","examples":[{"cn":"请乘客系好安全带。","pinyin":"qǐng chéng kè jì hǎo ān quán dài 。","vn":"Mời hành khách thắt dây an toàn."},{"cn":"这趟车上的乘客不多。","pinyin":"zhè tàng chē shàng de chéng kè bù duō 。","vn":"Chuyến xe này không có nhiều hành khách."},{"cn":"司机提醒乘客注意脚下。","pinyin":"sī jī tí xǐng chéng kè zhù yì jiǎo xià 。","vn":"Tài xế nhắc hành khách chú ý dưới chân."}]},{"hanzi":"购买","pinyin":"gòumǎi","pos":"dgt.","vn":"mua","examples":[{"cn":"他打算购买一套新房子。","pinyin":"tā dǎ suàn gòu mǎi yī tào xīn fáng zi 。","vn":"Anh ấy định mua một căn nhà mới."},{"cn":"这些材料需要去市场购买。","pinyin":"zhè xiē cái liào xū yào qù shì chǎng gòu mǎi 。","vn":"Những nguyên liệu này cần ra chợ mua."},{"cn":"购买前请仔细看看说明书。","pinyin":"gòu mǎi qián qǐng zǐ xì kàn kàn shuō míng shū 。","vn":"Trước khi mua hãy đọc kỹ hướng dẫn sử dụng."}]},{"hanzi":"食物","pinyin":"shíwù","pos":"dt.","vn":"thức ăn","examples":[{"cn":"冰箱里有不少食物。","pinyin":"bīng xiāng lǐ yǒu bù shǎo shí wù 。","vn":"Trong tủ lạnh có khá nhiều thức ăn."},{"cn":"这种食物对身体不太好。","pinyin":"zhè zhǒng shí wù duì shēn tǐ bù tài hǎo 。","vn":"Loại thức ăn này không tốt cho sức khỏe lắm."},{"cn":"旅行时要带一些食物。","pinyin":"lǚ xíng shí yào dài yī xiē shí wù 。","vn":"Khi đi du lịch nên mang theo ít thức ăn."}]},{"hanzi":"免费","pinyin":"miǎnfèi","pos":"dgt.","vn":"miễn phí","examples":[{"cn":"这个活动是免费参加的。","pinyin":"zhè ge huó dòng shì miǎn fèi cān jiā de 。","vn":"Hoạt động này được tham gia miễn phí."},{"cn":"第一次体验免费。","pinyin":"dì yī cì tǐ yàn miǎn fèi 。","vn":"Lần trải nghiệm đầu tiên miễn phí."},{"cn":"这里停车不免费。","pinyin":"zhè lǐ tíng chē bù miǎn fèi 。","vn":"Đỗ xe ở đây không miễn phí đâu."}]},{"hanzi":"早餐","pinyin":"zǎocān","pos":"dt.","vn":"bữa sáng","examples":[{"cn":"我每天都吃早餐。","pinyin":"wǒ měi tiān dōu chī zǎo cān 。","vn":"Ngày nào tôi cũng ăn sáng."},{"cn":"酒店提供免费早餐。","pinyin":"jiǔ diàn tí gōng miǎn fèi zǎo cān 。","vn":"Khách sạn cung cấp bữa sáng miễn phí."},{"cn":"他从来不吃早餐，习惯不好。","pinyin":"tā cóng lái bù chī zǎo cān ， xí guàn bù hǎo 。","vn":"Anh ấy chẳng bao giờ ăn sáng, thói quen không tốt."}]},{"hanzi":"来得及","pinyin":"láidejí","pos":"dgt.","vn":"kịp, còn kịp","examples":[{"cn":"现在出发还来得及。","pinyin":"xiàn zài chū fā hái lái de jí 。","vn":"Bây giờ xuất phát vẫn còn kịp."},{"cn":"别着急，时间来得及。","pinyin":"bié zháo jí ， shí jiān lái de jí 。","vn":"Đừng vội, thời gian vẫn còn kịp."},{"cn":"只要快点，还来得及赶上火车。","pinyin":"zhǐ yào kuài diǎn ， hái lái de jí gǎn shàng huǒ chē 。","vn":"Chỉ cần nhanh lên một chút, vẫn kịp bắt chuyến tàu."}]},{"hanzi":"鲜花","pinyin":"xiānhuā","pos":"dt.","vn":"hoa tươi","examples":[{"cn":"他送了我一束鲜花。","pinyin":"tā sòng le wǒ yī shù xiān huā 。","vn":"Anh ấy tặng tôi một bó hoa tươi."},{"cn":"婚礼现场摆满了鲜花。","pinyin":"hūn lǐ xiàn chǎng bǎi mǎn le xiān huā 。","vn":"Lễ cưới ngập tràn hoa tươi."},{"cn":"这些鲜花是今天早上刚送到的。","pinyin":"zhè xiē xiān huā shì jīn tiān zǎo shàng gāng sòng dào de 。","vn":"Chỗ hoa tươi này sáng nay vừa mới được giao đến."}]},{"hanzi":"顺便","pinyin":"shùnbiàn","pos":"phó.","vn":"tiện thể, nhân tiện","examples":[{"cn":"你去超市的时候顺便帮我买瓶水。","pinyin":"nǐ qù chāo shì de shí hòu shùn biàn bāng wǒ mǎi píng shuǐ 。","vn":"Khi bạn đi siêu thị thì tiện thể mua giúp tôi chai nước."},{"cn":"我去机场顺便去看看朋友。","pinyin":"wǒ qù jī chǎng shùn biàn qù kàn kàn péng yǒu 。","vn":"Tôi đi sân bay tiện thể ghé thăm bạn."},{"cn":"顺便问一下，你今天有空吗？","pinyin":"shùn biàn wèn yī xià ， nǐ jīn tiān yǒu kòng ma ？","vn":"Tiện thể hỏi luôn, hôm nay bạn có rảnh không?"}]},{"hanzi":"心情","pinyin":"xīnqíng","pos":"dt.","vn":"tâm trạng","examples":[{"cn":"今天心情不太好。","pinyin":"jīn tiān xīn qíng bù tài hǎo 。","vn":"Hôm nay tâm trạng không được tốt lắm."},{"cn":"听了这首歌，我的心情好多了。","pinyin":"tīng le zhè shǒu gē ， wǒ de xīn qíng hǎo duō le 。","vn":"Nghe bài hát này xong tâm trạng tôi khá hơn nhiều."},{"cn":"他似乎心情不错，一直在笑。","pinyin":"tā sì hū xīn qíng bù cuò ， yì zhí zài xiào 。","vn":"Anh ấy có vẻ tâm trạng tốt, cứ cười suốt."}]},{"hanzi":"更加","pinyin":"gèngjiā","pos":"phó.","vn":"càng, càng thêm","examples":[{"cn":"经过这件事，他变得更加成熟了。","pinyin":"jīng guò zhè jiàn shì ， tā biàn dé gèng jiā chéng shú le 。","vn":"Qua chuyện này, anh ấy trở nên chín chắn hơn."},{"cn":"有了你的帮助，事情更加顺利了。","pinyin":"yǒu le nǐ de bāng zhù ， shì qíng gèng jiā shùn lì le 。","vn":"Có sự giúp đỡ của bạn, mọi việc càng thêm thuận lợi."},{"cn":"天气更加冷了，多穿点衣服。","pinyin":"tiān qì gèng jiā lěng le ， duō chuān diǎn yī fú 。","vn":"Trời càng lạnh hơn rồi, mặc thêm quần áo vào."}]},{"hanzi":"愉快","pinyin":"yúkuài","pos":"tt.","vn":"vui vẻ","examples":[{"cn":"祝你周末愉快！","pinyin":"zhù nǐ zhōu mò yú kuài ！","vn":"Chúc bạn cuối tuần vui vẻ!"},{"cn":"我们合作得很愉快。","pinyin":"wǒ men hé zuò dé hěn yú kuài 。","vn":"Chúng tôi hợp tác rất vui vẻ."},{"cn":"这次旅行很愉快。","pinyin":"zhè cì lǚ xíng hěn yú kuài 。","vn":"Chuyến đi lần này rất vui vẻ."}]}],"grammar":[{"title":"可能补语\"动词+得/不+了\"","explanation_vn":"\"得了\" và \"不了\" được đặt sau động từ hoặc chen vào giữa từ ly hợp, tạo thành bổ ngữ khả năng, biểu thị động tác hay kết quả có thể hoàn thành hoặc thực hiện được hay không.","examples":[{"cn":"手机没有信号，上不了网，买不了地铁票了。","pinyin":"","vn":"Điện thoại không có sóng, không vào mạng được, nên không mua được vé tàu điện ngầm."},{"cn":"她刚才给我发信息，说她今天来不了了。","pinyin":"","vn":"Lúc nãy cô ấy nhắn tin cho tôi, nói hôm nay cô ấy không đến được."},{"cn":"明天的足球比赛，你们班男生参加得了吗？","pinyin":"","vn":"Trận bóng đá ngày mai, các bạn nam lớp bạn tham gia được không?"}]},{"title":"连词\"再说\"","explanation_vn":"Liên từ \"再说\" dùng để nêu ra một lý do hoặc tình huống, sau đó bổ sung thêm một lý do hoặc tình huống khác.","examples":[{"cn":"我提着这些东西就算锻炼身体了，再说邻居之间就是要互相帮助啊。","pinyin":"","vn":"Tôi xách mấy thứ này coi như tập thể dục rồi, hơn nữa hàng xóm với nhau thì phải giúp đỡ lẫn nhau chứ."},{"cn":"今天太晚了，别去超市了，再说外面还在下雨呢。","pinyin":"","vn":"Hôm nay muộn quá rồi, đừng đi siêu thị nữa, với lại bên ngoài vẫn đang mưa đấy."},{"cn":"你就跟我们一起参加活动吧。你今天正好有时间，再说人多也更热闹。","pinyin":"","vn":"Bạn cứ tham gia hoạt động cùng chúng tôi đi. Hôm nay bạn đúng lúc rảnh, hơn nữa đông người thì càng náo nhiệt."}]},{"title":"并列复句\"既……，又/也……\"","explanation_vn":"\"既……，又/也……\" dùng để liên kết tính từ, động từ hoặc cụm từ, biểu thị việc đồng thời có mấy tính chất hoặc tồn tại mấy tình huống cùng lúc.","examples":[{"cn":"她觉得这样既方便，又能锻炼身体，还能保护环境。","pinyin":"","vn":"Cô ấy thấy như vậy vừa tiện lợi, vừa có thể rèn luyện sức khỏe, lại còn bảo vệ được môi trường."},{"cn":"这家饭馆的菜既好吃，又便宜。","pinyin":"","vn":"Món ăn ở nhà hàng này vừa ngon, vừa rẻ."},{"cn":"我很喜欢这门课程，既能提高中文水平，也能学到历史知识。","pinyin":"","vn":"Tôi rất thích môn học này, vừa có thể nâng cao trình độ tiếng Trung, vừa có thể học được kiến thức lịch sử."}]},{"title":"固定短语\"来得及/来不及\"","explanation_vn":"\"来得及\" biểu thị vẫn còn thời gian, có thể lo liệu hoặc kịp làm; \"来不及\" biểu thị vì thời gian gấp gáp nên không thể lo liệu hoặc không kịp làm.","examples":[{"cn":"没来得及吃早饭的人在这里就能买到热包子和牛奶等。","pinyin":"","vn":"Những người chưa kịp ăn sáng có thể mua bánh bao nóng và sữa, v.v. ở đây."},{"cn":"你现在才告诉我，我来不及通知大家了。","pinyin":"","vn":"Bây giờ bạn mới nói cho tôi biết, tôi không kịp thông báo cho mọi người nữa rồi."},{"cn":"中午12点的飞机，咱们9点出发来得及吗？","pinyin":"","vn":"Chuyến bay 12 giờ trưa, chúng ta xuất phát lúc 9 giờ có kịp không?"}]}],"texts":[{"label":"Bài khóa 1","type":"dialogue","lines":[{"speaker":"陈天中","cn":"啊，我的手机停机了！怎么办啊？","pinyin":""},{"speaker":"路人","cn":"你好，你看上去很着急，需要帮忙吗？","pinyin":""},{"speaker":"陈天中","cn":"我忘了交电话费，手机停机了。我没带现金，手机没有信号，上不了网，买不了地铁票了。","pinyin":""},{"speaker":"路人","cn":"你要去哪儿？我帮你买张票。","pinyin":""},{"speaker":"陈天中","cn":"太感谢你了，我要去北京大学站。对了，能不能告诉我你的联系方式？我想把钱还给你。","pinyin":""},{"speaker":"路人","cn":"别客气，很高兴能帮到你。","pinyin":""}],"translation_vn":"Trần Thiên Trung: A, điện thoại của mình bị khóa máy rồi! Phải làm sao đây?\nNgười qua đường: Chào bạn, trông bạn có vẻ rất gấp, cần giúp đỡ không?\nTrần Thiên Trung: Mình quên đóng tiền điện thoại nên bị khóa máy rồi. Mình không mang tiền mặt, điện thoại lại không có sóng, không vào mạng được, không mua được vé tàu điện ngầm nữa.\nNgười qua đường: Bạn định đi đâu? Để mình mua vé giúp bạn.\nTrần Thiên Trung: Cảm ơn bạn nhiều lắm, mình muốn đến ga Đại học Bắc Kinh. Mà này, bạn có thể cho mình biết cách liên lạc với bạn không? Mình muốn trả lại tiền cho bạn.\nNgười qua đường: Đừng khách sáo, rất vui vì đã giúp được bạn.","audio_dialogue":"4-1.mp3","audio_vocab":"4-2.mp3"},{"label":"Bài khóa 2","type":"dialogue","lines":[{"speaker":"白家月","cn":"阿姨，您怎么站在这儿不上楼？","pinyin":""},{"speaker":"邻居","cn":"我开车去超市买了不少东西，刚拿过来了一些。我先休息一会儿，再去车里拿剩下的。","pinyin":""},{"speaker":"白家月","cn":"我正好要上楼，我帮您提上去吧。","pinyin":""},{"speaker":"邻居","cn":"不用不用，这几个袋子太重了，我自己拿吧。","pinyin":""},{"speaker":"白家月","cn":"没事，我提着这些东西就算锻炼身体了，再说邻居之间就是要互相帮助啊。","pinyin":""},{"speaker":"邻居","cn":"谢谢家月！那就辛苦你了。","pinyin":""}],"translation_vn":"Bạch Gia Nguyệt: Cô ơi, sao cô đứng đây mà không lên nhà vậy ạ?\nHàng xóm: Cô lái xe đi siêu thị mua kha khá đồ, vừa mang một ít lên đây. Cô nghỉ một chút rồi quay lại xe lấy nốt phần còn lại.\nBạch Gia Nguyệt: Cháu đúng lúc cũng định lên nhà, để cháu xách giúp cô lên nhé.\nHàng xóm: Không cần đâu, mấy túi này nặng lắm, để cô tự xách thôi.\nBạch Gia Nguyệt: Không sao đâu cô, cháu xách mấy thứ này coi như tập thể dục rồi, với lại hàng xóm với nhau thì phải giúp đỡ lẫn nhau chứ ạ.\nHàng xóm: Cảm ơn Gia Nguyệt nhé! Vậy thì vất vả cho cháu rồi.","audio_dialogue":"4-3.mp3","audio_vocab":"4-4.mp3"},{"label":"Bài khóa 3","type":"passage","lines":[{"speaker":"","cn":"在城市里，人们出行的方式越来越多。短距离出行时，骑自行车往往是人们常见的选择。白家月就很喜欢骑车去学校，她觉得这样既方便，又能锻炼身体，还能保护环境。除了骑自行车，人们还会选择骑电动车。电动车速度快，价格不高，充电也很方便，所以越来越流行。陈天中平时也骑自行车，不过为了省力气，他最近打算买一辆电动车。","pinyin":""}],"translation_vn":"Trong thành phố, cách thức đi lại của mọi người ngày càng đa dạng. Khi di chuyển quãng đường ngắn, đi xe đạp thường là lựa chọn phổ biến của mọi người. Bạch Gia Nguyệt rất thích đạp xe đến trường, cô ấy cảm thấy như vậy vừa tiện lợi, vừa có thể rèn luyện sức khỏe, lại vừa bảo vệ môi trường. Ngoài đi xe đạp ra, mọi người còn có thể chọn đi xe điện. Xe điện có tốc độ nhanh, giá cả không cao, sạc điện cũng rất tiện, nên ngày càng phổ biến. Trần Thiên Trung bình thường cũng đi xe đạp, nhưng để tiết kiệm sức lực, gần đây anh ấy định mua một chiếc xe điện.","audio_dialogue":"4-5.mp3","audio_vocab":"4-6.mp3"},{"label":"Bài khóa 4","type":"passage","lines":[{"speaker":"","cn":"在中国，乘客可以在不少地铁站里直接扫码购买食物和饮料，有的地铁站还提供免费借雨伞、发雨衣等服务。有些地铁站附近公司比较多，工作日站里还有早餐车，没来得及吃早饭的人在这里就能买到热包子和牛奶等，省了不少时间。有的地铁站里甚至还有鲜花店，乘客下班时可以顺便买花送给家人。这些小小的服务，不仅方便了人们的出行，也让大家的心情变得更加愉快。","pinyin":""}],"translation_vn":"Ở Trung Quốc, hành khách có thể quét mã trực tiếp để mua đồ ăn và thức uống ngay tại nhiều ga tàu điện ngầm, có ga còn cung cấp dịch vụ cho mượn ô miễn phí, phát áo mưa, v.v. Một số ga tàu điện ngầm gần nơi có nhiều công ty, vào ngày làm việc trong ga còn có xe bán đồ ăn sáng, những người không kịp ăn sáng có thể mua bánh bao nóng và sữa, v.v. ở đây, tiết kiệm được không ít thời gian. Có ga tàu điện ngầm thậm chí còn có cả cửa hàng hoa tươi, hành khách khi tan làm có thể tiện thể mua hoa tặng người thân. Những dịch vụ nhỏ bé này, không những giúp việc đi lại của mọi người thuận tiện hơn, mà còn khiến tâm trạng của mọi người trở nên vui vẻ hơn.","audio_dialogue":"4-7.mp3","audio_vocab":"4-8.mp3"}]},{"id":5,"title_cn":"“不怕辣”和“怕不辣”","title_pinyin":"","title_vn":"“Không sợ cay” và “sợ không cay”","goals":["Có thể nghe hiểu và trao đổi về chủ đề thói quen ăn uống và tụ họp ăn uống.","Có thể diễn đạt bằng lời nói hoặc chữ viết về sở thích ăn uống cá nhân và trải nghiệm dùng bữa.","Hiểu được thói quen ăn uống của người Trung Quốc và lễ nghi sắp xếp chỗ ngồi trong các bữa tiệc chính thức."],"vocab":[{"hanzi":"至少","pinyin":"zhìshǎo","pos":"phó.","vn":"ít nhất","examples":[{"cn":"这件事至少要三天才能做完。","pinyin":"Zhè jiàn shì zhìshǎo yào sān tiān cái néng zuò wán.","vn":"Việc này ít nhất phải ba ngày mới làm xong."},{"cn":"你至少也该打个电话告诉我一声吧。","pinyin":"Nǐ zhìshǎo yě gāi dǎ ge diànhuà gàosu wǒ yì shēng ba.","vn":"Cậu ít nhất cũng nên gọi điện báo cho tôi một tiếng chứ."},{"cn":"我们班至少有一半的人考过了HSK四级。","pinyin":"Wǒmen bān zhìshǎo yǒu yíbàn de rén kǎo guo le HSK sì jí.","vn":"Lớp tôi ít nhất có một nửa người đã thi đỗ HSK cấp 4."}]},{"hanzi":"中餐","pinyin":"zhōngcān","pos":"dt.","vn":"bữa ăn Trung Hoa, món Trung","examples":[{"cn":"你喜欢吃中餐还是西餐？","pinyin":"Nǐ xǐhuan chī zhōngcān háishi xīcān?","vn":"Bạn thích ăn món Trung hay món Tây hơn?"},{"cn":"这家饭店既做中餐也做西餐。","pinyin":"Zhè jiā fàndiàn jì zuò zhōngcān yě zuò xīcān.","vn":"Nhà hàng này vừa làm món Trung vừa làm món Tây."},{"cn":"在国外待久了，特别想吃一顿正宗的中餐。","pinyin":"Zài guówài dāi jiǔ le, tèbié xiǎng chī yí dùn zhèngzōng de zhōngcān.","vn":"Ở nước ngoài lâu rồi, tôi đặc biệt thèm ăn một bữa món Trung chính gốc."}]},{"hanzi":"专门","pinyin":"zhuānmén","pos":"phó./tt.","vn":"chuyên, đặc biệt; chuyên biệt","examples":[{"cn":"他专门为了这件事跑了一趟北京。","pinyin":"Tā zhuānmén wèile zhè jiàn shì pǎo le yí tàng Běijīng.","vn":"Anh ấy chuyên đi một chuyến Bắc Kinh chỉ vì việc này."},{"cn":"这家店是专门卖火锅底料的。","pinyin":"Zhè jiā diàn shì zhuānmén mài huǒguō dǐliào de.","vn":"Cửa hàng này chuyên bán gia vị nồi lẩu."},{"cn":"公司专门请了一位老师教我们商务汉语。","pinyin":"Gōngsī zhuānmén qǐng le yí wèi lǎoshī jiāo wǒmen shāngwù Hànyǔ.","vn":"Công ty mời riêng một thầy giáo dạy chúng tôi tiếng Hán thương mại."}]},{"hanzi":"煮","pinyin":"zhŭ","pos":"dgt.","vn":"nấu, luộc","examples":[{"cn":"水开了，把面条放进去煮五分钟就行。","pinyin":"Shuǐ kāi le, bǎ miàntiáo fàng jìnqù zhǔ wǔ fēnzhōng jiù xíng.","vn":"Nước sôi rồi, cho mì vào luộc năm phút là được."},{"cn":"我妈每天早上都给我煮鸡蛋吃。","pinyin":"Wǒ mā měi tiān zǎoshang dōu gěi wǒ zhǔ jīdàn chī.","vn":"Sáng nào mẹ tôi cũng luộc trứng cho tôi ăn."},{"cn":"这锅汤已经煮了两个小时了，应该很入味了。","pinyin":"Zhè guō tāng yǐjīng zhǔ le liǎng ge xiǎoshí le, yīnggāi hěn rùwèi le.","vn":"Nồi canh này đã nấu được hai tiếng rồi, chắc ngấm gia vị lắm rồi."}]},{"hanzi":"油","pinyin":"yóu","pos":"dt.","vn":"dầu","examples":[{"cn":"这道菜放了太多油，吃起来有点腻。","pinyin":"Zhè dào cài fàng le tài duō yóu, chī qǐlái yǒudiǎn nì.","vn":"Món này cho nhiều dầu quá, ăn hơi ngấy."},{"cn":"锅里的油热了以后再把葱花放进去炒。","pinyin":"Guō lǐ de yóu rè le yǐhòu zài bǎ cōnghuā fàng jìnqù chǎo.","vn":"Đợi dầu trong chảo nóng rồi mới cho hành lá vào xào."},{"cn":"医生让我少吃油，多吃清淡的东西。","pinyin":"Yīshēng ràng wǒ shǎo chī yóu, duō chī qīngdàn de dōngxi.","vn":"Bác sĩ bảo tôi ăn ít dầu mỡ, ăn nhiều đồ thanh đạm hơn."}]},{"hanzi":"道","pinyin":"dào","pos":"lượng.","vn":"(lượng từ chỉ món ăn, công đoạn...)","examples":[{"cn":"今天晚上我们点了十道菜，够吃了吧。","pinyin":"Jīntiān wǎnshang wǒmen diǎn le shí dào cài, gòu chī le ba.","vn":"Tối nay chúng tôi gọi mười món rồi, đủ ăn rồi nhỉ."},{"cn":"这道菜的做法其实挺简单的。","pinyin":"Zhè dào cài de zuòfǎ qíshí tǐng jiǎndān de.","vn":"Cách làm món này thật ra khá đơn giản."},{"cn":"服务员，再给我们上一道汤吧。","pinyin":"Fúwùyuán, zài gěi wǒmen shàng yí dào tāng ba.","vn":"Phục vụ ơi, cho chúng tôi thêm một món canh nữa nhé."}]},{"hanzi":"熟","pinyin":"shú/shóu","pos":"tt.","vn":"chín; quen thuộc","examples":[{"cn":"肉还没熟呢，再煮一会儿吧。","pinyin":"Ròu hái méi shú ne, zài zhǔ yíhuìr ba.","vn":"Thịt chưa chín đâu, nấu thêm một lúc nữa đi."},{"cn":"我们俩认识十几年了，关系很熟。","pinyin":"Wǒmen liǎ rènshi shí jǐ nián le, guānxi hěn shú.","vn":"Hai chúng tôi quen nhau hơn chục năm rồi, quan hệ rất thân."},{"cn":"这条路我走得很熟，闭着眼睛都能走。","pinyin":"Zhè tiáo lù wǒ zǒu de hěn shú, bì zhe yǎnjing dōu néng zǒu.","vn":"Con đường này tôi đi quen lắm rồi, nhắm mắt cũng đi được."}]},{"hanzi":"倒","pinyin":"dào","pos":"dgt.","vn":"đổ, rót","examples":[{"cn":"服务员帮我们把茶倒上了。","pinyin":"Fúwùyuán bāng wǒmen bǎ chá dào shàng le.","vn":"Phục vụ đã rót trà giúp chúng tôi."},{"cn":"小心点，别把汤倒出来了。","pinyin":"Xiǎoxīn diǎn, bié bǎ tāng dào chūlái le.","vn":"Cẩn thận chút, đừng để canh đổ ra ngoài."},{"cn":"你先把油倒进锅里，然后再放菜。","pinyin":"Nǐ xiān bǎ yóu dào jìn guō lǐ, ránhòu zài fàng cài.","vn":"Bạn đổ dầu vào chảo trước, rồi mới cho rau vào."}]},{"hanzi":"辣椒","pinyin":"làjiāo","pos":"dt.","vn":"ớt","examples":[{"cn":"四川菜里放的辣椒特别多。","pinyin":"Sìchuān cài lǐ fàng de làjiāo tèbié duō.","vn":"Món ăn Tứ Xuyên cho rất nhiều ớt."},{"cn":"我不太能吃辣椒，一点点就受不了。","pinyin":"Wǒ bú tài néng chī làjiāo, yìdiǎndiǎn jiù shòu bu liǎo.","vn":"Tôi không ăn ớt được mấy, chỉ một chút là chịu không nổi."},{"cn":"妈妈在阳台上种了几棵辣椒。","pinyin":"Māma zài yángtái shang zhòng le jǐ kē làjiāo.","vn":"Mẹ trồng mấy cây ớt trên ban công."}]},{"hanzi":"辣","pinyin":"là","pos":"tt.","vn":"cay","examples":[{"cn":"这个菜太辣了，我吃不下去。","pinyin":"Zhège cài tài là le, wǒ chī bu xiàqù.","vn":"Món này cay quá, tôi không ăn nổi."},{"cn":"你能吃辣吗？要不要少放点辣椒？","pinyin":"Nǐ néng chī là ma? Yào bu yào shǎo fàng diǎn làjiāo?","vn":"Bạn ăn cay được không? Có cần cho ít ớt lại không?"},{"cn":"湖南人口味一般比较辣。","pinyin":"Húnán rén kǒuwèi yìbān bǐjiào là.","vn":"Người Hồ Nam nói chung khẩu vị khá cay."}]},{"hanzi":"水煮鱼","pinyin":"Shuǐzhǔyú","pos":"danh từ riêng","vn":"Cá om nước kiểu Tứ Xuyên (Thủy chử ngư)","examples":[{"cn":"我们点一份水煮鱼吧，这家店做得特别好吃。","pinyin":"Wǒmen diǎn yí fèn Shuǐzhǔyú ba, zhè jiā diàn zuò de tèbié hǎochī.","vn":"Chúng ta gọi một phần cá om nước kiểu Tứ Xuyên đi, quán này làm ngon lắm."},{"cn":"水煮鱼虽然看着红红的，但其实没有那么辣。","pinyin":"Shuǐzhǔyú suīrán kàn zhe hónghóng de, dàn qíshí méiyǒu nàme là.","vn":"Cá om nước tuy nhìn đỏ rực nhưng thật ra không cay đến thế."},{"cn":"第一次吃水煮鱼的时候，我被辣得直流汗。","pinyin":"Dì yī cì chī Shuǐzhǔyú de shíhou, wǒ bèi là de zhí liú hàn.","vn":"Lần đầu ăn cá om nước, tôi bị cay đến chảy mồ hôi liên tục."}]},{"hanzi":"敢","pinyin":"gǎn","pos":"dgt.","vn":"dám","examples":[{"cn":"我不敢一个人走夜路。","pinyin":"Wǒ bù gǎn yí ge rén zǒu yèlù.","vn":"Tôi không dám đi đường đêm một mình."},{"cn":"你敢不敢吃这么辣的辣椒？","pinyin":"Nǐ gǎn bu gǎn chī zhème là de làjiāo?","vn":"Bạn có dám ăn quả ớt cay thế này không?"},{"cn":"他是我们班最敢说话的人。","pinyin":"Tā shì wǒmen bān zuì gǎn shuōhuà de rén.","vn":"Anh ấy là người dám nói nhất lớp chúng tôi."}]},{"hanzi":"肚子","pinyin":"dùzi","pos":"dt.","vn":"bụng","examples":[{"cn":"我肚子饿了，咱们快点吃饭吧。","pinyin":"Wǒ dùzi è le, zánmen kuài diǎn chīfàn ba.","vn":"Bụng tôi đói rồi, chúng ta ăn cơm nhanh lên đi."},{"cn":"吃坏肚子了，一直跑厕所。","pinyin":"Chī huài dùzi le, yìzhí pǎo cèsuǒ.","vn":"Ăn hỏng bụng rồi, cứ phải chạy toilet suốt."},{"cn":"吃得太饱了，肚子都撑了。","pinyin":"Chī de tài bǎo le, dùzi dōu chēng le.","vn":"Ăn no quá, bụng căng cứng luôn."}]},{"hanzi":"相同","pinyin":"xiāngtóng","pos":"tt.","vn":"giống nhau","examples":[{"cn":"我们俩的想法完全相同。","pinyin":"Wǒmen liǎ de xiǎngfǎ wánquán xiāngtóng.","vn":"Suy nghĩ của hai chúng tôi hoàn toàn giống nhau."},{"cn":"这两件衣服的颜色不太相同。","pinyin":"Zhè liǎng jiàn yīfu de yánsè bú tài xiāngtóng.","vn":"Màu sắc của hai chiếc áo này không hoàn toàn giống nhau."},{"cn":"每个人对这件事的看法都不相同。","pinyin":"Měi ge rén duì zhè jiàn shì de kànfǎ dōu bù xiāngtóng.","vn":"Mỗi người có cách nhìn về việc này đều khác nhau."}]},{"hanzi":"顺序","pinyin":"shùnxù","pos":"dt.","vn":"thứ tự, trình tự","examples":[{"cn":"请大家按顺序排队上车。","pinyin":"Qǐng dàjiā àn shùnxù páiduì shàng chē.","vn":"Mời mọi người xếp hàng theo thứ tự lên xe."},{"cn":"这些照片的顺序乱了，我重新排一下。","pinyin":"Zhèxiē zhàopiàn de shùnxù luàn le, wǒ chóngxīn pái yíxià.","vn":"Thứ tự mấy tấm ảnh này bị lộn rồi, tôi sắp lại một chút."},{"cn":"做菜也有顺序，先放什么后放什么很重要。","pinyin":"Zuò cài yě yǒu shùnxù, xiān fàng shénme hòu fàng shénme hěn zhòngyào.","vn":"Nấu ăn cũng có thứ tự, cho gì trước cho gì sau rất quan trọng."}]},{"hanzi":"够","pinyin":"gòu","pos":"phó./dgt.","vn":"khá, đủ mức; đủ","examples":[{"cn":"这些钱够不够买一台新手机？","pinyin":"Zhèxiē qián gòu bu gòu mǎi yì tái xīn shǒujī?","vn":"Số tiền này có đủ mua một chiếc điện thoại mới không?"},{"cn":"好了好了，够了，别再给我夹菜了。","pinyin":"Hǎo le hǎo le, gòu le, bié zài gěi wǒ jiā cài le.","vn":"Được rồi được rồi, đủ rồi, đừng gắp thêm thức ăn cho tôi nữa."},{"cn":"他已经够努力了，结果还是没考上。","pinyin":"Tā yǐjīng gòu nǔlì le, jiéguǒ háishi méi kǎo shàng.","vn":"Anh ấy đã đủ nỗ lực rồi, nhưng kết quả vẫn không thi đỗ."}]},{"hanzi":"不够","pinyin":"búgòu","pos":"phó./dgt.","vn":"không đủ","examples":[{"cn":"这点钱不够付房租的。","pinyin":"Zhè diǎn qián búgòu fù fángzū de.","vn":"Số tiền này không đủ để trả tiền thuê nhà."},{"cn":"我觉得你对他不够尊重。","pinyin":"Wǒ juéde nǐ duì tā búgòu zūnzhòng.","vn":"Tôi thấy bạn đối với anh ấy không đủ tôn trọng."},{"cn":"时间不够了，我们得快点走了。","pinyin":"Shíjiān búgòu le, wǒmen děi kuài diǎn zǒu le.","vn":"Thời gian không đủ nữa rồi, chúng ta phải đi nhanh thôi."}]},{"hanzi":"达到","pinyin":"dádào","pos":"dgt.","vn":"đạt đến, đạt tới","examples":[{"cn":"他终于达到了自己的目标。","pinyin":"Tā zhōngyú dádào le zìjǐ de mùbiāo.","vn":"Anh ấy cuối cùng đã đạt được mục tiêu của mình."},{"cn":"这次考试的成绩没有达到我的预期。","pinyin":"Zhè cì kǎoshì de chéngjì méiyǒu dádào wǒ de yùqī.","vn":"Kết quả kỳ thi lần này chưa đạt được kỳ vọng của tôi."},{"cn":"气温已经达到了三十五度。","pinyin":"Qìwēn yǐjīng dádào le sānshíwǔ dù.","vn":"Nhiệt độ đã đạt tới ba mươi lăm độ."}]},{"hanzi":"聚","pinyin":"jù","pos":"dgt.","vn":"tụ họp","examples":[{"cn":"周末我们几个老同学聚一聚吧。","pinyin":"Zhōumò wǒmen jǐ ge lǎo tóngxué jù yi jù ba.","vn":"Cuối tuần mấy bạn cũ chúng ta tụ tập lại đi."},{"cn":"放假了，一家人终于能聚在一起了。","pinyin":"Fàngjià le, yì jiā rén zhōngyú néng jù zài yìqǐ le.","vn":"Nghỉ lễ rồi, cả nhà cuối cùng cũng tụ họp được với nhau."},{"cn":"很多人聚在门口，不知道发生了什么事。","pinyin":"Hěn duō rén jù zài ménkǒu, bù zhīdào fāshēng le shénme shì.","vn":"Rất nhiều người tụ tập ở cửa, không biết đã xảy ra chuyện gì."}]},{"hanzi":"午餐","pinyin":"wǔcān","pos":"dt.","vn":"bữa trưa","examples":[{"cn":"我们公司的午餐是免费的。","pinyin":"Wǒmen gōngsī de wǔcān shì miǎnfèi de.","vn":"Bữa trưa ở công ty chúng tôi được miễn phí."},{"cn":"午餐时间到了，我们一起去吃饭吧。","pinyin":"Wǔcān shíjiān dào le, wǒmen yìqǐ qù chīfàn ba.","vn":"Đến giờ ăn trưa rồi, chúng ta cùng đi ăn cơm đi."},{"cn":"今天午餐我随便吃了点面包。","pinyin":"Jīntiān wǔcān wǒ suíbiàn chī le diǎn miànbāo.","vn":"Hôm nay bữa trưa tôi ăn qua loa mấy miếng bánh mì."}]},{"hanzi":"咸","pinyin":"xián","pos":"tt.","vn":"mặn","examples":[{"cn":"这个汤有点咸，加点水吧。","pinyin":"Zhège tāng yǒudiǎn xián, jiā diǎn shuǐ ba.","vn":"Canh này hơi mặn, cho thêm chút nước đi."},{"cn":"我口味比较清淡，不喜欢太咸的菜。","pinyin":"Wǒ kǒuwèi bǐjiào qīngdàn, bù xǐhuan tài xián de cài.","vn":"Khẩu vị tôi khá thanh đạm, không thích món quá mặn."},{"cn":"放盐的时候小心点，别放太咸了。","pinyin":"Fàng yán de shíhou xiǎoxīn diǎn, bié fàng tài xián le.","vn":"Lúc cho muối chú ý một chút, đừng cho mặn quá."}]},{"hanzi":"凉","pinyin":"liáng","pos":"tt.","vn":"nguội, mát; (món) nguội","examples":[{"cn":"饭凉了，我给你热一下吧。","pinyin":"Fàn liáng le, wǒ gěi nǐ rè yíxià ba.","vn":"Cơm nguội rồi, để tôi hâm nóng lại cho bạn nhé."},{"cn":"今天天气有点凉，多穿件衣服吧。","pinyin":"Jīntiān tiānqì yǒudiǎn liáng, duō chuān jiàn yīfu ba.","vn":"Hôm nay trời hơi mát lạnh, mặc thêm áo đi."},{"cn":"夏天我最喜欢吃凉面了。","pinyin":"Xiàtiān wǒ zuì xǐhuan chī liángmiàn le.","vn":"Mùa hè tôi thích nhất ăn mì lạnh."}]},{"hanzi":"酸","pinyin":"suān","pos":"tt.","vn":"chua","examples":[{"cn":"这个水果有点酸，不太甜。","pinyin":"Zhège shuǐguǒ yǒudiǎn suān, bú tài tián.","vn":"Loại trái cây này hơi chua, không ngọt lắm."},{"cn":"我怀孕的时候特别爱吃酸的东西。","pinyin":"Wǒ huáiyùn de shíhou tèbié ài chī suān de dōngxi.","vn":"Lúc mang thai tôi đặc biệt thích ăn đồ chua."},{"cn":"跑完步以后，我的腿有点酸。","pinyin":"Pǎo wán bù yǐhòu, wǒ de tuǐ yǒudiǎn suān.","vn":"Chạy bộ xong, chân tôi hơi mỏi."}]},{"hanzi":"汤","pinyin":"tāng","pos":"dt.","vn":"canh, súp","examples":[{"cn":"妈妈每天都给我们做一锅汤。","pinyin":"Māma měi tiān dōu gěi wǒmen zuò yì guō tāng.","vn":"Mẹ ngày nào cũng nấu một nồi canh cho chúng tôi."},{"cn":"你多喝点汤，暖暖身子。","pinyin":"Nǐ duō hē diǎn tāng, nuǎnnuǎn shēnzi.","vn":"Bạn uống nhiều canh một chút cho ấm người."},{"cn":"这家店的酸汤米线特别有名。","pinyin":"Zhè jiā diàn de suāntāng mǐxiàn tèbié yǒumíng.","vn":"Món bún nước chua của quán này nổi tiếng lắm."}]},{"hanzi":"各","pinyin":"gè","pos":"phó./đt.","vn":"mỗi, từng","examples":[{"cn":"大家各坐各的位置吧。","pinyin":"Dàjiā gè zuò gè de wèizhi ba.","vn":"Mọi người ai ngồi vị trí người nấy nhé."},{"cn":"各地的饮食习惯都不太一样。","pinyin":"Gè dì de yǐnshí xíguàn dōu bú tài yíyàng.","vn":"Thói quen ăn uống ở mỗi nơi đều không giống nhau."},{"cn":"这件事各有各的看法，很难说谁对谁错。","pinyin":"Zhè jiàn shì gè yǒu gè de kànfǎ, hěn nán shuō shéi duì shéi cuò.","vn":"Việc này mỗi người một ý, khó mà nói ai đúng ai sai."}]},{"hanzi":"付","pinyin":"fù","pos":"dgt.","vn":"trả (tiền)","examples":[{"cn":"这顿饭我来付钱吧。","pinyin":"Zhè dùn fàn wǒ lái fù qián ba.","vn":"Bữa này để tôi trả tiền nhé."},{"cn":"你可以用手机付款。","pinyin":"Nǐ kěyǐ yòng shǒujī fùkuǎn.","vn":"Bạn có thể dùng điện thoại để thanh toán."},{"cn":"房租得每个月按时付。","pinyin":"Fángzū děi měi ge yuè ànshí fù.","vn":"Tiền thuê nhà phải trả đúng hạn mỗi tháng."}]},{"hanzi":"聚餐","pinyin":"jùcān","pos":"dgt.","vn":"ăn tụ tập, liên hoan","examples":[{"cn":"今晚公司组织聚餐，大家都要参加。","pinyin":"Jīnwǎn gōngsī zǔzhī jùcān, dàjiā dōu yào cānjiā.","vn":"Tối nay công ty tổ chức liên hoan, mọi người đều phải tham gia."},{"cn":"周末我们班要去聚餐庆祝一下。","pinyin":"Zhōumò wǒmen bān yào qù jùcān qìngzhù yíxià.","vn":"Cuối tuần lớp chúng tôi sẽ đi liên hoan ăn mừng một chút."},{"cn":"好久没和老朋友聚餐了，真想他们。","pinyin":"Hǎojiǔ méi hé lǎo péngyou jùcān le, zhēn xiǎng tāmen.","vn":"Lâu rồi không đi ăn tụ tập với bạn cũ, thật sự nhớ họ."}]},{"hanzi":"辣子鸡","pinyin":"Làzijī","pos":"danh từ riêng","vn":"Gà xào ớt (Lạt tử kê)","examples":[{"cn":"这家馆子的辣子鸡做得特别地道。","pinyin":"Zhè jiā guǎnzi de làzijī zuò de tèbié dìdao.","vn":"Món gà xào ớt của quán này làm rất chuẩn vị."},{"cn":"我第一次吃辣子鸡的时候，被里面的辣椒吓了一跳。","pinyin":"Wǒ dì yī cì chī làzijī de shíhou, bèi lǐmiàn de làjiāo xià le yí tiào.","vn":"Lần đầu tiên ăn gà xào ớt, tôi bị đống ớt trong đó làm giật mình."},{"cn":"来重庆一定要尝尝正宗的辣子鸡。","pinyin":"Lái Chóngqìng yídìng yào chángchang zhèngzōng de làzijī.","vn":"Đến Trùng Khánh nhất định phải thử món gà xào ớt chính gốc."}]},{"hanzi":"松鼠鼟鱼","pinyin":"Sōngshǔ Guìyú","pos":"danh từ riêng","vn":"Cá quế hình sóc (Tùng thử quế ngư)","examples":[{"cn":"松鼠鼟鱼的样子看起来真的很像一只小松鼠。","pinyin":"Sōngshǔ Guìyú de yàngzi kàn qǐlái zhēnde hěn xiàng yì zhī xiǎo sōngshǔ.","vn":"Món cá quế hình sóc trông thật sự rất giống một chú sóc nhỏ."},{"cn":"这家饭店的松鼠鼟鱼味道又酸又甜，很好吃。","pinyin":"Zhè jiā fàndiàn de Sōngshǔ Guìyú wèidao yòu suān yòu tián, hěn hǎochī.","vn":"Món cá quế hình sóc của nhà hàng này vị vừa chua vừa ngọt, rất ngon."},{"cn":"朋友过生日，我们特意点了一道松鼠鼟鱼。","pinyin":"Péngyou guò shēngrì, wǒmen tèyì diǎn le yí dào Sōngshǔ Guìyú.","vn":"Bạn tôi sinh nhật, chúng tôi cố tình gọi riêng một món cá quế hình sóc."}]},{"hanzi":"红烧羊肉","pinyin":"Hóngshāo Yángròu","pos":"danh từ riêng","vn":"Thịt cừu kho đỏ","examples":[{"cn":"冬天吃一碗红烧羊肉，浑身都暖和了。","pinyin":"Dōngtiān chī yì wǎn Hóngshāo Yángròu, húnshēn dōu nuǎnhuo le.","vn":"Mùa đông ăn một bát thịt cừu kho đỏ là cả người ấm hẳn lên."},{"cn":"我妈做的红烧羊肉一点都不腥。","pinyin":"Wǒ mā zuò de Hóngshāo Yángròu yìdiǎn dōu bù xīng.","vn":"Thịt cừu kho đỏ mẹ tôi làm chẳng có mùi gây chút nào."},{"cn":"今天餐厅的特色菜是红烧羊肉。","pinyin":"Jīntiān cāntīng de tèsè cài shì Hóngshāo Yángròu.","vn":"Món đặc sản của nhà hàng hôm nay là thịt cừu kho đỏ."}]},{"hanzi":"贵州","pinyin":"Guìzhōu","pos":"danh từ riêng","vn":"tỉnh Quý Châu","examples":[{"cn":"贵州的风景非常美，很多人都喜欢去那儿旅游。","pinyin":"Guìzhōu de fēngjǐng fēicháng měi, hěn duō rén dōu xǐhuan qù nàr lǚyóu.","vn":"Phong cảnh Quý Châu rất đẹp, nhiều người thích đến đó du lịch."},{"cn":"他是贵州人，口味偏酸辣。","pinyin":"Tā shì Guìzhōu rén, kǒuwèi piān suān là.","vn":"Anh ấy là người Quý Châu, khẩu vị thiên về chua cay."},{"cn":"这次出差，我要去贵州待一个星期。","pinyin":"Zhè cì chūchāi, wǒ yào qù Guìzhōu dāi yí ge xīngqī.","vn":"Chuyến công tác này tôi sẽ ở Quý Châu một tuần."}]},{"hanzi":"酸汤米线","pinyin":"Suāntāng Mǐxiàn","pos":"danh từ riêng","vn":"Bún nước chua","examples":[{"cn":"贵州的酸汤米线闻起来很香，味道又酸又开胃。","pinyin":"Guìzhōu de suāntāng mǐxiàn wén qǐlái hěn xiāng, wèidao yòu suān yòu kāiwèi.","vn":"Bún nước chua Quý Châu ngửi rất thơm, vị vừa chua vừa kích thích vị giác."},{"cn":"我中午点了一碗酸汤米线当午餐。","pinyin":"Wǒ zhōngwǔ diǎn le yì wǎn suāntāng mǐxiàn dāng wǔcān.","vn":"Trưa nay tôi gọi một bát bún nước chua làm bữa trưa."},{"cn":"天冷的时候来一碗热乎乎的酸汤米线最舒服了。","pinyin":"Tiān lěng de shíhou lái yì wǎn rèhūhū de suāntāng mǐxiàn zuì shūfu le.","vn":"Trời lạnh mà ăn một bát bún nước chua nóng hổi thì sướng nhất."}]},{"hanzi":"随意","pinyin":"suíyì","pos":"tt.","vn":"tùy ý, thoải mái","examples":[{"cn":"大家随意坐，不用客气。","pinyin":"Dàjiā suíyì zuò, búyòng kèqi.","vn":"Mọi người cứ ngồi tùy ý, không cần khách sáo."},{"cn":"这顿饭不用太正式，随意吃点就行。","pinyin":"Zhè dùn fàn búyòng tài zhèngshì, suíyì chī diǎn jiù xíng.","vn":"Bữa này không cần quá trang trọng, ăn tùy ý một chút là được."},{"cn":"他做事一向很随意，从来不喜欢计划。","pinyin":"Tā zuòshì yíxiàng hěn suíyì, cónglái bù xǐhuan jìhuà.","vn":"Anh ấy làm việc luôn rất tùy hứng, chưa bao giờ thích lập kế hoạch."}]},{"hanzi":"正式","pinyin":"zhèngshì","pos":"tt.","vn":"chính thức","examples":[{"cn":"我们公司下个月才正式开业。","pinyin":"Wǒmen gōngsī xià ge yuè cái zhèngshì kāiyè.","vn":"Công ty chúng tôi tháng sau mới chính thức khai trương."},{"cn":"这是正式的邀请函，请大家按时出席。","pinyin":"Zhè shì zhèngshì de yāoqǐng hán, qǐng dàjiā ànshí chūxí.","vn":"Đây là thư mời chính thức, mời mọi người đến đúng giờ."},{"cn":"他今天穿得特别正式，是不是要去面试？","pinyin":"Tā jīntiān chuān de tèbié zhèngshì, shì bu shì yào qù miànshì?","vn":"Hôm nay anh ấy ăn mặc rất chỉnh tề, có phải sắp đi phỏng vấn không?"}]},{"hanzi":"普通","pinyin":"pǔtōng","pos":"tt.","vn":"bình thường, phổ thông","examples":[{"cn":"我只是一个普通的上班族。","pinyin":"Wǒ zhǐshì yí ge pǔtōng de shàngbānzú.","vn":"Tôi chỉ là một dân văn phòng bình thường."},{"cn":"这家饭店装修得很普通，但菜做得特别好吃。","pinyin":"Zhè jiā fàndiàn zhuāngxiū de hěn pǔtōng, dàn cài zuò de tèbié hǎochī.","vn":"Nhà hàng này trang trí rất bình thường nhưng món ăn nấu cực ngon."},{"cn":"这件事其实很普通，没什么好大惊小怪的。","pinyin":"Zhè jiàn shì qíshí hěn pǔtōng, méi shénme hǎo dàjīngxiǎoguài de.","vn":"Việc này thật ra rất bình thường, chẳng có gì phải ầm ĩ cả."}]},{"hanzi":"重视","pinyin":"zhòngshì","pos":"dgt.","vn":"coi trọng","examples":[{"cn":"这家公司非常重视员工的意见。","pinyin":"Zhè jiā gōngsī fēicháng zhòngshì yuángōng de yìjiàn.","vn":"Công ty này rất coi trọng ý kiến của nhân viên."},{"cn":"中国人吃饭时很重视座位的安排。","pinyin":"Zhōngguó rén chīfàn shí hěn zhòngshì zuòwèi de ānpái.","vn":"Người Trung Quốc khi ăn cơm rất coi trọng việc sắp xếp chỗ ngồi."},{"cn":"父母应该重视孩子的心理健康。","pinyin":"Fùmǔ yīnggāi zhòngshì háizi de xīnlǐ jiànkāng.","vn":"Bố mẹ nên coi trọng sức khỏe tâm lý của con cái."}]},{"hanzi":"座位","pinyin":"zuòwèi","pos":"dt.","vn":"chỗ ngồi","examples":[{"cn":"请问，这个座位有人坐吗？","pinyin":"Qǐngwèn, zhège zuòwèi yǒu rén zuò ma?","vn":"Xin hỏi, chỗ ngồi này có ai ngồi chưa ạ?"},{"cn":"服务员帮我们安排了一个靠窗的座位。","pinyin":"Fúwùyuán bāng wǒmen ānpái le yí ge kào chuāng de zuòwèi.","vn":"Phục vụ đã sắp xếp cho chúng tôi một chỗ ngồi cạnh cửa sổ."},{"cn":"电影院里的座位都是按号对号入座的。","pinyin":"Diànyǐngyuàn lǐ de zuòwèi dōu shì àn hào duìhào rùzuò de.","vn":"Chỗ ngồi trong rạp chiếu phim đều ngồi đúng theo số ghế."}]},{"hanzi":"安排","pinyin":"ānpái","pos":"dgt.","vn":"sắp xếp","examples":[{"cn":"这次旅行你帮我安排一下行程吧。","pinyin":"Zhè cì lǚxíng nǐ bāng wǒ ānpái yíxià xíngchéng ba.","vn":"Chuyến đi lần này bạn giúp tôi sắp xếp lịch trình một chút nhé."},{"cn":"老板把这个项目安排给了我。","pinyin":"Lǎobǎn bǎ zhège xiàngmù ānpái gěi le wǒ.","vn":"Sếp đã giao dự án này cho tôi."},{"cn":"我最近工作太忙，什么都没时间安排。","pinyin":"Wǒ zuìjìn gōngzuò tài máng, shénme dōu méi shíjiān ānpái.","vn":"Dạo này tôi làm việc bận quá, chẳng có thời gian sắp xếp gì cả."}]},{"hanzi":"按照","pinyin":"ànzhào","pos":"giới.","vn":"theo, dựa theo","examples":[{"cn":"请按照说明书上的步骤操作。","pinyin":"Qǐng ànzhào shuōmíngshū shang de bùzhòu cāozuò.","vn":"Hãy thao tác theo đúng các bước trong sách hướng dẫn."},{"cn":"我们应该按照年龄大小来安排座位。","pinyin":"Wǒmen yīnggāi ànzhào niánlíng dàxiǎo lái ānpái zuòwèi.","vn":"Chúng ta nên sắp xếp chỗ ngồi theo thứ tự tuổi tác."},{"cn":"一切都按照计划进行，没出什么问题。","pinyin":"Yíqiè dōu ànzhào jìhuà jìnxíng, méi chū shénme wèntí.","vn":"Mọi việc đều diễn ra theo đúng kế hoạch, không có vấn đề gì."}]},{"hanzi":"年龄","pinyin":"niánlíng","pos":"dt.","vn":"tuổi tác","examples":[{"cn":"请问您的年龄是多少？","pinyin":"Qǐngwèn nín de niánlíng shì duōshao?","vn":"Xin hỏi anh/chị bao nhiêu tuổi ạ?"},{"cn":"这份工作对年龄没有要求。","pinyin":"Zhè fèn gōngzuò duì niánlíng méiyǒu yāoqiú.","vn":"Công việc này không yêu cầu về tuổi tác."},{"cn":"随着年龄的增长，他越来越稳重了。","pinyin":"Suízhe niánlíng de zēngzhǎng, tā yuè lái yuè wěnzhòng le.","vn":"Cùng với tuổi tác tăng lên, anh ấy ngày càng chín chắn hơn."}]},{"hanzi":"面对","pinyin":"miànduì","pos":"dgt.","vn":"đối diện","examples":[{"cn":"我们应该勇敢地面对困难。","pinyin":"Wǒmen yīnggāi yǒnggǎn de miànduì kùnnan.","vn":"Chúng ta nên dũng cảm đối diện với khó khăn."},{"cn":"面对老师的提问，他一时不知道怎么回答。","pinyin":"Miànduì lǎoshī de tíwèn, tā yìshí bù zhīdào zěnme huídá.","vn":"Đối diện với câu hỏi của thầy giáo, cậu ấy nhất thời không biết trả lời thế nào."},{"cn":"吃饭的时候，长辈一般坐在面对门口的位置。","pinyin":"Chīfàn de shíhou, zhǎngbèi yìbān zuò zài miànduì ménkǒu de wèizhi.","vn":"Khi ăn cơm, người lớn tuổi thường ngồi ở vị trí hướng mặt ra cửa."}]},{"hanzi":"主人","pinyin":"zhǔrén","pos":"dt.","vn":"chủ nhà","examples":[{"cn":"作为主人，他对每位客人都照顾得很周到。","pinyin":"Zuòwéi zhǔrén, tā duì měi wèi kèrén dōu zhàogu de hěn zhōudào.","vn":"Là chủ nhà, anh ấy chăm sóc từng vị khách rất chu đáo."},{"cn":"客人到了，主人赶紧出来迎接。","pinyin":"Kèrén dào le, zhǔrén gǎnjǐn chūlái yíngjiē.","vn":"Khách đến rồi, chủ nhà vội vàng ra đón."},{"cn":"这只狗很听主人的话。","pinyin":"Zhè zhī gǒu hěn tīng zhǔrén de huà.","vn":"Con chó này rất nghe lời chủ của nó."}]},{"hanzi":"等","pinyin":"děng","pos":"giới.","vn":"đợi đến, chờ đến","examples":[{"cn":"等老板来了，我们再开始开会吧。","pinyin":"Děng lǎobǎn lái le, wǒmen zài kāishǐ kāihuì ba.","vn":"Đợi sếp đến rồi chúng ta mới bắt đầu họp."},{"cn":"我们一直等到晚上十点，他才到。","pinyin":"Wǒmen yìzhí děng dào wǎnshang shí diǎn, tā cái dào.","vn":"Chúng tôi đợi mãi đến mười giờ tối, anh ấy mới đến."},{"cn":"等菜都上齐了，大家才动筷子。","pinyin":"Děng cài dōu shàng qí le, dàjiā cái dòng kuàizi.","vn":"Đợi món ăn được bày đủ hết, mọi người mới bắt đầu cầm đũa."}]},{"hanzi":"尊重","pinyin":"zūnzhòng","pos":"dgt.","vn":"tôn trọng","examples":[{"cn":"我们应该尊重每一位长辈。","pinyin":"Wǒmen yīnggāi zūnzhòng měi yí wèi zhǎngbèi.","vn":"Chúng ta nên tôn trọng mỗi vị trưởng bối."},{"cn":"无论做什么决定，都要尊重孩子自己的意见。","pinyin":"Wúlùn zuò shénme juédìng, dōu yào zūnzhòng háizi zìjǐ de yìjiàn.","vn":"Dù đưa ra quyết định gì cũng phải tôn trọng ý kiến riêng của con cái."},{"cn":"他虽然是老板，但对员工一直很尊重。","pinyin":"Tā suīrán shì lǎobǎn, dàn duì yuángōng yìzhí hěn zūnzhòng.","vn":"Tuy là sếp nhưng anh ấy luôn tôn trọng nhân viên."}]}],"grammar":[{"title":"范围副词“至少” Phó từ chỉ phạm vi “至少”","explanation_vn":"Phó từ chỉ phạm vi \"至少\" biểu thị thời gian, số lượng, mức độ... không thấp hơn một giới hạn tối thiểu nào đó.","examples":[{"cn":"家月，你来中国至少两个月了，习惯吃中餐了吗？","pinyin":"","vn":"Gia Nguyệt, em đến Trung Quốc ít nhất đã hai tháng rồi, đã quen ăn món Trung chưa?"},{"cn":"每年至少有两百名留学生来我校学习中文专业。","pinyin":"","vn":"Mỗi năm có ít nhất hai trăm du học sinh đến trường chúng tôi học chuyên ngành tiếng Trung."},{"cn":"我们虽然没有见过面，但至少在网上聊过很多次，也算比较熟悉了。","pinyin":"","vn":"Tuy chúng tôi chưa gặp mặt nhau, nhưng ít nhất cũng đã trò chuyện trên mạng nhiều lần, cũng coi như khá quen biết rồi."}]},{"title":"副词/动词“够” Phó từ/Động từ “够”","explanation_vn":"\"够\" có hai từ loại: (1) phó từ, biểu thị mức độ cao, thường dùng trong cấu trúc cố định \"够……的\"; (2) động từ, biểu thị về số lượng đáp ứng đủ nhu cầu hoặc đạt đến một tiêu chuẩn, mức độ nào đó.","examples":[{"cn":"你的中文水平够高的，这都听懂了！","pinyin":"","vn":"Trình độ tiếng Trung của bạn khá cao đấy, cái này cũng nghe hiểu được!"},{"cn":"明天请家月和李文来家里吃饭，四个菜够不够？","pinyin":"","vn":"Ngày mai mời Gia Nguyệt và Lý Văn đến nhà ăn cơm, bốn món có đủ không?"},{"cn":"我尝了一下，还不够甸，再加一点儿糖吧。","pinyin":"","vn":"Tôi nếm thử rồi, vẫn chưa đủ ngọt, cho thêm chút đường nữa đi."}]},{"title":"固定格式“各×各的” Cấu trúc cố định “各×各的”","explanation_vn":"Cấu trúc cố định \"各×各的\" biểu thị mỗi người độc lập thực hiện cùng một loại hành động, không ảnh hưởng lẫn nhau.","examples":[{"cn":"大家觉得还是各付各的更合适。","pinyin":"","vn":"Mọi người cảm thấy ai trả tiền của người đó thì hợp lý hơn."},{"cn":"到了办公室，大家就开始各忙各的了。","pinyin":"","vn":"Đến văn phòng, mọi người liền bắt đầu ai làm việc của người nấy."},{"cn":"在图书馆里，大家都很安静，各看各的书。","pinyin":"","vn":"Trong thư viện, mọi người đều rất yên lặng, ai đọc sách của người nấy."}]},{"title":"介词“等” Giới từ “等”","explanation_vn":"Trong bài này, \"等\" là giới từ, biểu thị \"đợi đến\", dùng để dẫn ra thời gian, điều kiện.","examples":[{"cn":"如果聚餐时有老人，年轻人要等老人坐下后再坐。","pinyin":"","vn":"Nếu trong bữa tiệc có người lớn tuổi, người trẻ phải đợi người lớn tuổi ngồi xuống rồi mới ngồi."},{"cn":"等我写完作业，再跟你出去玩。","pinyin":"","vn":"Đợi tôi làm xong bài tập rồi sẽ ra ngoài chơi với bạn."},{"cn":"等我们到火车站的时候，火车已经开走了。","pinyin":"","vn":"Đợi đến khi chúng tôi tới ga tàu thì tàu đã chạy mất rồi."}]}],"texts":[{"label":"Bài khóa 1","type":"dialogue","lines":[{"speaker":"刘明","cn":"家月，你来中国至少两个月了，习惯吃中餐了吗？","pinyin":""},{"speaker":"白家月","cn":"习惯了，而且我很喜欢吃中国菜。","pinyin":""},{"speaker":"王一雪","cn":"你还没吃过水煮鱼吧？这是我专门为你做的。","pinyin":""},{"speaker":"白家月","cn":"看起来不像水煮鱼，更像“油煮鱼”。","pinyin":""},{"speaker":"王一雪","cn":"这道菜是先用水把鱼煮熟，最后再倒上辣椒油，其实只有最上面那一层是油。你尝尝，对你来说辣不辣？","pinyin":""},{"speaker":"白家月","cn":"辣是辣，但是非常好吃！","pinyin":""},{"speaker":"王一雪","cn":"那你多吃点儿，不要客气。","pinyin":""}],"translation_vn":"Lưu Minh: Gia Nguyệt, em đến Trung Quốc ít nhất đã hai tháng rồi, đã quen ăn món Trung chưa?\nBạch Gia Nguyệt: Quen rồi ạ, với lại em rất thích ăn món Trung Quốc.\nVương Nhất Tuyết: Em chưa ăn cá om kiểu Tứ Xuyên bao giờ đúng không? Đây là món chị làm riêng cho em đấy.\nBạch Gia Nguyệt: Trông không giống cá om nước, mà giống “cá om dầu” hơn.\nVương Nhất Tuyết: Món này là luộc chín cá bằng nước trước, cuối cùng mới đổ dầu ớt lên trên, thực ra chỉ có lớp trên cùng là dầu thôi. Em nếm thử xem, với em thì có cay không?\nBạch Gia Nguyệt: Cay thì cay thật, nhưng rất ngon!\nVương Nhất Tuyết: Vậy em ăn nhiều một chút, đừng khách sáo.","audio_dialogue":"5-1.mp3","audio_vocab":"5-2.mp3"},{"label":"Bài khóa 2","type":"dialogue","lines":[{"speaker":"王一雪","cn":"我听李文说，你现在也爱吃辣了？","pinyin":""},{"speaker":"白家月","cn":"是的，来中国以后，我越来越喜欢吃辣了。","pinyin":""},{"speaker":"王一雪","cn":"我们以前不太敢吃辣，吃完可能会肚子不舒服，不过现在也慢慢适应了。","pinyin":""},{"speaker":"刘明","cn":"对，我们现在都不怕辣了。家月，你是“不怕辣”还是“怕不辣”？","pinyin":""},{"speaker":"白家月","cn":"中文真有意思，相同的字，顺序一换，意思就变了。","pinyin":""},{"speaker":"李文","cn":"你的中文水平够高的，这都听懂了！你说得对，“不怕辣”是说不怕吃辣的菜，“怕不辣”是担心菜还不够辣呢。","pinyin":""},{"speaker":"白家月","cn":"我还达不到“怕不辣”的水平，甚至也不能算“不怕辣”，只是喜欢吃辣。","pinyin":""}],"translation_vn":"Vương Nhất Tuyết: Chị nghe Lý Văn nói, bây giờ em cũng thích ăn cay rồi à?\nBạch Gia Nguyệt: Vâng, sau khi đến Trung Quốc, em ngày càng thích ăn cay hơn.\nVương Nhất Tuyết: Trước đây bọn chị không dám ăn cay lắm, ăn xong có thể bị đau bụng, nhưng giờ cũng dần thích nghi rồi.\nLưu Minh: Đúng vậy, giờ bọn anh đều không sợ cay nữa. Gia Nguyệt, em là kiểu “không sợ cay” hay “sợ không cay”?\nBạch Gia Nguyệt: Tiếng Trung thật thú vị, cùng những chữ đó, chỉ đổi thứ tự là ý nghĩa đã thay đổi rồi.\nLý Văn: Trình độ tiếng Trung của em khá cao đấy, cái này cũng nghe hiểu được! Em nói đúng, “không sợ cay” là nói không sợ ăn món cay, “sợ không cay” là lo món chưa đủ cay đấy.\nBạch Gia Nguyệt: Em còn chưa đạt đến trình độ “sợ không cay”, thậm chí cũng không tính là “không sợ cay”, chỉ là thích ăn cay thôi.","audio_dialogue":"5-3.mp3","audio_vocab":"5-4.mp3"},{"label":"Bài khóa 3","type":"passage","lines":[{"speaker":"","cn":"周末，白家月、陈天中、李文和安妮聚在一起吃午餐。白家月想吃辣的，要了辣子鸡；陈天中爱吃甸的，想尝尝松鼠鼟鱼；李文更喜欢吃咸的，选了红烧羊肉和一道凉菜；安妮听说贵州酸汤很有名，点了酸汤米线。他们边吃边聊，非常愉快。\n结账时，李文想请客，但大家觉得还是各付各的更合适。于是，李文付完钱后，大家把钱转给了他，还笑着说下次再一起聚餐。","pinyin":""}],"translation_vn":"Cuối tuần, Bạch Gia Nguyệt, Trần Thiên Trung, Lý Văn và Annie tụ họp cùng nhau ăn trưa. Bạch Gia Nguyệt muốn ăn cay nên gọi món gà xào ớt; Trần Thiên Trung thích ăn ngọt, muốn nếm thử cá quế hình sóc; Lý Văn lại thích ăn mặn hơn, chọn thịt cừu kho đỏ và một món nguội; Annie nghe nói canh chua Quý Châu rất nổi tiếng nên gọi bún nước chua. Họ vừa ăn vừa trò chuyện, rất vui vẻ.\nKhi thanh toán, Lý Văn muốn mời cả nhóm, nhưng mọi người cảm thấy ai trả tiền của người đó thì hợp lý hơn. Thế là, sau khi Lý Văn trả tiền xong, mọi người chuyển tiền lại cho anh, còn cười nói lần sau lại cùng nhau tụ họp ăn uống.","audio_dialogue":"5-5.mp3","audio_vocab":"5-6.mp3"},{"label":"Bài khóa 4","type":"passage","lines":[{"speaker":"","cn":"今天吃饭的时候，大家坐得比较随意。李文告诉白家月，在中国，正式聚餐和普通聚餐不同，正式聚餐时人们比较重视座位的安排，比如可以按照年龄大小来安排，年龄比较大的客人往往会坐在中间或者面对门口的座位。大家坐下时，主人会请客人先坐。如果聚餐时有老人，年轻人要等老人坐下后再坐。\n白家月听后觉得很有意思，她认为这么做是照顾客人、尊重老人的表现。","pinyin":""}],"translation_vn":"Hôm nay lúc ăn cơm, mọi người ngồi khá tùy ý. Lý Văn nói với Bạch Gia Nguyệt rằng ở Trung Quốc, tụ họp ăn uống chính thức khác với tụ họp thông thường, khi tụ họp chính thức người ta khá coi trọng việc sắp xếp chỗ ngồi, chẳng hạn có thể sắp xếp theo tuổi tác, những vị khách lớn tuổi hơn thường sẽ ngồi ở giữa hoặc chỗ ngồi đối diện cửa ra vào. Khi mọi người ngồi xuống, chủ nhà sẽ mời khách ngồi trước. Nếu trong bữa tiệc có người lớn tuổi, người trẻ phải đợi người lớn tuổi ngồi xuống rồi mới ngồi.\nBạch Gia Nguyệt nghe xong cảm thấy rất thú vị, cô cho rằng làm như vậy là biểu hiện của việc quan tâm khách và tôn trọng người lớn tuổi.","audio_dialogue":"5-7.mp3","audio_vocab":"5-8.mp3"}]},{"id":6,"title_cn":"我陪你去看病","title_pinyin":"","title_vn":"Tôi đưa bạn đi khám bệnh","goals":["Có thể nghe hiểu và trao đổi các thông tin như tình trạng sức khỏe và phương án điều trị.","Có thể diễn đạt bằng lời nói hoặc chữ viết về quá trình đi khám bệnh.","Hiểu được quy trình cơ bản khi đi khám bệnh ở Trung Quốc."],"vocab":[{"hanzi":"咳嗽","pinyin":"késou","pos":"dgt.","vn":"ho","examples":[{"cn":"我最近老咳嗽，也不知道是不是感冒了。","pinyin":"Wǒ zuìjìn lǎo késou, yě bù zhīdào shì bu shì gǎnmào le.","vn":"Dạo này tôi cứ ho mãi, không biết có phải bị cảm không."},{"cn":"孩子咳嗽得厉害，我们赶紧带他去医院了。","pinyin":"Háizi késou de lìhai, wǒmen gǎnjǐn dài tā qù yīyuàn le.","vn":"Đứa bé ho dữ dội quá, chúng tôi vội đưa cháu đi bệnh viện."},{"cn":"多喝点热水，对咳嗽有好处。","pinyin":"Duō hē diǎn rè shuǐ, duì késou yǒu hǎochu.","vn":"Uống nhiều nước ấm sẽ có lợi cho việc ho."}]},{"hanzi":"咳","pinyin":"ké","pos":"dgt.","vn":"ho","examples":[{"cn":"他咳了两声，清了清嗓子。","pinyin":"Tā ké le liǎng shēng, qīng le qīng sǎngzi.","vn":"Anh ấy ho hai tiếng, hắng giọng một chút."},{"cn":"晚上睡觉的时候别老咳，会吵醒别人的。","pinyin":"Wǎnshang shuìjiào de shíhou bié lǎo ké, huì chǎo xǐng biérén de.","vn":"Ban đêm ngủ đừng ho mãi, sẽ làm người khác tỉnh giấc đấy."},{"cn":"烟太大了，呛得我直咳。","pinyin":"Yān tài dà le, qiàng de wǒ zhí ké.","vn":"Khói nhiều quá, sặc đến mức tôi ho liên tục."}]},{"hanzi":"厉害","pinyin":"lìhai","pos":"tt.","vn":"nghiêm trọng, dữ dội","examples":[{"cn":"他最近咳得很厉害，应该去看医生。","pinyin":"Tā zuìjìn ké de hěn lìhai, yīnggāi qù kàn yīshēng.","vn":"Dạo này anh ấy ho dữ dội lắm, nên đi khám bác sĩ."},{"cn":"他的汉语说得真厉害，跟中国人一样。","pinyin":"Tā de Hànyǔ shuō de zhēn lìhai, gēn Zhōngguó rén yíyàng.","vn":"Anh ấy nói tiếng Hán giỏi thật, giống hệt người Trung Quốc."},{"cn":"今天外面风刮得特别厉害。","pinyin":"Jīntiān wàimiàn fēng guā de tèbié lìhai.","vn":"Hôm nay ngoài trời gió thổi dữ dội lắm."}]},{"hanzi":"严重","pinyin":"yánzhòng","pos":"tt.","vn":"nghiêm trọng","examples":[{"cn":"医生说他的病情不算严重，吃点药就好了。","pinyin":"Yīshēng shuō tā de bìngqíng bú suàn yánzhòng, chī diǎn yào jiù hǎo le.","vn":"Bác sĩ nói bệnh tình của anh ấy không nghiêm trọng lắm, uống chút thuốc là khỏi."},{"cn":"这座城市的空气污染越来越严重了。","pinyin":"Zhè zuò chéngshì de kōngqì wūrǎn yuè lái yuè yánzhòng le.","vn":"Ô nhiễm không khí của thành phố này ngày càng nghiêm trọng."},{"cn":"这次事故造成了严重的损失。","pinyin":"Zhè cì shìgù zàochéng le yánzhòng de sǔnshī.","vn":"Vụ tai nạn lần này gây ra tổn thất nghiêm trọng."}]},{"hanzi":"赶快","pinyin":"gǎnkuài","pos":"phó.","vn":"nhanh chóng, ngay lập tức","examples":[{"cn":"快迟到了，我们赶快走吧。","pinyin":"Kuài chídào le, wǒmen gǎnkuài zǒu ba.","vn":"Sắp trễ rồi, chúng ta nhanh đi thôi."},{"cn":"你发烧了，赶快去医院看看吧。","pinyin":"Nǐ fāshāo le, gǎnkuài qù yīyuàn kànkan ba.","vn":"Bạn bị sốt rồi, mau đi bệnh viện khám đi."},{"cn":"下雨了，赶快把窗户关上。","pinyin":"Xià yǔ le, gǎnkuài bǎ chuānghu guān shàng.","vn":"Trời mưa rồi, mau đóng cửa sổ lại."}]},{"hanzi":"陪","pinyin":"péi","pos":"dgt.","vn":"đi cùng, tháp tùng","examples":[{"cn":"周末我陪妈妈去医院检查身体。","pinyin":"Zhōumò wǒ péi māma qù yīyuàn jiǎnchá shēntǐ.","vn":"Cuối tuần tôi đưa mẹ đi bệnh viện khám sức khỏe."},{"cn":"他一个人在国外，没人陪他过生日。","pinyin":"Tā yí ge rén zài guówài, méi rén péi tā guò shēngrì.","vn":"Anh ấy một mình ở nước ngoài, không có ai cùng đón sinh nhật."},{"cn":"你能不能陪我去一趟超市？","pinyin":"Nǐ néng bu néng péi wǒ qù yí tàng chāoshì?","vn":"Bạn có thể đi cùng tôi đến siêu thị một chuyến không?"}]},{"hanzi":"翻译","pinyin":"fānyì","pos":"dgt./dt.","vn":"phiên dịch; người phiên dịch","examples":[{"cn":"她的工作是把中文翻译成英文。","pinyin":"Tā de gōngzuò shì bǎ Zhōngwén fānyì chéng Yīngwén.","vn":"Công việc của cô ấy là dịch tiếng Trung sang tiếng Anh."},{"cn":"我们需要请一位翻译来帮忙。","pinyin":"Wǒmen xūyào qǐng yí wèi fānyì lái bāngmáng.","vn":"Chúng tôi cần mời một phiên dịch viên đến giúp đỡ."},{"cn":"这句话很难翻译，意思不太好表达。","pinyin":"Zhè jù huà hěn nán fānyì, yìsi bú tài hǎo biǎodá.","vn":"Câu này rất khó dịch, ý nghĩa không dễ diễn đạt."}]},{"hanzi":"护士","pinyin":"hùshi","pos":"dt.","vn":"y tá","examples":[{"cn":"护士给我量了体温，说有点发烧。","pinyin":"Hùshi gěi wǒ liáng le tǐwēn, shuō yǒudiǎn fāshāo.","vn":"Y tá đo thân nhiệt cho tôi, nói là hơi sốt."},{"cn":"她大学毕业以后当了一名护士。","pinyin":"Tā dàxué bìyè yǐhòu dāng le yì míng hùshi.","vn":"Sau khi tốt nghiệp đại học, cô ấy trở thành một y tá."},{"cn":"护士很耐心地教我怎么吃药。","pinyin":"Hùshi hěn nàixīn de jiāo wǒ zěnme chī yào.","vn":"Y tá kiên nhẫn chỉ cho tôi cách uống thuốc."}]},{"hanzi":"表","pinyin":"biǎo","pos":"dt.","vn":"biểu mẫu, bảng","examples":[{"cn":"请先填一下这张表。","pinyin":"Qǐng xiān tián yíxià zhè zhāng biǎo.","vn":"Xin hãy điền vào biểu mẫu này trước."},{"cn":"挂号的时候需要填写个人信息表。","pinyin":"Guàhào de shíhou xūyào tiánxiě gèrén xìnxī biǎo.","vn":"Khi đăng ký khám bệnh cần điền bảng thông tin cá nhân."},{"cn":"你把这份表格交给护士就行了。","pinyin":"Nǐ bǎ zhè fèn biǎogé jiāo gěi hùshi jiù xíng le.","vn":"Bạn đưa tờ biểu mẫu này cho y tá là được."}]},{"hanzi":"性别","pinyin":"xìngbié","pos":"dt.","vn":"giới tính","examples":[{"cn":"表格上要写姓名、年龄和性别。","pinyin":"Biǎogé shang yào xiě xìngmíng, niánlíng hé xìngbié.","vn":"Trên biểu mẫu cần ghi họ tên, tuổi tác và giới tính."},{"cn":"这份工作不限性别，男女都可以报名。","pinyin":"Zhè fèn gōngzuò bú xiàn xìngbié, nánnǚ dōu kěyǐ bàomíng.","vn":"Công việc này không giới hạn giới tính, nam nữ đều có thể đăng ký."},{"cn":"现在还不知道孩子的性别。","pinyin":"Xiànzài hái bù zhīdào háizi de xìngbié.","vn":"Hiện tại vẫn chưa biết giới tính của đứa bé."}]},{"hanzi":"国籍","pinyin":"guójí","pos":"dt.","vn":"quốc tịch","examples":[{"cn":"请问您的国籍是哪里？","pinyin":"Qǐngwèn nín de guójí shì nǎli?","vn":"Xin hỏi quốc tịch của anh/chị là gì?"},{"cn":"办理签证需要提供国籍证明。","pinyin":"Bànlǐ qiānzhèng xūyào tígōng guójí zhèngmíng.","vn":"Làm thủ tục visa cần cung cấp giấy chứng nhận quốc tịch."},{"cn":"他虽然长得像中国人，但其实是越南国籍。","pinyin":"Tā suīrán zhǎng de xiàng Zhōngguó rén, dàn qíshí shì Yuènán guójí.","vn":"Anh ấy tuy trông giống người Trung Quốc nhưng thực ra mang quốc tịch Việt Nam."}]},{"hanzi":"家庭","pinyin":"jiātíng","pos":"dt.","vn":"gia đình","examples":[{"cn":"他出生在一个普通的家庭。","pinyin":"Tā chūshēng zài yí ge pǔtōng de jiātíng.","vn":"Anh ấy sinh ra trong một gia đình bình thường."},{"cn":"家庭和睦对孩子的成长很重要。","pinyin":"Jiātíng hémù duì háizi de chéngzhǎng hěn zhòngyào.","vn":"Gia đình hòa thuận rất quan trọng đối với sự trưởng thành của trẻ."},{"cn":"工作太忙了，没时间照顾家庭。","pinyin":"Gōngzuò tài máng le, méi shíjiān zhàogu jiātíng.","vn":"Công việc bận quá, không có thời gian chăm lo gia đình."}]},{"hanzi":"地址","pinyin":"dìzhǐ","pos":"dt.","vn":"địa chỉ","examples":[{"cn":"麻烦你把你家地址发给我一下。","pinyin":"Máfan nǐ bǎ nǐ jiā dìzhǐ fā gěi wǒ yíxià.","vn":"Phiền bạn gửi địa chỉ nhà cho tôi một chút."},{"cn":"快递送到这个地址就行了。","pinyin":"Kuàidì sòng dào zhège dìzhǐ jiù xíng le.","vn":"Chuyển phát nhanh giao đến địa chỉ này là được."},{"cn":"我搬家了，地址换了。","pinyin":"Wǒ bānjiā le, dìzhǐ huàn le.","vn":"Tôi chuyển nhà rồi, địa chỉ thay đổi rồi."}]},{"hanzi":"挂号","pinyin":"guàhào","pos":"dgt.","vn":"đăng ký khám bệnh","examples":[{"cn":"我们先去挂号，然后排队看病。","pinyin":"Wǒmen xiān qù guàhào, ránhòu páiduì kànbìng.","vn":"Chúng ta đi đăng ký khám bệnh trước, rồi xếp hàng khám."},{"cn":"现在可以用手机提前挂号了，不用排队了。","pinyin":"Xiànzài kěyǐ yòng shǒujī tíqián guàhào le, búyòng páiduì le.","vn":"Bây giờ có thể dùng điện thoại đăng ký khám trước, không cần xếp hàng nữa."},{"cn":"今天医院人太多了，挂号都挂了半天。","pinyin":"Jīntiān yīyuàn rén tài duō le, guàhào dōu guà le bàntiān.","vn":"Hôm nay bệnh viện đông người quá, đăng ký khám mất cả buổi."}]},{"hanzi":"排队","pinyin":"páiduì","pos":"dgt.","vn":"xếp hàng","examples":[{"cn":"请大家排队，不要插队。","pinyin":"Qǐng dàjiā páiduì, búyào chāduì.","vn":"Mời mọi người xếp hàng, đừng chen ngang."},{"cn":"我在医院排队排了快一个小时了。","pinyin":"Wǒ zài yīyuàn páiduì pái le kuài yí ge xiǎoshí le.","vn":"Tôi xếp hàng ở bệnh viện gần một tiếng đồng hồ rồi."},{"cn":"买这款手机的人太多了，大家都在门口排队。","pinyin":"Mǎi zhè kuǎn shǒujī de rén tài duō le, dàjiā dōu zài ménkǒu páiduì.","vn":"Người mua mẫu điện thoại này đông quá, ai cũng xếp hàng trước cửa."}]},{"hanzi":"大厅","pinyin":"dàtīng","pos":"dt.","vn":"sảnh lớn, đại sảnh","examples":[{"cn":"请在一楼大厅等我，我马上下来。","pinyin":"Qǐng zài yī lóu dàtīng děng wǒ, wǒ mǎshàng xiàlái.","vn":"Hãy đợi tôi ở sảnh lớn tầng một, tôi xuống ngay."},{"cn":"医院大厅里挂号的人特别多。","pinyin":"Yīyuàn dàtīng lǐ guàhào de rén tèbié duō.","vn":"Trong sảnh lớn bệnh viện người đăng ký khám đông vô cùng."},{"cn":"机场大厅里有很多行李箱。","pinyin":"Jīchǎng dàtīng lǐ yǒu hěn duō xínglixiāng.","vn":"Trong sảnh lớn sân bay có rất nhiều vali."}]},{"hanzi":"偶尔","pinyin":"ǔ'ěr","pos":"phó./tt.","vn":"thỉnh thoảng; không thường xuyên","examples":[{"cn":"我平时很少喝咖啡，偶尔才喝一杯。","pinyin":"Wǒ píngshí hěn shǎo hē kāfēi, ǒu'ěr cái hē yì bēi.","vn":"Bình thường tôi ít uống cà phê, thỉnh thoảng mới uống một ly."},{"cn":"他工作很忙，偶尔才有时间回家看看。","pinyin":"Tā gōngzuò hěn máng, ǒu'ěr cái yǒu shíjiān huí jiā kànkan.","vn":"Anh ấy làm việc bận rộn, thỉnh thoảng mới có thời gian về nhà thăm."},{"cn":"偶尔吃点辣的也没关系。","pinyin":"Ǒu'ěr chī diǎn là de yě méi guānxi.","vn":"Thỉnh thoảng ăn chút đồ cay cũng không sao."}]},{"hanzi":"身","pinyin":"shēn","pos":"dt./lượng.","vn":"thân, người; (lượng từ chỉ) bộ (quần áo)","examples":[{"cn":"他浑身都是汗，刚运动完。","pinyin":"Tā húnshēn dōu shì hàn, gāng yùndòng wán.","vn":"Anh ấy cả người đầy mồ hôi, vừa mới tập thể dục xong."},{"cn":"她今天穿了一身新衣服。","pinyin":"Tā jīntiān chuān le yì shēn xīn yīfu.","vn":"Hôm nay cô ấy mặc một bộ quần áo mới."},{"cn":"他身上带了不少现金。","pinyin":"Tā shēnshang dài le bù shǎo xiànjīn.","vn":"Trên người anh ấy mang theo khá nhiều tiền mặt."}]},{"hanzi":"结果","pinyin":"jiéguǒ","pos":"dt./liên.","vn":"kết quả; kết quả là","examples":[{"cn":"体检结果出来了，一切正常。","pinyin":"Tǐjiǎn jiéguǒ chūlái le, yíqiè zhèngcháng.","vn":"Kết quả khám sức khỏe đã có rồi, mọi thứ bình thường."},{"cn":"我复习了一整晚，结果还是没考好。","pinyin":"Wǒ fùxí le yì zhěng wǎn, jiéguǒ háishi méi kǎo hǎo.","vn":"Tôi ôn bài cả đêm, kết quả là vẫn thi không tốt."},{"cn":"他想早点出发，结果路上堵车迟到了。","pinyin":"Tā xiǎng zǎodiǎn chūfā, jiéguǒ lùshang dǔchē chídào le.","vn":"Anh ấy muốn xuất phát sớm, kết quả là bị kẹt xe nên đến muộn."}]},{"hanzi":"性","pinyin":"xìng","pos":"htố.","vn":"(hậu tố chỉ tính chất, đặc điểm, phạm vi nhất định)","examples":[{"cn":"这个药只有一定的治疗性，不能完全根治。","pinyin":"Zhège yào zhǐyǒu yídìng de zhìliáoxìng, bù néng wánquán gēnzhì.","vn":"Loại thuốc này chỉ có tính điều trị nhất định, không thể chữa dứt hoàn toàn."},{"cn":"这个决定的重要性大家都明白。","pinyin":"Zhège juédìng de zhòngyàoxìng dàjiā dōu míngbai.","vn":"Tầm quan trọng của quyết định này mọi người đều hiểu rõ."},{"cn":"这种病有一定的传染性，要注意隔离。","pinyin":"Zhè zhǒng bìng yǒu yídìng de chuánrǎnxìng, yào zhùyì gélí.","vn":"Loại bệnh này có tính lây nhiễm nhất định, cần chú ý cách ly."}]},{"hanzi":"体温","pinyin":"tǐwēn","pos":"dt.","vn":"thân nhiệt","examples":[{"cn":"护士给病人量了体温。","pinyin":"Hùshi gěi bìngrén liáng le tǐwēn.","vn":"Y tá đo thân nhiệt cho bệnh nhân."},{"cn":"他的体温已经恢复正常了。","pinyin":"Tā de tǐwēn yǐjīng huīfù zhèngcháng le.","vn":"Thân nhiệt của anh ấy đã trở lại bình thường."},{"cn":"进门之前要先测一下体温。","pinyin":"Jìn mén zhīqián yào xiān cè yíxià tǐwēn.","vn":"Trước khi vào cửa cần đo thân nhiệt trước."}]},{"hanzi":"降","pinyin":"jiàng","pos":"dgt.","vn":"hạ, giảm","examples":[{"cn":"吃了药以后，他的体温慢慢降下来了。","pinyin":"Chī le yào yǐhòu, tā de tǐwēn mànmàn jiàng xiàlái le.","vn":"Sau khi uống thuốc, thân nhiệt của anh ấy từ từ hạ xuống."},{"cn":"最近气温降得很快，大家要注意保暖。","pinyin":"Zuìjìn qìwēn jiàng de hěn kuài, dàjiā yào zhùyì bǎonuǎn.","vn":"Dạo này nhiệt độ hạ rất nhanh, mọi người chú ý giữ ấm."},{"cn":"这款手机最近降价了不少。","pinyin":"Zhè kuǎn shǒujī zuìjìn jiàngjià le bù shǎo.","vn":"Mẫu điện thoại này dạo gần đây giảm giá khá nhiều."}]},{"hanzi":"光","pinyin":"guāng","pos":"phó.","vn":"chỉ, chỉ riêng","examples":[{"cn":"这件事光靠我一个人是做不完的。","pinyin":"Zhè jiàn shì guāng kào wǒ yí ge rén shì zuò bu wán de.","vn":"Việc này chỉ dựa vào một mình tôi thì không làm xong được."},{"cn":"他光说不做，一点用都没有。","pinyin":"Tā guāng shuō bú zuò, yìdiǎn yòng dōu méiyǒu.","vn":"Anh ta chỉ nói mà không làm, chẳng ích gì cả."},{"cn":"别光顾着玩手机，快去写作业。","pinyin":"Bié guāng gùzhe wán shǒujī, kuài qù xiě zuòyè.","vn":"Đừng chỉ mải chơi điện thoại, mau đi làm bài tập đi."}]},{"hanzi":"打针","pinyin":"dǎhēn","pos":"dgt.","vn":"tiêm (thuốc)","examples":[{"cn":"医生说需要打针才能好得快一点。","pinyin":"Yīshēng shuō xūyào dǎzhēn cái néng hǎo de kuài yìdiǎn.","vn":"Bác sĩ nói cần tiêm thuốc mới khỏi nhanh hơn một chút."},{"cn":"我最怕打针了，一看到针就紧张。","pinyin":"Wǒ zuì pà dǎzhēn le, yí kàndào zhēn jiù jǐnzhāng.","vn":"Tôi sợ tiêm nhất, cứ nhìn thấy kim là căng thẳng."},{"cn":"护士给孩子打针的时候特别温柔。","pinyin":"Hùshi gěi háizi dǎzhēn de shíhou tèbié wēnróu.","vn":"Lúc tiêm cho em bé, cô y tá rất nhẹ nhàng."}]},{"hanzi":"有效","pinyin":"yǒuxiào","pos":"dgt.","vn":"có hiệu quả","examples":[{"cn":"这个方法对治疗咳嗽很有效。","pinyin":"Zhège fāngfǎ duì zhìliáo késou hěn yǒuxiào.","vn":"Phương pháp này rất có hiệu quả trong việc điều trị ho."},{"cn":"这张票三天内有效，过期就不能用了。","pinyin":"Zhè zhāng piào sān tiān nèi yǒuxiào, guòqī jiù bù néng yòng le.","vn":"Tấm vé này có hiệu lực trong ba ngày, quá hạn thì không dùng được nữa."},{"cn":"吃药以后退烧很有效，一下就好多了。","pinyin":"Chī yào yǐhòu tuìshāo hěn yǒuxiào, yíxià jiù hǎo duō le.","vn":"Uống thuốc xong hạ sốt rất hiệu quả, khỏi hẳn ngay."}]},{"hanzi":"按时","pinyin":"ànshí","pos":"phó.","vn":"đúng giờ, đúng thời gian quy định","examples":[{"cn":"你一定要按时吃药，不能忘。","pinyin":"Nǐ yídìng yào ànshí chī yào, bù néng wàng.","vn":"Bạn nhất định phải uống thuốc đúng giờ, không được quên."},{"cn":"我们每天都按时上下班。","pinyin":"Wǒmen měi tiān dōu ànshí shàngxiàbān.","vn":"Chúng tôi ngày nào cũng đi làm tan làm đúng giờ."},{"cn":"这份作业要按时交，不能迟交。","pinyin":"Zhè fèn zuòyè yào ànshí jiāo, bù néng chí jiāo.","vn":"Bài tập này phải nộp đúng hạn, không được nộp muộn."}]},{"hanzi":"汗","pinyin":"hàn","pos":"dt.","vn":"mồ hôi","examples":[{"cn":"天太热了，我出了一身汗。","pinyin":"Tiān tài rè le, wǒ chū le yì shēn hàn.","vn":"Trời nóng quá, tôi ra mồ hôi khắp người."},{"cn":"他紧张得手心都出汗了。","pinyin":"Tā jǐnzhāng de shǒuxīn dōu chūhàn le.","vn":"Anh ấy căng thẳng đến mức lòng bàn tay cũng ra mồ hôi."},{"cn":"发烧出点汗以后，体温就降下来了。","pinyin":"Fāshāo chū diǎn hàn yǐhòu, tǐwēn jiù jiàng xiàlái le.","vn":"Sốt mà ra chút mồ hôi rồi thì thân nhiệt sẽ hạ xuống."}]},{"hanzi":"醒","pinyin":"xǐng","pos":"dgt.","vn":"tỉnh dậy, thức giấc","examples":[{"cn":"我昨天晚上半夜醒了好几次。","pinyin":"Wǒ zuótiān wǎnshang bànyè xǐng le hǎo jǐ cì.","vn":"Tối qua tôi tỉnh giấc mấy lần giữa đêm."},{"cn":"闹钟响了，他还没醒。","pinyin":"Nàozhōng xiǎng le, tā hái méi xǐng.","vn":"Chuông báo thức kêu rồi mà anh ấy vẫn chưa tỉnh."},{"cn":"孩子睡醒了，开始哭闹找妈妈。","pinyin":"Háizi shuì xǐng le, kāishǐ kūnào zhǎo māma.","vn":"Đứa bé ngủ dậy rồi, bắt đầu khóc lóc đòi tìm mẹ."}]},{"hanzi":"感觉","pinyin":"gǎnjué","pos":"dgt./dt.","vn":"cảm thấy; cảm giác","examples":[{"cn":"我今天感觉不太舒服，有点头疼。","pinyin":"Wǒ jīntiān gǎnjué bú tài shūfu, yǒudiǎn tóuténg.","vn":"Hôm nay tôi cảm thấy không được khỏe lắm, hơi đau đầu."},{"cn":"他给人的感觉特别真诚。","pinyin":"Tā gěi rén de gǎnjué tèbié zhēnchéng.","vn":"Anh ấy mang lại cảm giác rất chân thành cho người khác."},{"cn":"吃完药以后，感觉好多了。","pinyin":"Chī wán yào yǐhòu, gǎnjué hǎo duō le.","vn":"Uống thuốc xong rồi, cảm thấy khá hơn nhiều."}]},{"hanzi":"低","pinyin":"dī","pos":"tt.","vn":"thấp","examples":[{"cn":"他的体温有点低，才三十五度。","pinyin":"Tā de tǐwēn yǒudiǎn dī, cái sānshíwǔ dù.","vn":"Thân nhiệt của anh ấy hơi thấp, mới ba mươi lăm độ."},{"cn":"这份工作的工资太低了，我不想做。","pinyin":"Zhè fèn gōngzuò de gōngzī tài dī le, wǒ bù xiǎng zuò.","vn":"Lương công việc này thấp quá, tôi không muốn làm."},{"cn":"今天的气温比昨天低了不少。","pinyin":"Jīntiān de qìwēn bǐ zuótiān dī le bù shǎo.","vn":"Nhiệt độ hôm nay thấp hơn hôm qua khá nhiều."}]},{"hanzi":"难受","pinyin":"nánshòu","pos":"tt.","vn":"khó chịu","examples":[{"cn":"我肚子疼得难受，想去医院看看。","pinyin":"Wǒ dùzi téng de nánshòu, xiǎng qù yīyuàn kànkan.","vn":"Bụng tôi đau khó chịu quá, muốn đi bệnh viện khám."},{"cn":"听到这个消息，我心里特别难受。","pinyin":"Tīngdào zhège xiāoxi, wǒ xīnli tèbié nánshòu.","vn":"Nghe tin này, lòng tôi cảm thấy rất khó chịu."},{"cn":"穿这双鞋走路脚很难受。","pinyin":"Chuān zhè shuāng xié zǒulù jiǎo hěn nánshòu.","vn":"Đi giày này đi bộ chân cảm thấy rất khó chịu."}]},{"hanzi":"通","pinyin":"tōng","pos":"dgt.","vn":"hiểu, thông suốt","examples":[{"cn":"他汉语说得很流利，但书面语还不太通。","pinyin":"Tā Hànyǔ shuō de hěn liúlì, dàn shūmiànyǔ hái bú tài tōng.","vn":"Anh ấy nói tiếng Hán rất trôi chảy nhưng văn viết thì chưa thông thạo lắm."},{"cn":"这条路现在已经通了，可以开车过去了。","pinyin":"Zhè tiáo lù xiànzài yǐjīng tōng le, kěyǐ kāichē guòqù le.","vn":"Con đường này bây giờ đã thông rồi, có thể lái xe qua được."},{"cn":"我打了好几次电话都打不通。","pinyin":"Wǒ dǎ le hǎo jǐ cì diànhuà dōu dǎ bu tōng.","vn":"Tôi gọi điện mấy lần liền đều không thông được."}]},{"hanzi":"过程","pinyin":"guòchéng","pos":"dt.","vn":"quá trình","examples":[{"cn":"学习一门语言的过程虽然辛苦，但很有意思。","pinyin":"Xuéxí yì mén yǔyán de guòchéng suīrán xīnkǔ, dàn hěn yǒu yìsi.","vn":"Quá trình học một ngôn ngữ tuy vất vả nhưng rất thú vị."},{"cn":"治疗的过程需要一段时间，别着急。","pinyin":"Zhìliáo de guòchéng xūyào yí duàn shíjiān, bié zháojí.","vn":"Quá trình điều trị cần một khoảng thời gian, đừng vội."},{"cn":"整个过程我都记录下来了。","pinyin":"Zhěnggè guòchéng wǒ dōu jìlù xiàlái le.","vn":"Cả quá trình tôi đều ghi chép lại hết."}]},{"hanzi":"部","pinyin":"bù","pos":"dt.","vn":"khoa, bộ phận","examples":[{"cn":"你应该去挂号部挂个号。","pinyin":"Nǐ yīnggāi qù guàhào bù guà ge hào.","vn":"Bạn nên đến khoa đăng ký khám để đăng ký."},{"cn":"他在市场部工作了五年了。","pinyin":"Tā zài shìchǎng bù gōngzuò le wǔ nián le.","vn":"Anh ấy làm việc ở bộ phận thị trường được năm năm rồi."},{"cn":"医院的内科部在二楼。","pinyin":"Yīyuàn de nèikē bù zài èr lóu.","vn":"Khoa nội của bệnh viện ở tầng hai."}]},{"hanzi":"收费","pinyin":"shōufei","pos":"dgt.","vn":"thu phí","examples":[{"cn":"这个停车场是收费的，停一小时十块钱。","pinyin":"Zhège tíngchēchǎng shì shōufèi de, tíng yì xiǎoshí shí kuài qián.","vn":"Bãi đỗ xe này có thu phí, đỗ một tiếng mười đồng."},{"cn":"这家医院挂号不收费。","pinyin":"Zhè jiā yīyuàn guàhào bù shōufèi.","vn":"Bệnh viện này đăng ký khám không thu phí."},{"cn":"请问送货上门还收费吗？","pinyin":"Qǐngwèn sònghuò shàngmén hái shōufèi ma?","vn":"Xin hỏi giao hàng tận nhà có thu phí nữa không?"}]},{"hanzi":"情况","pinyin":"qíngkuàng","pos":"dt.","vn":"tình hình","examples":[{"cn":"你的情况我已经了解了，别担心。","pinyin":"Nǐ de qíngkuàng wǒ yǐjīng liǎojiě le, bié dānxīn.","vn":"Tình hình của bạn tôi đã nắm rõ rồi, đừng lo lắng."},{"cn":"根据目前的情况来看，还需要再观察几天。","pinyin":"Gēnjù mùqián de qíngkuàng lái kàn, hái xūyào zài guānchá jǐ tiān.","vn":"Theo tình hình hiện tại thì cần phải theo dõi thêm vài ngày."},{"cn":"他突然遇到这种情况，一时不知道怎么办。","pinyin":"Tā tūrán yùdào zhè zhǒng qíngkuàng, yìshí bù zhīdào zěnme bàn.","vn":"Anh ấy đột nhiên gặp phải tình huống này, nhất thời không biết làm sao."}]},{"hanzi":"好","pinyin":"hǎo","pos":"dgt.","vn":"để, nhằm","examples":[{"cn":"把窗户关好，别感冒了。","pinyin":"Bǎ chuānghu guān hǎo, bié gǎnmào le.","vn":"Đóng cửa sổ lại cho kín để khỏi bị cảm."},{"cn":"你多穿点衣服，好出门。","pinyin":"Nǐ duō chuān diǎn yīfu, hǎo chūmén.","vn":"Bạn mặc thêm quần áo để tiện ra ngoài."},{"cn":"我把药放在这儿，好随时吃。","pinyin":"Wǒ bǎ yào fàng zài zhèr, hǎo suíshí chī.","vn":"Tôi để thuốc ở đây để tiện uống bất cứ lúc nào."}]},{"hanzi":"治疗","pinyin":"zhìliáo","pos":"dgt.","vn":"điều trị","examples":[{"cn":"这种病需要住院治疗。","pinyin":"Zhè zhǒng bìng xūyào zhùyuàn zhìliáo.","vn":"Loại bệnh này cần phải nhập viện điều trị."},{"cn":"经过一段时间的治疗，他的病好多了。","pinyin":"Jīngguò yí duàn shíjiān de zhìliáo, tā de bìng hǎo duō le.","vn":"Sau một thời gian điều trị, bệnh của anh ấy đã khá hơn nhiều."},{"cn":"医生正在研究新的治疗方法。","pinyin":"Yīshēng zhèngzài yánjiū xīn de zhìliáo fāngfǎ.","vn":"Bác sĩ đang nghiên cứu phương pháp điều trị mới."}]},{"hanzi":"步","pinyin":"bù","pos":"dt.","vn":"bước","examples":[{"cn":"他走了几步就觉得累了。","pinyin":"Tā zǒu le jǐ bù jiù juéde lèi le.","vn":"Anh ấy đi vài bước là cảm thấy mệt rồi."},{"cn":"做事要一步一步来，不能着急。","pinyin":"Zuòshì yào yí bù yí bù lái, bù néng zháojí.","vn":"Làm việc phải từng bước một, không được vội vàng."},{"cn":"这是治疗过程中很重要的一步。","pinyin":"Zhè shì zhìliáo guòchéng zhōng hěn zhòngyào de yí bù.","vn":"Đây là một bước rất quan trọng trong quá trình điều trị."}]}],"grammar":[{"title":"形容词“厉害” Tính từ “厉害”","explanation_vn":"Tính từ \"厉害\" có thể đặt sau động từ hoặc tính từ, biểu thị mức độ rất cao, cấu trúc là \"động từ + được + (phó từ) + 厉害\" hoặc \"tính từ + được + 厉害\".","examples":[{"cn":"我还发烧，一直咳嗽，咳得很厉害。","pinyin":"","vn":"Tôi còn bị sốt, cứ ho mãi, ho rất dữ dội."},{"cn":"我昨天跑步跑多了，今天腐疼得厉害。","pinyin":"","vn":"Hôm qua tôi chạy bộ nhiều quá, hôm nay chân đau kinh khủng."},{"cn":"这道菜辣得厉害，我吃了一口就不敢再吃了。","pinyin":"","vn":"Món này cay kinh khủng, tôi ăn một miếng là không dám ăn nữa."}]},{"title":"固定格式“（没）有什么（好）×的” Cấu trúc cố định “（没）有什么（好）×的”","explanation_vn":"Cấu trúc cố định \"(没)有什么(好)×的\" biểu thị không cần thiết phải làm việc gì đó, hoặc có một cảm giác, trạng thái nào đó.","examples":[{"cn":"你跟我有什么好客气的。","pinyin":"","vn":"Bạn với tôi thì có gì phải khách sáo chứ."},{"cn":"这种事在网上有很多，没有什么奇怪的。","pinyin":"","vn":"Chuyện như vậy trên mạng có nhiều lắm, chẳng có gì lạ cả."},{"cn":"我觉得这家商场里的东西都很一般，没有什么好买的。","pinyin":"","vn":"Tôi thấy đồ trong trung tâm thương mại này đều bình thường, chẳng có gì đáng mua cả."}]},{"title":"频率副词“偶尔” Phó từ tần suất “偶尔”","explanation_vn":"Phó từ tần suất \"偶尔\" biểu thị hành động hoặc tình huống xảy ra rất ít lần.","examples":[{"cn":"她告诉医生，自己平时身体不错，偶尔才会生一次病。","pinyin":"","vn":"Cô ấy nói với bác sĩ rằng bình thường sức khỏe mình khá tốt, thỉnh thoảng mới bị bệnh một lần."},{"cn":"他经常在家看电影，偶尔才去电影院看。","pinyin":"","vn":"Anh ấy thường xem phim ở nhà, thỉnh thoảng mới đến rạp chiếu phim xem."},{"cn":"我一般都在学校食堂吃饭，偶尔会跟朋友一起出去吃。","pinyin":"","vn":"Tôi thường ăn ở căng tin trường, thỉnh thoảng mới cùng bạn bè ra ngoài ăn."}]},{"title":"目的复句“……，好……” Câu phức chỉ mục đích “……，好……”","explanation_vn":"Vế trước nói về một hành động hay tình huống nào đó, vế sau nêu rõ mục đích của hành động hay tình huống đó.","examples":[{"cn":"医生有时还会做一些检查，好给出合适的治疗方法。","pinyin":"","vn":"Bác sĩ đôi khi còn làm một số xét nghiệm, để đưa ra phương pháp điều trị phù hợp."},{"cn":"你们先了解一下情况，好做出决定。","pinyin":"","vn":"Các bạn hãy tìm hiểu tình hình trước, để đưa ra quyết định."},{"cn":"我把电话号码告诉你，以后有什么事好联系我。","pinyin":"","vn":"Tôi cho bạn số điện thoại, sau này có việc gì thì tiện liên lạc với tôi."}]}],"texts":[{"label":"Bài khóa 1","type":"dialogue","lines":[{"speaker":"白家月","cn":"喜，李文，我身体不舒服。","pinyin":""},{"speaker":"李文","cn":"你怎么了？听你的声音，好像感冒了。","pinyin":""},{"speaker":"白家月","cn":"对，我还发烧，一直咳嗽，咳得很厉害。","pinyin":""},{"speaker":"李文","cn":"那挺严重的，最好赶快去医院检查一下。","pinyin":""},{"speaker":"白家月","cn":"我也这么想，不过我来中国后还没去过医院，不知道怎么在中国的医院看病。","pinyin":""},{"speaker":"李文","cn":"没关系，我陪你一起去，还能帮你翻译。你在家等一下，我现在就去接你。","pinyin":""},{"speaker":"白家月","cn":"太好了！有你陪着，我就放心多了。","pinyin":""}],"translation_vn":"Bạch Gia Nguyệt: Alo, Lý Văn, mình thấy khó chịu trong người.\nLý Văn: Bạn làm sao vậy? Nghe giọng có vẻ bị cảm rồi.\nBạch Gia Nguyệt: Đúng vậy, mình còn bị sốt, cứ ho mãi, ho rất dữ dội.\nLý Văn: Nghe có vẻ nghiêm trọng đấy, tốt nhất nên nhanh chóng đến bệnh viện kiểm tra một lần.\nBạch Gia Nguyệt: Mình cũng nghĩ vậy, nhưng từ khi đến Trung Quốc mình chưa đi bệnh viện lần nào, không biết cách khám bệnh ở bệnh viện Trung Quốc như thế nào.\nLý Văn: Không sao, mình đi cùng bạn, còn có thể giúp bạn phiên dịch nữa. Bạn ở nhà đợi một lát, mình đến đón bạn ngay bây giờ.\nBạch Gia Nguyệt: Tuyệt quá! Có bạn đi cùng, mình yên tâm hơn nhiều rồi.","audio_dialogue":"6-1.mp3","audio_vocab":"6-2.mp3"},{"label":"Bài khóa 2","type":"dialogue","lines":[{"speaker":"李文","cn":"护士，您好，我的这位外国朋友生病了，第一次来这里看病，需要怎么做？","pinyin":""},{"speaker":"护士","cn":"请在这张表上写上病人的姓名、性别、国籍、年龄、电话号码和家庭地址。","pinyin":""},{"speaker":"李文","cn":"我写好了，您看看，这样可以吗？","pinyin":""},{"speaker":"护士","cn":"没问题，您拿着病人的护照去挂号吧。","pinyin":""},{"speaker":"李文","cn":"家月，我去排队挂号，你先在大厅休息，别着急。","pinyin":""},{"speaker":"白家月","cn":"好的，真是太谢谢你了！","pinyin":""},{"speaker":"李文","cn":"你跟我有什么好客气的。","pinyin":""}],"translation_vn":"Lý Văn: Chào y tá, bạn nước ngoài của tôi bị ốm, đây là lần đầu tiên bạn ấy đến đây khám bệnh, cần làm thế nào ạ?\nY tá: Xin anh điền vào biểu mẫu này họ tên, giới tính, quốc tịch, tuổi, số điện thoại và địa chỉ gia đình của bệnh nhân.\nLý Văn: Tôi viết xong rồi, chị xem giúp, thế này được chưa ạ?\nY tá: Không có vấn đề gì, anh cầm hộ chiếu của bệnh nhân đi đăng ký khám bệnh nhé.\nLý Văn: Gia Nguyệt, mình đi xếp hàng đăng ký khám đây, bạn cứ nghỉ ở sảnh trước, đừng lo lắng.\nBạch Gia Nguyệt: Được rồi, thật sự cảm ơn bạn nhiều lắm!\nLý Văn: Bạn với mình thì có gì phải khách sáo chứ.","audio_dialogue":"6-3.mp3","audio_vocab":"6-4.mp3"},{"label":"Bài khóa 3","type":"passage","lines":[{"speaker":"","cn":"下午白家月去看病了，她告诉医生，自己平时身体不错，偶尔才会生一次病。这次她病得很厉害，头也一直疼，身上一点儿力气都没有。医生给她做了检查，检查结果出来后，发现她得了比较严重的流行性感冒。\n医生告诉她，现在需要把体温降下来，光吃药恐怕不够，打针会更有效。医生还让她回家以后按时吃药，多喝水，多休息。\n晚上，白家月睡觉时出了一身汗。第二天醒来时，她感觉头不那么疼了，体温也低了一些，身体不那么难受了。","pinyin":""}],"translation_vn":"Buổi chiều Bạch Gia Nguyệt đi khám bệnh, cô nói với bác sĩ rằng bình thường sức khỏe mình khá tốt, thỉnh thoảng mới bị bệnh một lần. Lần này cô bị bệnh khá nặng, đầu cứ đau mãi, người không còn chút sức lực nào. Bác sĩ đã khám cho cô, sau khi có kết quả kiểm tra, phát hiện cô bị cúm mùa khá nghiêm trọng.\nBác sĩ nói với cô rằng bây giờ cần hạ thân nhiệt xuống, chỉ uống thuốc thôi e là chưa đủ, tiêm thuốc sẽ hiệu quả hơn. Bác sĩ còn dặn cô về nhà uống thuốc đúng giờ, uống nhiều nước, nghỉ ngơi nhiều.\nBuổi tối, lúc ngủ Bạch Gia Nguyệt đổ một thân mồ hôi. Sáng hôm sau tỉnh dậy, cô cảm thấy đầu đỡ đau hơn, thân nhiệt cũng hạ xuống một chút, người không còn khó chịu như trước nữa.","audio_dialogue":"6-5.mp3","audio_vocab":"6-6.mp3"},{"label":"Bài khóa 4","type":"passage","lines":[{"speaker":"","cn":"外国人第一次在中国看病，可能会担心语言不通，或者觉得看病的过程和自己的国家不同。其实，这些问题都有办法解决。\n有的医院有国际部，那里的医生一般会说英文，交流比较方便，但是国际部的收费比较高。如果没有特别需要，可以选择普通部，用简单的中文和医生交流。\n在中国看病要先挂号，然后再去找医生。医生会问病人的情况，有时还会做一些检查，好给出合适的治疗方法。只要按照医生说的一步一步来，一般都可以顺利得到治疗。","pinyin":""}],"translation_vn":"Người nước ngoài lần đầu đi khám bệnh ở Trung Quốc có thể lo lắng về bất đồng ngôn ngữ, hoặc cảm thấy quy trình khám bệnh khác với đất nước mình. Thực ra, những vấn đề này đều có cách giải quyết.\nMột số bệnh viện có khoa quốc tế, bác sĩ ở đó thường biết nói tiếng Anh, giao tiếp khá thuận tiện, nhưng chi phí của khoa quốc tế lại khá cao. Nếu không có nhu cầu đặc biệt, có thể chọn khoa thường, dùng tiếng Trung đơn giản để giao tiếp với bác sĩ.\nKhám bệnh ở Trung Quốc cần đăng ký trước, sau đó mới đi gặp bác sĩ. Bác sĩ sẽ hỏi tình hình của bệnh nhân, có khi còn làm một số xét nghiệm, để đưa ra phương pháp điều trị phù hợp. Chỉ cần làm theo từng bước mà bác sĩ nói, nhìn chung đều có thể được điều trị thuận lợi.","audio_dialogue":"6-7.mp3","audio_vocab":"6-8.mp3"}]},{"id":7,"title_cn":"在工作中学习","title_pinyin":"","title_vn":"Học hỏi trong công việc","goals":["Có thể nghe hiểu và trao đổi về nhiệm vụ công việc, sắp xếp công việc và các nội dung liên quan.","Có thể trình bày bằng lời nói hoặc văn bản kinh nghiệm làm việc và đưa ra lời khuyên về phát triển sự nghiệp.","Hiểu được cách làm việc coi trọng học hỏi và tích lũy kinh nghiệm trong môi trường công sở."],"vocab":[{"hanzi":"打扰","pinyin":"dǎrǎo","pos":"dgt.","vn":"làm phiền, quấy rầy","examples":[{"cn":"不好意思，打扰您一下，请问洗手间在哪儿？","pinyin":"bù hǎoyìsi, dǎrǎo nín yíxià, qǐngwèn xǐshǒujiān zài nǎr?","vn":"Xin lỗi, làm phiền anh/chị một chút, cho hỏi nhà vệ sinh ở đâu ạ?"},{"cn":"他正在开会，你最好别打扰他。","pinyin":"tā zhèngzài kāihuì, nǐ zuìhǎo bié dǎrǎo tā.","vn":"Anh ấy đang họp, tốt nhất bạn đừng làm phiền anh ấy."},{"cn":"真不好意思，打扰你休息了。","pinyin":"zhēn bù hǎoyìsi, dǎrǎo nǐ xiūxi le.","vn":"Thật xin lỗi, đã làm phiền bạn nghỉ ngơi rồi."}]},{"hanzi":"市场","pinyin":"shìchǎng","pos":"dt.","vn":"thị trường, chợ","examples":[{"cn":"这个产品在市场上很受欢迎。","pinyin":"zhège chǎnpǐn zài shìchǎng shàng hěn shòu huānyíng.","vn":"Sản phẩm này rất được ưa chuộng trên thị trường."},{"cn":"我周末喜欢去菜市场买新鲜的蔬菜。","pinyin":"wǒ zhōumò xǐhuan qù càishìchǎng mǎi xīnxiān de shūcài.","vn":"Cuối tuần tôi thích đi chợ mua rau tươi."},{"cn":"最近市场竞争越来越激烈了。","pinyin":"zuìjìn shìchǎng jìngzhēng yuèláiyuè jīliè le.","vn":"Gần đây cạnh tranh trên thị trường ngày càng khốc liệt."}]},{"hanzi":"调查","pinyin":"diàochá","pos":"dgt.","vn":"điều tra, khảo sát","examples":[{"cn":"公司打算做一个市场调查，了解客户的需求。","pinyin":"gōngsī dǎsuàn zuò yí ge shìchǎng diàochá, liǎojiě kèhù de xūqiú.","vn":"Công ty dự định làm một cuộc khảo sát thị trường để hiểu nhu cầu khách hàng."},{"cn":"警察正在调查这起案件。","pinyin":"jǐngchá zhèngzài diàochá zhè qǐ ànjiàn.","vn":"Cảnh sát đang điều tra vụ án này."},{"cn":"我们对一百个用户做了调查，结果挺有意思的。","pinyin":"wǒmen duì yìbǎi ge yònghù zuò le diàochá, jiéguǒ tǐng yǒuyìsi de.","vn":"Chúng tôi đã khảo sát một trăm người dùng, kết quả khá thú vị."}]},{"hanzi":"计划","pinyin":"jìhuà","pos":"dt./dgt.","vn":"kế hoạch; lập kế hoạch","examples":[{"cn":"我计划暑假的时候去云南旅游。","pinyin":"wǒ jìhuà shǔjià de shíhou qù Yúnnán lǚyóu.","vn":"Tôi dự định nghỉ hè sẽ đi du lịch Vân Nam."},{"cn":"这个计划听起来不错，我们试试吧。","pinyin":"zhège jìhuà tīngqǐlái búcuò, wǒmen shìshi ba.","vn":"Kế hoạch này nghe có vẻ hay, chúng ta thử xem."},{"cn":"因为下雨，我们的计划被打乱了。","pinyin":"yīnwèi xiàyǔ, wǒmen de jìhuà bèi dǎluàn le.","vn":"Vì trời mưa nên kế hoạch của chúng tôi bị đảo lộn."}]},{"hanzi":"内容","pinyin":"nèiróng","pos":"dt.","vn":"nội dung","examples":[{"cn":"这本书的内容很丰富，值得一看。","pinyin":"zhè běn shū de nèiróng hěn fēngfù, zhídé yí kàn.","vn":"Nội dung của cuốn sách này rất phong phú, đáng để đọc."},{"cn":"你能把报告的主要内容讲一下吗？","pinyin":"nǐ néng bǎ bàogào de zhǔyào nèiróng jiǎng yíxià ma?","vn":"Bạn có thể trình bày nội dung chính của báo cáo không?"},{"cn":"这部电影的内容太无聊了，我看到一半就睡着了。","pinyin":"zhè bù diànyǐng de nèiróng tài wúliáo le, wǒ kàndào yíbàn jiù shuìzháo le.","vn":"Nội dung bộ phim này quá nhàm chán, tôi xem đến nửa chừng đã ngủ mất rồi."}]},{"hanzi":"改","pinyin":"gǎi","pos":"dgt.","vn":"sửa, thay đổi","examples":[{"cn":"这篇文章有几个地方需要改一下。","pinyin":"zhè piān wénzhāng yǒu jǐ ge dìfang xūyào gǎi yíxià.","vn":"Bài viết này có mấy chỗ cần sửa lại."},{"cn":"我已经把错误的地方都改好了。","pinyin":"wǒ yǐjīng bǎ cuòwù de dìfang dōu gǎihǎo le.","vn":"Tôi đã sửa xong hết những chỗ sai rồi."},{"cn":"他下定决心要改掉熬夜的坏习惯。","pinyin":"tā xiàdìng juéxīn yào gǎidiào áoyè de huài xíguàn.","vn":"Anh ấy quyết tâm sửa bỏ thói quen xấu thức khuya."}]},{"hanzi":"细心","pinyin":"xìxīn","pos":"tt.","vn":"cẩn thận, tỉ mỉ","examples":[{"cn":"她做事一向很细心，很少出错。","pinyin":"tā zuòshì yíxiàng hěn xìxīn, hěn shǎo chūcuò.","vn":"Cô ấy làm việc luôn rất cẩn thận, hiếm khi sai sót."},{"cn":"护士对病人非常细心，照顾得很周到。","pinyin":"hùshi duì bìngrén fēicháng xìxīn, zhàogù de hěn zhōudào.","vn":"Y tá rất tỉ mỉ với bệnh nhân, chăm sóc rất chu đáo."},{"cn":"这份工作需要细心的人才能做好。","pinyin":"zhè fèn gōngzuò xūyào xìxīn de rén cái néng zuòhǎo.","vn":"Công việc này cần người cẩn thận mới làm tốt được."}]},{"hanzi":"客户","pinyin":"kèhù","pos":"dt.","vn":"khách hàng","examples":[{"cn":"我今天下午要跟一个重要客户见面。","pinyin":"wǒ jīntiān xiàwǔ yào gēn yí ge zhòngyào kèhù jiànmiàn.","vn":"Chiều nay tôi phải gặp một khách hàng quan trọng."},{"cn":"我们公司非常重视客户的意见。","pinyin":"wǒmen gōngsī fēicháng zhòngshì kèhù de yìjiàn.","vn":"Công ty chúng tôi rất coi trọng ý kiến của khách hàng."},{"cn":"这家店的老客户特别多，生意一直很好。","pinyin":"zhè jiā diàn de lǎo kèhù tèbié duō, shēngyi yìzhí hěn hǎo.","vn":"Cửa hàng này có rất nhiều khách quen, việc kinh doanh luôn tốt."}]},{"hanzi":"真正","pinyin":"zhēnzhèng","pos":"tt./phó.","vn":"thực sự, chân chính","examples":[{"cn":"他才是我真正的朋友，一直在我困难的时候帮我。","pinyin":"tā cái shì wǒ zhēnzhèng de péngyou, yìzhí zài wǒ kùnnan de shíhou bāng wǒ.","vn":"Anh ấy mới thực sự là bạn tôi, luôn giúp tôi lúc khó khăn."},{"cn":"我现在才真正明白这句话的意思。","pinyin":"wǒ xiànzài cái zhēnzhèng míngbai zhè jù huà de yìsi.","vn":"Bây giờ tôi mới thực sự hiểu ý nghĩa của câu nói này."},{"cn":"这才是真正的中国味道。","pinyin":"zhè cái shì zhēnzhèng de Zhōngguó wèidao.","vn":"Đây mới chính là hương vị Trung Quốc thực thụ."}]},{"hanzi":"想法","pinyin":"xiǎngfǎ","pos":"dt.","vn":"ý kiến, suy nghĩ","examples":[{"cn":"我对这件事有一个不一样的想法。","pinyin":"wǒ duì zhè jiàn shì yǒu yí ge bù yíyàng de xiǎngfǎ.","vn":"Tôi có một suy nghĩ khác về chuyện này."},{"cn":"你能说说你的想法吗？","pinyin":"nǐ néng shuōshuo nǐ de xiǎngfǎ ma?","vn":"Bạn có thể nói ra suy nghĩ của mình không?"},{"cn":"他的想法总是跟别人不太一样，挺有创意的。","pinyin":"tā de xiǎngfǎ zǒngshì gēn biéren bú tài yíyàng, tǐng yǒu chuàngyì de.","vn":"Suy nghĩ của anh ấy luôn khác người khác, khá sáng tạo."}]},{"hanzi":"任务","pinyin":"rènwù","pos":"dt.","vn":"nhiệm vụ","examples":[{"cn":"老板给我安排了一个新任务。","pinyin":"lǎobǎn gěi wǒ ānpái le yí ge xīn rènwù.","vn":"Sếp đã giao cho tôi một nhiệm vụ mới."},{"cn":"这次的任务很难，但是我们一定能完成。","pinyin":"zhè cì de rènwù hěn nán, dànshì wǒmen yídìng néng wánchéng.","vn":"Nhiệm vụ lần này rất khó, nhưng chúng tôi nhất định hoàn thành được."},{"cn":"我终于把这个月的任务完成了，可以放松一下了。","pinyin":"wǒ zhōngyú bǎ zhège yuè de rènwù wánchéng le, kěyǐ fàngsōng yíxià le.","vn":"Cuối cùng tôi cũng hoàn thành nhiệm vụ tháng này, có thể thư giãn một chút rồi."}]},{"hanzi":"及时","pinyin":"jíshí","pos":"phó./tt.","vn":"kịp thời","examples":[{"cn":"多亏了你及时提醒，不然我就迟到了。","pinyin":"duōkuī le nǐ jíshí tíxǐng, bùrán wǒ jiù chídào le.","vn":"May nhờ bạn nhắc nhở kịp thời, không thì tôi đã trễ rồi."},{"cn":"医生及时赶到，救了病人一命。","pinyin":"yīshēng jíshí gǎndào, jiù le bìngrén yí mìng.","vn":"Bác sĩ đến kịp thời, đã cứu sống bệnh nhân."},{"cn":"有问题要及时反馈给我们，别拖着。","pinyin":"yǒu wèntí yào jíshí fǎnkuì gěi wǒmen, bié tuōzhe.","vn":"Có vấn đề gì phải phản hồi kịp thời cho chúng tôi, đừng trì hoãn."}]},{"hanzi":"出差","pinyin":"chūchāi","pos":"dgt.","vn":"đi công tác","examples":[{"cn":"我下周要去上海出差。","pinyin":"wǒ xiàzhōu yào qù Shànghǎi chūchāi.","vn":"Tuần sau tôi phải đi công tác Thượng Hải."},{"cn":"他经常出差，一个月在家待不了几天。","pinyin":"tā jīngcháng chūchāi, yí ge yuè zài jiā dāibuliǎo jǐ tiān.","vn":"Anh ấy thường xuyên đi công tác, một tháng ở nhà không được mấy ngày."},{"cn":"出差的时候别忘了带充电器。","pinyin":"chūchāi de shíhou bié wàng le dài chōngdiànqì.","vn":"Lúc đi công tác đừng quên mang theo sạc điện thoại."}]},{"hanzi":"经验","pinyin":"jīngyàn","pos":"dt.","vn":"kinh nghiệm","examples":[{"cn":"这位老师教学经验很丰富。","pinyin":"zhè wèi lǎoshī jiàoxué jīngyàn hěn fēngfù.","vn":"Giáo viên này có kinh nghiệm giảng dạy rất phong phú."},{"cn":"没关系，失败也是一种经验。","pinyin":"méiguānxi, shībài yě shì yì zhǒng jīngyàn.","vn":"Không sao, thất bại cũng là một loại kinh nghiệm."},{"cn":"找工作的时候，经验比学历更重要。","pinyin":"zhǎo gōngzuò de shíhou, jīngyàn bǐ xuélì gèng zhòngyào.","vn":"Khi tìm việc, kinh nghiệm quan trọng hơn bằng cấp."}]},{"hanzi":"采访","pinyin":"cǎifǎng","pos":"dgt.","vn":"phỏng vấn","examples":[{"cn":"记者正在采访一位获奖的运动员。","pinyin":"jìzhě zhèngzài cǎifǎng yí wèi huòjiǎng de yùndòngyuán.","vn":"Phóng viên đang phỏng vấn một vận động viên đoạt giải."},{"cn":"明天电视台要来公司采访我们的经理。","pinyin":"míngtiān diànshìtái yào lái gōngsī cǎifǎng wǒmen de jīnglǐ.","vn":"Ngày mai đài truyền hình sẽ đến công ty phỏng vấn giám đốc của chúng tôi."},{"cn":"这次采访让我了解了很多以前不知道的事情。","pinyin":"zhè cì cǎifǎng ràng wǒ liǎojiě le hěn duō yǐqián bù zhīdào de shìqing.","vn":"Lần phỏng vấn này giúp tôi hiểu được nhiều điều mà trước đây không biết."}]},{"hanzi":"产品","pinyin":"chǎnpǐn","pos":"dt.","vn":"sản phẩm","examples":[{"cn":"我们公司新出的产品卖得特别好。","pinyin":"wǒmen gōngsī xīn chū de chǎnpǐn mài de tèbié hǎo.","vn":"Sản phẩm mới ra của công ty chúng tôi bán rất chạy."},{"cn":"这款产品质量不错，价格也合理。","pinyin":"zhè kuǎn chǎnpǐn zhìliàng búcuò, jiàgé yě hélǐ.","vn":"Sản phẩm này chất lượng tốt, giá cả cũng hợp lý."},{"cn":"他们正在开发一种新产品。","pinyin":"tāmen zhèngzài kāifā yì zhǒng xīn chǎnpǐn.","vn":"Họ đang phát triển một loại sản phẩm mới."}]},{"hanzi":"看法","pinyin":"kànfǎ","pos":"dt.","vn":"quan điểm, cách nhìn","examples":[{"cn":"你对这件事有什么看法？","pinyin":"nǐ duì zhè jiàn shì yǒu shénme kànfǎ?","vn":"Bạn có quan điểm gì về chuyện này?"},{"cn":"每个人的看法不一样，我们可以听听大家的意见。","pinyin":"měi ge rén de kànfǎ bù yíyàng, wǒmen kěyǐ tīngting dàjiā de yìjiàn.","vn":"Quan điểm mỗi người mỗi khác, chúng ta có thể lắng nghe ý kiến mọi người."},{"cn":"经过这次经历，我对生活有了新的看法。","pinyin":"jīngguò zhè cì jīnglì, wǒ duì shēnghuó yǒu le xīn de kànfǎ.","vn":"Qua trải nghiệm lần này, tôi đã có cách nhìn mới về cuộc sống."}]},{"hanzi":"提前","pinyin":"tíqián","pos":"dgt.","vn":"làm trước, tiến hành sớm","examples":[{"cn":"飞机提前了半个小时起飞。","pinyin":"fēijī tíqián le bàn ge xiǎoshí qǐfēi.","vn":"Máy bay cất cánh sớm nửa tiếng."},{"cn":"考试要提前十分钟到教室。","pinyin":"kǎoshì yào tíqián shí fēnzhōng dào jiàoshì.","vn":"Thi cử phải đến phòng học sớm mười phút."},{"cn":"我们最好提前订票，不然可能买不到了。","pinyin":"wǒmen zuìhǎo tíqián dìng piào, bùrán kěnéng mǎibudào le.","vn":"Chúng ta tốt nhất nên đặt vé trước, không thì có thể không mua được."}]},{"hanzi":"便于","pinyin":"biànyú","pos":"dgt.","vn":"thuận tiện cho","examples":[{"cn":"请把资料整理好，便于大家查看。","pinyin":"qǐng bǎ zīliào zhěnglǐhǎo, biànyú dàjiā chákàn.","vn":"Xin hãy sắp xếp tài liệu cho gọn, để mọi người tiện xem."},{"cn":"这种设计便于用户操作。","pinyin":"zhè zhǒng shèjì biànyú yònghù cāozuò.","vn":"Thiết kế kiểu này thuận tiện cho người dùng thao tác."},{"cn":"为了便于联系，请留下你的手机号码。","pinyin":"wèile biànyú liánxì, qǐng liúxià nǐ de shǒujī hàomǎ.","vn":"Để tiện liên lạc, xin để lại số điện thoại của bạn."}]},{"hanzi":"既然","pinyin":"jìrán","pos":"liên.","vn":"đã như vậy thì, bởi vì","examples":[{"cn":"既然你已经决定了，我就不再劝你了。","pinyin":"jìrán nǐ yǐjīng juédìng le, wǒ jiù bú zài quàn nǐ le.","vn":"Đã như vậy là bạn quyết định rồi, tôi sẽ không khuyên bạn nữa."},{"cn":"既然下雨了，我们就改天再去吧。","pinyin":"jìrán xiàyǔ le, wǒmen jiù gǎitiān zài qù ba.","vn":"Đã mưa rồi thì chúng ta đổi ngày khác đi vậy."},{"cn":"既然大家都同意，那就这么定了。","pinyin":"jìrán dàjiā dōu tóngyì, nà jiù zhème dìng le.","vn":"Mọi người đã đồng ý rồi thì cứ quyết định như vậy nhé."}]},{"hanzi":"谈","pinyin":"tán","pos":"dgt.","vn":"bàn bạc, nói chuyện","examples":[{"cn":"我们找个时间好好谈谈吧。","pinyin":"wǒmen zhǎo ge shíjiān hǎohǎo tántan ba.","vn":"Chúng ta tìm thời gian nói chuyện kỹ một chút đi."},{"cn":"他正在和客户谈一个大项目。","pinyin":"tā zhèngzài hé kèhù tán yí ge dà xiàngmù.","vn":"Anh ấy đang bàn bạc với khách hàng về một dự án lớn."},{"cn":"这个问题不太好谈，我们先放一放吧。","pinyin":"zhège wèntí bú tài hǎo tán, wǒmen xiān fàng yi fàng ba.","vn":"Vấn đề này khó bàn, chúng ta tạm gác lại đã."}]},{"hanzi":"笔","pinyin":"bǐ","pos":"lượng.","vn":"khoản (dùng cho tiền bạc, tài khoản...)","examples":[{"cn":"公司这个月签了一笔大生意。","pinyin":"gōngsī zhège yuè qiān le yì bǐ dà shēngyi.","vn":"Tháng này công ty đã ký được một khoản làm ăn lớn."},{"cn":"他从银行取了一笔钱。","pinyin":"tā cóng yínháng qǔ le yì bǐ qián.","vn":"Anh ấy đã rút một khoản tiền từ ngân hàng."},{"cn":"这笔账我还没算清楚。","pinyin":"zhè bǐ zhàng wǒ hái méi suàn qīngchu.","vn":"Khoản tiền này tôi vẫn chưa tính rõ ràng."}]},{"hanzi":"生意","pinyin":"shēngyi","pos":"dt.","vn":"công việc kinh doanh, buôn bán","examples":[{"cn":"他的生意做得越来越大了。","pinyin":"tā de shēngyi zuò de yuèláiyuè dà le.","vn":"Công việc kinh doanh của anh ấy ngày càng lớn mạnh."},{"cn":"最近生意不太好，店里客人很少。","pinyin":"zuìjìn shēngyi bú tài hǎo, diàn lǐ kèrén hěn shǎo.","vn":"Dạo này buôn bán không tốt lắm, khách ở cửa hàng rất ít."},{"cn":"她辞职以后自己开始做生意了。","pinyin":"tā cízhí yǐhòu zìjǐ kāishǐ zuò shēngyi le.","vn":"Sau khi nghỉ việc, cô ấy bắt đầu tự kinh doanh."}]},{"hanzi":"困难","pinyin":"kùnnan","pos":"dt./tt.","vn":"khó khăn","examples":[{"cn":"我们遇到了一些困难，但一定能克服。","pinyin":"wǒmen yùdào le yìxiē kùnnan, dàn yídìng néng kèfú.","vn":"Chúng tôi gặp phải một số khó khăn, nhưng nhất định sẽ vượt qua được."},{"cn":"这道题对我来说有点困难。","pinyin":"zhè dào tí duì wǒ láishuō yǒudiǎn kùnnan.","vn":"Bài này đối với tôi hơi khó."},{"cn":"家里经济困难，他从小就很懂事。","pinyin":"jiā lǐ jīngjì kùnnan, tā cóngxiǎo jiù hěn dǒngshì.","vn":"Kinh tế gia đình khó khăn, anh ấy từ nhỏ đã rất hiểu chuyện."}]},{"hanzi":"优点","pinyin":"yōudiǎn","pos":"dt.","vn":"ưu điểm","examples":[{"cn":"她的优点是做事很认真。","pinyin":"tā de yōudiǎn shì zuòshì hěn rènzhēn.","vn":"Ưu điểm của cô ấy là làm việc rất nghiêm túc."},{"cn":"这种材料的优点是又轻又结实。","pinyin":"zhè zhǒng cáiliào de yōudiǎn shì yòu qīng yòu jiēshi.","vn":"Ưu điểm của loại vật liệu này là vừa nhẹ vừa chắc chắn."},{"cn":"每个人都有自己的优点，不用跟别人比。","pinyin":"měi ge rén dōu yǒu zìjǐ de yōudiǎn, búyòng gēn biéren bǐ.","vn":"Mỗi người đều có ưu điểm riêng, không cần so sánh với người khác."}]},{"hanzi":"缺点","pinyin":"quēdiǎn","pos":"dt.","vn":"khuyết điểm, nhược điểm","examples":[{"cn":"每个人都有缺点，不用太在意。","pinyin":"měi ge rén dōu yǒu quēdiǎn, búyòng tài zàiyì.","vn":"Ai cũng có khuyết điểm, không cần để tâm quá."},{"cn":"这个计划有一个明显的缺点，就是花费太高。","pinyin":"zhège jìhuà yǒu yí ge míngxiǎn de quēdiǎn, jiùshì huāfèi tài gāo.","vn":"Kế hoạch này có một khuyết điểm rõ ràng, đó là chi phí quá cao."},{"cn":"他最大的缺点是太固执了。","pinyin":"tā zuìdà de quēdiǎn shì tài gùzhí le.","vn":"Khuyết điểm lớn nhất của anh ấy là quá cố chấp."}]},{"hanzi":"实际","pinyin":"shíjì","pos":"tt./dt.","vn":"thực tế","examples":[{"cn":"这个计划听起来不错，但不太实际。","pinyin":"zhège jìhuà tīngqǐlái búcuò, dàn bú tài shíjì.","vn":"Kế hoạch này nghe có vẻ hay, nhưng không thực tế lắm."},{"cn":"我们要根据实际情况来调整计划。","pinyin":"wǒmen yào gēnjù shíjì qíngkuàng lái tiáozhěng jìhuà.","vn":"Chúng ta phải điều chỉnh kế hoạch theo tình hình thực tế."},{"cn":"他看起来很年轻，实际已经四十岁了。","pinyin":"tā kànqǐlái hěn niánqīng, shíjì yǐjīng sìshí suì le.","vn":"Anh ấy trông còn trẻ, thực tế đã bốn mươi tuổi rồi."}]},{"hanzi":"效果","pinyin":"xiàoguǒ","pos":"dt.","vn":"hiệu quả","examples":[{"cn":"这种药的效果很明显，吃了两天就好多了。","pinyin":"zhè zhǒng yào de xiàoguǒ hěn míngxiǎn, chī le liǎng tiān jiù hǎo duō le.","vn":"Loại thuốc này hiệu quả rất rõ, uống hai ngày đã đỡ nhiều rồi."},{"cn":"广告效果不太好，没带来多少客户。","pinyin":"guǎnggào xiàoguǒ bú tài hǎo, méi dàilái duōshǎo kèhù.","vn":"Hiệu quả quảng cáo không tốt lắm, không mang lại nhiều khách hàng."},{"cn":"新方法试了一下，效果比以前好多了。","pinyin":"xīn fāngfǎ shì le yíxià, xiàoguǒ bǐ yǐqián hǎo duō le.","vn":"Thử phương pháp mới, hiệu quả tốt hơn trước nhiều."}]},{"hanzi":"点","pinyin":"diǎn","pos":"dt.","vn":"điểm","examples":[{"cn":"你说的这个点很重要，我记下来了。","pinyin":"nǐ shuō de zhège diǎn hěn zhòngyào, wǒ jìxiàlái le.","vn":"Điểm bạn nói rất quan trọng, tôi đã ghi lại rồi."},{"cn":"这篇报告有几个重点需要再强调一下。","pinyin":"zhè piān bàogào yǒu jǐ ge zhòngdiǎn xūyào zài qiángdiào yíxià.","vn":"Bản báo cáo này có mấy điểm trọng tâm cần nhấn mạnh thêm."},{"cn":"我觉得他说得有道理，特别是最后那一点。","pinyin":"wǒ juéde tā shuō de yǒu dàolǐ, tèbié shì zuìhòu nà yì diǎn.","vn":"Tôi thấy anh ấy nói có lý, đặc biệt là điểm cuối cùng đó."}]},{"hanzi":"一下","pinyin":"yíxià","pos":"phó.","vn":"ngay lập tức, bỗng nhiên","examples":[{"cn":"他一下愣住了，不知道该说什么。","pinyin":"tā yíxià lèngzhù le, bù zhīdào gāi shuō shénme.","vn":"Anh ấy bỗng sững người, không biết nên nói gì."},{"cn":"听到这个消息，她一下哭了出来。","pinyin":"tīngdào zhège xiāoxi, tā yíxià kū le chūlái.","vn":"Nghe tin này, cô ấy bỗng bật khóc."},{"cn":"天气一下冷了下来，大家都穿上了外套。","pinyin":"tiānqì yíxià lěng le xiàlái, dàjiā dōu chuānshàng le wàitào.","vn":"Thời tiết bỗng trở lạnh, mọi người đều khoác thêm áo khoác."}]},{"hanzi":"份","pinyin":"fèn","pos":"lượng.","vn":"phần, bản (dùng để chỉ phần, bản, bộ...)","examples":[{"cn":"请给我一份报纸。","pinyin":"qǐng gěi wǒ yí fèn bàozhǐ.","vn":"Cho tôi một tờ báo."},{"cn":"这份报告你看完了吗？","pinyin":"zhè fèn bàogào nǐ kànwán le ma?","vn":"Bản báo cáo này bạn xem xong chưa?"},{"cn":"我想点一份炒饭和一份汤。","pinyin":"wǒ xiǎng diǎn yí fèn chǎofàn hé yí fèn tāng.","vn":"Tôi muốn gọi một phần cơm rang và một phần canh."}]},{"hanzi":"积累","pinyin":"jīlěi","pos":"dgt.","vn":"tích lũy","examples":[{"cn":"学习语言需要慢慢积累词汇量。","pinyin":"xuéxí yǔyán xūyào mànmàn jīlěi cíhuìliàng.","vn":"Học ngôn ngữ cần tích lũy dần dần vốn từ vựng."},{"cn":"他工作多年，积累了不少经验。","pinyin":"tā gōngzuò duō nián, jīlěi le bùshǎo jīngyàn.","vn":"Anh ấy làm việc nhiều năm, đã tích lũy không ít kinh nghiệm."},{"cn":"这些问题都是长期积累下来的，不是一天造成的。","pinyin":"zhèxiē wèntí dōu shì chángqī jīlěi xiàlái de, búshì yì tiān zàochéng de.","vn":"Những vấn đề này đều do tích lũy lâu dài, không phải do một ngày mà thành."}]},{"hanzi":"使","pinyin":"shǐ","pos":"dgt.","vn":"khiến cho, làm cho","examples":[{"cn":"这件事使我明白了很多道理。","pinyin":"zhè jiàn shì shǐ wǒ míngbai le hěn duō dàolǐ.","vn":"Chuyện này khiến tôi hiểu ra được nhiều đạo lý."},{"cn":"他的鼓励使我有了继续努力的勇气。","pinyin":"tā de gǔlì shǐ wǒ yǒu le jìxù nǔlì de yǒngqì.","vn":"Sự động viên của anh ấy khiến tôi có dũng khí tiếp tục cố gắng."},{"cn":"这种新技术能使生产效率大大提高。","pinyin":"zhè zhǒng xīn jìshù néng shǐ shēngchǎn xiàolǜ dàdà tígāo.","vn":"Công nghệ mới này có thể khiến hiệu suất sản xuất tăng lên đáng kể."}]},{"hanzi":"进入","pinyin":"jìnrù","pos":"dgt.","vn":"tiến vào, bước vào","examples":[{"cn":"毕业以后他就进入了一家大公司工作。","pinyin":"bìyè yǐhòu tā jiù jìnrù le yì jiā dà gōngsī gōngzuò.","vn":"Sau khi tốt nghiệp, anh ấy đã vào làm việc tại một công ty lớn."},{"cn":"我们已经正式进入冬天了。","pinyin":"wǒmen yǐjīng zhèngshì jìnrù dōngtiān le.","vn":"Chúng ta đã chính thức bước vào mùa đông."},{"cn":"请大家把手机静音，比赛马上就要进入第二轮了。","pinyin":"qǐng dàjiā bǎ shǒujī jìngyīn, bǐsài mǎshàng jiù yào jìnrù dì èr lún le.","vn":"Mời mọi người tắt chuông điện thoại, trận đấu sắp bước vào vòng hai rồi."}]},{"hanzi":"社会","pinyin":"shèhuì","pos":"dt.","vn":"xã hội","examples":[{"cn":"我们要努力做一个对社会有用的人。","pinyin":"wǒmen yào nǔlì zuò yí ge duì shèhuì yǒuyòng de rén.","vn":"Chúng ta phải cố gắng trở thành người có ích cho xã hội."},{"cn":"现在社会发展得很快，变化很大。","pinyin":"xiànzài shèhuì fāzhǎn de hěn kuài, biànhuà hěn dà.","vn":"Xã hội hiện nay phát triển rất nhanh, thay đổi rất lớn."},{"cn":"刚进入社会的年轻人往往缺少经验。","pinyin":"gāng jìnrù shèhuì de niánqīngrén wǎngwǎng quēshǎo jīngyàn.","vn":"Những người trẻ mới bước vào xã hội thường thiếu kinh nghiệm."}]},{"hanzi":"管理","pinyin":"guǎnlǐ","pos":"dgt.","vn":"quản lý","examples":[{"cn":"他负责管理公司的财务。","pinyin":"tā fùzé guǎnlǐ gōngsī de cáiwù.","vn":"Anh ấy phụ trách quản lý tài chính của công ty."},{"cn":"这个小区的管理做得不错，很安全。","pinyin":"zhège xiǎoqū de guǎnlǐ zuò de búcuò, hěn ānquán.","vn":"Khu dân cư này quản lý khá tốt, rất an toàn."},{"cn":"她工作能力强，很快就被提升为管理人员。","pinyin":"tā gōngzuò nénglì qiáng, hěn kuài jiù bèi tíshēng wéi guǎnlǐ rényuán.","vn":"Năng lực làm việc của cô ấy mạnh, chẳng mấy chốc đã được thăng chức làm quản lý."}]},{"hanzi":"基础","pinyin":"jīchǔ","pos":"dt.","vn":"nền tảng, cơ sở","examples":[{"cn":"打好基础对学习来说非常重要。","pinyin":"dǎhǎo jīchǔ duì xuéxí láishuō fēicháng zhòngyào.","vn":"Xây dựng nền tảng vững chắc rất quan trọng đối với việc học."},{"cn":"他的英语基础很好，学起来很快。","pinyin":"tā de Yīngyǔ jīchǔ hěn hǎo, xué qǐlái hěn kuài.","vn":"Nền tảng tiếng Anh của anh ấy rất tốt, học rất nhanh."},{"cn":"信任是朋友关系的基础。","pinyin":"xìnrèn shì péngyou guānxì de jīchǔ.","vn":"Sự tin tưởng là nền tảng của mối quan hệ bạn bè."}]},{"hanzi":"能力","pinyin":"nénglì","pos":"dt.","vn":"năng lực","examples":[{"cn":"他的工作能力很强，经理很信任他。","pinyin":"tā de gōngzuò nénglì hěn qiáng, jīnglǐ hěn xìnrèn tā.","vn":"Năng lực làm việc của anh ấy rất mạnh, giám đốc rất tin tưởng anh ấy."},{"cn":"这家公司很看重应聘者的沟通能力。","pinyin":"zhè jiā gōngsī hěn kànzhòng yìngpìnzhě de gōutōng nénglì.","vn":"Công ty này rất coi trọng khả năng giao tiếp của ứng viên."},{"cn":"多参加这样的活动可以锻炼你的能力。","pinyin":"duō cānjiā zhèyàng de huódòng kěyǐ duànliàn nǐ de nénglì.","vn":"Tham gia nhiều hoạt động như vậy có thể rèn luyện năng lực của bạn."}]},{"hanzi":"今后","pinyin":"jīnhòu","pos":"dt.","vn":"từ nay về sau, tương lai","examples":[{"cn":"今后我会更加努力工作。","pinyin":"jīnhòu wǒ huì gèngjiā nǔlì gōngzuò.","vn":"Từ nay về sau tôi sẽ làm việc chăm chỉ hơn."},{"cn":"希望大家今后多多关照。","pinyin":"xīwàng dàjiā jīnhòu duōduō guānzhào.","vn":"Mong mọi người từ nay về sau chiếu cố nhiều."},{"cn":"今后遇到问题要及时跟我说。","pinyin":"jīnhòu yùdào wèntí yào jíshí gēn wǒ shuō.","vn":"Về sau gặp vấn đề gì phải nói với tôi kịp thời."}]}],"grammar":[{"title":"固定格式\"在……方面\"","explanation_vn":"Cấu trúc cố định \"在……方面\" (về mặt...) dùng để giới hạn phạm vi hoặc lĩnh vực đang bàn luận.","examples":[{"cn":"在内容方面，您觉得有需要改的吗？","pinyin":"","vn":"Về mặt nội dung, chị thấy có cần sửa gì không?"},{"cn":"在时间安排方面，你可以再想一想。","pinyin":"","vn":"Về mặt sắp xếp thời gian, bạn có thể suy nghĩ thêm."},{"cn":"他才来中国两个月，在生活方面，还不太习惯。","pinyin":"","vn":"Anh ấy mới đến Trung Quốc được hai tháng, về mặt sinh hoạt, vẫn chưa quen lắm."}]},{"title":"因果复句\"既然……，就……\"","explanation_vn":"Câu phức nhân quả \"既然……，就……\" (đã như vậy thì...): vế trước nêu tiền đề, vế sau nêu kết luận được suy ra từ tiền đề đó.","examples":[{"cn":"既然出差时间不长，就要安排好时间，多获得有用的信息。","pinyin":"","vn":"Đã đi công tác không lâu thì phải sắp xếp thời gian tốt, thu thập nhiều thông tin hữu ích."},{"cn":"既然大家都同意，我们就这么做吧。","pinyin":"","vn":"Đã mọi người đều đồng ý thì chúng ta cứ làm như vậy đi."},{"cn":"既然你们已经决定了，就不要再改了。","pinyin":"","vn":"Đã các bạn quyết định rồi thì đừng thay đổi nữa."}]},{"title":"固定格式\"拿……来说\"","explanation_vn":"Cấu trúc cố định \"拿……来说\" (lấy... mà nói) dùng để dẫn ra một khía cạnh cụ thể hoặc ví dụ.","examples":[{"cn":"拿和客户交流来说，虽然她能把产品的优缺点说得很清楚，但实际效果并不理想。","pinyin":"","vn":"Lấy việc giao tiếp với khách hàng mà nói, tuy cô ấy có thể trình bày rõ ràng ưu nhược điểm của sản phẩm, nhưng hiệu quả thực tế lại không như ý."},{"cn":"现在的生活很方便。拿购物来说，人们不出门就能买到想要的东西。","pinyin":"","vn":"Cuộc sống hiện nay rất tiện lợi. Lấy việc mua sắm mà nói, người ta không cần ra khỏi nhà cũng có thể mua được thứ mình muốn."},{"cn":"在中国，南北方的生活习惯不同。拿吃饭来说，一般南方人更爱吃米饭。","pinyin":"","vn":"Ở Trung Quốc, thói quen sinh hoạt giữa miền Nam và miền Bắc khác nhau. Lấy việc ăn uống mà nói, người miền Nam nhìn chung thích ăn cơm hơn."}]},{"title":"兼语句\"主语+使+宾语+动词短语\"","explanation_vn":"Câu kiêm ngữ \"chủ ngữ + 使 + tân ngữ + cụm động từ\" biểu thị một tình huống hoặc nguyên nhân nào đó khiến người hoặc sự vật xảy ra thay đổi hoặc tạo ra kết quả.","examples":[{"cn":"如果总是换工作，可能会使自己的发展受到影响。","pinyin":"","vn":"Nếu cứ liên tục đổi việc, có thể sẽ khiến sự phát triển của bản thân bị ảnh hưởng."},{"cn":"这个新方法使工作变得更加简单了。","pinyin":"","vn":"Phương pháp mới này khiến công việc trở nên đơn giản hơn."},{"cn":"参加这些交流活动使留学生更快适应了大学生活。","pinyin":"","vn":"Việc tham gia các hoạt động giao lưu này giúp lưu học sinh thích nghi nhanh hơn với cuộc sống đại học."}]}],"texts":[{"label":"Bài khóa 1","type":"dialogue","lines":[{"speaker":"同事","cn":"经理，打扰您一下。市场调查的计划书我昨天发到您邮箱了。在内容方面，您觉得有需要改的吗？","pinyin":""},{"speaker":"王一雪","cn":"我看过了，写得不错，就是调查的地点只有超市，不太够。","pinyin":""},{"speaker":"同事","cn":"好的，那我再加一些网店。","pinyin":""},{"speaker":"王一雪","cn":"行。做调查的时候要细心，注意了解客户真正的想法。","pinyin":""},{"speaker":"同事","cn":"明白了，我会认真准备，按时完成任务。","pinyin":""},{"speaker":"王一雪","cn":"嗯，如果遇到什么问题，及时跟我联系。","pinyin":""}],"translation_vn":"Đồng nghiệp: Giám đốc, làm phiền chị một chút. Bản kế hoạch khảo sát thị trường em đã gửi vào email của chị hôm qua rồi. Về mặt nội dung, chị thấy có cần sửa gì không ạ?\nVương Nhất Tuyết: Chị xem rồi, viết khá tốt, chỉ có điều địa điểm khảo sát chỉ có siêu thị, chưa đủ.\nĐồng nghiệp: Vâng, vậy em sẽ thêm một số cửa hàng trực tuyến.\nVương Nhất Tuyết: Được. Khi khảo sát phải cẩn thận, chú ý tìm hiểu suy nghĩ thực sự của khách hàng.\nĐồng nghiệp: Em hiểu rồi, em sẽ chuẩn bị kỹ càng, hoàn thành nhiệm vụ đúng hạn.\nVương Nhất Tuyết: Ừ, nếu gặp vấn đề gì thì liên hệ với chị kịp thời nhé.","audio_dialogue":"7-1.mp3","audio_vocab":"7-2.mp3"},{"label":"Bài khóa 2","type":"dialogue","lines":[{"speaker":"同事","cn":"杨哥，经理让我下周去上海出差，做市场调查，你有这方面的经验吗？","pinyin":""},{"speaker":"杨同乐","cn":"你要去几天？主要调查什么内容？","pinyin":""},{"speaker":"同事","cn":"去四天，打算采访一些客户，了解他们对新产品的看法。","pinyin":""},{"speaker":"杨同乐","cn":"那你要提前准备好问题，便于和客户交流。","pinyin":""},{"speaker":"同事","cn":"好的，我已经准备了一些问题。","pinyin":""},{"speaker":"杨同乐","cn":"很好。既然出差时间不长，就要安排好时间，多获得有用的信息。","pinyin":""}],"translation_vn":"Đồng nghiệp: Anh Dương, giám đốc bảo em tuần sau đi công tác Thượng Hải, làm khảo sát thị trường, anh có kinh nghiệm về việc này không?\nDương Đồng Lạc: Em đi mấy ngày? Chủ yếu khảo sát nội dung gì?\nĐồng nghiệp: Đi bốn ngày, em định phỏng vấn một số khách hàng, tìm hiểu ý kiến của họ về sản phẩm mới.\nDương Đồng Lạc: Vậy em phải chuẩn bị trước các câu hỏi, để thuận tiện giao tiếp với khách hàng.\nĐồng nghiệp: Vâng, em đã chuẩn bị sẵn một số câu hỏi rồi.\nDương Đồng Lạc: Tốt lắm. Đã đi công tác không lâu thì phải sắp xếp thời gian tốt, thu thập nhiều thông tin hữu ích.","audio_dialogue":"7-3.mp3","audio_vocab":"7-4.mp3"},{"label":"Bài khóa 3","type":"passage","lines":[{"speaker":"","cn":"前段时间，杨同乐的同事谈成了一笔不错的生意。刚开始，这位同事也遇到了一些困难。拿和客户交流来说，虽然她能把产品的优缺点说得很清楚，但实际效果并不理想。杨同乐告诉她，这是因为她介绍的方式都一样。其实，不同年龄、不同性别的客户对产品的关注点是不一样的。于是，这位同事又认真地进行了几次市场调查，了解不同客户的想法。后来她在面对不同客户时，能根据他们的情况介绍产品，效果一下就好了很多。","pinyin":""}],"translation_vn":"Một thời gian trước, đồng nghiệp của Dương Đồng Lạc đã đàm phán thành công một thương vụ khá tốt. Lúc đầu, đồng nghiệp này cũng gặp phải một số khó khăn. Lấy việc giao tiếp với khách hàng mà nói, tuy cô ấy có thể trình bày rõ ràng ưu nhược điểm của sản phẩm, nhưng hiệu quả thực tế lại không như ý. Dương Đồng Lạc nói với cô ấy rằng đó là vì cách giới thiệu của cô lúc nào cũng giống nhau. Thực ra, khách hàng ở độ tuổi khác nhau, giới tính khác nhau sẽ có những điểm quan tâm khác nhau đối với sản phẩm. Thế là, đồng nghiệp này lại nghiêm túc tiến hành khảo sát thị trường thêm vài lần nữa, tìm hiểu suy nghĩ của các khách hàng khác nhau. Sau đó khi đối diện với các khách hàng khác nhau, cô ấy có thể giới thiệu sản phẩm theo tình hình của từng người, hiệu quả nhờ đó tốt lên rất nhiều.","audio_dialogue":"7-5.mp3","audio_vocab":"7-6.mp3"},{"label":"Bài khóa 4","type":"passage","lines":[{"speaker":"","cn":"有的年轻人经常换工作，总觉得下一份工作会更好。但是，适应新工作往往需要比较长的时间。如果总是换工作，不但很难积累经验，还可能会使自己的发展受到影响。我认为，年轻人刚进入社会时，不能只关心工资的高低，更要重视学习。比如，学习课本中没有的专业知识，了解公司的管理方式，学会和同事有效交流，等等。只有把这些基础打好，提高工作能力，今后才会有更好的发展机会。","pinyin":""}],"translation_vn":"Có những người trẻ thường xuyên đổi việc, luôn cảm thấy công việc tiếp theo sẽ tốt hơn. Nhưng thích nghi với công việc mới thường cần một khoảng thời gian khá dài. Nếu cứ liên tục đổi việc, không những khó tích lũy kinh nghiệm, mà còn có thể khiến sự phát triển của bản thân bị ảnh hưởng. Tôi cho rằng, khi người trẻ mới bước vào xã hội, không nên chỉ quan tâm đến mức lương cao hay thấp, mà càng phải coi trọng việc học hỏi. Ví dụ như học những kiến thức chuyên môn không có trong sách giáo khoa, tìm hiểu cách quản lý của công ty, học cách giao tiếp hiệu quả với đồng nghiệp, v.v. Chỉ khi xây dựng tốt những nền tảng này, nâng cao năng lực làm việc, thì sau này mới có cơ hội phát triển tốt hơn.","audio_dialogue":"7-7.mp3","audio_vocab":"7-8.mp3"}]},{"id":8,"title_cn":"该放松时就放松","title_pinyin":"","title_vn":"Khi cần thư giãn thì hãy thư giãn","goals":["Có thể nghe hiểu và trao đổi về các chủ đề liên quan đến phương pháp và cách thức giảm căng thẳng.","Có thể trình bày bằng lời nói hoặc văn bản quan điểm về việc giảm căng thẳng và thư giãn.","Hiểu được vào cuối tuần người Trung Quốc thường đi đâu để thư giãn."],"vocab":[{"hanzi":"紧张","pinyin":"jǐnzhāng","pos":"tt.","vn":"căng thẳng; (nguồn cung) khan hiếm","examples":[{"cn":"我第一次上台演讲，特别紧张。","pinyin":"wǒ dì yī cì shàngtái yǎnjiǎng, tèbié jǐnzhāng.","vn":"Lần đầu tiên lên sân khấu diễn thuyết, tôi rất căng thẳng."},{"cn":"最近工作太忙了，生活节奏一直很紧张。","pinyin":"zuìjìn gōngzuò tài máng le, shēnghuó jiézòu yìzhí hěn jǐnzhāng.","vn":"Dạo này công việc quá bận, nhịp sống luôn căng thẳng."},{"cn":"过年期间火车票很紧张，要提前订。","pinyin":"guònián qījiān huǒchēpiào hěn jǐnzhāng, yào tíqián dìng.","vn":"Dịp Tết vé tàu rất khan hiếm, phải đặt trước."}]},{"hanzi":"放松","pinyin":"fàngsōng","pos":"dgt.","vn":"thư giãn, thả lỏng","examples":[{"cn":"周末我喜欢听听音乐，放松一下。","pinyin":"zhōumò wǒ xǐhuan tīngting yīnyuè, fàngsōng yíxià.","vn":"Cuối tuần tôi thích nghe nhạc để thư giãn một chút."},{"cn":"考完试了，终于可以放松放松了。","pinyin":"kǎowán shì le, zhōngyú kěyǐ fàngsōng fàngsōng le.","vn":"Thi xong rồi, cuối cùng cũng có thể thư giãn một chút."},{"cn":"深呼吸，放松身体，别那么紧张。","pinyin":"shēn hūxī, fàngsōng shēntǐ, bié nàme jǐnzhāng.","vn":"Hít thở sâu, thả lỏng cơ thể, đừng căng thẳng như vậy."}]},{"hanzi":"呀","pinyin":"yā","pos":"ct.","vn":"ôi, ồ (thán từ)","examples":[{"cn":"呀，下雨了！快把衣服收进来。","pinyin":"yā, xiàyǔ le! kuài bǎ yīfu shōu jìnlái.","vn":"Ôi, trời mưa rồi! Mau thu quần áo vào đi."},{"cn":"呀，这个蛋糕看起来好好吃啊！","pinyin":"yā, zhège dàngāo kànqǐlái hǎo hǎochī a!","vn":"Ồ, cái bánh này trông ngon quá đi!"},{"cn":"呀，我把钥匙忘在家里了。","pinyin":"yā, wǒ bǎ yàoshi wàng zài jiā lǐ le.","vn":"Ôi, tôi để quên chìa khóa ở nhà rồi."}]},{"hanzi":"不管","pinyin":"bùguǎn","pos":"liên.","vn":"bất kể, dù cho","examples":[{"cn":"不管多忙，他每天都抽时间陪孩子。","pinyin":"bùguǎn duō máng, tā měitiān dōu chōu shíjiān péi háizi.","vn":"Dù bận đến đâu, anh ấy mỗi ngày đều dành thời gian ở bên con."},{"cn":"不管别人怎么说，我都要坚持自己的想法。","pinyin":"bùguǎn biéren zěnme shuō, wǒ dōu yào jiānchí zìjǐ de xiǎngfǎ.","vn":"Dù người khác nói thế nào, tôi vẫn kiên trì suy nghĩ của mình."},{"cn":"不管刮风下雨，他都坚持跑步。","pinyin":"bùguǎn guāfēng xiàyǔ, tā dōu jiānchí pǎobù.","vn":"Bất kể mưa gió, anh ấy đều kiên trì chạy bộ."}]},{"hanzi":"郊区","pinyin":"jiāoqū","pos":"dt.","vn":"ngoại ô","examples":[{"cn":"我家住在郊区，空气比市区好多了。","pinyin":"wǒ jiā zhù zài jiāoqū, kōngqì bǐ shìqū hǎo duō le.","vn":"Nhà tôi ở ngoại ô, không khí tốt hơn nội thành nhiều."},{"cn":"周末我们打算去郊区爬山。","pinyin":"zhōumò wǒmen dǎsuàn qù jiāoqū páshān.","vn":"Cuối tuần chúng tôi định đi leo núi ở ngoại ô."},{"cn":"这家餐厅开在郊区，环境特别安静。","pinyin":"zhè jiā cāntīng kāi zài jiāoqū, huánjìng tèbié ānjìng.","vn":"Nhà hàng này mở ở ngoại ô, môi trường rất yên tĩnh."}]},{"hanzi":"游玩","pinyin":"yóuwán","pos":"dgt.","vn":"đi chơi, du ngoạn","examples":[{"cn":"我们打算这个周末去公园游玩。","pinyin":"wǒmen dǎsuàn zhège zhōumò qù gōngyuán yóuwán.","vn":"Chúng tôi định cuối tuần này đi công viên chơi."},{"cn":"暑假我带孩子去海边游玩了几天。","pinyin":"shǔjià wǒ dài háizi qù hǎibiān yóuwán le jǐ tiān.","vn":"Nghỉ hè tôi đưa con đi chơi ở biển mấy ngày."},{"cn":"这个景点很适合一家人游玩。","pinyin":"zhège jǐngdiǎn hěn shìhé yì jiā rén yóuwán.","vn":"Điểm tham quan này rất thích hợp cho cả gia đình đi chơi."}]},{"hanzi":"主意","pinyin":"zhǔyi","pos":"dt.","vn":"ý kiến, chủ ý","examples":[{"cn":"他突然想到一个好主意。","pinyin":"tā tūrán xiǎngdào yí ge hǎo zhǔyi.","vn":"Anh ấy bỗng nghĩ ra một ý kiến hay."},{"cn":"你拿个主意吧，我都行。","pinyin":"nǐ ná ge zhǔyi ba, wǒ dōu xíng.","vn":"Bạn quyết định đi, tôi sao cũng được."},{"cn":"别总是改主意，这样很难做决定。","pinyin":"bié zǒngshì gǎi zhǔyi, zhèyàng hěn nán zuò juédìng.","vn":"Đừng cứ đổi ý suốt, như vậy rất khó đưa ra quyết định."}]},{"hanzi":"外出","pinyin":"wàichū","pos":"dgt.","vn":"ra ngoài, đi ra ngoài","examples":[{"cn":"外出的时候请记得带上雨伞。","pinyin":"wàichū de shíhou qǐng jìde dàishàng yǔsǎn.","vn":"Khi ra ngoài xin nhớ mang theo ô."},{"cn":"他经常外出办事，很少在办公室。","pinyin":"tā jīngcháng wàichū bànshì, hěn shǎo zài bàngōngshì.","vn":"Anh ấy thường xuyên ra ngoài giải quyết việc, ít khi ở văn phòng."},{"cn":"外出旅行前要检查好所有证件。","pinyin":"wàichū lǚxíng qián yào jiǎnchá hǎo suǒyǒu zhèngjiàn.","vn":"Trước khi ra ngoài du lịch phải kiểm tra kỹ tất cả giấy tờ."}]},{"hanzi":"戴","pinyin":"dài","pos":"dgt.","vn":"đội, đeo","examples":[{"cn":"外面很冷，出门记得戴手套。","pinyin":"wàimian hěn lěng, chūmén jìde dài shǒutào.","vn":"Bên ngoài rất lạnh, ra ngoài nhớ đeo găng tay."},{"cn":"她戴着一副好看的眼镜。","pinyin":"tā dàizhe yí fù hǎokàn de yǎnjìng.","vn":"Cô ấy đang đeo một cặp kính rất đẹp."},{"cn":"骑车的时候一定要戴头盔。","pinyin":"qíchē de shíhou yídìng yào dài tóukuī.","vn":"Khi đi xe nhất định phải đội mũ bảo hiểm."}]},{"hanzi":"帽子","pinyin":"màozi","pos":"dt.","vn":"mũ, nón","examples":[{"cn":"今天太阳很大，我戴了一顶帽子。","pinyin":"jīntiān tàiyáng hěn dà, wǒ dài le yì dǐng màozi.","vn":"Hôm nay nắng to, tôi đã đội một chiếc mũ."},{"cn":"这顶帽子是我妈妈送我的生日礼物。","pinyin":"zhè dǐng màozi shì wǒ māma sòng wǒ de shēngrì lǐwù.","vn":"Chiếc mũ này là quà sinh nhật mẹ tặng tôi."},{"cn":"风太大了，他的帽子被吹跑了。","pinyin":"fēng tài dà le, tā de màozi bèi chuīpǎo le.","vn":"Gió quá to, mũ của anh ấy bị thổi bay mất."}]},{"hanzi":"长城","pinyin":"Chángchéng","pos":"danh từ riêng","vn":"Vạn Lý Trường Thành","examples":[{"cn":"我终于有机会去长城看看了。","pinyin":"wǒ zhōngyú yǒu jīhuì qù Chángchéng kànkan le.","vn":"Cuối cùng tôi cũng có cơ hội đi xem Vạn Lý Trường Thành."},{"cn":"长城是中国最有名的景点之一。","pinyin":"Chángchéng shì Zhōngguó zuì yǒumíng de jǐngdiǎn zhī yī.","vn":"Vạn Lý Trường Thành là một trong những điểm tham quan nổi tiếng nhất Trung Quốc."},{"cn":"站在长城上，风景真是太美了。","pinyin":"zhàn zài Chángchéng shàng, fēngjǐng zhēnshi tài měi le.","vn":"Đứng trên Vạn Lý Trường Thành, phong cảnh thật sự quá đẹp."}]},{"hanzi":"项目","pinyin":"xiàngmù","pos":"dt.","vn":"dự án","examples":[{"cn":"我们公司正在做一个新项目。","pinyin":"wǒmen gōngsī zhèngzài zuò yí ge xīn xiàngmù.","vn":"Công ty chúng tôi đang làm một dự án mới."},{"cn":"这个项目下个月就要结束了。","pinyin":"zhège xiàngmù xià ge yuè jiù yào jiéshù le.","vn":"Dự án này tháng sau sẽ kết thúc."},{"cn":"他被安排负责这个重要项目。","pinyin":"tā bèi ānpái fùzé zhège zhòngyào xiàngmù.","vn":"Anh ấy được phân công phụ trách dự án quan trọng này."}]},{"hanzi":"加班","pinyin":"jiābān","pos":"dgt.","vn":"làm thêm giờ, tăng ca","examples":[{"cn":"今天任务太多了，我得加班。","pinyin":"jīntiān rènwù tài duō le, wǒ děi jiābān.","vn":"Hôm nay việc quá nhiều, tôi phải làm thêm giờ."},{"cn":"他经常加班到很晚才回家。","pinyin":"tā jīngcháng jiābān dào hěn wǎn cái huíjiā.","vn":"Anh ấy thường xuyên tăng ca đến rất khuya mới về nhà."},{"cn":"周末还要加班，真是太累了。","pinyin":"zhōumò hái yào jiābān, zhēnshi tài lèi le.","vn":"Cuối tuần còn phải làm thêm giờ, thật sự quá mệt."}]},{"hanzi":"熬夜","pinyin":"áoyè","pos":"dgt.","vn":"thức khuya","examples":[{"cn":"为了赶报告，他昨晚熬夜到很晚。","pinyin":"wèile gǎn bàogào, tā zuówǎn áoyè dào hěn wǎn.","vn":"Để kịp báo cáo, tối qua anh ấy thức khuya đến rất muộn."},{"cn":"经常熬夜对身体不好。","pinyin":"jīngcháng áoyè duì shēntǐ bù hǎo.","vn":"Thức khuya thường xuyên không tốt cho sức khỏe."},{"cn":"我昨天熬夜看球赛，今天特别困。","pinyin":"wǒ zuótiān áoyè kàn qiúsài, jīntiān tèbié kùn.","vn":"Hôm qua tôi thức khuya xem bóng đá, hôm nay buồn ngủ ghê."}]},{"hanzi":"否则","pinyin":"fǒuzé","pos":"liên.","vn":"nếu không thì","examples":[{"cn":"你得早点出发，否则就赶不上火车了。","pinyin":"nǐ děi zǎodiǎn chūfā, fǒuzé jiù gǎnbushàng huǒchē le.","vn":"Bạn phải xuất phát sớm hơn, nếu không sẽ lỡ tàu đấy."},{"cn":"多穿点衣服，否则会感冒的。","pinyin":"duō chuān diǎn yīfu, fǒuzé huì gǎnmào de.","vn":"Mặc thêm quần áo, không thì sẽ bị cảm đấy."},{"cn":"我们要抓紧时间完成，否则来不及了。","pinyin":"wǒmen yào zhuājǐn shíjiān wánchéng, fǒuzé láibují le.","vn":"Chúng ta phải tranh thủ thời gian hoàn thành, nếu không sẽ không kịp."}]},{"hanzi":"失去","pinyin":"shīqù","pos":"dgt.","vn":"mất đi, đánh mất","examples":[{"cn":"他因为一次错误失去了这份工作。","pinyin":"tā yīnwèi yí cì cuòwù shīqù le zhè fèn gōngzuò.","vn":"Anh ấy vì một sai lầm mà mất đi công việc này."},{"cn":"健康失去了就很难再找回来。","pinyin":"jiànkāng shīqù le jiù hěn nán zài zhǎohuílái.","vn":"Sức khỏe đã mất đi thì rất khó tìm lại được."},{"cn":"别让机会白白失去了。","pinyin":"bié ràng jīhuì báibái shīqù le.","vn":"Đừng để cơ hội uổng phí trôi mất."}]},{"hanzi":"值得","pinyin":"zhídé","pos":"dgt.","vn":"đáng, xứng đáng","examples":[{"cn":"这部电影真的很值得一看。","pinyin":"zhè bù diànyǐng zhēnde hěn zhídé yí kàn.","vn":"Bộ phim này thực sự rất đáng xem."},{"cn":"为了这个结果，一切付出都值得。","pinyin":"wèile zhège jiéguǒ, yíqiè fùchū dōu zhídé.","vn":"Vì kết quả này, mọi công sức bỏ ra đều xứng đáng."},{"cn":"他的建议很值得我们参考。","pinyin":"tā de jiànyì hěn zhídé wǒmen cānkǎo.","vn":"Gợi ý của anh ấy rất đáng để chúng ta tham khảo."}]},{"hanzi":"暂停","pinyin":"zàntíng","pos":"dgt.","vn":"tạm dừng","examples":[{"cn":"因为下大雨，比赛暂停了一会儿。","pinyin":"yīnwèi xià dàyǔ, bǐsài zàntíng le yíhuìr.","vn":"Vì mưa to, trận đấu đã tạm dừng một lúc."},{"cn":"这个项目因为资金问题暂停了。","pinyin":"zhège xiàngmù yīnwèi zījīn wèntí zàntíng le.","vn":"Dự án này vì vấn đề kinh phí đã bị tạm dừng."},{"cn":"我们先暂停讨论，休息十分钟再继续。","pinyin":"wǒmen xiān zàntíng tǎolùn, xiūxi shí fēnzhōng zài jìxù.","vn":"Chúng ta tạm dừng thảo luận trước, nghỉ mười phút rồi tiếp tục."}]},{"hanzi":"之后","pinyin":"zhīhòu","pos":"dt.","vn":"sau đó, sau khi","examples":[{"cn":"下班之后我们一起去吃饭吧。","pinyin":"xiàbān zhīhòu wǒmen yìqǐ qù chīfàn ba.","vn":"Sau khi tan làm chúng ta cùng đi ăn cơm nhé."},{"cn":"毕业之后他就去北京工作了。","pinyin":"bìyè zhīhòu tā jiù qù Běijīng gōngzuò le.","vn":"Sau khi tốt nghiệp, anh ấy đã đi Bắc Kinh làm việc."},{"cn":"之后的事情我们再慢慢商量。","pinyin":"zhīhòu de shìqing wǒmen zài mànmàn shāngliang.","vn":"Những việc sau đó chúng ta từ từ bàn bạc tiếp."}]},{"hanzi":"风景","pinyin":"fēngjǐng","pos":"dt.","vn":"phong cảnh","examples":[{"cn":"这里的风景真美，让人心情愉快。","pinyin":"zhèlǐ de fēngjǐng zhēn měi, ràng rén xīnqíng yúkuài.","vn":"Phong cảnh ở đây thật đẹp, khiến người ta vui vẻ."},{"cn":"我们开车沿着海边，一路风景特别好。","pinyin":"wǒmen kāichē yánzhe hǎibiān, yílù fēngjǐng tèbié hǎo.","vn":"Chúng tôi lái xe dọc bờ biển, suốt chặng đường phong cảnh rất đẹp."},{"cn":"这张照片把当地的风景拍得非常漂亮。","pinyin":"zhè zhāng zhàopiàn bǎ dāngdì de fēngjǐng pāi de fēicháng piàoliang.","vn":"Bức ảnh này chụp phong cảnh địa phương rất đẹp."}]},{"hanzi":"效率","pinyin":"xiàolǜ","pos":"dt.","vn":"hiệu suất","examples":[{"cn":"用了新软件以后，工作效率提高了不少。","pinyin":"yòng le xīn ruǎnjiàn yǐhòu, gōngzuò xiàolǜ tígāo le bùshǎo.","vn":"Sau khi dùng phần mềm mới, hiệu suất công việc đã tăng lên không ít."},{"cn":"他做事效率很高，总能提前完成任务。","pinyin":"tā zuòshì xiàolǜ hěn gāo, zǒng néng tíqián wánchéng rènwù.","vn":"Anh ấy làm việc rất hiệu quả, luôn hoàn thành nhiệm vụ sớm."},{"cn":"开会时间太长会影响大家的效率。","pinyin":"kāihuì shíjiān tài cháng huì yǐngxiǎng dàjiā de xiàolǜ.","vn":"Họp quá lâu sẽ ảnh hưởng đến hiệu suất của mọi người."}]},{"hanzi":"下降","pinyin":"xiàjiàng","pos":"dgt.","vn":"giảm xuống, hạ xuống","examples":[{"cn":"最近公司的销售量下降了很多。","pinyin":"zuìjìn gōngsī de xiāoshòuliàng xiàjiàng le hěn duō.","vn":"Dạo này doanh số của công ty đã giảm xuống nhiều."},{"cn":"气温下降了，大家要注意保暖。","pinyin":"qìwēn xiàjiàng le, dàjiā yào zhùyì bǎonuǎn.","vn":"Nhiệt độ đã giảm xuống, mọi người cần chú ý giữ ấm."},{"cn":"熬夜太多会使记忆力下降。","pinyin":"áoyè tài duō huì shǐ jìyìlì xiàjiàng.","vn":"Thức khuya quá nhiều sẽ làm trí nhớ giảm sút."}]},{"hanzi":"相比","pinyin":"xiāngbǐ","pos":"dgt.","vn":"so với, so sánh","examples":[{"cn":"跟以前相比，现在的生活方便多了。","pinyin":"gēn yǐqián xiāngbǐ, xiànzài de shēnghuó fāngbiàn duō le.","vn":"So với trước đây, cuộc sống hiện nay tiện lợi hơn nhiều."},{"cn":"这两种方法相比，我觉得第二种更有效。","pinyin":"zhè liǎng zhǒng fāngfǎ xiāngbǐ, wǒ juéde dì èr zhǒng gèng yǒuxiào.","vn":"So sánh hai phương pháp này, tôi thấy cách thứ hai hiệu quả hơn."},{"cn":"跟城市相比，这里的空气新鲜多了。","pinyin":"gēn chéngshì xiāngbǐ, zhèlǐ de kōngqì xīnxiān duō le.","vn":"So với thành phố, không khí ở đây trong lành hơn nhiều."}]},{"hanzi":"因此","pinyin":"yīncǐ","pos":"liên.","vn":"do đó, vì vậy","examples":[{"cn":"他工作很努力，因此得到了老板的赏识。","pinyin":"tā gōngzuò hěn nǔlì, yīncǐ dédào le lǎobǎn de shǎngshí.","vn":"Anh ấy làm việc rất chăm chỉ, do đó được sếp đánh giá cao."},{"cn":"最近下雨太多，因此交通变得很堵。","pinyin":"zuìjìn xiàyǔ tài duō, yīncǐ jiāotōng biàn de hěn dǔ.","vn":"Gần đây mưa quá nhiều, vì vậy giao thông trở nên ùn tắc."},{"cn":"她身体不舒服，因此今天请假没来上班。","pinyin":"tā shēntǐ bù shūfu, yīncǐ jīntiān qǐngjià méi lái shàngbān.","vn":"Cô ấy không khỏe trong người, vì vậy hôm nay xin nghỉ không đi làm."}]},{"hanzi":"提醒","pinyin":"tíxǐng","pos":"dgt.","vn":"nhắc nhở","examples":[{"cn":"谢谢你提醒我，不然我就忘了。","pinyin":"xièxie nǐ tíxǐng wǒ, bùrán wǒ jiù wàng le.","vn":"Cảm ơn bạn đã nhắc tôi, không thì tôi đã quên mất rồi."},{"cn":"妈妈每天都提醒我多穿点衣服。","pinyin":"māma měitiān dōu tíxǐng wǒ duō chuān diǎn yīfu.","vn":"Mẹ mỗi ngày đều nhắc tôi mặc thêm quần áo."},{"cn":"老师提醒大家明天考试要带铅笔。","pinyin":"lǎoshī tíxǐng dàjiā míngtiān kǎoshì yào dài qiānbǐ.","vn":"Thầy giáo nhắc nhở mọi người ngày mai thi phải mang bút chì."}]},{"hanzi":"与","pinyin":"yǔ","pos":"giới./liên.","vn":"với; và","examples":[{"cn":"这件事与你没有任何关系。","pinyin":"zhè jiàn shì yǔ nǐ méiyǒu rènhé guānxì.","vn":"Chuyện này không liên quan gì đến bạn."},{"cn":"成功与努力是分不开的。","pinyin":"chénggōng yǔ nǔlì shì fēnbukāi de.","vn":"Thành công và sự nỗ lực là không thể tách rời."},{"cn":"他与朋友一起开了一家小店。","pinyin":"tā yǔ péngyou yìqǐ kāi le yì jiā xiǎo diàn.","vn":"Anh ấy cùng bạn mở một cửa hàng nhỏ."}]},{"hanzi":"大自然","pinyin":"dàzìrán","pos":"dt.","vn":"thiên nhiên","examples":[{"cn":"我们应该保护大自然，爱护环境。","pinyin":"wǒmen yīnggāi bǎohù dàzìrán, àihù huánjìng.","vn":"Chúng ta nên bảo vệ thiên nhiên, giữ gìn môi trường."},{"cn":"周末我喜欢去郊外接触大自然。","pinyin":"zhōumò wǒ xǐhuan qù jiāowài jiēchù dàzìrán.","vn":"Cuối tuần tôi thích ra ngoại ô để gần gũi với thiên nhiên."},{"cn":"大自然真是太神奇了，什么都能找到答案。","pinyin":"dàzìrán zhēnshi tài shénqí le, shénme dōu néng zhǎodào dá'àn.","vn":"Thiên nhiên thật kỳ diệu, cái gì cũng có thể tìm thấy câu trả lời."}]},{"hanzi":"美丽","pinyin":"měilì","pos":"tt.","vn":"đẹp, xinh đẹp","examples":[{"cn":"这座城市真美丽，到处都是绿树和花。","pinyin":"zhè zuò chéngshì zhēn měilì, dàochù dōu shì lǜshù hé huā.","vn":"Thành phố này thật đẹp, khắp nơi đều là cây xanh và hoa."},{"cn":"她今天穿得特别美丽。","pinyin":"tā jīntiān chuān de tèbié měilì.","vn":"Hôm nay cô ấy ăn mặc đặc biệt xinh đẹp."},{"cn":"桂林的山水非常美丽，是著名的旅游景点。","pinyin":"Guìlín de shānshuǐ fēicháng měilì, shì zhùmíng de lǚyóu jǐngdiǎn.","vn":"Sơn thủy Quế Lâm rất đẹp, là điểm du lịch nổi tiếng."}]},{"hanzi":"景色","pinyin":"jǐngsè","pos":"dt.","vn":"cảnh sắc, phong cảnh","examples":[{"cn":"山顶上的景色让人看了忘不了。","pinyin":"shāndǐng shàng de jǐngsè ràng rén kàn le wàngbuliǎo.","vn":"Cảnh sắc trên đỉnh núi khiến người ta xem rồi không thể quên."},{"cn":"秋天的景色特别好看，到处都是红叶。","pinyin":"qiūtiān de jǐngsè tèbié hǎokàn, dàochù dōu shì hóngyè.","vn":"Cảnh sắc mùa thu đặc biệt đẹp, khắp nơi đều là lá đỏ."},{"cn":"从窗户望出去，外面的景色非常漂亮。","pinyin":"cóng chuānghu wàng chūqù, wàimian de jǐngsè fēicháng piàoliang.","vn":"Nhìn ra từ cửa sổ, cảnh sắc bên ngoài rất đẹp."}]},{"hanzi":"首都","pinyin":"shǒudū","pos":"dt.","vn":"thủ đô","examples":[{"cn":"北京是中国的首都。","pinyin":"Běijīng shì Zhōngguó de shǒudū.","vn":"Bắc Kinh là thủ đô của Trung Quốc."},{"cn":"我打算暑假去首都旅游。","pinyin":"wǒ dǎsuàn shǔjià qù shǒudū lǚyóu.","vn":"Tôi dự định nghỉ hè đi du lịch thủ đô."},{"cn":"首都的交通一般都比较拥挤。","pinyin":"shǒudū de jiāotōng yìbān dōu bǐjiào yōngjǐ.","vn":"Giao thông ở thủ đô nhìn chung thường khá đông đúc."}]},{"hanzi":"市区","pinyin":"shìqū","pos":"dt.","vn":"khu vực nội thành","examples":[{"cn":"我们公司在市区，交通很方便。","pinyin":"wǒmen gōngsī zài shìqū, jiāotōng hěn fāngbiàn.","vn":"Công ty chúng tôi ở khu nội thành, giao thông rất tiện lợi."},{"cn":"市区的房租比郊区贵不少。","pinyin":"shìqū de fángzū bǐ jiāoqū guì bùshǎo.","vn":"Tiền thuê nhà ở nội thành đắt hơn ngoại ô nhiều."},{"cn":"周末市区人太多了，我们还是去郊区吧。","pinyin":"zhōumò shìqū rén tài duō le, wǒmen háishi qù jiāoqū ba.","vn":"Cuối tuần nội thành đông người quá, chúng ta đi ngoại ô thôi."}]},{"hanzi":"眼前","pinyin":"yǎnqián","pos":"dt.","vn":"trước mắt","examples":[{"cn":"眼前的这片风景让大家都惊呆了。","pinyin":"yǎnqián de zhè piàn fēngjǐng ràng dàjiā dōu jīngdāi le.","vn":"Cảnh tượng trước mắt khiến mọi người đều sững sờ."},{"cn":"我们先解决眼前的问题，别想太远。","pinyin":"wǒmen xiān jiějué yǎnqián de wèntí, bié xiǎng tài yuǎn.","vn":"Chúng ta giải quyết vấn đề trước mắt trước, đừng nghĩ quá xa."},{"cn":"到了山顶，眼前是一片美丽的景色。","pinyin":"dào le shāndǐng, yǎnqián shì yí piàn měilì de jǐngsè.","vn":"Lên đến đỉnh núi, trước mắt là một khung cảnh đẹp."}]},{"hanzi":"美景","pinyin":"měijǐng","pos":"dt.","vn":"cảnh đẹp","examples":[{"cn":"这里的美景吸引了很多游客前来参观。","pinyin":"zhèlǐ de měijǐng xīyǐn le hěn duō yóukè qiánlái cānguān.","vn":"Cảnh đẹp ở đây đã thu hút rất nhiều du khách đến tham quan."},{"cn":"我想用相机把这片美景拍下来。","pinyin":"wǒ xiǎng yòng xiàngjī bǎ zhè piàn měijǐng pāixiàlái.","vn":"Tôi muốn dùng máy ảnh chụp lại cảnh đẹp này."},{"cn":"黄山的美景真是让人流连忘返。","pinyin":"Huángshān de měijǐng zhēnshi ràng rén liúlián wàngfǎn.","vn":"Cảnh đẹp của núi Hoàng Sơn thực sự khiến người ta lưu luyến không muốn rời."}]},{"hanzi":"参观","pinyin":"cānguān","pos":"dgt.","vn":"tham quan","examples":[{"cn":"明天我们要去博物馆参观。","pinyin":"míngtiān wǒmen yào qù bówùguǎn cānguān.","vn":"Ngày mai chúng tôi sẽ đi tham quan bảo tàng."},{"cn":"欢迎大家来我们学校参观。","pinyin":"huānyíng dàjiā lái wǒmen xuéxiào cānguān.","vn":"Hoan nghênh mọi người đến tham quan trường chúng tôi."},{"cn":"参观完故宫以后，我对中国历史更感兴趣了。","pinyin":"cānguān wán Gùgōng yǐhòu, wǒ duì Zhōngguó lìshǐ gèng gǎn xìngqù le.","vn":"Sau khi tham quan Cố Cung xong, tôi càng thêm hứng thú với lịch sử Trung Quốc."}]},{"hanzi":"景点","pinyin":"jǐngdiǎn","pos":"dt.","vn":"điểm tham quan, danh lam thắng cảnh","examples":[{"cn":"这个城市有很多著名的景点。","pinyin":"zhège chéngshì yǒu hěn duō zhùmíng de jǐngdiǎn.","vn":"Thành phố này có rất nhiều điểm tham quan nổi tiếng."},{"cn":"暑假景点里到处都是游客。","pinyin":"shǔjià jǐngdiǎn lǐ dàochù dōu shì yóukè.","vn":"Nghỉ hè ở các điểm tham quan khắp nơi đều là du khách."},{"cn":"我们打算把每个景点都走一遍。","pinyin":"wǒmen dǎsuàn bǎ měi ge jǐngdiǎn dōu zǒu yí biàn.","vn":"Chúng tôi dự định đi qua từng điểm tham quan một."}]},{"hanzi":"交通","pinyin":"jiāotōng","pos":"dt.","vn":"giao thông","examples":[{"cn":"这个城市的交通特别方便。","pinyin":"zhège chéngshì de jiāotōng tèbié fāngbiàn.","vn":"Giao thông của thành phố này đặc biệt thuận tiện."},{"cn":"下班高峰期交通很堵，建议坐地铁。","pinyin":"xiàbān gāofēngqī jiāotōng hěn dǔ, jiànyì zuò dìtiě.","vn":"Giờ cao điểm tan tầm giao thông rất tắc, nên đi tàu điện ngầm."},{"cn":"过马路要注意交通安全。","pinyin":"guò mǎlù yào zhùyì jiāotōng ānquán.","vn":"Qua đường phải chú ý an toàn giao thông."}]},{"hanzi":"乘坐","pinyin":"chéngzuò","pos":"dgt.","vn":"đi, ngồi (xe, tàu...)","examples":[{"cn":"我们乘坐火车去上海。","pinyin":"wǒmen chéngzuò huǒchē qù Shànghǎi.","vn":"Chúng tôi đi tàu hỏa đến Thượng Hải."},{"cn":"请乘坐电梯到五楼。","pinyin":"qǐng chéngzuò diàntī dào wǔ lóu.","vn":"Xin đi thang máy lên tầng năm."},{"cn":"第一次乘坐飞机，她有点紧张。","pinyin":"dì yī cì chéngzuò fēijī, tā yǒudiǎn jǐnzhāng.","vn":"Lần đầu tiên đi máy bay, cô ấy hơi căng thẳng."}]},{"hanzi":"十分","pinyin":"shífēn","pos":"phó.","vn":"rất, vô cùng","examples":[{"cn":"这个消息让大家十分兴奋。","pinyin":"zhège xiāoxi ràng dàjiā shífēn xīngfèn.","vn":"Tin tức này khiến mọi người vô cùng phấn khích."},{"cn":"他对这次的结果十分满意。","pinyin":"tā duì zhè cì de jiéguǒ shífēn mǎnyì.","vn":"Anh ấy rất hài lòng với kết quả lần này."},{"cn":"这里的风景十分美丽，值得一来。","pinyin":"zhèlǐ de fēngjǐng shífēn měilì, zhídé yì lái.","vn":"Phong cảnh ở đây vô cùng đẹp, rất đáng để đến."}]},{"hanzi":"实际上","pinyin":"shíjìshàng","pos":"phó.","vn":"thực tế thì, trên thực tế","examples":[{"cn":"他看起来很忙，实际上没什么事做。","pinyin":"tā kànqǐlái hěn máng, shíjìshàng méi shénme shì zuò.","vn":"Anh ấy trông có vẻ bận, nhưng thực tế thì không có việc gì làm."},{"cn":"大家都以为她很严肃，实际上她很幽默。","pinyin":"dàjiā dōu yǐwéi tā hěn yánsù, shíjìshàng tā hěn yōumò.","vn":"Mọi người đều tưởng cô ấy nghiêm túc, nhưng thực tế cô ấy rất hài hước."},{"cn":"这个方法听起来复杂，实际上操作很简单。","pinyin":"zhège fāngfǎ tīngqǐlái fùzá, shíjìshàng cāozuò hěn jiǎndān.","vn":"Phương pháp này nghe có vẻ phức tạp, nhưng thực tế thao tác rất đơn giản."}]},{"hanzi":"故宫","pinyin":"Gùgōng","pos":"danh từ riêng","vn":"Cố Cung (Tử Cấm Thành)","examples":[{"cn":"去北京旅游一定要去故宫看看。","pinyin":"qù Běijīng lǚyóu yídìng yào qù Gùgōng kànkan.","vn":"Đi du lịch Bắc Kinh nhất định phải đến Cố Cung xem thử."},{"cn":"故宫是明清两代的皇宫。","pinyin":"Gùgōng shì Míng Qīng liǎng dài de huánggōng.","vn":"Cố Cung là hoàng cung của hai triều đại Minh và Thanh."},{"cn":"故宫里的建筑非常宏伟，让人印象深刻。","pinyin":"Gùgōng lǐ de jiànzhù fēicháng hóngwěi, ràng rén yìnxiàng shēnkè.","vn":"Các công trình kiến trúc trong Cố Cung rất hùng vĩ, để lại ấn tượng sâu sắc."}]}],"grammar":[{"title":"条件复句\"不管……，都/也……\"","explanation_vn":"Câu phức điều kiện \"不管……，都/也……\" (bất kể... đều/cũng...): vế trước nêu một điều kiện có khả năng xảy ra, vế sau biểu thị kết quả không thay đổi. Cấu trúc cơ bản: 不管 + điều kiện/tình huống/sự thay đổi, (chủ ngữ) + 都/也 + kết quả.","examples":[{"cn":"不管去哪儿，能放松的地方都行。","pinyin":"","vn":"Bất kể đi đâu, chỉ cần là nơi có thể thư giãn thì đều được."},{"cn":"不管有什么想法，你都要说出来，让我们知道。","pinyin":"","vn":"Bất kể có suy nghĩ gì, bạn đều phải nói ra để chúng tôi biết."},{"cn":"不管遇到多大困难，我们也要坚持，最后一定能完成任务。","pinyin":"","vn":"Bất kể gặp phải khó khăn lớn đến đâu, chúng ta cũng phải kiên trì, cuối cùng nhất định sẽ hoàn thành được nhiệm vụ."}]},{"title":"假设复句\"……，否则……\"","explanation_vn":"Câu phức giả thiết \"……，否则……\" (…, nếu không thì…): vế trước nêu ra yêu cầu, đề nghị hoặc điều kiện, vế sau nói rõ hậu quả sẽ xảy ra nếu tình huống ở vế trước không được thực hiện.","examples":[{"cn":"还是别给自己太大压力，否则，失去健康就不值得了。","pinyin":"","vn":"Tốt nhất đừng tạo cho mình quá nhiều áp lực, nếu không, đánh mất sức khỏe thì không đáng chút nào."},{"cn":"今晚早点儿睡吧，否则明天早上起不来，又该迟到了。","pinyin":"","vn":"Tối nay ngủ sớm một chút đi, nếu không sáng mai dậy không nổi, lại trễ giờ mất."},{"cn":"吃不完的菜要放进冰箱，否则很容易坏。","pinyin":"","vn":"Thức ăn không ăn hết phải cho vào tủ lạnh, nếu không rất dễ bị hỏng."}]},{"title":"比较句\"跟……相比\"","explanation_vn":"\"跟……相比\" (so với...) là cấu trúc biểu thị sự so sánh. Giới từ \"跟\" thường được dùng trong khẩu ngữ, trong những hoàn cảnh không trang trọng lắm. Trong văn viết, trong những hoàn cảnh trang trọng thường dùng \"与\".","examples":[{"cn":"跟一直加班相比，休息好了再工作，效率更高。","pinyin":"","vn":"So với việc cứ liên tục làm thêm giờ, nghỉ ngơi đầy đủ rồi mới làm việc sẽ có hiệu suất cao hơn."},{"cn":"跟读研究生相比，我更想直接工作。","pinyin":"","vn":"So với việc học lên thạc sĩ, tôi muốn đi làm trực tiếp hơn."},{"cn":"跟用现金相比，手机支付更方便些。","pinyin":"","vn":"So với việc dùng tiền mặt, thanh toán bằng điện thoại tiện lợi hơn một chút."}]},{"title":"固定短语\"有A有B\"","explanation_vn":"Trong cụm từ cố định \"有A有B\" (có A có B), A và B phần lớn là dạng đơn âm tiết, một số ít là dạng song âm tiết. A và B thường có ý nghĩa liên quan, gần giống hoặc đối lập nhau.","examples":[{"cn":"郊区有山有水，还有很多农家乐。","pinyin":"","vn":"Vùng ngoại ô có núi có sông, còn có rất nhiều nhà nghỉ dưỡng kiểu nông trại."},{"cn":"超市里的苹果有大有小，有红有绿，看起来都非常好吃。","pinyin":"","vn":"Táo trong siêu thị có to có nhỏ, có đỏ có xanh, trông đều rất ngon."},{"cn":"春天，公园里到处都是人，有男有女，有大人有孩子，特别热闹。","pinyin":"","vn":"Mùa xuân, trong công viên đâu đâu cũng là người, có nam có nữ, có người lớn có trẻ em, rất náo nhiệt."}]}],"texts":[{"label":"Bài khóa 1","type":"dialogue","lines":[{"speaker":"安妮","cn":"家月，最近学习太紧张了，咱们明天出去放松放松吧。","pinyin":""},{"speaker":"白家月","cn":"呀，正好我也想出去呢。咱们去哪儿好呢？","pinyin":""},{"speaker":"安妮","cn":"不管去哪儿，能放松的地方都行。","pinyin":""},{"speaker":"白家月","cn":"郊区怎么样？","pinyin":""},{"speaker":"安妮","cn":"天中说，下周王老师要带咱们去郊区游玩呢。","pinyin":""},{"speaker":"白家月","cn":"是吗？那咱们明天去爬长城吧，不是说\"不到长城非好汉\"吗？","pinyin":""},{"speaker":"安妮","cn":"好主意！不过明天是个大晴天，外出记得戴帽子。","pinyin":""}],"translation_vn":"Annie: Gia Nguyệt, dạo này học hành căng thẳng quá, ngày mai chúng mình ra ngoài thư giãn một chút đi.\nBạch Gia Nguyệt: Ôi, đúng lúc mình cũng muốn ra ngoài đây. Chúng mình đi đâu nhỉ?\nAnnie: Bất kể đi đâu, chỗ nào có thể thư giãn là được.\nBạch Gia Nguyệt: Đi ngoại ô thì sao?\nAnnie: Thiên Trung nói tuần sau thầy Vương sẽ dẫn chúng mình đi chơi ngoại ô đấy.\nBạch Gia Nguyệt: Thật à? Vậy ngày mai chúng mình đi leo Vạn Lý Trường Thành đi, chẳng phải người ta nói \"chưa đến Trường Thành chưa phải hảo hán\" sao?\nAnnie: Ý hay đấy! Nhưng ngày mai trời nắng to, ra ngoài nhớ đội mũ nhé.","audio_dialogue":"8-1.mp3","audio_vocab":"8-2.mp3"},{"label":"Bài khóa 2","type":"dialogue","lines":[{"speaker":"李文","cn":"同乐哥，你们平时工作忙吗？","pinyin":""},{"speaker":"杨同乐","cn":"挺忙的。以前我总觉得年轻时要多学多干，所以参加了公司里的很多项目，经常加班、熬夜，身体也亮起了红灯。","pinyin":""},{"speaker":"李文","cn":"还是别给自己太大压力，否则，失去健康就不值得了。","pinyin":""},{"speaker":"杨同乐","cn":"是啊，后来我就不接那么多项目了。我发现暂停下来、好好休息之后，我能把工作做得更快更好。","pinyin":""},{"speaker":"李文","cn":"对，该工作时就工作，该放松时就要放松。","pinyin":""},{"speaker":"杨同乐","cn":"是的，现在我周末常来郊区，在好山好水好风景中放松自己。","pinyin":""}],"translation_vn":"Lý Văn: Anh Đồng Lạc, mọi người thường ngày làm việc bận không?\nDương Đồng Lạc: Khá bận. Trước đây anh luôn nghĩ rằng lúc còn trẻ phải học nhiều làm nhiều, nên đã tham gia rất nhiều dự án trong công ty, thường xuyên tăng ca, thức khuya, sức khỏe cũng báo động rồi.\nLý Văn: Vẫn nên đừng tạo cho mình quá nhiều áp lực, nếu không, đánh mất sức khỏe thì không đáng đâu.\nDương Đồng Lạc: Đúng vậy, sau đó anh không nhận nhiều dự án như thế nữa. Anh phát hiện ra rằng sau khi tạm dừng lại, nghỉ ngơi thật tốt, anh có thể làm việc nhanh hơn và tốt hơn.\nLý Văn: Đúng rồi, nên làm việc khi cần làm việc, và nên thư giãn khi cần thư giãn.\nDương Đồng Lạc: Đúng vậy, bây giờ cuối tuần anh thường đến ngoại ô, thư giãn bản thân giữa núi non sông nước và phong cảnh đẹp.","audio_dialogue":"8-3.mp3","audio_vocab":"8-4.mp3"},{"label":"Bài khóa 3","type":"passage","lines":[{"speaker":"","cn":"以前杨同乐总觉得自己年轻，就应该多学多干、积累经验。很多年轻人和他想法一样。但是，由于工作紧张，他们经常加班、熬夜，休息不够，结果工作效率下降，健康也受到了影响。现在越来越多的人认识到，跟一直加班相比，休息好了再工作，效率更高。因此，很多人开始做出改变，提醒自己减轻压力、多多放松。比如，杨同乐周末时或者与朋友们去郊区游玩，在大自然美丽的景色中好好放松自己；或者就在家里安安静静地看看书。休息好了，再回去上班时，心情愉快，工作效率也更高。","pinyin":""}],"translation_vn":"Trước đây Dương Đồng Lạc luôn nghĩ rằng mình còn trẻ, nên phải học nhiều làm nhiều, tích lũy kinh nghiệm. Rất nhiều người trẻ cũng có suy nghĩ giống anh. Nhưng vì công việc căng thẳng, họ thường xuyên tăng ca, thức khuya, nghỉ ngơi không đủ, kết quả là hiệu suất làm việc giảm xuống, sức khỏe cũng bị ảnh hưởng. Hiện nay ngày càng nhiều người nhận ra rằng, so với việc cứ liên tục tăng ca, nghỉ ngơi đầy đủ rồi mới làm việc sẽ có hiệu suất cao hơn. Vì vậy, nhiều người bắt đầu thay đổi, tự nhắc nhở bản thân giảm bớt áp lực, thư giãn nhiều hơn. Ví dụ, Dương Đồng Lạc vào cuối tuần thường cùng bạn bè đi chơi ở ngoại ô, thư giãn bản thân giữa cảnh sắc thiên nhiên tươi đẹp; hoặc ở nhà yên tĩnh đọc sách. Khi nghỉ ngơi đầy đủ rồi, lúc quay lại đi làm, tâm trạng vui vẻ, hiệu suất làm việc cũng cao hơn.","audio_dialogue":"8-5.mp3","audio_vocab":"8-6.mp3"},{"label":"Bài khóa 4","type":"passage","lines":[{"speaker":"","cn":"一到周末，很多人都喜欢外出游玩。你一般去哪里呢？我生活在中国的首都——北京。在北京，周末的时候，有人会在市区公园走走，看看眼前的美景；有人喜欢去参观长城、故宫等有名的景点，放松心情的同时，也能了解历史文化。北京交通很方便，所以我和家人更爱乘坐公交车去郊区，偶尔也会自己开车。郊区有山有水，还有很多农家乐，吃、玩、住都十分方便。在我看来，不管去哪里玩，实际上都是为了放松。也可以说，只要能放松，去哪儿都合适。","pinyin":""}],"translation_vn":"Cứ đến cuối tuần là rất nhiều người thích ra ngoài đi chơi. Bạn thường đi đâu nhỉ? Tôi sống ở thủ đô của Trung Quốc — Bắc Kinh. Ở Bắc Kinh, vào cuối tuần, có người đi dạo ở công viên trong khu nội thành, ngắm nhìn cảnh đẹp trước mắt; có người thích đi tham quan các điểm du lịch nổi tiếng như Vạn Lý Trường Thành, Cố Cung, vừa thư giãn tâm trạng vừa có thể tìm hiểu lịch sử văn hóa. Giao thông ở Bắc Kinh rất thuận tiện, nên tôi và gia đình thích đi xe buýt ra ngoại ô hơn, thỉnh thoảng cũng tự lái xe. Vùng ngoại ô có núi có sông, còn có rất nhiều nhà nghỉ dưỡng kiểu nông trại, ăn, chơi, ở đều rất thuận tiện. Theo tôi, bất kể đi chơi ở đâu, thực chất đều là để thư giãn. Cũng có thể nói, chỉ cần có thể thư giãn được thì đi đâu cũng thích hợp.","audio_dialogue":"8-7.mp3","audio_vocab":"8-8.mp3"}]},{"id":9,"title_cn":"遇见你，刚刚好","title_pinyin":"","title_vn":"Gặp em, thật vừa vặn","goals":["Có thể nghe hiểu và trao đổi về các chủ đề liên quan đến tình yêu, tình bạn.","Có thể diễn đạt bằng lời nói hoặc văn viết về giá trị hay ý nghĩa của tình yêu, tình bạn.","Hiểu được quan niệm về tình yêu, tình bạn của người Trung Quốc."],"vocab":[{"hanzi":"祝","pinyin":"zhù","pos":"dgt.","vn":"chúc","examples":[{"cn":"祝你生日快乐！","pinyin":"Zhù nǐ shēngrì kuàilè!","vn":"Chúc bạn sinh nhật vui vẻ!"},{"cn":"我祝你们俩百年好合。","pinyin":"Wǒ zhù nǐmen liǎ bǎinián hǎohé.","vn":"Tôi chúc hai bạn trăm năm hạnh phúc."},{"cn":"老师祝我们考试顺利。","pinyin":"Lǎoshī zhù wǒmen kǎoshì shùnlì.","vn":"Thầy giáo chúc chúng tôi thi cử thuận lợi."}]},{"hanzi":"巧克力","pinyin":"qiǎokèlì","pos":"dt.","vn":"sô-cô-la","examples":[{"cn":"我特别喜欢吃巧克力。","pinyin":"Wǒ tèbié xǐhuan chī qiǎokèlì.","vn":"Tôi đặc biệt thích ăn sô-cô-la."},{"cn":"情人节他送了我一盒巧克力。","pinyin":"Qíngrénjié tā sòngle wǒ yì hé qiǎokèlì.","vn":"Ngày lễ tình nhân anh ấy tặng tôi một hộp sô-cô-la."},{"cn":"这个蛋糕里加了很多巧克力。","pinyin":"Zhège dàngāo lǐ jiāle hěn duō qiǎokèlì.","vn":"Chiếc bánh này cho rất nhiều sô-cô-la."}]},{"hanzi":"感动","pinyin":"gǎndòng","pos":"tt./dgt.","vn":"cảm động; làm cảm động","examples":[{"cn":"看完这部电影我特别感动。","pinyin":"Kànwán zhè bù diànyǐng wǒ tèbié gǎndòng.","vn":"Xem xong bộ phim này tôi rất cảm động."},{"cn":"他的话深深地感动了大家。","pinyin":"Tā de huà shēnshēn de gǎndòngle dàjiā.","vn":"Lời nói của anh ấy làm mọi người cảm động sâu sắc."},{"cn":"她被朋友们的关心感动得哭了。","pinyin":"Tā bèi péngyoumen de guānxīn gǎndòng de kūle.","vn":"Cô ấy được bạn bè quan tâm nên cảm động đến phát khóc."}]},{"hanzi":"浪漫","pinyin":"làngmàn","pos":"tt.","vn":"lãng mạn","examples":[{"cn":"他是个很浪漫的人，总是给我惊喜。","pinyin":"Tā shì ge hěn làngmàn de rén, zǒngshì gěi wǒ jīngxǐ.","vn":"Anh ấy là người rất lãng mạn, luôn cho tôi bất ngờ."},{"cn":"巴黎是个充满浪漫气息的城市。","pinyin":"Bālí shì ge chōngmǎn làngmàn qìxī de chéngshì.","vn":"Paris là thành phố tràn đầy không khí lãng mạn."},{"cn":"他们在海边看日落，气氛特别浪漫。","pinyin":"Tāmen zài hǎibiān kàn rìluò, qìfēn tèbié làngmàn.","vn":"Họ ngắm hoàng hôn trên biển, không khí rất lãng mạn."}]},{"hanzi":"幽默","pinyin":"yōumò","pos":"tt.","vn":"hài hước","examples":[{"cn":"他说话很幽默，大家都喜欢跟他聊天。","pinyin":"Tā shuōhuà hěn yōumò, dàjiā dōu xǐhuan gēn tā liáotiān.","vn":"Anh ấy nói chuyện rất hài hước, mọi người đều thích trò chuyện với anh ấy."},{"cn":"这个老师讲课很幽默，一点都不无聊。","pinyin":"Zhège lǎoshī jiǎngkè hěn yōumò, yìdiǎn dōu bù wúliáo.","vn":"Thầy giáo này giảng bài rất hài hước, chẳng chán tí nào."},{"cn":"她有很强的幽默感。","pinyin":"Tā yǒu hěn qiáng de yōumògǎn.","vn":"Cô ấy có khiếu hài hước rất mạnh."}]},{"hanzi":"耐心","pinyin":"nàixīn","pos":"tt./dt.","vn":"kiên nhẫn; sự kiên nhẫn","examples":[{"cn":"教小孩子一定要有耐心。","pinyin":"Jiāo xiǎoháizi yídìng yào yǒu nàixīn.","vn":"Dạy trẻ con nhất định phải có kiên nhẫn."},{"cn":"她很耐心地给我解释了好几遍。","pinyin":"Tā hěn nàixīn de gěi wǒ jiěshìle hǎo jǐ biàn.","vn":"Cô ấy rất kiên nhẫn giải thích cho tôi mấy lần."},{"cn":"老板对我们一直很有耐心。","pinyin":"Lǎobǎn duì wǒmen yìzhí hěn yǒu nàixīn.","vn":"Sếp luôn rất kiên nhẫn với chúng tôi."}]},{"hanzi":"吸引","pinyin":"xīyǐn","pos":"dgt.","vn":"thu hút","examples":[{"cn":"这家店的橱窗设计很吸引人。","pinyin":"Zhè jiā diàn de chúchuāng shèjì hěn xīyǐn rén.","vn":"Cách thiết kế tủ kính của cửa hàng này rất thu hút người xem."},{"cn":"她的笑容一下子就吸引了我。","pinyin":"Tā de xiàoróng yíxiàzi jiù xīyǐnle wǒ.","vn":"Nụ cười của cô ấy ngay lập tức thu hút tôi."},{"cn":"这个活动吸引了很多年轻人参加。","pinyin":"Zhège huódòng xīyǐnle hěn duō niánqīngrén cānjiā.","vn":"Hoạt động này thu hút rất nhiều bạn trẻ tham gia."}]},{"hanzi":"当时","pinyin":"dāngshí","pos":"dt.","vn":"lúc đó, khi đó","examples":[{"cn":"我当时太紧张了，什么都忘了。","pinyin":"Wǒ dāngshí tài jǐnzhāng le, shénme dōu wàngle.","vn":"Lúc đó tôi quá hồi hộp nên quên hết cả."},{"cn":"当时我们都还是学生。","pinyin":"Dāngshí wǒmen dōu hái shì xuésheng.","vn":"Khi đó chúng tôi vẫn còn là học sinh."},{"cn":"他当时并没有意识到问题的严重性。","pinyin":"Tā dāngshí bìng méiyǒu yìshí dào wèntí de yánzhòngxìng.","vn":"Lúc đó anh ấy hoàn toàn chưa nhận ra mức độ nghiêm trọng của vấn đề."}]},{"hanzi":"错过","pinyin":"cuòguò","pos":"dgt.","vn":"bỏ lỡ","examples":[{"cn":"我差点错过了这班飞机。","pinyin":"Wǒ chàdiǎn cuòguòle zhè bān fēijī.","vn":"Tôi suýt lỡ chuyến bay này."},{"cn":"别错过这次难得的机会。","pinyin":"Bié cuòguò zhè cì nándé de jīhuì.","vn":"Đừng bỏ lỡ cơ hội hiếm có này."},{"cn":"他因为睡过头错过了面试。","pinyin":"Tā yīnwèi shuìguòtóu cuòguòle miànshì.","vn":"Anh ấy vì ngủ quên nên lỡ buổi phỏng vấn."}]},{"hanzi":"幸运","pinyin":"xìngyùn","pos":"tt./dt.","vn":"may mắn","examples":[{"cn":"能认识你真是我的幸运。","pinyin":"Néng rènshi nǐ zhēnshi wǒ de xìngyùn.","vn":"Được quen biết bạn thực sự là may mắn của tôi."},{"cn":"他很幸运，中了彩票。","pinyin":"Tā hěn xìngyùn, zhòngle cǎipiào.","vn":"Anh ấy rất may mắn, trúng số."},{"cn":"我觉得自己是个幸运的人。","pinyin":"Wǒ juéde zìjǐ shì ge xìngyùn de rén.","vn":"Tôi cảm thấy mình là người may mắn."}]},{"hanzi":"幸福","pinyin":"xìngfú","pos":"tt./dt.","vn":"hạnh phúc","examples":[{"cn":"一家人在一起就是幸福。","pinyin":"Yì jiā rén zài yìqǐ jiùshì xìngfú.","vn":"Cả nhà bên nhau chính là hạnh phúc."},{"cn":"她现在的生活很幸福。","pinyin":"Tā xiànzài de shēnghuó hěn xìngfú.","vn":"Cuộc sống hiện tại của cô ấy rất hạnh phúc."},{"cn":"他们俩看起来很幸福。","pinyin":"Tāmen liǎ kànqǐlái hěn xìngfú.","vn":"Hai người họ trông rất hạnh phúc."}]},{"hanzi":"尽管","pinyin":"jǐnguǎn","pos":"liên.","vn":"mặc dù","examples":[{"cn":"尽管下着大雨，他还是坚持去上班。","pinyin":"Jǐnguǎn xiàzhe dàyǔ, tā háishi jiānchí qù shàngbān.","vn":"Mặc dù trời mưa to, anh ấy vẫn kiên quyết đi làm."},{"cn":"尽管很累，她还是把作业做完了。","pinyin":"Jǐnguǎn hěn lèi, tā háishi bǎ zuòyè zuòwánle.","vn":"Mặc dù rất mệt, cô ấy vẫn làm xong bài tập."},{"cn":"尽管工资不高，他依然很喜欢这份工作。","pinyin":"Jǐnguǎn gōngzī bù gāo, tā yīrán hěn xǐhuan zhè fèn gōngzuò.","vn":"Mặc dù lương không cao, anh ấy vẫn rất thích công việc này."}]},{"hanzi":"性格","pinyin":"xìnggé","pos":"dt.","vn":"tính cách","examples":[{"cn":"他的性格很开朗。","pinyin":"Tā de xìnggé hěn kāilǎng.","vn":"Tính cách của anh ấy rất cởi mở."},{"cn":"我们俩性格差别很大。","pinyin":"Wǒmen liǎ xìnggé chābié hěn dà.","vn":"Tính cách của hai chúng tôi khác nhau nhiều."},{"cn":"这个孩子性格有点内向。","pinyin":"Zhège háizi xìnggé yǒudiǎn nèixiàng.","vn":"Đứa trẻ này tính cách hơi hướng nội."}]},{"hanzi":"共同","pinyin":"gòngtóng","pos":"tt.","vn":"chung","examples":[{"cn":"我们有共同的爱好。","pinyin":"Wǒmen yǒu gòngtóng de àihào.","vn":"Chúng tôi có sở thích chung."},{"cn":"这是大家共同努力的结果。","pinyin":"Zhè shì dàjiā gòngtóng nǔlì de jiéguǒ.","vn":"Đây là kết quả nỗ lực chung của mọi người."},{"cn":"他们俩有很多共同语言。","pinyin":"Tāmen liǎ yǒu hěn duō gòngtóng yǔyán.","vn":"Hai người họ có rất nhiều điểm chung để nói chuyện."}]},{"hanzi":"责任","pinyin":"zérèn","pos":"dt.","vn":"trách nhiệm","examples":[{"cn":"这是我的责任，我会负责到底。","pinyin":"Zhè shì wǒ de zérèn, wǒ huì fùzé dàodǐ.","vn":"Đây là trách nhiệm của tôi, tôi sẽ chịu trách nhiệm đến cùng."},{"cn":"家长要对孩子的教育负责任。","pinyin":"Jiāzhǎng yào duì háizi de jiàoyù fù zérèn.","vn":"Phụ huynh phải có trách nhiệm với việc giáo dục con cái."},{"cn":"他把责任都推给了别人。","pinyin":"Tā bǎ zérèn dōu tuī gěile biérén.","vn":"Anh ấy đẩy hết trách nhiệm cho người khác."}]},{"hanzi":"相互","pinyin":"xiānghù","pos":"phó.","vn":"lẫn nhau, qua lại","examples":[{"cn":"我们应该相互理解，相互帮助。","pinyin":"Wǒmen yīnggāi xiānghù lǐjiě, xiānghù bāngzhù.","vn":"Chúng ta nên hiểu nhau và giúp đỡ lẫn nhau."},{"cn":"朋友之间要相互信任。","pinyin":"Péngyou zhījiān yào xiānghù xìnrèn.","vn":"Bạn bè với nhau phải tin tưởng lẫn nhau."},{"cn":"这两件事相互影响。","pinyin":"Zhè liǎng jiàn shì xiānghù yǐngxiǎng.","vn":"Hai việc này ảnh hưởng lẫn nhau."}]},{"hanzi":"理解","pinyin":"lǐjiě","pos":"dgt.","vn":"hiểu, thấu hiểu","examples":[{"cn":"我完全理解你的感受。","pinyin":"Wǒ wánquán lǐjiě nǐ de gǎnshòu.","vn":"Tôi hoàn toàn hiểu cảm nhận của bạn."},{"cn":"父母有时候很难理解孩子的想法。","pinyin":"Fùmǔ yǒu shíhou hěn nán lǐjiě háizi de xiǎngfǎ.","vn":"Cha mẹ đôi khi rất khó hiểu suy nghĩ của con cái."},{"cn":"谢谢你的理解。","pinyin":"Xièxie nǐ de lǐjiě.","vn":"Cảm ơn sự thấu hiểu của bạn."}]},{"hanzi":"支持","pinyin":"zhīchí","pos":"dgt.","vn":"ủng hộ","examples":[{"cn":"不管你做什么决定，我都支持你。","pinyin":"Bùguǎn nǐ zuò shénme juédìng, wǒ dōu zhīchí nǐ.","vn":"Dù bạn quyết định thế nào, tôi đều ủng hộ bạn."},{"cn":"家人的支持对我很重要。","pinyin":"Jiārén de zhīchí duì wǒ hěn zhòngyào.","vn":"Sự ủng hộ của gia đình rất quan trọng với tôi."},{"cn":"这个计划得到了大家的支持。","pinyin":"Zhège jìhuà dédàole dàjiā de zhīchí.","vn":"Kế hoạch này nhận được sự ủng hộ của mọi người."}]},{"hanzi":"印象","pinyin":"yìnxiàng","pos":"dt.","vn":"ấn tượng","examples":[{"cn":"她给我留下了很深的印象。","pinyin":"Tā gěi wǒ liúxiàle hěn shēn de yìnxiàng.","vn":"Cô ấy để lại cho tôi ấn tượng rất sâu sắc."},{"cn":"我对那个城市印象特别好。","pinyin":"Wǒ duì nàge chéngshì yìnxiàng tèbié hǎo.","vn":"Tôi có ấn tượng rất tốt về thành phố đó."},{"cn":"第一印象很重要。","pinyin":"Dì yī yìnxiàng hěn zhòngyào.","vn":"Ấn tượng ban đầu rất quan trọng."}]},{"hanzi":"实在","pinyin":"shízài","pos":"tt./phó.","vn":"thật thà; thực ra","examples":[{"cn":"他是个实在人，从不说谎。","pinyin":"Tā shì ge shízài rén, cóngbù shuōhuǎng.","vn":"Anh ấy là người thật thà, chưa bao giờ nói dối."},{"cn":"这件事实在太麻烦了。","pinyin":"Zhè jiàn shì shízài tài máfan le.","vn":"Việc này thực sự quá phiền phức."},{"cn":"我实在不知道该怎么办。","pinyin":"Wǒ shízài bù zhīdào gāi zěnme bàn.","vn":"Tôi thực sự không biết nên làm thế nào."}]},{"hanzi":"阳光","pinyin":"yángguāng","pos":"tt./dt.","vn":"rạng rỡ; ánh nắng","examples":[{"cn":"今天阳光真好。","pinyin":"Jīntiān yángguāng zhēn hǎo.","vn":"Hôm nay nắng thật đẹp."},{"cn":"她笑起来特别阳光。","pinyin":"Tā xiào qǐlái tèbié yángguāng.","vn":"Cô ấy cười lên trông thật rạng rỡ."},{"cn":"我喜欢躺在阳光下晒太阳。","pinyin":"Wǒ xǐhuan tǎng zài yángguāng xià shài tàiyáng.","vn":"Tôi thích nằm phơi nắng dưới ánh mặt trời."}]},{"hanzi":"负责","pinyin":"fùzé","pos":"tt./dgt.","vn":"có trách nhiệm; phụ trách","examples":[{"cn":"这个项目由我负责。","pinyin":"Zhège xiàngmù yóu wǒ fùzé.","vn":"Dự án này do tôi phụ trách."},{"cn":"他做事很负责任。","pinyin":"Tā zuòshì hěn fùzérèn.","vn":"Anh ấy làm việc rất có trách nhiệm."},{"cn":"谁负责今天的会议记录？","pinyin":"Shéi fùzé jīntiān de huìyì jìlù?","vn":"Ai phụ trách ghi biên bản cuộc họp hôm nay?"}]},{"hanzi":"积极","pinyin":"jījí","pos":"tt.","vn":"tích cực","examples":[{"cn":"他工作一直很积极。","pinyin":"Tā gōngzuò yìzhí hěn jījí.","vn":"Anh ấy làm việc luôn rất tích cực."},{"cn":"我们要积极面对困难。","pinyin":"Wǒmen yào jījí miànduì kùnnan.","vn":"Chúng ta phải tích cực đối mặt với khó khăn."},{"cn":"她对生活态度很积极。","pinyin":"Tā duì shēnghuó tàidu hěn jījí.","vn":"Cô ấy có thái độ sống rất tích cực."}]},{"hanzi":"此","pinyin":"cǐ","pos":"đt.","vn":"này","examples":[{"cn":"由此可见，他真的很努力。","pinyin":"Yóucǐ kějiàn, tā zhēn de hěn nǔlì.","vn":"Từ đó có thể thấy, anh ấy thực sự rất nỗ lực."},{"cn":"就此打住吧，别再说了。","pinyin":"Jiù cǐ dǎzhù ba, bié zài shuōle.","vn":"Dừng tại đây thôi, đừng nói nữa."},{"cn":"特此通知，请大家注意。","pinyin":"Tècǐ tōngzhī, qǐng dàjiā zhùyì.","vn":"Đặc biệt thông báo điều này, xin mọi người lưu ý."}]},{"hanzi":"从此","pinyin":"cóngcǐ","pos":"phó.","vn":"từ đó","examples":[{"cn":"从此以后，我们再也没见过面。","pinyin":"Cóngcǐ yǐhòu, wǒmen zài yě méi jiànguò miàn.","vn":"Từ đó về sau, chúng tôi không bao giờ gặp lại nhau nữa."},{"cn":"从此他改掉了坏习惯。","pinyin":"Cóngcǐ tā gǎidiàole huài xíguàn.","vn":"Từ đó anh ấy bỏ được thói quen xấu."},{"cn":"从此，她爱上了画画。","pinyin":"Cóngcǐ, tā àishàngle huàhuà.","vn":"Từ đó, cô ấy yêu thích vẽ tranh."}]},{"hanzi":"产生","pinyin":"chǎnshēng","pos":"dgt.","vn":"nảy sinh","examples":[{"cn":"这件事让我对他产生了怀疑。","pinyin":"Zhè jiàn shì ràng wǒ duì tā chǎnshēngle huáiyí.","vn":"Việc này khiến tôi nảy sinh nghi ngờ với anh ta."},{"cn":"两人之间渐渐产生了感情。","pinyin":"Liǎng rén zhījiān jiànjiàn chǎnshēngle gǎnqíng.","vn":"Hai người dần dần nảy sinh tình cảm."},{"cn":"这个决定会产生很大的影响。","pinyin":"Zhège juédìng huì chǎnshēng hěn dà de yǐngxiǎng.","vn":"Quyết định này sẽ gây ra ảnh hưởng rất lớn."}]},{"hanzi":"爱情","pinyin":"àiqíng","pos":"dt.","vn":"tình yêu","examples":[{"cn":"他们的爱情故事很感人。","pinyin":"Tāmen de àiqíng gùshi hěn gǎnrén.","vn":"Câu chuyện tình yêu của họ rất cảm động."},{"cn":"爱情需要用心经营。","pinyin":"Àiqíng xūyào yòngxīn jīngyíng.","vn":"Tình yêu cần được vun đắp bằng cả tấm lòng."},{"cn":"她还没遇到真正的爱情。","pinyin":"Tā hái méi yùdào zhēnzhèng de àiqíng.","vn":"Cô ấy vẫn chưa gặp được tình yêu đích thực."}]},{"hanzi":"间","pinyin":"jiān","pos":"dt.","vn":"khoảng giữa","examples":[{"cn":"他们之间的关系越来越好。","pinyin":"Tāmen zhījiān de guānxi yuè lái yuè hǎo.","vn":"Mối quan hệ giữa họ ngày càng tốt đẹp."},{"cn":"中美两国之间有很多合作项目。","pinyin":"Zhōng Měi liǎng guó zhījiān yǒu hěn duō hézuò xiàngmù.","vn":"Giữa hai nước Trung-Mỹ có rất nhiều dự án hợp tác."},{"cn":"朋友之间应该坦诚相待。","pinyin":"Péngyou zhījiān yīnggāi tǎnchéng xiāngdài.","vn":"Bạn bè với nhau nên đối xử chân thành."}]},{"hanzi":"友情","pinyin":"yǒuqíng","pos":"dt.","vn":"tình bạn","examples":[{"cn":"我们的友情已经十年了。","pinyin":"Wǒmen de yǒuqíng yǐjīng shí nián le.","vn":"Tình bạn của chúng tôi đã mười năm rồi."},{"cn":"她很珍惜这段友情。","pinyin":"Tā hěn zhēnxī zhè duàn yǒuqíng.","vn":"Cô ấy rất trân trọng tình bạn này."},{"cn":"友情比金钱更珍贵。","pinyin":"Yǒuqíng bǐ jīnqián gèng zhēnguì.","vn":"Tình bạn quý giá hơn tiền bạc."}]},{"hanzi":"美好","pinyin":"měihǎo","pos":"tt.","vn":"tốt đẹp","examples":[{"cn":"祝你有一个美好的明天。","pinyin":"Zhù nǐ yǒu yí ge měihǎo de míngtiān.","vn":"Chúc bạn có một ngày mai tốt đẹp."},{"cn":"那是我童年最美好的回忆。","pinyin":"Nà shì wǒ tóngnián zuì měihǎo de huíyì.","vn":"Đó là kỷ niệm đẹp nhất thời thơ ấu của tôi."},{"cn":"愿你的生活一直这么美好。","pinyin":"Yuàn nǐ de shēnghuó yìzhí zhème měihǎo.","vn":"Mong cuộc sống của bạn luôn tốt đẹp như thế này."}]},{"hanzi":"人生","pinyin":"rénshēng","pos":"dt.","vn":"cuộc đời, nhân sinh","examples":[{"cn":"人生就像一场旅行。","pinyin":"Rénshēng jiù xiàng yì chǎng lǚxíng.","vn":"Cuộc đời giống như một chuyến du hành."},{"cn":"他的人生经历很丰富。","pinyin":"Tā de rénshēng jīnglì hěn fēngfù.","vn":"Trải nghiệm cuộc đời của anh ấy rất phong phú."},{"cn":"这是我人生中最重要的决定。","pinyin":"Zhè shì wǒ rénshēng zhōng zuì zhòngyào de juédìng.","vn":"Đây là quyết định quan trọng nhất trong cuộc đời tôi."}]},{"hanzi":"精彩","pinyin":"jīngcǎi","pos":"tt.","vn":"tuyệt vời, đặc sắc","examples":[{"cn":"这场比赛太精彩了。","pinyin":"Zhè chǎng bǐsài tài jīngcǎi le.","vn":"Trận đấu này thật tuyệt vời."},{"cn":"他的演讲非常精彩。","pinyin":"Tā de yǎnjiǎng fēicháng jīngcǎi.","vn":"Bài diễn thuyết của anh ấy rất đặc sắc."},{"cn":"这部电影的结局很精彩。","pinyin":"Zhè bù diànyǐng de jiéjú hěn jīngcǎi.","vn":"Kết thúc của bộ phim này rất hay."}]},{"hanzi":"感情","pinyin":"gǎnqíng","pos":"dt.","vn":"tình cảm","examples":[{"cn":"他们俩的感情越来越好。","pinyin":"Tāmen liǎ de gǎnqíng yuè lái yuè hǎo.","vn":"Tình cảm của hai người ngày càng tốt."},{"cn":"我对这个地方有很深的感情。","pinyin":"Wǒ duì zhège dìfang yǒu hěn shēn de gǎnqíng.","vn":"Tôi có tình cảm sâu đậm với nơi này."},{"cn":"感情的事不能勉强。","pinyin":"Gǎnqíng de shì bùnéng miǎnqiǎng.","vn":"Chuyện tình cảm không thể miễn cưỡng."}]},{"hanzi":"深","pinyin":"shēn","pos":"tt.","vn":"sâu đậm","examples":[{"cn":"他们之间的感情很深。","pinyin":"Tāmen zhījiān de gǎnqíng hěn shēn.","vn":"Tình cảm giữa họ rất sâu đậm."},{"cn":"这条河很深，小心别掉进去。","pinyin":"Zhè tiáo hé hěn shēn, xiǎoxīn bié diào jìnqù.","vn":"Con sông này rất sâu, cẩn thận đừng ngã xuống."},{"cn":"她对他的印象很深。","pinyin":"Tā duì tā de yìnxiàng hěn shēn.","vn":"Cô ấy có ấn tượng rất sâu sắc về anh ta."}]},{"hanzi":"经营","pinyin":"jīngyíng","pos":"dgt.","vn":"vun đắp, quản lý","examples":[{"cn":"他在经营一家小餐馆。","pinyin":"Tā zài jīngyíng yì jiā xiǎo cānguǎn.","vn":"Anh ấy đang quản lý một nhà hàng nhỏ."},{"cn":"婚姻需要双方共同经营。","pinyin":"Hūnyīn xūyào shuāngfāng gòngtóng jīngyíng.","vn":"Hôn nhân cần cả hai bên cùng vun đắp."},{"cn":"这家公司经营得不错。","pinyin":"Zhè jiā gōngsī jīngyíng de búcuò.","vn":"Công ty này quản lý kinh doanh khá tốt."}]},{"hanzi":"对方","pinyin":"duìfāng","pos":"dt.","vn":"đối phương","examples":[{"cn":"吵架的时候也要听听对方的想法。","pinyin":"Chǎojià de shíhou yě yào tīngting duìfāng de xiǎngfǎ.","vn":"Khi cãi nhau cũng nên lắng nghe suy nghĩ của đối phương."},{"cn":"打电话的时候要先确认对方是谁。","pinyin":"Dǎ diànhuà de shíhou yào xiān quèrèn duìfāng shì shéi.","vn":"Khi gọi điện phải xác nhận trước người ở đầu dây là ai."},{"cn":"他总是能站在对方的角度考虑问题。","pinyin":"Tā zǒngshì néng zhàn zài duìfāng de jiǎodù kǎolǜ wèntí.","vn":"Anh ấy luôn có thể suy nghĩ vấn đề từ góc độ của đối phương."}]},{"hanzi":"感受","pinyin":"gǎnshòu","pos":"dt./dgt.","vn":"cảm nhận","examples":[{"cn":"说说你对这件事的感受吧。","pinyin":"Shuōshuo nǐ duì zhè jiàn shì de gǎnshòu ba.","vn":"Nói xem cảm nhận của bạn về việc này đi."},{"cn":"我能感受到你的真诚。","pinyin":"Wǒ néng gǎnshòu dào nǐ de zhēnchéng.","vn":"Tôi có thể cảm nhận được sự chân thành của bạn."},{"cn":"每个人的感受都不一样。","pinyin":"Měi ge rén de gǎnshòu dōu bù yíyàng.","vn":"Cảm nhận của mỗi người đều khác nhau."}]},{"hanzi":"尤其","pinyin":"yóuqí","pos":"phó.","vn":"đặc biệt là","examples":[{"cn":"我喜欢吃水果，尤其是西瓜。","pinyin":"Wǒ xǐhuan chī shuǐguǒ, yóuqí shì xīguā.","vn":"Tôi thích ăn trái cây, đặc biệt là dưa hấu."},{"cn":"夏天很热，尤其是在南方。","pinyin":"Xiàtiān hěn rè, yóuqí shì zài nánfāng.","vn":"Mùa hè rất nóng, đặc biệt là ở miền Nam."},{"cn":"他对历史很感兴趣，尤其是中国古代史。","pinyin":"Tā duì lìshǐ hěn gǎn xìngqù, yóuqí shì Zhōngguó gǔdàishǐ.","vn":"Anh ấy rất thích lịch sử, đặc biệt là lịch sử cổ đại Trung Quốc."}]},{"hanzi":"日子","pinyin":"rìzi","pos":"dt.","vn":"ngày tháng, cuộc sống","examples":[{"cn":"这些日子你过得怎么样？","pinyin":"Zhèxiē rìzi nǐ guò de zěnmeyàng?","vn":"Những ngày qua bạn sống thế nào?"},{"cn":"结婚的日子已经定好了。","pinyin":"Jiéhūn de rìzi yǐjīng dìnghǎole.","vn":"Ngày cưới đã được ấn định rồi."},{"cn":"他们俩的日子过得很幸福。","pinyin":"Tāmen liǎ de rìzi guò de hěn xìngfú.","vn":"Ngày tháng của hai người họ sống rất hạnh phúc."}]},{"hanzi":"从来","pinyin":"cónglái","pos":"phó.","vn":"từ trước đến nay","examples":[{"cn":"他从来不迟到。","pinyin":"Tā cónglái bù chídào.","vn":"Anh ấy từ trước đến nay chưa bao giờ đến muộn."},{"cn":"我从来没去过国外。","pinyin":"Wǒ cónglái méi qùguò guówài.","vn":"Tôi chưa bao giờ ra nước ngoài."},{"cn":"她从来都这么热情。","pinyin":"Tā cónglái dōu zhème rèqíng.","vn":"Cô ấy từ trước đến nay luôn nhiệt tình như vậy."}]}],"grammar":[{"title":"紧缩复句\"不……也……\"","explanation_vn":"Câu phức rút gọn \"不……也……\" biểu thị rằng dù trong một điều kiện phủ định nào đó, kết quả phía sau vẫn chắc chắn xảy ra. Thường dùng trong khẩu ngữ.","examples":[{"cn":"我不说你也懂我在想什么。","pinyin":"","vn":"Em không nói mà anh vẫn hiểu em đang nghĩ gì."},{"cn":"他不复习也能考出好成绩。","pinyin":"","vn":"Cậu ấy không ôn bài vẫn thi được điểm cao."},{"cn":"我很清楚他为什么生气，不问我也知道。","pinyin":"","vn":"Tôi biết rất rõ tại sao anh ấy giận, không cần hỏi tôi cũng biết."}]},{"title":"转折复句\"尽管……，但是/可是……\"","explanation_vn":"Câu phức chuyển ý \"尽管……，但是/可是……\" biểu thị sự chuyển ý. \"尽管\" có nghĩa là \"mặc dù\", dùng để dẫn ra một tình huống nào đó, còn \"但是、可是\" dẫn ra tình huống hoặc kết quả trái ngược.","examples":[{"cn":"他们尽管性格不同，但是有很多共同爱好。","pinyin":"","vn":"Mặc dù tính cách họ khác nhau, nhưng họ có rất nhiều sở thích chung."},{"cn":"尽管时间紧张、压力很大，但是他们还是完成了任务。","pinyin":"","vn":"Dù thời gian gấp gáp, áp lực lớn, nhưng họ vẫn hoàn thành nhiệm vụ."},{"cn":"尽管她已经很累了，可是还是很耐心地给女儿读睡前故事。","pinyin":"","vn":"Dù cô ấy đã rất mệt, nhưng vẫn kiên nhẫn đọc truyện trước khi ngủ cho con gái."}]},{"title":"指示代词\"此\"","explanation_vn":"Đại từ chỉ định \"此\" biểu thị \"này, cái này\", thường dùng trong văn viết hoặc các trường hợp trang trọng.","examples":[{"cn":"此次出差，让两人熟悉了起来，从此成了好朋友。","pinyin":"","vn":"Chuyến công tác này đã giúp hai người trở nên thân thiết, từ đó trở thành bạn tốt."},{"cn":"此人聪明、有能力，一定能顺利完成任务。","pinyin":"","vn":"Người này thông minh, có năng lực, nhất định sẽ hoàn thành nhiệm vụ thuận lợi."},{"cn":"此材料很重要，必须直接交给他。","pinyin":"","vn":"Tài liệu này rất quan trọng, phải trực tiếp đưa cho anh ấy."}]},{"title":"时间副词\"从来\"","explanation_vn":"Phó từ chỉ thời gian \"从来\" chỉ việc gì đó luôn như vậy từ trước đến nay. Thường dùng trong câu phủ định, đôi khi cũng dùng trong câu khẳng định.","examples":[{"cn":"爱，从来都是相互尊重、理解与支持，不是吗？","pinyin":"","vn":"Tình yêu, từ trước đến nay vẫn luôn là sự tôn trọng, thấu hiểu và ủng hộ lẫn nhau, phải không?"},{"cn":"我从来没见过这个颜色的花，它叫什么名字啊？","pinyin":"","vn":"Tôi chưa từng thấy bông hoa màu này bao giờ, nó tên là gì vậy?"},{"cn":"我从来不喜欢一个人旅游，每次都要和家人或朋友一起去。","pinyin":"","vn":"Tôi chưa bao giờ thích đi du lịch một mình, lần nào cũng phải đi cùng gia đình hoặc bạn bè."}]}],"texts":[{"label":"Bài khóa 1","type":"dialogue","lines":[{"speaker":"李文","cn":"家月，给你的，祝你生日快乐！","pinyin":""},{"speaker":"白家月","cn":"啊，好漂亮的花！还有巧克力！你怎么知道我喜欢这个巧克力？","pinyin":""},{"speaker":"李文","cn":"上次咱们去超市，看你拿起来看了看又放下了，我就记住了。","pinyin":""},{"speaker":"白家月","cn":"好感动！我不说你也懂我在想什么，你真是细心又浪漫。其实刚认识不久，你的幽默与耐心就很吸引我，不过我当时也只把你当普通朋友。如果你没有一直找我聊天儿，我们可能就错过了。","pinyin":""},{"speaker":"李文","cn":"我终于遇见了对的人，哪能错过呢？","pinyin":""},{"speaker":"白家月","cn":"遇见你，我也觉得很幸运。","pinyin":""}],"translation_vn":"Lý Văn: Gia Nguyệt, tặng em này, chúc em sinh nhật vui vẻ!\nBạch Gia Nguyệt: A, hoa đẹp quá! Còn có cả sô-cô-la nữa! Sao anh biết em thích loại sô-cô-la này?\nLý Văn: Lần trước mình đi siêu thị, anh thấy em cầm lên xem rồi lại đặt xuống, nên anh nhớ luôn.\nBạch Gia Nguyệt: Cảm động quá! Em không nói mà anh vẫn hiểu em đang nghĩ gì, anh đúng là người tinh tế lại lãng mạn. Thật ra mới quen nhau không lâu, sự hài hước và kiên nhẫn của anh đã rất thu hút em rồi, nhưng lúc đó em cũng chỉ coi anh là bạn bình thường thôi. Nếu anh không liên tục tìm em trò chuyện, có lẽ chúng ta đã bỏ lỡ nhau rồi.\nLý Văn: Cuối cùng anh cũng gặp được đúng người, sao có thể bỏ lỡ được chứ?\nBạch Gia Nguyệt: Gặp được anh, em cũng thấy mình thật may mắn.","audio_dialogue":"9-1.mp3","audio_vocab":"9-2.mp3"},{"label":"Bài khóa 2","type":"dialogue","lines":[{"speaker":"王一雪","cn":"看到一飞和同乐结婚后这么幸福，我这个介绍人也特别开心。","pinyin":""},{"speaker":"刘明","cn":"是啊，同乐是你的好朋友，一飞是你妹妹，你都很了解。","pinyin":""},{"speaker":"王一雪","cn":"嗯，他们尽管性格不同，但是有很多共同爱好。特别是同乐人好，性格也好，很有责任感。","pinyin":""},{"speaker":"刘明","cn":"是的，一飞也算在对的时间遇到了对的人。后边的路还很长，希望他们能一直相互理解、相互支持。","pinyin":""},{"speaker":"王一雪","cn":"我了解同乐，更了解一飞，相信他们会一直走下去的。","pinyin":""},{"speaker":"刘明","cn":"祝他们越来越幸福。","pinyin":""}],"translation_vn":"Vương Nhất Tuyết: Thấy Nhất Phi và Đồng Lạc kết hôn hạnh phúc như vậy, mình là người mai mối cũng thấy đặc biệt vui.\nLưu Minh: Đúng vậy, Đồng Lạc là bạn thân của em, Nhất Phi là em gái em, em hiểu rõ cả hai người.\nVương Nhất Tuyết: Ừm, dù hai người tính cách khác nhau, nhưng có rất nhiều sở thích chung. Đặc biệt Đồng Lạc là người tốt, tính cách cũng tốt, rất có trách nhiệm.\nLưu Minh: Đúng vậy, Nhất Phi cũng coi như đã gặp đúng người vào đúng thời điểm. Con đường phía trước còn dài, hy vọng họ sẽ luôn thấu hiểu và ủng hộ lẫn nhau.\nVương Nhất Tuyết: Em hiểu Đồng Lạc, lại càng hiểu Nhất Phi hơn, tin rằng họ sẽ đi cùng nhau đến cuối con đường.\nLưu Minh: Chúc họ ngày càng hạnh phúc.","audio_dialogue":"9-3.mp3","audio_vocab":"9-4.mp3"},{"label":"Bài khóa 3","type":"passage","lines":[{"speaker":"","cn":"王一雪比杨同乐更早进入公司。杨同乐刚来不久，王一雪对他印象就非常好：人很实在，性格阳光，工作负责，表现积极……后来他们一起出了次差，此次出差，让两人熟悉了起来，从此成了好朋友。一次聊天儿时，王一雪了解到杨同乐还没女朋友，正好自己的妹妹王一飞也没有男朋友，于是王一雪就把王一飞介绍给了他。杨同乐和王一飞认识后，很聊得来，两人之间慢慢产生了爱情，最后成了夫妻。杨同乐说自己很幸运，和王一雪这份同事间的友情，给他带来了美好的爱情。","pinyin":""}],"translation_vn":"Vương Nhất Tuyết vào công ty sớm hơn Dương Đồng Lạc. Dương Đồng Lạc mới đến chưa lâu, Vương Nhất Tuyết đã có ấn tượng rất tốt về anh: con người thật thà, tính cách rạng rỡ, làm việc có trách nhiệm, thể hiện tích cực... Sau đó hai người cùng đi công tác một lần, chuyến công tác này đã giúp hai người trở nên thân thiết, từ đó trở thành bạn tốt của nhau. Trong một lần trò chuyện, Vương Nhất Tuyết biết được Dương Đồng Lạc vẫn chưa có bạn gái, đúng lúc em gái mình là Vương Nhất Phi cũng chưa có bạn trai, thế là Vương Nhất Tuyết liền giới thiệu Nhất Phi cho anh. Sau khi Dương Đồng Lạc và Vương Nhất Phi quen biết nhau, hai người rất hợp chuyện, tình cảm giữa họ dần dần nảy sinh, cuối cùng trở thành vợ chồng. Dương Đồng Lạc nói rằng mình thật may mắn, chính tình bạn đồng nghiệp này với Vương Nhất Tuyết đã mang đến cho anh một tình yêu tốt đẹp.","audio_dialogue":"9-5.mp3","audio_vocab":"9-6.mp3"},{"label":"Bài khóa 4","type":"passage","lines":[{"speaker":"","cn":"李文在校园里遇见白家月，从此，他们的人生变得更加精彩；王一飞和杨同乐通过王一雪介绍认识后，感情越来越深，最后两人幸福地走到了一起。在我看来，遇见爱情的方式并不重要，重要的是在合适的时间遇到了合适的人。遇见你，刚刚好。不过美好的遇见只是爱的开始，爱更需要经营。在一段感情中，两个人要多关注对方的感受，尤其是结婚后，更要共同经营好家庭，日子才能越过越好。爱，从来都是相互尊重、理解与支持，不是吗？","pinyin":""}],"translation_vn":"Lý Văn gặp Bạch Gia Nguyệt trong khuôn viên trường, từ đó, cuộc sống của họ trở nên rực rỡ hơn; Vương Nhất Phi và Dương Đồng Lạc quen nhau qua sự giới thiệu của Vương Nhất Tuyết, tình cảm ngày càng sâu đậm, cuối cùng hai người đã hạnh phúc đến với nhau. Theo tôi, cách thức gặp được tình yêu không quan trọng, điều quan trọng là đã gặp đúng người vào đúng thời điểm. Gặp em, thật vừa vặn. Nhưng cuộc gặp gỡ tốt đẹp chỉ là khởi đầu của tình yêu, tình yêu còn cần được vun đắp nhiều hơn nữa. Trong một mối quan hệ, hai người cần quan tâm nhiều hơn đến cảm nhận của đối phương, đặc biệt là sau khi kết hôn, càng cần cùng nhau vun đắp tổ ấm, để cuộc sống ngày càng tốt đẹp hơn. Tình yêu, từ trước đến nay vẫn luôn là sự tôn trọng, thấu hiểu và ủng hộ lẫn nhau, phải không?","audio_dialogue":"9-7.mp3","audio_vocab":"9-8.mp3"}]},{"id":10,"title_cn":"南方不懂北方的冷","title_pinyin":"","title_vn":"Người miền Nam không hiểu cái lạnh miền Bắc","goals":["Có thể nghe hiểu và trao đổi các chủ đề liên quan đến mối quan hệ giữa khí hậu với môi trường, cuộc sống.","Có thể diễn đạt bằng lời nói hoặc văn viết về tầm quan trọng và cách thực hiện cụ thể của việc bảo vệ môi trường.","Hiểu được sự khác biệt về khí hậu, đời sống xã hội,... giữa miền Nam và miền Bắc Trung Quốc."],"vocab":[{"hanzi":"小伙子","pinyin":"xiǎohuǒzi","pos":"dt.","vn":"chàng trai, anh chàng","examples":[{"cn":"这个小伙子真能干。","pinyin":"Zhège xiǎohuǒzi zhēn nénggàn.","vn":"Chàng trai này thật giỏi giang."},{"cn":"那个小伙子长得很帅。","pinyin":"Nàge xiǎohuǒzi zhǎng de hěn shuài.","vn":"Chàng trai đó trông rất đẹp trai."},{"cn":"小伙子，你这是要去哪儿啊？","pinyin":"Xiǎohuǒzi, nǐ zhè shì yào qù nǎr a?","vn":"Này chàng trai, cậu định đi đâu vậy?"}]},{"hanzi":"气温","pinyin":"qìwēn","pos":"dt.","vn":"nhiệt độ không khí","examples":[{"cn":"今天气温下降了很多。","pinyin":"Jīntiān qìwēn xiàjiàngle hěn duō.","vn":"Hôm nay nhiệt độ không khí giảm xuống rất nhiều."},{"cn":"这几天气温一直很高。","pinyin":"Zhè jǐ tiān qìwēn yìzhí hěn gāo.","vn":"Mấy ngày nay nhiệt độ không khí luôn cao."},{"cn":"气温变化大，注意保暖。","pinyin":"Qìwēn biànhuà dà, zhùyì bǎonuǎn.","vn":"Nhiệt độ thay đổi lớn, chú ý giữ ấm."}]},{"hanzi":"零下","pinyin":"líng xià","pos":"","vn":"dưới 0 độ, âm độ","examples":[{"cn":"哈尔滨冬天经常是零下二十多度。","pinyin":"Hā'ěrbīn dōngtiān jīngcháng shì líng xià èrshí duō dù.","vn":"Mùa đông Cáp Nhĩ Tân thường âm hơn hai mươi độ."},{"cn":"今天气温零下五度，特别冷。","pinyin":"Jīntiān qìwēn líng xià wǔ dù, tèbié lěng.","vn":"Hôm nay nhiệt độ âm năm độ, lạnh vô cùng."},{"cn":"零下的天气里，河水都结冰了。","pinyin":"Líng xià de tiānqì lǐ, héshuǐ dōu jiébīng le.","vn":"Trong thời tiết dưới 0 độ, nước sông đã đóng băng."}]},{"hanzi":"度","pinyin":"dù","pos":"lượng.","vn":"độ","examples":[{"cn":"今天最高温度三十五度。","pinyin":"Jīntiān zuì gāo wēndù sānshíwǔ dù.","vn":"Nhiệt độ cao nhất hôm nay là ba mươi lăm độ."},{"cn":"水烧到一百度就会沸腾。","pinyin":"Shuǐ shāo dào yìbǎi dù jiù huì fèiténg.","vn":"Nước đun đến một trăm độ sẽ sôi."},{"cn":"这个角度大概是九十度。","pinyin":"Zhège jiǎodù dàgài shì jiǔshí dù.","vn":"Góc này khoảng chín mươi độ."}]},{"hanzi":"冻","pinyin":"dòng","pos":"dgt.","vn":"lạnh cóng, đóng băng","examples":[{"cn":"外面太冷了，我的手都冻僵了。","pinyin":"Wàimiàn tài lěng le, wǒ de shǒu dōu dòngjiāng le.","vn":"Bên ngoài lạnh quá, tay tôi lạnh cóng cứng cả lại."},{"cn":"把肉放进冰箱冻一下。","pinyin":"Bǎ ròu fàng jìn bīngxiāng dòng yíxià.","vn":"Cho thịt vào tủ lạnh đông một chút."},{"cn":"河面都冻住了。","pinyin":"Hémiàn dōu dòngzhù le.","vn":"Mặt sông đều đã đóng băng."}]},{"hanzi":"后悔","pinyin":"hòuhuǐ","pos":"dgt.","vn":"hối hận","examples":[{"cn":"我很后悔当初没有好好学习。","pinyin":"Wǒ hěn hòuhuǐ dāngchū méiyǒu hǎohāo xuéxí.","vn":"Tôi rất hối hận vì ngày trước đã không học hành đàng hoàng."},{"cn":"你要是现在放弃，以后会后悔的。","pinyin":"Nǐ yàoshi xiànzài fàngqì, yǐhòu huì hòuhuǐ de.","vn":"Nếu bây giờ bạn bỏ cuộc, sau này sẽ hối hận đấy."},{"cn":"他后悔没有听父母的话。","pinyin":"Tā hòuhuǐ méiyǒu tīng fùmǔ de huà.","vn":"Anh ấy hối hận vì không nghe lời bố mẹ."}]},{"hanzi":"就是","pinyin":"jiùshì","pos":"phó.","vn":"đúng vậy, chính là","examples":[{"cn":"对，我就是这个意思。","pinyin":"Duì, wǒ jiùshì zhège yìsi.","vn":"Đúng vậy, ý tôi chính là như vậy."},{"cn":"他就是我们常说的那个人。","pinyin":"Tā jiùshì wǒmen cháng shuō de nàge rén.","vn":"Anh ta chính là người mà chúng ta hay nhắc tới."},{"cn":"就是因为下雨，比赛才取消了。","pinyin":"Jiùshì yīnwèi xiàyǔ, bǐsài cái qǔxiāo le.","vn":"Chính vì trời mưa nên trận đấu mới bị hủy."}]},{"hanzi":"温度","pinyin":"wēndù","pos":"dt.","vn":"nhiệt độ","examples":[{"cn":"今天的温度有点低。","pinyin":"Jīntiān de wēndù yǒudiǎn dī.","vn":"Nhiệt độ hôm nay hơi thấp."},{"cn":"请调一下空调的温度。","pinyin":"Qǐng tiáo yíxià kōngtiáo de wēndù.","vn":"Làm ơn chỉnh lại nhiệt độ điều hòa."},{"cn":"这里的温度全年都很稳定。","pinyin":"Zhèlǐ de wēndù quánnián dōu hěn wěndìng.","vn":"Nhiệt độ ở đây ổn định quanh năm."}]},{"hanzi":"差别","pinyin":"chābié","pos":"dt.","vn":"sự khác biệt","examples":[{"cn":"南方和北方的气候差别很大。","pinyin":"Nánfāng hé běifāng de qìhòu chābié hěn dà.","vn":"Khí hậu miền Nam và miền Bắc khác nhau rất nhiều."},{"cn":"这两种产品质量差别不大。","pinyin":"Zhè liǎng zhǒng chǎnpǐn zhìliàng chābié bú dà.","vn":"Chất lượng của hai sản phẩm này không khác nhau nhiều."},{"cn":"他们俩的想法差别很大。","pinyin":"Tāmen liǎ de xiǎngfǎ chābié hěn dà.","vn":"Suy nghĩ của hai người họ khác nhau rất nhiều."}]},{"hanzi":"厚","pinyin":"hòu","pos":"tt.","vn":"dày","examples":[{"cn":"这本书很厚，我还没看完。","pinyin":"Zhè běn shū hěn hòu, wǒ hái méi kànwán.","vn":"Cuốn sách này rất dày, tôi vẫn chưa đọc xong."},{"cn":"冬天要穿厚一点的衣服。","pinyin":"Dōngtiān yào chuān hòu yìdiǎn de yīfu.","vn":"Mùa đông phải mặc quần áo dày hơn một chút."},{"cn":"这件大衣挺厚的，很保暖。","pinyin":"Zhè jiàn dàyī tǐng hòu de, hěn bǎonuǎn.","vn":"Chiếc áo khoác này khá dày, rất giữ ấm."}]},{"hanzi":"广州","pinyin":"Guǎngzhōu","pos":"danh từ riêng","vn":"Quảng Châu","examples":[{"cn":"我下个月要去广州出差。","pinyin":"Wǒ xià ge yuè yào qù Guǎngzhōu chūchāi.","vn":"Tháng sau tôi phải đi công tác Quảng Châu."},{"cn":"广州的夏天特别热。","pinyin":"Guǎngzhōu de xiàtiān tèbié rè.","vn":"Mùa hè ở Quảng Châu đặc biệt nóng."},{"cn":"她是广州人。","pinyin":"Tā shì Guǎngzhōu rén.","vn":"Cô ấy là người Quảng Châu."}]},{"hanzi":"哈尔滨","pinyin":"Hā'ěrbīn","pos":"danh từ riêng","vn":"Cáp Nhĩ Tân","examples":[{"cn":"哈尔滨的冰雕很有名。","pinyin":"Hā'ěrbīn de bīngdiāo hěn yǒumíng.","vn":"Tượng băng ở Cáp Nhĩ Tân rất nổi tiếng."},{"cn":"哈尔滨冬天非常冷。","pinyin":"Hā'ěrbīn dōngtiān fēicháng lěng.","vn":"Mùa đông ở Cáp Nhĩ Tân rất lạnh."},{"cn":"他是哈尔滨人，特别能喝酒。","pinyin":"Tā shì Hā'ěrbīn rén, tèbié néng hē jiǔ.","vn":"Anh ấy là người Cáp Nhĩ Tân, uống rượu rất giỏi."}]},{"hanzi":"寒假","pinyin":"hánjià","pos":"dt.","vn":"kỳ nghỉ đông","examples":[{"cn":"寒假我打算回老家过年。","pinyin":"Hánjià wǒ dǎsuàn huí lǎojiā guònián.","vn":"Kỳ nghỉ đông tôi định về quê ăn Tết."},{"cn":"孩子们寒假都在家写作业。","pinyin":"Háizimen hánjià dōu zài jiā xiě zuòyè.","vn":"Bọn trẻ nghỉ đông đều ở nhà làm bài tập."},{"cn":"寒假期间学校不上课。","pinyin":"Hánjià qījiān xuéxiào bú shàngkè.","vn":"Trong kỳ nghỉ đông trường không học."}]},{"hanzi":"暖和","pinyin":"nuǎnhuo","pos":"tt./dgt.","vn":"ấm áp; trở nên ấm áp","examples":[{"cn":"今天天气很暖和。","pinyin":"Jīntiān tiānqì hěn nuǎnhuo.","vn":"Hôm nay thời tiết rất ấm áp."},{"cn":"多穿点衣服，暖和一些。","pinyin":"Duō chuān diǎn yīfu, nuǎnhuo yìxiē.","vn":"Mặc thêm quần áo để ấm hơn một chút."},{"cn":"屋里开了暖气，特别暖和。","pinyin":"Wū lǐ kāile nuǎnqì, tèbié nuǎnhuo.","vn":"Trong phòng bật lò sưởi nên rất ấm áp."}]},{"hanzi":"低于","pinyin":"dīyú","pos":"dgt.","vn":"thấp hơn","examples":[{"cn":"今天的气温低于零度。","pinyin":"Jīntiān de qìwēn dīyú líng dù.","vn":"Nhiệt độ hôm nay thấp hơn 0 độ."},{"cn":"这个月的销售额低于预期。","pinyin":"Zhège yuè de xiāoshòu'é dīyú yùqī.","vn":"Doanh số tháng này thấp hơn dự kiến."},{"cn":"他的分数低于及格线。","pinyin":"Tā de fēnshù dīyú jígéxiàn.","vn":"Điểm số của anh ấy thấp hơn điểm đạt."}]},{"hanzi":"摄氏度","pinyin":"shèshìdù","pos":"lượng.","vn":"độ C","examples":[{"cn":"今天气温是三十摄氏度。","pinyin":"Jīntiān qìwēn shì sānshí shèshìdù.","vn":"Nhiệt độ hôm nay là ba mươi độ C."},{"cn":"水的沸点是一百摄氏度。","pinyin":"Shuǐ de fèidiǎn shì yìbǎi shèshìdù.","vn":"Điểm sôi của nước là một trăm độ C."},{"cn":"这里冬天气温能到零下十摄氏度。","pinyin":"Zhèlǐ dōngtiān qìwēn néng dào líng xià shí shèshìdù.","vn":"Mùa đông ở đây nhiệt độ có thể xuống âm mười độ C."}]},{"hanzi":"受不了","pinyin":"shòubuliǎo","pos":"dgt.","vn":"không chịu nổi","examples":[{"cn":"这里的天气太热了，我真受不了。","pinyin":"Zhèlǐ de tiānqì tài rè le, wǒ zhēn shòubuliǎo.","vn":"Thời tiết ở đây nóng quá, tôi thực sự không chịu nổi."},{"cn":"他说话太啰嗦，我都受不了了。","pinyin":"Tā shuōhuà tài luōsuo, wǒ dōu shòubuliǎo le.","vn":"Anh ấy nói chuyện dài dòng quá, tôi không chịu nổi nữa."},{"cn":"这种噪音让人受不了。","pinyin":"Zhè zhǒng zàoyīn ràng rén shòubuliǎo.","vn":"Tiếng ồn kiểu này khiến người ta không chịu nổi."}]},{"hanzi":"举办","pinyin":"jǔbàn","pos":"dgt.","vn":"tổ chức","examples":[{"cn":"学校下周要举办一场运动会。","pinyin":"Xuéxiào xià zhōu yào jǔbàn yì chǎng yùndònghuì.","vn":"Tuần sau trường sẽ tổ chức một hội thao."},{"cn":"这次晚会是由学生会举办的。","pinyin":"Zhè cì wǎnhuì shì yóu xuéshēnghuì jǔbàn de.","vn":"Buổi tối văn nghệ lần này do hội sinh viên tổ chức."},{"cn":"北京举办过奥运会。","pinyin":"Běijīng jǔbànguò Àoyùnhuì.","vn":"Bắc Kinh từng tổ chức Thế vận hội."}]},{"hanzi":"各种","pinyin":"gèzhǒng","pos":"đt.","vn":"các loại, mọi loại","examples":[{"cn":"市场上有各种各样的水果。","pinyin":"Shìchǎng shàng yǒu gè zhǒng gè yàng de shuǐguǒ.","vn":"Ở chợ có đủ các loại trái cây."},{"cn":"他经历过各种困难。","pinyin":"Tā jīnglìguò gèzhǒng kùnnan.","vn":"Anh ấy đã trải qua đủ các loại khó khăn."},{"cn":"这里提供各种服务。","pinyin":"Zhèlǐ tígōng gèzhǒng fúwù.","vn":"Ở đây cung cấp đủ các loại dịch vụ."}]},{"hanzi":"植物","pinyin":"zhíwù","pos":"dt.","vn":"thực vật","examples":[{"cn":"她家阳台上种了很多植物。","pinyin":"Tā jiā yángtái shàng zhòngle hěn duō zhíwù.","vn":"Trên ban công nhà cô ấy trồng rất nhiều cây."},{"cn":"这种植物只能在热带生长。","pinyin":"Zhè zhǒng zhíwù zhǐnéng zài rèdài shēngzhǎng.","vn":"Loại thực vật này chỉ sinh trưởng được ở vùng nhiệt đới."},{"cn":"他很喜欢研究植物。","pinyin":"Tā hěn xǐhuan yánjiū zhíwù.","vn":"Anh ấy rất thích nghiên cứu thực vật."}]},{"hanzi":"公里","pinyin":"gōnglǐ","pos":"lượng.","vn":"ki-lô-mét","examples":[{"cn":"这里离市中心大概十公里。","pinyin":"Zhèlǐ lí shìzhōngxīn dàgài shí gōnglǐ.","vn":"Chỗ này cách trung tâm thành phố khoảng mười ki-lô-mét."},{"cn":"他每天跑五公里。","pinyin":"Tā měitiān pǎo wǔ gōnglǐ.","vn":"Anh ấy chạy bộ năm ki-lô-mét mỗi ngày."},{"cn":"这条路全长一百多公里。","pinyin":"Zhè tiáo lù quáncháng yìbǎi duō gōnglǐ.","vn":"Con đường này dài tổng cộng hơn một trăm ki-lô-mét."}]},{"hanzi":"气候","pinyin":"qìhòu","pos":"dt.","vn":"khí hậu","examples":[{"cn":"这里的气候四季分明。","pinyin":"Zhèlǐ de qìhòu sìjì fēnmíng.","vn":"Khí hậu ở đây bốn mùa rõ rệt."},{"cn":"南方气候比较潮湿。","pinyin":"Nánfāng qìhòu bǐjiào cháoshī.","vn":"Khí hậu miền Nam khá ẩm ướt."},{"cn":"气候变化对农业影响很大。","pinyin":"Qìhòu biànhuà duì nóngyè yǐngxiǎng hěn dà.","vn":"Biến đổi khí hậu ảnh hưởng rất lớn đến nông nghiệp."}]},{"hanzi":"而","pinyin":"ér","pos":"liên.","vn":"mà, nhưng, và","examples":[{"cn":"他不是不努力，而是方法不对。","pinyin":"Tā búshì bù nǔlì, érshì fāngfǎ bú duì.","vn":"Anh ấy không phải không cố gắng, mà là phương pháp sai."},{"cn":"这件事说起来容易，而做起来很难。","pinyin":"Zhè jiàn shì shuō qǐlái róngyì, ér zuò qǐlái hěn nán.","vn":"Việc này nói thì dễ, nhưng làm thì rất khó."},{"cn":"她既聪明而又勤奋。","pinyin":"Tā jì cōngming ér yòu qínfèn.","vn":"Cô ấy vừa thông minh lại vừa chăm chỉ."}]},{"hanzi":"此外","pinyin":"cǐwài","pos":"liên.","vn":"ngoài ra","examples":[{"cn":"此外，我们还需要准备一些材料。","pinyin":"Cǐwài, wǒmen hái xūyào zhǔnbèi yìxiē cáiliào.","vn":"Ngoài ra, chúng ta còn cần chuẩn bị thêm một số tài liệu."},{"cn":"他会说英语，此外还会说法语。","pinyin":"Tā huì shuō Yīngyǔ, cǐwài hái huì shuō Fǎyǔ.","vn":"Anh ấy biết nói tiếng Anh, ngoài ra còn biết nói tiếng Pháp."},{"cn":"此外，这个计划还有一些细节需要讨论。","pinyin":"Cǐwài, zhège jìhuà hái yǒu yìxiē xìjié xūyào tǎolùn.","vn":"Ngoài ra, kế hoạch này còn có một số chi tiết cần bàn bạc."}]},{"hanzi":"方言","pinyin":"fāngyán","pos":"dt.","vn":"phương ngữ, tiếng địa phương","examples":[{"cn":"中国各地的方言差别很大。","pinyin":"Zhōngguó gèdì de fāngyán chābié hěn dà.","vn":"Tiếng địa phương ở các vùng của Trung Quốc khác nhau rất nhiều."},{"cn":"我听不懂他说的方言。","pinyin":"Wǒ tīngbudǒng tā shuō de fāngyán.","vn":"Tôi không nghe hiểu tiếng địa phương anh ấy nói."},{"cn":"她能说好几种方言。","pinyin":"Tā néng shuō hǎo jǐ zhǒng fāngyán.","vn":"Cô ấy biết nói mấy loại phương ngữ."}]},{"hanzi":"普通话","pinyin":"pǔtōnghuà","pos":"dt.","vn":"tiếng phổ thông (Trung Quốc)","examples":[{"cn":"他的普通话说得很标准。","pinyin":"Tā de pǔtōnghuà shuō de hěn biāozhǔn.","vn":"Anh ấy nói tiếng phổ thông rất chuẩn."},{"cn":"在学校老师都用普通话教学。","pinyin":"Zài xuéxiào lǎoshī dōu yòng pǔtōnghuà jiàoxué.","vn":"Ở trường thầy cô đều dùng tiếng phổ thông để giảng dạy."},{"cn":"我正在学习普通话。","pinyin":"Wǒ zhèngzài xuéxí pǔtōnghuà.","vn":"Tôi đang học tiếng phổ thông."}]},{"hanzi":"较","pinyin":"jiào","pos":"phó.","vn":"tương đối, khá","examples":[{"cn":"这个方法较为简单。","pinyin":"Zhège fāngfǎ jiàowéi jiǎndān.","vn":"Phương pháp này tương đối đơn giản."},{"cn":"今年的收入较去年有所增长。","pinyin":"Jīnnián de shōurù jiào qùnián yǒusuǒ zēngzhǎng.","vn":"Thu nhập năm nay tăng hơn so với năm ngoái."},{"cn":"他的态度较以前好多了。","pinyin":"Tā de tàidu jiào yǐqián hǎo duō le.","vn":"Thái độ của anh ấy khá hơn trước nhiều."}]},{"hanzi":"使用","pinyin":"shǐyòng","pos":"dgt.","vn":"sử dụng","examples":[{"cn":"请按照说明书正确使用这个产品。","pinyin":"Qǐng ànzhào shuōmíngshū zhèngquè shǐyòng zhège chǎnpǐn.","vn":"Xin hãy sử dụng sản phẩm này đúng cách theo hướng dẫn."},{"cn":"这个软件使用起来很方便。","pinyin":"Zhège ruǎnjiàn shǐyòng qǐlái hěn fāngbiàn.","vn":"Phần mềm này sử dụng rất tiện lợi."},{"cn":"他经常使用这台电脑工作。","pinyin":"Tā jīngcháng shǐyòng zhè tái diànnǎo gōngzuò.","vn":"Anh ấy thường xuyên dùng chiếc máy tính này để làm việc."}]},{"hanzi":"引起","pinyin":"yǐnqǐ","pos":"dgt.","vn":"gây ra","examples":[{"cn":"这件事引起了大家的注意。","pinyin":"Zhè jiàn shì yǐnqǐle dàjiā de zhùyì.","vn":"Việc này đã thu hút sự chú ý của mọi người."},{"cn":"他的发言引起了争论。","pinyin":"Tā de fāyán yǐnqǐle zhēnglùn.","vn":"Bài phát biểu của anh ấy đã gây ra tranh luận."},{"cn":"吸烟容易引起肺部疾病。","pinyin":"Xīyān róngyì yǐnqǐ fèibù jíbìng.","vn":"Hút thuốc dễ gây ra bệnh về phổi."}]},{"hanzi":"误会","pinyin":"wùhuì","pos":"dt./dgt.","vn":"hiểu lầm","examples":[{"cn":"这只是个误会，我们解释清楚就好了。","pinyin":"Zhè zhǐshì ge wùhuì, wǒmen jiěshì qīngchu jiù hǎole.","vn":"Đây chỉ là hiểu lầm thôi, chúng ta giải thích rõ là được."},{"cn":"他误会了我的意思。","pinyin":"Tā wùhuìle wǒ de yìsi.","vn":"Anh ấy đã hiểu lầm ý của tôi."},{"cn":"别误会，我不是那个意思。","pinyin":"Bié wùhuì, wǒ búshì nàge yìsi.","vn":"Đừng hiểu lầm, tôi không có ý đó."}]},{"hanzi":"亲爱","pinyin":"qīn'ài","pos":"tt.","vn":"thân mến","examples":[{"cn":"亲爱的朋友们，大家好。","pinyin":"Qīn'ài de péngyoumen, dàjiā hǎo.","vn":"Các bạn thân mến, xin chào mọi người."},{"cn":"亲爱的，我回来了。","pinyin":"Qīn'ài de, wǒ huílái le.","vn":"Em yêu, anh về rồi."},{"cn":"亲爱的妈妈，我很想你。","pinyin":"Qīn'ài de māma, wǒ hěn xiǎng nǐ.","vn":"Mẹ thân yêu, con rất nhớ mẹ."}]},{"hanzi":"再次","pinyin":"zàicì","pos":"phó.","vn":"một lần nữa","examples":[{"cn":"我再次提醒大家注意安全。","pinyin":"Wǒ zàicì tíxǐng dàjiā zhùyì ānquán.","vn":"Tôi một lần nữa nhắc nhở mọi người chú ý an toàn."},{"cn":"他们再次见面已经是十年后了。","pinyin":"Tāmen zàicì jiànmiàn yǐjīng shì shí nián hòu le.","vn":"Họ gặp lại nhau một lần nữa đã là mười năm sau."},{"cn":"请再次确认一下信息是否正确。","pinyin":"Qǐng zàicì quèrèn yíxià xìnxī shìfǒu zhèngquè.","vn":"Xin hãy xác nhận lại một lần nữa xem thông tin có chính xác không."}]},{"hanzi":"开展","pinyin":"kāizhǎn","pos":"dgt.","vn":"triển khai","examples":[{"cn":"学校将开展一系列环保活动。","pinyin":"Xuéxiào jiāng kāizhǎn yíxìliè huánbǎo huódòng.","vn":"Nhà trường sẽ triển khai một loạt hoạt động bảo vệ môi trường."},{"cn":"公司决定在海外开展业务。","pinyin":"Gōngsī juédìng zài hǎiwài kāizhǎn yèwù.","vn":"Công ty quyết định triển khai kinh doanh ở nước ngoài."},{"cn":"这项工作正在顺利开展。","pinyin":"Zhè xiàng gōngzuò zhèngzài shùnlì kāizhǎn.","vn":"Công việc này đang được triển khai thuận lợi."}]},{"hanzi":"绿色","pinyin":"lǜsè","pos":"tt.","vn":"xanh, thân thiện với môi trường","examples":[{"cn":"现在很多人提倡绿色出行。","pinyin":"Xiànzài hěn duō rén tíchàng lǜsè chūxíng.","vn":"Hiện nay nhiều người đề xướng di chuyển xanh, thân thiện môi trường."},{"cn":"她喜欢穿绿色的衣服。","pinyin":"Tā xǐhuan chuān lǜsè de yīfu.","vn":"Cô ấy thích mặc quần áo màu xanh."},{"cn":"这是一款绿色环保产品。","pinyin":"Zhè shì yì kuǎn lǜsè huánbǎo chǎnpǐn.","vn":"Đây là một sản phẩm xanh, thân thiện với môi trường."}]},{"hanzi":"环保","pinyin":"huánbǎo","pos":"dt./tt.","vn":"bảo vệ môi trường","examples":[{"cn":"我们应该提高环保意识。","pinyin":"Wǒmen yīnggāi tígāo huánbǎo yìshí.","vn":"Chúng ta nên nâng cao ý thức bảo vệ môi trường."},{"cn":"这种材料很环保。","pinyin":"Zhè zhǒng cáiliào hěn huánbǎo.","vn":"Loại vật liệu này rất thân thiện với môi trường."},{"cn":"政府大力推广环保政策。","pinyin":"Zhèngfǔ dàlì tuīguǎng huánbǎo zhèngcè.","vn":"Chính phủ ra sức thúc đẩy chính sách bảo vệ môi trường."}]},{"hanzi":"拒绝","pinyin":"jùjué","pos":"dgt.","vn":"từ chối","examples":[{"cn":"他拒绝了我的请求。","pinyin":"Tā jùjuéle wǒ de qǐngqiú.","vn":"Anh ấy đã từ chối yêu cầu của tôi."},{"cn":"她很委婉地拒绝了那份工作。","pinyin":"Tā hěn wěiwǎn de jùjuéle nà fèn gōngzuò.","vn":"Cô ấy đã khéo léo từ chối công việc đó."},{"cn":"面对诱惑，他果断地拒绝了。","pinyin":"Miànduì yòuhuò, tā guǒduàn de jùjuéle.","vn":"Đối mặt với cám dỗ, anh ấy đã dứt khoát từ chối."}]},{"hanzi":"浪费","pinyin":"làngfèi","pos":"dgt.","vn":"lãng phí","examples":[{"cn":"别浪费粮食。","pinyin":"Bié làngfèi liángshi.","vn":"Đừng lãng phí lương thực."},{"cn":"这样做太浪费时间了。","pinyin":"Zhèyàng zuò tài làngfèi shíjiān le.","vn":"Làm như vậy quá lãng phí thời gian."},{"cn":"他从不浪费一分钱。","pinyin":"Tā cóngbù làngfèi yì fēn qián.","vn":"Anh ấy không bao giờ lãng phí dù một đồng."}]},{"hanzi":"节约","pinyin":"jiéyuē","pos":"dgt.","vn":"tiết kiệm","examples":[{"cn":"我们应该节约用水。","pinyin":"Wǒmen yīnggāi jiéyuē yòngshuǐ.","vn":"Chúng ta nên tiết kiệm nước."},{"cn":"她生活很节约，不乱花钱。","pinyin":"Tā shēnghuó hěn jiéyuē, bú luàn huāqián.","vn":"Cô ấy sống rất tiết kiệm, không tiêu tiền bừa bãi."},{"cn":"节约能源，从我做起。","pinyin":"Jiéyuē néngyuán, cóng wǒ zuòqǐ.","vn":"Tiết kiệm năng lượng, bắt đầu từ chính tôi."}]},{"hanzi":"资源","pinyin":"zīyuán","pos":"dt.","vn":"tài nguyên","examples":[{"cn":"水是非常宝贵的资源。","pinyin":"Shuǐ shì fēicháng bǎoguì de zīyuán.","vn":"Nước là nguồn tài nguyên vô cùng quý giá."},{"cn":"这个地区自然资源丰富。","pinyin":"Zhège dìqū zìrán zīyuán fēngfù.","vn":"Khu vực này tài nguyên thiên nhiên phong phú."},{"cn":"我们要合理利用资源。","pinyin":"Wǒmen yào hélǐ lìyòng zīyuán.","vn":"Chúng ta phải sử dụng tài nguyên một cách hợp lý."}]},{"hanzi":"光","pinyin":"guāng","pos":"tt.","vn":"hết sạch","examples":[{"cn":"他把身上的钱都花光了。","pinyin":"Tā bǎ shēnshang de qián dōu huāguāng le.","vn":"Anh ấy tiêu hết sạch tiền trong người."},{"cn":"这瓶水我一口气喝光了。","pinyin":"Zhè píng shuǐ wǒ yìkǒuqì hēguāng le.","vn":"Chai nước này tôi uống hết sạch một hơi."},{"cn":"饭都被孩子们吃光了。","pinyin":"Fàn dōu bèi háizimen chīguāng le.","vn":"Cơm đã bị bọn trẻ ăn hết sạch."}]},{"hanzi":"垃圾","pinyin":"lājī","pos":"dt.","vn":"rác","examples":[{"cn":"请把垃圾扔进垃圾桶。","pinyin":"Qǐng bǎ lājī rēng jìn lājītǒng.","vn":"Xin hãy vứt rác vào thùng rác."},{"cn":"这里到处都是垃圾。","pinyin":"Zhèlǐ dàochù dōu shì lājī.","vn":"Nơi này khắp nơi đều là rác."},{"cn":"我们应该学会垃圾分类。","pinyin":"Wǒmen yīnggāi xuéhuì lājī fēnlèi.","vn":"Chúng ta nên học cách phân loại rác."}]},{"hanzi":"分类","pinyin":"fēnlèi","pos":"dgt.","vn":"phân loại","examples":[{"cn":"垃圾要分类处理。","pinyin":"Lājī yào fēnlèi chǔlǐ.","vn":"Rác phải được xử lý theo phân loại."},{"cn":"这些文件需要按类别分类。","pinyin":"Zhèxiē wénjiàn xūyào àn lèibié fēnlèi.","vn":"Những tài liệu này cần được phân loại theo hạng mục."},{"cn":"图书馆的书都按主题分类摆放。","pinyin":"Túshūguǎn de shū dōu àn zhǔtí fēnlèi bǎifàng.","vn":"Sách trong thư viện đều được phân loại và sắp xếp theo chủ đề."}]},{"hanzi":"日常","pinyin":"rìcháng","pos":"tt.","vn":"thường ngày, hàng ngày","examples":[{"cn":"这些都是我们日常生活中常用的东西。","pinyin":"Zhèxiē dōu shì wǒmen rìcháng shēnghuó zhōng chángyòng de dōngxi.","vn":"Đây đều là những thứ thường dùng trong cuộc sống hàng ngày của chúng ta."},{"cn":"他把日常开支记得很清楚。","pinyin":"Tā bǎ rìcháng kāizhī jì de hěn qīngchu.","vn":"Anh ấy ghi chép chi tiêu hàng ngày rất rõ ràng."},{"cn":"保持日常锻炼对身体很好。","pinyin":"Bǎochí rìcháng duànliàn duì shēntǐ hěn hǎo.","vn":"Duy trì tập luyện hàng ngày rất tốt cho sức khỏe."}]}],"grammar":[{"title":"固定格式\"说什么/怎么（着）也得×\"","explanation_vn":"Cấu trúc cố định \"说什么/怎么（着）也得×\" biểu thị sự cần thiết hoặc quyết tâm bắt buộc phải làm gì đó, thường dùng trong khẩu ngữ.","examples":[{"cn":"更重要的是，说什么也得穿上厚一点儿的衣服。","pinyin":"","vn":"Quan trọng hơn là, dù thế nào cũng phải mặc quần áo dày một chút."},{"cn":"假期还有两天就结束了，我明天说什么也得把作业做完了。","pinyin":"","vn":"Kỳ nghỉ còn hai ngày nữa là kết thúc, ngày mai dù thế nào tôi cũng phải làm xong bài tập."},{"cn":"我很后悔上次没参加这个活动，这次怎么着也得去。","pinyin":"","vn":"Tôi rất hối hận vì lần trước không tham gia hoạt động này, lần này dù thế nào cũng phải đi."}]},{"title":"固定短语\"有的是\"","explanation_vn":"Cụm từ cố định \"有的是\" thường dùng trong khẩu ngữ, biểu thị có rất nhiều, nhấn mạnh số lượng dồi dào.","examples":[{"cn":"没问题，受得了，我有的是厚衣服。","pinyin":"","vn":"Không vấn đề gì, chịu được, tôi có thừa quần áo dày."},{"cn":"过年时，家里有的是好吃的、好喝的，孩子们特别开心。","pinyin":"","vn":"Dịp Tết, trong nhà có đầy đồ ăn ngon, đồ uống ngon, bọn trẻ đặc biệt vui."},{"cn":"这个市场特别大，有的是水果和菜，你想买什么菜都能买到。","pinyin":"","vn":"Khu chợ này rất lớn, có đủ loại hoa quả và rau, bạn muốn mua rau gì cũng mua được."}]},{"title":"连词\"而\"","explanation_vn":"Liên từ \"而\" nối động từ, tính từ hoặc cụm từ, vế câu, có nhiều nghĩa khác nhau, ở đây giới thiệu ba cách dùng: (1) biểu thị sự chuyển ý, \"而\" nối hai thành phần có ý nghĩa trái ngược nhau; (2) biểu thị sự tiếp nối về mặt ý nghĩa; (3) biểu thị quan hệ nhân quả trước sau về mặt sự lý.","examples":[{"cn":"广州基本上没有冬天，而哈尔滨的冬天一般会从十月开始，到第二年的三四月才结束。","pinyin":"","vn":"Quảng Châu hầu như không có mùa đông, còn mùa đông ở Cáp Nhĩ Tân thường bắt đầu từ tháng Mười, đến tận tháng Ba tháng Tư năm sau mới kết thúc."},{"cn":"在这个紧张而兴奋的日子里，我们都走出教室，为运动员们加油。","pinyin":"","vn":"Trong những ngày căng thẳng mà phấn khích này, chúng tôi đều ra khỏi lớp học để cổ vũ cho các vận động viên."},{"cn":"冬天，这个城市因为天气暖和而吸引了很多游客。","pinyin":"","vn":"Vào mùa đông, thành phố này vì thời tiết ấm áp nên thu hút rất nhiều du khách."}]},{"title":"频率副词\"再次\"","explanation_vn":"Phó từ tần suất \"再次\" đứng trước động từ, biểu thị lần thứ hai, thêm một lần nữa.","examples":[{"cn":"今年的\"世界环境日\"，我们再次开展\"绿色生活\"活动。","pinyin":"","vn":"Nhân \"Ngày Môi trường Thế giới\" năm nay, chúng ta lại tiếp tục triển khai hoạt động \"Sống xanh\"."},{"cn":"我去年冬天去过一次哈尔滨，很喜欢那里的雪；今年冬天，我计划再次去哈尔滨看雪。","pinyin":"","vn":"Mùa đông năm ngoái tôi từng đến Cáp Nhĩ Tân một lần, rất thích tuyết ở đó; mùa đông năm nay, tôi dự định đi Cáp Nhĩ Tân ngắm tuyết một lần nữa."},{"cn":"再次感谢您的支持与关心！","pinyin":"","vn":"Một lần nữa xin cảm ơn sự ủng hộ và quan tâm của quý vị!"}]}],"texts":[{"label":"Bài khóa 1","type":"dialogue","lines":[{"speaker":"刘明","cn":"你看，这个小伙子从广州去哈尔滨出差，没想到哈尔滨的气温降到了零下二十几度，把他冻坏了。","pinyin":""},{"speaker":"王一雪","cn":"他一定后悔自己穿少了吧？","pinyin":""},{"speaker":"刘明","cn":"是啊，这就叫南方不懂北方的冷。","pinyin":""},{"speaker":"王一雪","cn":"就是呢，冬天北方和南方的温度差别还是很大的。","pinyin":""},{"speaker":"刘明","cn":"所以冬天来北方，尤其是东北，一定要提前查好目的地的天气，看看下不下雪，气温怎么样。","pinyin":""},{"speaker":"王一雪","cn":"对。更重要的是，说什么也得穿上厚一点儿的衣服。","pinyin":""}],"translation_vn":"Lưu Minh: Em xem này, anh chàng này từ Quảng Châu đi công tác đến Cáp Nhĩ Tân, không ngờ nhiệt độ ở Cáp Nhĩ Tân hạ xuống âm hai mươi mấy độ, khiến anh ta lạnh cóng luôn.\nVương Nhất Tuyết: Chắc anh ta hối hận vì mặc ít đồ quá nhỉ?\nLưu Minh: Đúng vậy, đây gọi là người miền Nam không hiểu được cái lạnh của miền Bắc.\nVương Nhất Tuyết: Đúng thế, mùa đông sự chênh lệch nhiệt độ giữa miền Bắc và miền Nam vẫn rất lớn.\nLưu Minh: Vì vậy mùa đông đến miền Bắc, đặc biệt là vùng Đông Bắc, nhất định phải tra trước thời tiết nơi đến, xem có tuyết không, nhiệt độ thế nào.\nVương Nhất Tuyết: Đúng vậy. Quan trọng hơn là, dù thế nào cũng phải mặc quần áo dày một chút.","audio_dialogue":"10-1.mp3","audio_vocab":"10-2.mp3"},{"label":"Bài khóa 2","type":"dialogue","lines":[{"speaker":"王一飞","cn":"寒假你们打算做什么呢？","pinyin":""},{"speaker":"陈天中","cn":"我们刚刚还说呢，家月春节时要去广州，我计划去哈尔滨。","pinyin":""},{"speaker":"王一飞","cn":"那时候广州暖和，但哈尔滨特别冷，气温一般都低于零下十摄氏度甚至零下二十摄氏度，这么低的温度你受不了吧？","pinyin":""},{"speaker":"陈天中","cn":"没问题，受得了，我有的是厚衣服。我去哈尔滨主要是想看雪，听说春节时那里会举办很多活动。","pinyin":""},{"speaker":"白家月","cn":"我想在广州过年，那里冬天比较暖和。而且我喜欢看花，听说广州的鲜花市场很有名，里面有各种植物。","pinyin":""},{"speaker":"王一飞","cn":"真不错！听你们这么一说，我也想外出旅游了。","pinyin":""}],"translation_vn":"Vương Nhất Phi: Kỳ nghỉ đông các bạn định làm gì vậy?\nTrần Thiên Trung: Bọn mình vừa mới nói đấy, Gia Nguyệt Tết sẽ đi Quảng Châu, mình thì định đi Cáp Nhĩ Tân.\nVương Nhất Phi: Lúc đó Quảng Châu ấm áp, nhưng Cáp Nhĩ Tân lại rất lạnh, nhiệt độ thường thấp hơn âm mười độ C thậm chí âm hai mươi độ C, nhiệt độ thấp như vậy cậu chịu được không?\nTrần Thiên Trung: Không vấn đề gì, chịu được, mình có thừa quần áo dày mà. Mình đi Cáp Nhĩ Tân chủ yếu là muốn xem tuyết, nghe nói Tết ở đó sẽ tổ chức rất nhiều hoạt động.\nBạch Gia Nguyệt: Mình muốn đón Tết ở Quảng Châu, mùa đông ở đó khá ấm áp. Hơn nữa mình thích ngắm hoa, nghe nói chợ hoa tươi ở Quảng Châu rất nổi tiếng, trong đó có đủ loại thực vật.\nVương Nhất Phi: Hay thật đấy! Nghe các bạn nói vậy, mình cũng muốn đi du lịch rồi.","audio_dialogue":"10-3.mp3","audio_vocab":"10-4.mp3"},{"label":"Bài khóa 3","type":"passage","lines":[{"speaker":"","cn":"广州和哈尔滨，一个在南方，一个在北方，两个城市之间的距离有三千多公里，气候也大不相同。广州基本上没有冬天，而哈尔滨的冬天一般会从十月开始，到第二年的三四月才结束。广州四季开满鲜花，所以又叫\"花城\"；哈尔滨冬天冰雪多，所以也叫\"冰城\"。此外，两地的方言也不一样。哈尔滨方言和普通话听起来比较像，而广州方言和普通话差别较大。如果广州人和哈尔滨人都只使用自己的方言，那么交流就很困难，甚至还可能引起误会。其实，中国很多地方都有自己的方言，所以，为了顺利交流，中国人从小都要学习普通话。","pinyin":""}],"translation_vn":"Quảng Châu và Cáp Nhĩ Tân, một ở miền Nam, một ở miền Bắc, khoảng cách giữa hai thành phố hơn ba nghìn ki-lô-mét, khí hậu cũng rất khác nhau. Quảng Châu hầu như không có mùa đông, còn mùa đông ở Cáp Nhĩ Tân thường bắt đầu từ tháng Mười, đến tận tháng Ba tháng Tư năm sau mới kết thúc. Quảng Châu bốn mùa hoa nở rộ, nên còn được gọi là \"thành phố hoa\"; mùa đông ở Cáp Nhĩ Tân nhiều băng tuyết, nên cũng được gọi là \"thành phố băng\". Ngoài ra, phương ngữ của hai nơi cũng không giống nhau. Phương ngữ Cáp Nhĩ Tân nghe khá giống tiếng phổ thông, còn phương ngữ Quảng Châu lại khác biệt khá lớn so với tiếng phổ thông. Nếu người Quảng Châu và người Cáp Nhĩ Tân đều chỉ dùng phương ngữ của mình, thì việc giao tiếp sẽ rất khó khăn, thậm chí còn có thể gây hiểu lầm. Thực ra, rất nhiều nơi ở Trung Quốc đều có phương ngữ riêng, vì vậy, để giao tiếp thuận lợi, người Trung Quốc từ nhỏ đều phải học tiếng phổ thông.","audio_dialogue":"10-5.mp3","audio_vocab":"10-6.mp3"},{"label":"Bài khóa 4","type":"passage","lines":[{"speaker":"","cn":"亲爱的同学们：今年的\"世界环境日\"，我们再次开展\"绿色生活\"活动，希望同学们做到：一、绿色出行。绿色一小步，环保一大步。根据距离选择绿色交通方式。距离短时可以走路或者骑自行车，距离长时多乘坐公交车或者地铁。二、拒绝浪费。节约资源，坚持一水多用、人走灯关、餐餐都\"光盘\"。三、垃圾分类。积极参加校园、小区环保活动，学习垃圾分类知识，从小事做起，做好垃圾分类。保护环境是每一个人的责任。同学们，让我们共同努力，让绿色生活成为我们的日常习惯！校学生会 2026年6月5日","pinyin":""}],"translation_vn":"Các bạn học sinh thân mến: Nhân \"Ngày Môi trường Thế giới\" năm nay, chúng ta lại tiếp tục triển khai hoạt động \"Sống xanh\", hy vọng các bạn làm được những điều sau: Một, Di chuyển xanh. Một bước nhỏ xanh, một bước lớn bảo vệ môi trường. Hãy chọn phương thức di chuyển xanh tùy theo khoảng cách. Khi khoảng cách gần có thể đi bộ hoặc đi xe đạp, khi khoảng cách xa nên đi xe buýt hoặc tàu điện ngầm nhiều hơn. Hai, Nói không với lãng phí. Tiết kiệm tài nguyên, kiên trì dùng nước nhiều lần, ra khỏi phòng tắt đèn, mỗi bữa ăn đều \"sạch đĩa\". Ba, Phân loại rác. Tích cực tham gia các hoạt động bảo vệ môi trường ở trường học, khu dân cư, học kiến thức phân loại rác, bắt đầu từ những việc nhỏ, làm tốt việc phân loại rác. Bảo vệ môi trường là trách nhiệm của mỗi người. Các bạn ơi, hãy cùng nhau nỗ lực, để lối sống xanh trở thành thói quen hàng ngày của chúng ta! Hội Học sinh Nhà trường, Ngày 5 tháng 6 năm 2026","audio_dialogue":"10-7.mp3","audio_vocab":"10-8.mp3"}]}],"pos_table":[{"pos_cn":"名词","pos_vn":"Danh từ","abbr":"dt."},{"pos_cn":"动词","pos_vn":"Động từ","abbr":"dgt."},{"pos_cn":"形容词","pos_vn":"Tính từ","abbr":"tt."},{"pos_cn":"代词","pos_vn":"Đại từ","abbr":"đt."},{"pos_cn":"副词","pos_vn":"Phó từ","abbr":"phó."},{"pos_cn":"介词","pos_vn":"Giới từ","abbr":"giới."},{"pos_cn":"连词","pos_vn":"Liên từ","abbr":"liên."},{"pos_cn":"助词","pos_vn":"Trợ từ","abbr":"trợ."},{"pos_cn":"数词","pos_vn":"Từ chỉ số đếm","abbr":"số."},{"pos_cn":"量词","pos_vn":"Lượng từ","abbr":"lượng."},{"pos_cn":"数量词","pos_vn":"Từ chỉ số lượng","abbr":"sl."},{"pos_cn":"叹词","pos_vn":"Từ cảm thán","abbr":"ct."},{"pos_cn":"拟声词","pos_vn":"Từ tượng thanh","abbr":"tượng."},{"pos_cn":"能愿动词","pos_vn":"Động từ năng nguyện","abbr":"đtnn."},{"pos_cn":"前缀","pos_vn":"Tiền tố","abbr":"ttố."},{"pos_cn":"后缀","pos_vn":"Hậu tố","abbr":"htố."}]};